	public void InitCadCamSimulation()
	{
		if (buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawHead)
		{
			clsFiles.OpenMachineConfig(AppPath.MachineSimConfig + "\\Machine.bumachdef", ref ccVars.SimMachine);
			new List<Entity>();
			List<Entity> list = new List<Entity>();
			if (ccVars.SimMachine == null)
			{
				ccVars.SimMachine = new MachineDef();
			}
			if (ccVars.SimMachine != null)
			{
				if (ccVars.SimMachine.MachineParts.Count > 0)
				{
					for (int i = 0; i <= ccVars.SimMachine.MachineParts.Count - 1; i++)
					{
						for (int j = 0; j <= ccVars.SimMachine.MachineParts[i].Entities.Count - 1; j++)
						{
							bool flag = true;
							bool flag2 = false;
							Entity entity = buVector5.CopyEntities(ccVars.SimMachine.MachineParts[i].Entities[j]);
							CustomData customData = new CustomData();
							customData.typeDefination = entityTypeDefination.MachineParts;
							customData.EntityName = ccVars.SimMachine.MachineParts[i].PartName;
							if (ccVars.SimMachine.MachineParts[i].PartType == "Lathe")
							{
								customData.infoString = "NotDelete";
								customData.ActionName = "Lathe";
								flag2 = true;
							}
							entity.EntityData = customData;
							if (flag2 & !buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawLathe)
							{
								flag = false;
							}
							if (flag)
							{
								entity.Regen(new RegenParams(buSystem.RegenDeviation, ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
								list.Add(entity);
							}
						}
					}
				}
				if (list.Count > 0)
				{
					for (int k = 0; k <= list.Count - 1; k++)
					{
						string text = ((CustomData)list[k].EntityData).EntityName;
						if (text.Length == 0)
						{
							text = "Block" + k;
						}
						Block block = new Block(text);
						Entity entity2 = buVector5.CopyEntities(list[k]);
						entity2.Color = Color.Linen;
						if (k <= ccVars.SimMachine.MachineParts.Count - 1)
						{
							int alpha = 255;
							if ((ccVars.SimMachine.MachineParts[k].Transparency >= 0) & (ccVars.SimMachine.MachineParts[k].Transparency <= 255))
							{
								alpha = ccVars.SimMachine.MachineParts[k].Transparency;
							}
							entity2.Color = Color.FromArgb(alpha, ccVars.SimMachine.MachineParts[k].Color);
						}
						entity2.ColorMethod = colorMethodType.byEntity;
						block.Entities.Add(entity2);
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(block);
					}
				}
			}
		}
		if (buEyeItems.viewportDialogs == null)
		{
			ViewportDialogsInit();
		}
		if (!AppBool.MachineMode)
		{
			if (clsItem.ModelMainPreview == null)
			{
				CreateModelProperties createModelProperties = new CreateModelProperties();
				createModelProperties.CoordinateSystemIconVisible = false;
				createModelProperties.ViewCubeIconVisible = false;
				createModelProperties.OrigineCaptionVisible = false;
				createModelProperties.ToolBorVisible = false;
				createModelProperties.BottomColor = Color.DarkGray;
				createModelProperties.MiddleColor = Color.Silver;
				createModelProperties.TopColor = Color.Gray;
				clsItem.ModelMainPreview = new Design();
				clsInit.cVector5.CreateModelControl(ref clsItem.ModelMainPreview, clsVar.UnlockKey, createModelProperties);
			}
			clsItem.ModelMainPreview.ActiveViewport.DisplayMode = displayType.Rendered;
			clsItem.ModelMainPreview.Rendered.ShadowMode = shadowType.None;
		}
		timSim.Tick += Sim_Tick;
		timSim.Interval = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimInterval;
	}

	public void DisposeAll()
	{
		for (int i = 0; i <= ccVars.Pages.Count - 1; i++)
		{
			ccVars.Pages[i].Form.viewportcad.Dispose();
		}
		if (clsFiles.modelCommon != null)
		{
			clsFiles.modelCommon.Dispose();
		}
	}

	public void cmdHorVerCut(bool isHorizontal)
	{
		if (buMarbleForms.frmHorOrVerDialog == null)
		{
			buMarbleForms.frmHorOrVerDialog = new F_MarbleHorVerCutV2();
		}
		if (buMarbleForms.frmHorOrVerDialog.pnl_viewport.Controls.Count == 2)
		{
			buMarbleForms.frmHorOrVerDialog.pnl_viewport.Controls.RemoveAt(1);
		}
		if (buMarbleForms.frmHorOrVerDialog.pnl_viewport.Controls.Count == 0)
		{
			buMarbleForms.frmHorOrVerDialog.pnl_viewport.Controls.Add(buEyeItems.viewportDialogs);
		}
		if (buMarbleCalc.varMarbleSettings.SliceListClearAfterFinished)
		{
			for (int i = 0; i <= MarbleTempVars.cutItemsHor.Length - 1; i++)
			{
				MarbleTempVars.cutItemsHor[i].Length = 0.0;
				MarbleTempVars.cutItemsHor[i].StartAngle = 0.0;
				MarbleTempVars.cutItemsHor[i].EndAngle = 0.0;
				MarbleTempVars.cutItemsHor[i].Count = 0;
			}
			for (int j = 0; j <= MarbleTempVars.cutItemsVer.Length - 1; j++)
			{
				MarbleTempVars.cutItemsVer[j].Length = 0.0;
				MarbleTempVars.cutItemsVer[j].StartAngle = 0.0;
				MarbleTempVars.cutItemsVer[j].EndAngle = 0.0;
				MarbleTempVars.cutItemsVer[j].Count = 0;
			}
		}
		if (isHorizontal)
		{
			if ((MarbleTempVars.HorizontalStartPos.C < -45.0) | (MarbleTempVars.HorizontalStartPos.C > 45.0))
			{
				MarbleTempVars.HorizontalStartPos.C = 0.0;
			}
			if (buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal <= 0.0)
			{
				buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal = 1000.0;
			}
			buMarbleForms.frmHorOrVerDialog.buGround1.Text = buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.Cutting;
		}
		else
		{
			if ((MarbleTempVars.VerticalStartPos.C < 45.0) | (MarbleTempVars.VerticalStartPos.C > 135.0))
			{
				MarbleTempVars.VerticalStartPos.C = 90.0;
			}
			if (buMarbleCalc.varMarbleRunSettings.CutLengthVertical <= 0.0)
			{
				buMarbleCalc.varMarbleRunSettings.CutLengthVertical = 1000.0;
			}
			buMarbleForms.frmHorOrVerDialog.buGround1.Text = buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.Cutting;
		}
		MarbleTempVars.isHorizontal = isHorizontal;
		ItemControlValueUpdateHorOrVerDialog(isHorizontal);
		buMarbleForms.frmHorOrVerDialog.Properties.FormCloseMode = FormCloseModeType.Invisible;
		buMarbleForms.frmHorOrVerDialog.isHorizontal = isHorizontal;
		buMarbleForms.frmHorOrVerDialog.isDialog = true;
		buMarbleForms.frmHorOrVerDialog.Init();
		if (isHorizontal)
		{
			clsInit.appMarble.activeItemType = MarbleItemType.HorizontalCut;
			buMarbleForms.frmHorOrVerDialog.spn_itemlength.Value = buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal;
		}
		else
		{
			clsInit.appMarble.activeItemType = MarbleItemType.VerticalCut;
			buMarbleForms.frmHorOrVerDialog.spn_itemlength.Value = buMarbleCalc.varMarbleRunSettings.CutLengthVertical;
		}
		if (buMarbleForms.frmHorOrVerDialog.spn_itemlength.Value <= 0.0)
		{
			buMarbleForms.frmHorOrVerDialog.spn_itemlength.Value = 1000.0;
		}
		timCommand.Enabled = true;
		buMarbleForms.frmHorOrVerDialog.ShowDialog();
		if (buMarbleForms.frmHorOrVerDialog.Properties.Result != DialogResult.OK)
		{
			clsInit.appCommand.Reset();
			return;
		}
		MarbleTempVars.isDialogItem = true;
		if (!isHorizontal)
		{
			buMarbleCalc.varMarbleRunSettings.CutLengthVertical = buMarbleForms.frmHorOrVerDialog.spn_itemlength.Value;
			MarbleTempVars.VerticalStartPos.C = buMarbleForms.frmHorOrVerDialog.spn_angle.Value;
		}
		else
		{
			buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal = buMarbleForms.frmHorOrVerDialog.spn_itemlength.Value;
			MarbleTempVars.HorizontalStartPos.C = buMarbleForms.frmHorOrVerDialog.spn_angle.Value;
		}
		doAddItemVerHorMainForm(new Point3D(), buMarbleForms.frmHorOrVerDialog.spn_angle.Value, buMarbleForms.frmHorOrVerDialog.spn_itemlength.Value);
		MarbleTempVars.isSolidMove = true;
		clsInit.appMarble.entitiesForMove.Clear();
		if (MarbleTempVars.ItemsSlice.Count > 0)
		{
			for (int k = 0; k <= MarbleTempVars.ItemsSlice.Count - 1; k++)
			{
				for (int l = 0; l <= MarbleTempVars.ItemsSlice[k].ItemEntities.SolidEntity.Count - 1; l++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(MarbleTempVars.ItemsSlice[k].ItemEntities.SolidEntity[l], ref copiedEntity);
					clsInit.appMarble.entitiesForMove.Add(copiedEntity);
				}
			}
			MoveCreatedEntity = true;
		}
		cmdOperationCommon();
	}

