	public void cmdContourMenu(bool EditorMode = false)
	{
		frmContourMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmContourMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		frmContourMenu.ItemType = MarbleItemType.Contour;
		frmContourMenu.MenuType = new marbleMenuType(buMarbleCalc.varMarbleRunSettings.selectedContour);
		frmContourMenu.MenuType.InsideMilling = buMarbleCalc.varMarbleRunSettings.InisdeMilling;
		frmContourMenu.chk_addtonesting.Check = buMarbleCalc.varMarbleRunSettings.selectedContourAddNesting;
		frmContourMenu.Init();
		if (!EditorMode)
		{
			frmContourMenu.ShowDialog();
		}
		if (!(frmContourMenu.PropertiesForm.Result == DialogResult.OK || EditorMode))
		{
			return;
		}
		SaveMarbleFile();
		buMarbleCalc.varMarbleRunSettings.selectedContourAddNesting = frmContourMenu.chk_addtonesting.Check;
		if (EditorMode)
		{
			frmContourMenu.ContourType = MarbleContourMenuType.Editor;
		}
		DirectoryInfo directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileContour);
		if (!directoryInfo.Exists)
		{
			buMarbleCalc.varMarbleRunSettings.pathFromFileContour = AppPath.Base + "\\External2DFiles\\Contour";
			directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileContour);
			if (!directoryInfo.Exists)
			{
				buMarbleCalc.varMarbleRunSettings.pathFromFileContour = AppPath.Base;
			}
		}
		buMarbleCalc.varMarbleRunSettings.selectedContour = new marbleMenuType(frmContourMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(frmContourMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.InisdeMilling = frmContourMenu.chk_insidemilling.Check;
		if (MarbleTempVars.ItemsContour != null)
		{
			MarbleTempVars.ItemsContour.Clear();
		}
		else
		{
			MarbleTempVars.ItemsContour = new List<MarbleItem>();
		}
		entitiesForContour.Clear();
		List<buEntity> list = new List<buEntity>();
		buMarbleCalc.varMarbleRunSettings.BorderEnable = false;
		if (frmContourMenu.ContourType != MarbleContourMenuType.Editor)
		{
			if (frmContourMenu.ContourType == MarbleContourMenuType.FromFile)
			{
				OpenFileDialog openFileDialog = new OpenFileDialog();
				openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileContour;
				openFileDialog.Filter = "All Drawing Files (*.Dxf,*.Dwg,*.bucadV5)|*.dxf;*.dwg;*.bucadV5;|Dxf Files (*.dxf)|*.dxf|Dwg Files (*.dwg)|*.dwg|BuCad Files (*.bucadV5)|*.bucadV5";
				openFileDialog.FilterIndex = 1;
				if (openFileDialog.ShowDialog() != DialogResult.OK)
				{
					return;
				}
				buMarbleCalc.varMarbleRunSettings.pathFromFileContour = buFile5.GetPath(openFileDialog.FileName);
				FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
				if (!fileInfo.Exists)
				{
					return;
				}
				if ((fileInfo.Extension.ToLower() == ".dxf") | (fileInfo.Extension.ToLower() == ".dwg"))
				{
					List<Entity> EntityList = new List<Entity>();
					buFile5.OpenDxfDwg(ref EntityList, fileInfo.FullName);
					for (int i = 0; i <= EntityList.Count - 1; i++)
					{
						buEntity copiedEntity = null;
						buEntity.Copy(EntityList[i], ref copiedEntity);
						list.Add(copiedEntity);
					}
				}
				if (fileInfo.Extension.ToLower() == ".bucadv5")
				{
					List<Entity> refEntities = new List<Entity>();
					clsInit.appFiles.OpenBuCadFileVer5(fileInfo.FullName, Clear: true, ref refEntities);
					for (int j = 0; j <= refEntities.Count - 1; j++)
					{
						buEntity copiedEntity2 = null;
						buEntity.Copy(refEntities[j], ref copiedEntity2);
						list.Add(copiedEntity2);
					}
				}
				clsInit.appEditor.SaveEditorFile();
			}
			if (frmContourMenu.ContourType == MarbleContourMenuType.FromList)
			{
				if (clsItem.FrmFromFile == null)
				{
					clsItem.FrmFromFile = new F_AddFromFile();
				}
				clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
				clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
				clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileContour;
				clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
				clsItem.FrmFromFile.ExtensionList.Clear();
				clsItem.FrmFromFile.ExtensionList.Add(".dxf");
				clsItem.FrmFromFile.ExtensionList.Add(".dwg");
				clsItem.FrmFromFile.ExtensionList.Add(".bucadv5");
				clsItem.FrmFromFile.MoveEntities = false;
				clsItem.FrmFromFile.Init();
				clsItem.FrmFromFile.ShowDialog();
				if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
				{
					return;
				}
				buEntityUtilities.EntityRegenDeviation = 0.05;
				buMarbleCalc.varMarbleRunSettings.pathFromFileContour = clsItem.FrmFromFile.Path;
				clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
				for (int k = 0; k <= clsItem.FrmFromFile.viewport.Entities.Count - 1; k++)
				{
					buEntity copiedEntity3 = null;
					buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[k], ref copiedEntity3);
					list.Add(copiedEntity3);
				}
				clsInit.appEditor.SaveEditorFile();
			}
			if (frmContourMenu.ContourType == MarbleContourMenuType.Digitizer)
			{
				OpenFileDialog openFileDialog2 = new OpenFileDialog();
				openFileDialog2.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileContour;
				openFileDialog2.Filter = "All Drawing Files (*.Txt,*.budigit)|*.txt;*.budigit;|Digitizer Txt Files (*.txt)|*.txt|Bu Dgitizer File (*.budigit)|*.budigit";
				openFileDialog2.FilterIndex = 1;
				if (openFileDialog2.ShowDialog() != DialogResult.OK)
				{
					return;
				}
				ArrayList StringList = new ArrayList();
				List<List<string>> CalcList = new List<List<string>>();
				buMarbleCalc.varMarbleRunSettings.pathFromFileContour = buFile5.GetPath(openFileDialog2.FileName);
				buFile5.OpenFromFile(openFileDialog2.FileName, ref StringList);
				buStatics.ListToSpecificList("<Contour>", "</Contour>", AddStartEndKey: true, StringList, ref CalcList);
				for (int l = 0; l <= CalcList.Count - 1; l++)
				{
					List<string> CalcList2 = new List<string>();
					buStatics.ListToSpecificList("<Outer>", "</Outer>", AddStartEndKey: false, CalcList[l], ref CalcList2);
					List<Point3D> list2 = new List<Point3D>();
					for (int m = 0; m <= CalcList2.Count - 1; m++)
					{
						string[] array = CalcList2[m].Split(';');
						if (array.Length >= 2)
						{
							Point3D item = new Point3D(Convert.ToDouble(array[0]), Convert.ToDouble(array[1]));
							list2.Add(item);
						}
					}
					if (list2.Count >= 2)
					{
						List<List<Point3D>> PLFixed = new List<List<Point3D>>();
						clsInit.cVector5.FixPoints(list2, ref PLFixed);
						if (clsItem.frmEditor == null)
						{
							clsItem.frmEditor = new F_Editor();
						}
						clsVar.varEditorRuntimeSet.isSketchMode = false;
						clsVar.varEditorRuntimeSet.isSewingMode = false;
						clsItem.frmEditor = new F_Editor();
						clsItem.frmEditor.entitiesExisting.Clear();
						for (int n = 0; n <= PLFixed.Count - 1; n++)
						{
							LinearPath item2 = new LinearPath(PLFixed[n]);
							clsItem.frmEditor.entitiesExisting.Add(item2);
						}
						clsItem.frmEditor.OpenFileExtension.Clear();
						clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
						clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
						clsItem.frmEditor.Init();
						clsItem.frmEditor.ShowDialog(clsItem.FrmMain);
					}
				}
				for (int num = 0; num <= clsItem.frmEditor.viewport.Entities.Count - 1; num++)
				{
					buEntity copiedEntity4 = null;
					buEntity.Copy(clsItem.frmEditor.viewport.Entities[num], ref copiedEntity4);
					if ((copiedEntity4 != null) & (clsItem.frmEditor.viewport.Entities[num] is ICurve))
					{
						list.Add(copiedEntity4);
					}
				}
				clsInit.appEditor.SaveEditorFile();
			}
			cmdContourCommon(list);
		}
		else
		{
			if (clsItem.frmEditorV2 == null)
			{
				clsItem.frmEditorV2 = new F_EditorV2();
			}
			clsItem.frmEditorV2.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsVar.varEditorRuntimeSet.isSketchMode = true;
			clsItem.frmEditorV2.Init();
			clsItem.frmEditorV2.ShowDialog(clsItem.FrmMain);
			clsInit.appEditor2.SaveEditorFile(AppPath.MachineSettings + "\\Editor.prm");
		}
	}

	public void cmdLibraryMenu()
	{
		frmLibraryMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmLibraryMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		frmLibraryMenu.ItemType = MarbleItemType.Contour;
		frmLibraryMenu.MenuType = new marbleMenuType(buMarbleCalc.varMarbleRunSettings.selectedLibrary);
		frmLibraryMenu.chk_addtonesting.Check = buMarbleCalc.varMarbleRunSettings.selectedLibraryAddNesting;
		frmLibraryMenu.MenuType.InsideMilling = buMarbleCalc.varMarbleRunSettings.InisdeMilling;
		frmLibraryMenu.Init();
		frmLibraryMenu.ShowDialog();
		if (frmLibraryMenu.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		SaveMarbleFile();
		DirectoryInfo directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileLibray);
		if (!directoryInfo.Exists)
		{
			buMarbleCalc.varMarbleRunSettings.pathFromFileLibray = AppPath.Base + "\\Library";
			directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileLibray);
			if (!directoryInfo.Exists)
			{
				buMarbleCalc.varMarbleRunSettings.pathFromFileLibray = AppPath.Base;
			}
		}
		buMarbleCalc.varMarbleRunSettings.selectedLibraryAddNesting = frmLibraryMenu.chk_addtonesting.Check;
		buMarbleCalc.varMarbleRunSettings.selectedLibrary = new marbleMenuType(frmLibraryMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(frmLibraryMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.InisdeMilling = frmLibraryMenu.chk_insidemilling.Check;
		if (MarbleTempVars.ItemsContour != null)
		{
			MarbleTempVars.ItemsContour.Clear();
		}
		else
		{
			MarbleTempVars.ItemsContour = new List<MarbleItem>();
		}
		entitiesForContour.Clear();
		List<buEntity> copyEntities = new List<buEntity>();
		if (frmLibraryMenu.LibraryType == MarbleLibraryMenuType.Editor)
		{
			if (clsItem.frmEditor == null)
			{
				clsItem.frmEditor = new F_Editor();
			}
			clsVar.varEditorRuntimeSet.isSketchMode = true;
			clsVar.varEditorRuntimeSet.isSewingMode = false;
			clsItem.frmEditor = new F_Editor();
			clsItem.frmEditor.OpenFileExtension.Clear();
			clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
			clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.frmEditor.Init();
			clsItem.frmEditor.ShowDialog(clsItem.FrmMain);
			for (int i = 0; i <= clsItem.frmEditor.viewport.Entities.Count - 1; i++)
			{
				if (clsItem.frmEditor.viewport.Entities[i] is ICurve)
				{
					buEntity copiedEntity = null;
					buEntity.Copy(clsItem.frmEditor.viewport.Entities[i], ref copiedEntity);
					if (((copiedEntity != null) & (clsItem.frmEditor.viewport.Entities[i] is ICurve)) && clsItem.frmEditor.viewport.Entities[i].GetType() != typeof(devDept.Eyeshot.Entities.Point))
					{
						copyEntities.Add(copiedEntity);
					}
				}
			}
		}
		if (frmLibraryMenu.LibraryType == MarbleLibraryMenuType.FromList)
		{
			clsVar.varLibrary.pathLibrary = buMarbleCalc.varMarbleRunSettings.pathFromFileLibray;
			cmdLibDraw();
			if (FrmLibraryDraw.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileLibray = clsVar.varLibrary.pathLibrary;
			EntitiesCopySettings entitiesCopySettings = new EntitiesCopySettings(addPoint: false, addDimension: false, addCurve: true, addCircular: true, addCompositeCurve: true, addEllipse: true, compositeCurveToEntities: true, 0.05, 0.1);
			entitiesCopySettings.ForcePlaneXY = true;
			clsInit.cVector5.CopyEntitiesToEntities(FrmLibraryDraw.LibraryEntities, ref copyEntities, entitiesCopySettings);
			for (int j = 0; j <= copyEntities.Count - 1; j++)
			{
				if (copyEntities[j] is buArc)
				{
					buArc buArc2 = copyEntities[j] as buArc;
					buArc2.StartAngle = clsInit.cVector5.PointAngle(buArc2.StartPoint, buArc2.Center);
					buArc2.EndAngle = clsInit.cVector5.PointAngle(buArc2.EndPoint, buArc2.Center);
				}
			}
		}
		cmdContourCommon(copyEntities);
		copyEntities.Clear();
	}

