	public void cmdContourCommon(List<buEntity> EL)
	{
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
		if (EL.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		clsInit.cVector5.RemoveDublicatedEntities(ref EL);
		if (!buMarbleCalc.varMarbleRunSettings.selectedType.Rotate90Minus)
		{
			if (!buMarbleCalc.varMarbleRunSettings.selectedType.Rotate180Minus)
			{
				if (!buMarbleCalc.varMarbleRunSettings.selectedType.Rotate90Plus)
				{
					if (buMarbleCalc.varMarbleRunSettings.selectedType.Rotate180Plus)
					{
						clsInit.cVector5.Rotate(new Point3D(), 180.0, Vector3D.AxisZ, ref EL);
					}
				}
				else
				{
					clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisZ, ref EL);
				}
			}
			else
			{
				clsInit.cVector5.Rotate(new Point3D(), -180.0, Vector3D.AxisZ, ref EL);
			}
		}
		else
		{
			clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisZ, ref EL);
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedType.MirrorX)
		{
			clsInit.cVector5.Mirror(new Point3D(), new Point3D(100.0, 0.0, 0.0), Plane.XY, ref EL);
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedType.MirrorY)
		{
			clsInit.cVector5.Mirror(new Point3D(), new Point3D(0.0, 100.0, 0.0), Plane.XY, ref EL);
		}
		entityToolType entityToolType2 = entityToolType.Saw;
		bool isMilling = false;
		bool isMillingHead = false;
		bool isWaterJet = false;
		if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.Milling)
		{
			entityToolType2 = entityToolType.Milling;
			isMilling = true;
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.MillingHead)
		{
			entityToolType2 = entityToolType.MillingHead;
			isMillingHead = true;
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.WaterJet)
		{
			entityToolType2 = entityToolType.WaterJet;
			isWaterJet = true;
		}
		if (entityToolType2 == entityToolType.Saw)
		{
			clsInit.cMarble.AnalyzeImportEntities(ref EL);
		}
		entitiesGroupForContour.Clear();
		entitiesGroupForContour = new List<buEntitiesGroup>();
		entitiesGroupForRefEntities.Clear();
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(EL, ref MinPoint, ref MidPoint, ref MaxPoint);
		if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.BottomLeft)
		{
			if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.BottomCenter)
			{
				if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.BottomRight)
				{
					if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.MiddleLeft)
					{
						if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.MiddleCenter)
						{
							if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.MiddleRight)
							{
								if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.TopLeft)
								{
									if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.TopCenter)
									{
										if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.TopRight)
										{
											clsInit.cVector5.Move(0.0 - MaxPoint.X, 0.0 - MaxPoint.Y, 0.0 - MinPoint.Z, ref EL);
										}
									}
									else
									{
										clsInit.cVector5.Move(0.0 - MidPoint.X, 0.0 - MaxPoint.Y, 0.0 - MinPoint.Z, ref EL);
									}
								}
								else
								{
									clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MaxPoint.Y, 0.0 - MinPoint.Z, ref EL);
								}
							}
							else
							{
								clsInit.cVector5.Move(0.0 - MaxPoint.X, 0.0 - MidPoint.Y, 0.0 - MinPoint.Z, ref EL);
							}
						}
						else
						{
							clsInit.cVector5.Move(0.0 - MidPoint.X, 0.0 - MidPoint.Y, 0.0 - MinPoint.Z, ref EL);
						}
					}
					else
					{
						clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MidPoint.Y, 0.0 - MinPoint.Z, ref EL);
					}
				}
				else
				{
					clsInit.cVector5.Move(0.0 - MaxPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref EL);
				}
			}
			else
			{
				clsInit.cVector5.Move(0.0 - MidPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref EL);
			}
		}
		else
		{
			clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref EL);
		}
		entitiesGroupForContour.Clear();
		if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.Saw)
		{
			clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), EL, Plane.XY, ref entitiesGroupForContour, new FindEntitiesGroupSettings(SortingIntersectionRulesType.LowerIndex, SortingNextGroupFindRulesType.ClosestLength, 0.05, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection, buMarbleCalc.varOperation.settingMarbleCam.ContourInsideDirection));
		}
		else if (buMarbleCalc.varMarbleSettings.OutsideEntityIsReferance)
		{
			List<buEntitiesGroup> Groups = new List<buEntitiesGroup>();
			clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), EL, Plane.XY, ref Groups, new FindEntitiesGroupSettings(SortingIntersectionRulesType.LowerIndex, SortingNextGroupFindRulesType.ClosestLength, 0.05, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection, buMarbleCalc.varOperation.settingMarbleCam.ContourInsideDirection));
			entitiesGroupForContour.Clear();
			for (int i = 0; i <= Groups.Count - 1; i++)
			{
				if (Groups[i].Inside != null)
				{
					for (int j = 0; j <= Groups[i].Inside.Count - 1; j++)
					{
						buEntitiesGroup buEntitiesGroup2 = new buEntitiesGroup();
						buEntitiesGroup2.Outside = new buEntityList(Groups[i].Inside[j]);
						entitiesGroupForContour.Add(buEntitiesGroup2);
					}
				}
				if (Groups[i].Outside.Entities.Count > 0)
				{
					buEntitiesGroup buEntitiesGroup3 = new buEntitiesGroup();
					buEntitiesGroup3.Outside = new buEntityList(Groups[i].Outside);
					entitiesGroupForRefEntities.Add(buEntitiesGroup3);
				}
			}
		}
		else
		{
			clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), EL, Plane.XY, ref entitiesGroupForContour, new FindEntitiesGroupSettings(SortingIntersectionRulesType.LowerIndex, SortingNextGroupFindRulesType.ClosestLength, 0.05, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection, buMarbleCalc.varOperation.settingMarbleCam.ContourInsideDirection));
		}
		if (entitiesGroupForContour.Count > 0)
		{
			buMarbleCalc.CountertopRefEntGroup = new buEntitiesGroup(entitiesGroupForContour[0]);
		}
		for (int k = 0; k <= entitiesGroupForContour.Count - 1; k++)
		{
			entitiesGroupForContour[k].Outside.Marble = new marbleEntityData();
			clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool, ref entitiesGroupForContour[k].Outside.Marble);
			entitiesGroupForContour[k].Outside.ToolType = entityToolType2;
			if (entitiesGroupForContour[k].Outside.Entities.Count > 0 && buMarbleCalc.varMarbleRunSettings.InisdeMilling)
			{
				entitiesGroupForContour[k].Outside.ToolType = entityToolType.Saw;
			}
			if (entitiesGroupForContour[k].Inside != null)
			{
				for (int l = 0; l <= entitiesGroupForContour[k].Inside.Count - 1; l++)
				{
					entitiesGroupForContour[k].Inside[l].ToolType = entityToolType2;
					if (buMarbleCalc.varMarbleRunSettings.InisdeMilling)
					{
						entitiesGroupForContour[k].Inside[l].ToolType = entityToolType.Milling;
					}
					entitiesGroupForContour[k].Inside[l].Marble = new marbleEntityData();
					clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool, ref entitiesGroupForContour[k].Inside[l].Marble);
				}
			}
			if (entitiesGroupForContour[k].OpenEntities == null)
			{
				continue;
			}
			for (int m = 0; m <= entitiesGroupForContour[k].OpenEntities.Count - 1; m++)
			{
				entitiesGroupForContour[k].OpenEntities[m].ToolType = entityToolType2;
				if (buMarbleCalc.varMarbleRunSettings.InisdeMilling)
				{
					entitiesGroupForContour[k].OpenEntities[m].ToolType = entityToolType.Milling;
				}
				entitiesGroupForContour[k].OpenEntities[m].Marble = new marbleEntityData();
				clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool, ref entitiesGroupForContour[k].OpenEntities[m].Marble);
			}
		}
		if (!buMarbleCalc.varMarbleRunSettings.selectedContourAddNesting)
		{
			clsInit.appMarble.activeItemType = MarbleItemType.Contour;
			doAddItemShapeContour(new Point3D(), isShape: false, isFinished: false, isText: false, isMilling, isMillingHead, isWaterJet, isCamCalc: false, -1);
			clsInit.appMarble.entitiesForMove.Clear();
			if (MarbleTempVars.ItemsContour.Count > 0)
			{
				for (int n = 0; n <= EL.Count - 1; n++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(EL[n], ref copiedEntity);
					clsInit.appMarble.entitiesForMove.Add(copiedEntity);
				}
				for (int num = 0; num <= MarbleTempVars.ItemsContour.Count - 1; num++)
				{
					if (MarbleTempVars.ItemsContour[num].ItemEntities.SolidEntity != null)
					{
						for (int num2 = 0; num2 <= MarbleTempVars.ItemsContour[num].ItemEntities.SolidEntity.Count - 1; num2++)
						{
							Entity copiedEntity2 = null;
							buEntity.Copy(MarbleTempVars.ItemsContour[num].ItemEntities.SolidEntity[num2], ref copiedEntity2);
							clsInit.appMarble.entitiesForMove.Add(copiedEntity2);
						}
					}
				}
				MoveCreatedEntity = true;
				if (clsItem.pnlSettings != null)
				{
					Size panelSize = new Size(clsItem.pnlSettings.Size.Width, clsItem.pnlSettings.Size.Height);
					if (clsItem.pnlSettings.Parent != null && panelSize.Width < clsItem.pnlSettings.Parent.Size.Width - 10)
					{
						panelSize.Width = clsItem.pnlSettings.Parent.Size.Width - 6;
					}
					OperationControlSizeAdjustment(panelSize, buMarbleCalc.varOperation);
					clsItem.pnlSettings.Visible = true;
				}
			}
			cmdOperationCommon();
		}
		else if (clsInit.appNesting != null)
		{
			clsInit.appNesting.doAddShapePart(entitiesGroupForContour);
		}
	}

