		if (frmShapeMenu.ShapeType == MarbleShapeTypes.Arc)
		{
			frmShape.buTab_shape.SelectedIndex = 11;
		}
		if (frmShapeMenu.ShapeType == MarbleShapeTypes.ShipNose)
		{
			frmShape.buTab_shape.SelectedIndex = 12;
		}
		if (frmShapeMenu.ShapeType == MarbleShapeTypes.EllipsePie)
		{
			frmShape.buTab_shape.SelectedIndex = 13;
		}
		frmShape.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmShape.Init();
		frmShape.ShowDialog();
		if (frmShape.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varMarbleRunSettings.BorderEnable = false;
		clsInit.appMarble.activeItemType = MarbleItemType.Shape;
		Entity solidEntity = null;
		ICurve wireEntity = null;
		clsInit.cMarble.CreateShape(clsInit.appMarble.ShapeType, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref solidEntity, ref wireEntity);
		if (!buMarbleCalc.varMarbleRunSettings.selectedType.Rotate90Minus)
		{
			if (!buMarbleCalc.varMarbleRunSettings.selectedType.Rotate180Minus)
			{
				if (!buMarbleCalc.varMarbleRunSettings.selectedType.Rotate90Plus)
				{
					if (buMarbleCalc.varMarbleRunSettings.selectedType.Rotate180Plus)
					{
						Entity refEntity = wireEntity as Entity;
						clsInit.cVector5.Rotate(new Point3D(), 180.0, Vector3D.AxisZ, ref refEntity);
					}
				}
				else
				{
					Entity refEntity2 = wireEntity as Entity;
					clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisZ, ref refEntity2);
				}
			}
			else
			{
				Entity refEntity3 = wireEntity as Entity;
				clsInit.cVector5.Rotate(new Point3D(), -180.0, Vector3D.AxisZ, ref refEntity3);
			}
		}
		else
		{
			Entity refEntity4 = wireEntity as Entity;
			clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisZ, ref refEntity4);
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedType.MirrorX)
		{
			Entity refEntity5 = wireEntity as Entity;
			clsInit.cVector5.Mirror(new Point3D(), new Point3D(100.0, 0.0, 0.0), Plane.XY, ref refEntity5);
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedType.MirrorY)
		{
			Entity refEntity6 = wireEntity as Entity;
			clsInit.cVector5.Mirror(new Point3D(), new Point3D(0.0, 100.0, 0.0), Plane.XY, ref refEntity6);
		}
		if (!buMarbleCalc.varMarbleRunSettings.selectedDrawingAddNesting)
		{
			int num = 1;
			int num2 = 1;
			double num3 = buMarbleCalc.activeToolSaw.Geometry.Thickness;
			if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.Milling)
			{
				if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.MillingHead)
				{
					if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.WaterJet)
					{
						num3 = buMarbleCalc.activeToolWaterjet.Geometry.Diameter;
					}
				}
				else
				{
					num3 = buMarbleCalc.activeToolMillingHead.Geometry.Diameter;
				}
			}
			else
			{
				num3 = buMarbleCalc.activeToolMilling.Geometry.Diameter;
			}
			if (buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayEnable)
			{
				num = (int)buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayXCount;
				num2 = (int)buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayYCount;
			}
			Point3D MinPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			clsInit.cVector5.BoxSizeCalculate((Entity)wireEntity, ref MinPoint, ref MidPoint, ref MaxPoint);
			if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.BottomLeft)
			{
				if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.BottomCenter)
				{
					if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.BottomRight)
					{
						if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.MiddleLeft)
						{
							if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.MiddleCenter)
							{
								if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.MiddleRight)
								{
									if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.TopLeft)
									{
										if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment != ObjectAlignment.TopCenter)
										{
											if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.TopRight)
											{
												Entity refEntities = wireEntity as Entity;
												clsInit.cVector5.Move(0.0 - MaxPoint.X, 0.0 - MaxPoint.Y, 0.0 - MinPoint.Z, ref refEntities);
											}
										}
										else
										{
											Entity refEntities2 = wireEntity as Entity;
											clsInit.cVector5.Move(0.0 - MidPoint.X, 0.0 - MaxPoint.Y, 0.0 - MinPoint.Z, ref refEntities2);
										}
									}
									else
									{
										Entity refEntities3 = wireEntity as Entity;
										clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MaxPoint.Y, 0.0 - MinPoint.Z, ref refEntities3);
									}
								}
								else
								{
									Entity refEntities4 = wireEntity as Entity;
									clsInit.cVector5.Move(0.0 - MaxPoint.X, 0.0 - MidPoint.Y, 0.0 - MinPoint.Z, ref refEntities4);
								}
							}
							else
							{
								Entity refEntities5 = wireEntity as Entity;
								clsInit.cVector5.Move(0.0 - MidPoint.X, 0.0 - MidPoint.Y, 0.0 - MinPoint.Z, ref refEntities5);
							}
						}
						else
						{
							Entity refEntities6 = wireEntity as Entity;
							clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MidPoint.Y, 0.0 - MinPoint.Z, ref refEntities6);
						}
					}
					else
					{
						Entity refEntities7 = wireEntity as Entity;
						clsInit.cVector5.Move(0.0 - MaxPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref refEntities7);
					}
				}
				else
				{
					Entity refEntities8 = wireEntity as Entity;
					clsInit.cVector5.Move(0.0 - MidPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref refEntities8);
				}
			}
			else
			{
				Entity refEntities9 = wireEntity as Entity;
				clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref refEntities9);
			}
			double num4 = MaxPoint.X - MinPoint.X + num3 + buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayXDistance;
			double num5 = MaxPoint.Y - MinPoint.Y + num3 + buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayYDistance;
			for (int i = 0; i <= num - 1; i++)
			{
				for (int j = 0; j <= num2 - 1; j++)
				{
					double dx = (double)i * num4;
					double dy = (double)j * num5;
					Entity copiedEntity = null;
					buEntity.Copy((Entity)wireEntity, ref copiedEntity);
					copiedEntity.Translate(dx, dy);
					clsInit.appMarble.entitiesForMove.Add(copiedEntity);
				}
			}
			clsInit.appMarble.activeItemType = MarbleItemType.Shape;
			clsInit.appMarble.MoveCreatedEntity = true;
			cmdOperationCommon();
		}
		else if (clsInit.appNesting != null)
		{
			entitiesGroupForContour.Clear();
			buEntitiesGroup buEntitiesGroup2 = new buEntitiesGroup();
			buEntity copiedEntity2 = null;
			buEntity.Copy((Entity)wireEntity, ref copiedEntity2);
			buEntitiesGroup2.Outside.Entities.Add(copiedEntity2);
			buEntitiesGroup2.Outside.Points = new List<Point3D>();
			clsInit.cVector5.EntitiesToPointsWithCamDirection(buEntitiesGroup2.Outside.Entities, ref buEntitiesGroup2.Outside.Points);
			entitiesGroupForContour.Add(buEntitiesGroup2);
			clsInit.appNesting.doAddShapePart(entitiesGroupForContour);
		}
	}

