	public void cmdEasyDrawing(bool EditorMode = false)
	{
		if (buMarbleForms.frmEasyDraw == null)
		{
			buMarbleForms.frmEasyDraw = new F_MarbleEasyDraw();
		}
		buMarbleForms.frmEasyDraw.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		if (buMarbleForms.frmEasyDraw.pnl_viewport.Controls.Count == 0)
		{
			buMarbleForms.frmEasyDraw.pnl_viewport.Controls.Add(buEyeItems.viewportDialogs);
		}
		buEyeItems.viewportDialogs.Entities.Clear();
		buMarbleForms.frmEasyDraw.Init();
		buMarbleForms.frmEasyDraw.ShowDialog();
		if (buMarbleForms.frmEasyDraw.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		SaveMarbleFile();
		List<buEntity> list = new List<buEntity>();
		for (int i = 0; i <= buEyeItems.viewportDialogs.Entities.Count - 1; i++)
		{
			if (buEyeItems.viewportDialogs.Entities[i] is ICurve)
			{
				buEntity copiedEntity = null;
				buEntity.Copy(buEyeItems.viewportDialogs.Entities[i], ref copiedEntity);
				list.Add(copiedEntity);
			}
		}
		buMarbleForms.frmEasyDraw.pnl_viewport.Controls.Clear();
		SaveMarbleFile();
		if (list.Count > 0)
		{
			cmdContourCommon(list);
		}
	}

	public void cmdProfileMenu()
	{
		frmProfileMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmProfileMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		if (buMarbleCalc.varMarbleRunSettings.selectedProfile.selectedTool == MarbleToolType.WaterJet)
		{
			buMarbleCalc.varMarbleRunSettings.selectedProfile.selectedTool = MarbleToolType.Saw;
		}
		frmProfileMenu.MenuType = new marbleMenuType(buMarbleCalc.varMarbleRunSettings.selectedProfile);
		frmProfileMenu.ItemType = MarbleItemType.Profiling;
		frmProfileMenu.Init();
		frmProfileMenu.ShowDialog();
		if (frmProfileMenu.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		DirectoryInfo directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileProfiling);
		if (!directoryInfo.Exists)
		{
			buMarbleCalc.varMarbleRunSettings.pathFromFileProfiling = AppPath.Base + "\\External2DFiles\\Profile";
			directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileProfiling);
			if (!directoryInfo.Exists)
			{
				buMarbleCalc.varMarbleRunSettings.pathFromFileProfiling = AppPath.Base;
			}
		}
		buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(frmProfileMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.selectedProfile = new marbleMenuType(frmProfileMenu.MenuType);
		if (MarbleTempVars.ItemsProfile != null)
		{
			MarbleTempVars.ItemsProfile.Clear();
		}
		else
		{
			MarbleTempVars.ItemsProfile = new List<MarbleItem>();
		}
		entitiesForProfiling.Clear();
		List<buEntity> refEntities = new List<buEntity>();
		if (frmProfileMenu.ProfileType == MarbleProfileMenuType.Editor)
		{
			if (clsItem.frmEditor == null)
			{
				clsItem.frmEditor = new F_Editor();
			}
			clsVar.varEditorRuntimeSet.isSketchMode = false;
			clsVar.varEditorRuntimeSet.isSewingMode = false;
			clsItem.frmEditor = new F_Editor();
			clsItem.frmEditor.OpenFileExtension.Clear();
			clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
			clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.frmEditor.Init();
			clsItem.frmEditor.ShowDialog(clsItem.FrmMain);
			for (int i = 0; i <= clsItem.frmEditor.viewport.Entities.Count - 1; i++)
			{
				buEntity copiedEntity = null;
				buEntity.Copy(clsItem.frmEditor.viewport.Entities[i], ref copiedEntity);
				if ((copiedEntity != null) & (clsItem.frmEditor.viewport.Entities[i] is ICurve))
				{
					refEntities.Add(copiedEntity);
				}
			}
		}
		if (frmProfileMenu.ProfileType == MarbleProfileMenuType.FromFile)
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileProfiling;
			openFileDialog.Filter = "All Drawing Files (*.Dxf,*.Dwg,*.bucadV5)|*.dxf;*.dwg;*.bucadV5;|Dxf Files (*.dxf)|*.dxf|Dwg Files (*.dwg)|*.dwg|BuCad Files (*.bucadV5)|*.bucadV5";
			openFileDialog.FilterIndex = 1;
			if (openFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileProfiling = buFile5.GetPath(openFileDialog.FileName);
			FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
			if (!fileInfo.Exists)
			{
				return;
			}
			if ((fileInfo.Extension.ToLower() == ".dxf") | (fileInfo.Extension.ToLower() == ".dwg"))
			{
				List<Entity> EntityList = new List<Entity>();
				buFile5.OpenDxfDwg(ref EntityList, fileInfo.FullName);
				for (int j = 0; j <= EntityList.Count - 1; j++)
				{
					buEntity copiedEntity2 = null;
					buEntity.Copy(EntityList[j], ref copiedEntity2);
					refEntities.Add(copiedEntity2);
				}
			}
			if (fileInfo.Extension.ToLower() == ".bucadv5")
			{
				List<Entity> refEntities2 = new List<Entity>();
				clsInit.appFiles.OpenBuCadFileVer5(fileInfo.FullName, Clear: true, ref refEntities2);
				for (int k = 0; k <= refEntities2.Count - 1; k++)
				{
					buEntity copiedEntity3 = null;
					buEntity.Copy(refEntities2[k], ref copiedEntity3);
					refEntities.Add(copiedEntity3);
				}
			}
			clsInit.appEditor.SaveEditorFile();
		}
		if (frmProfileMenu.ProfileType == MarbleProfileMenuType.FromList)
		{
			if (clsItem.FrmFromFile == null)
			{
				clsItem.FrmFromFile = new F_AddFromFile();
			}
			clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileProfiling;
			clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
			clsItem.FrmFromFile.ExtensionList.Clear();
			clsItem.FrmFromFile.ExtensionList.Add(".dxf");
			clsItem.FrmFromFile.ExtensionList.Add(".dwg");
			clsItem.FrmFromFile.ExtensionList.Add(".bucad5");
			clsItem.FrmFromFile.MoveEntities = false;
			clsItem.FrmFromFile.Init();
			clsItem.FrmFromFile.ShowDialog();
			if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileProfiling = clsItem.FrmFromFile.Path;
			clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
			for (int l = 0; l <= clsItem.FrmFromFile.viewport.Entities.Count - 1; l++)
			{
				buEntity copiedEntity4 = null;
				buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[l], ref copiedEntity4);
				refEntities.Add(copiedEntity4);
			}
			clsInit.appEditor.SaveEditorFile();
		}
		if (refEntities.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		frmProfile.Properties.FormPosition = FormStartPosition.CenterScreen;
		frmProfile.Properties.FormCloseMode = FormCloseModeType.Invisible;
		frmProfile.varProfileCut = new marbleProfileCutPars(buMarbleCalc.varOperation.settingProfileCut);
		frmProfile.CamVisible = false;
		frmProfile.Init();
		frmProfile.ShowDialog();
		if (frmProfile.Properties.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varOperation.settingProfileCut = new marbleProfileCutPars(frmProfile.varProfileCut);
		buMarbleCalc.varOperation.settingProfileCut.RoughDevideLen = buMarbleCalc.activeToolSaw.Geometry.Thickness;
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
		clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref refEntities);
		SortbuSettings sortbuSettings = new SortbuSettings();
		sortbuSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
		new List<buEntity>();
		Point3D point3D = null;
		Point3D pntEnd = new Point3D();
		point3D = ((refEntities[0].StartPoint.X < refEntities[0].EndPoint.X) ? buVector5.ToPoint3D(refEntities[0].StartPoint) : ((refEntities[0].StartPoint.X > refEntities[0].EndPoint.X) ? buVector5.ToPoint3D(refEntities[0].EndPoint) : buVector5.ToPoint3D(refEntities[0].StartPoint)));
		clsInit.cVector5.SortEntitiesByRefPoint(point3D, ref refEntities, sortbuSettings, ref entitiesForProfiling);
		clsInit.cVector5.Move(0.0, buMarbleCalc.varOperation.settingProfileCut.BaseHeight, 0.0, ref entitiesForProfiling);
		clsInit.cVector5.GetEntityStartPointByCamDirection(entitiesForProfiling[0], ref point3D);
		clsInit.cVector5.GetEntityEndPointByCamDirection(entitiesForProfiling[entitiesForProfiling.Count - 1], ref pntEnd);
		if (!clsInit.cVector5.isEntitiesClosed(entitiesForProfiling))
		{
			if (Math.Round(point3D.Y, 5) > 0.0)
			{
				buLine item = new buLine(new Point3D(point3D.X, 0.0, point3D.Z), point3D);
				entitiesForProfiling.Insert(0, item);
			}
			if (Math.Round(pntEnd.Y, 5) > 0.0)
			{
				buLine item2 = new buLine(pntEnd, new Point3D(pntEnd.X, 0.0, pntEnd.Z));
				entitiesForProfiling.Add(item2);
			}
		}
		doAddItemProfiling(new Point3D());
		clsInit.appMarble.activeItemType = MarbleItemType.Profiling;
		cmdOperationCommon();
		clsInit.appMarble.entitiesForMove.Clear();
		if (MarbleTempVars.ItemsProfile.Count <= 0)
		{
			return;
		}
		for (int m = 0; m <= MarbleTempVars.ItemsProfile.Count - 1; m++)
		{
			for (int n = 0; n <= MarbleTempVars.ItemsProfile[m].ItemEntities.SolidEntity.Count - 1; n++)
			{
				Entity copiedEntity5 = null;
				buEntity.Copy(MarbleTempVars.ItemsProfile[m].ItemEntities.SolidEntity[n], ref copiedEntity5);
				if (copiedEntity5.BoxMin == null)
				{
					copiedEntity5.Regen(buMarbleCalc.varMarbleDrawSettings.SolidOnlineDrawDeviation);
				}
				Entity rectangleEntity = null;
				clsInit.cVector5.DrawRectangle(copiedEntity5.BoxMin, copiedEntity5.BoxMax.X - copiedEntity5.BoxMin.X, copiedEntity5.BoxMax.Y - copiedEntity5.BoxMin.Y, Plane.XY, ref rectangleEntity);
				rectangleEntity.Translate(0.0, 0.0, buMarbleCalc.varMarbleDrawSettings.WireframeOnlineDrawZOffset);
				rectangleEntity.Regen(0.1);
				clsInit.appMarble.entitiesForMove.Add(rectangleEntity);
			}
		}
		MoveCreatedEntity = true;
	}

