				refEntities.Add(copiedEntity4);
			}
			clsInit.appEditor.SaveEditorFile();
		}
		if (refEntities.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		frmProfileCurve.Properties.FormPosition = FormStartPosition.CenterScreen;
		frmProfileCurve.Properties.FormCloseMode = FormCloseModeType.Invisible;
