		frmProfileCurve.ShowDialog();
		if (frmProfileCurve.Properties.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varOperation.settingProfileCurveCut = new marbleProfileCurveCutPars(frmProfileCurve.varProfileCurveCut);
		buMarbleCalc.varOperation.settingProfileCurveCut.RoughStepover = buMarbleCalc.activeToolSaw.Geometry.Thickness;
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
		clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref refEntities);
		SortbuSettings sortbuSettings = new SortbuSettings();
		sortbuSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
		new List<buEntity>();
		Point3D point3D = null;
		Point3D pntEnd = new Point3D();
		point3D = ((refEntities[0].StartPoint.X < refEntities[0].EndPoint.X) ? buVector5.ToPoint3D(refEntities[0].StartPoint) : ((refEntities[0].StartPoint.X > refEntities[0].EndPoint.X) ? buVector5.ToPoint3D(refEntities[0].EndPoint) : buVector5.ToPoint3D(refEntities[0].StartPoint)));
		clsInit.cVector5.SortEntitiesByRefPoint(point3D, ref refEntities, sortbuSettings, ref entitiesForProfiling);
		clsInit.cVector5.Move(0.0, buMarbleCalc.varOperation.settingProfileCurveCut.BaseHeight, 0.0, ref entitiesForProfiling);
		clsInit.cVector5.GetEntityStartPointByCamDirection(entitiesForProfiling[0], ref point3D);
		clsInit.cVector5.GetEntityEndPointByCamDirection(entitiesForProfiling[entitiesForProfiling.Count - 1], ref pntEnd);
		if (!clsInit.cVector5.isEntitiesClosed(entitiesForProfiling))
		{
			if (point3D.Y > 0.0)
			{
				buLine item = new buLine(new Point3D(point3D.X, 0.0, point3D.Z), point3D);
				entitiesForProfiling.Insert(0, item);
			}
			if (pntEnd.Y > 0.0)
			{
				buLine item2 = new buLine(pntEnd, new Point3D(pntEnd.X, 0.0, pntEnd.Z));
				entitiesForProfiling.Add(item2);
			}
		}
		clsInit.appMarble.activeItemType = MarbleItemType.ProfileCurve;
		doAddItemProfileCurve(new Point3D());
		cmdOperationCommon();
		clsInit.appMarble.entitiesForMove.Clear();
		if (MarbleTempVars.ItemsProfile.Count <= 0)
		{
			return;
		}
		for (int m = 0; m <= MarbleTempVars.ItemsProfile.Count - 1; m++)
		{
			for (int n = 0; n <= MarbleTempVars.ItemsProfile[m].ItemEntities.SolidEntity.Count - 1; n++)
			{
				Entity copiedEntity5 = null;
				buEntity.Copy(MarbleTempVars.ItemsProfile[m].ItemEntities.SolidEntity[n], ref copiedEntity5);
				if (copiedEntity5.BoxMin == null)
				{
					copiedEntity5.Regen(buMarbleCalc.varMarbleDrawSettings.SolidOnlineDrawDeviation);
				}
				Entity rectangleEntity = null;
				clsInit.cVector5.DrawRectangle(copiedEntity5.BoxMin, copiedEntity5.BoxMax.X - copiedEntity5.BoxMin.X, copiedEntity5.BoxMax.Y - copiedEntity5.BoxMin.Y, Plane.XY, ref rectangleEntity);
				rectangleEntity.Translate(0.0 - copiedEntity5.BoxMin.X, 0.0 - copiedEntity5.BoxMin.Y, buMarbleCalc.varMarbleDrawSettings.WireframeOnlineDrawZOffset);
				clsInit.appMarble.entitiesForMove.Add(rectangleEntity);
			}
		}
		MoveCreatedEntity = true;
	}

