	public void cmdCavityMenu()
	{
		if (buMarbleForms.frmCavity == null)
		{
			buMarbleForms.frmCavity = new F_MarbleCavity();
		}
		buMarbleForms.frmCavity.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		buMarbleForms.frmCavity.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		buMarbleForms.frmCavity.varSettings = new marbleCavityPars(buMarbleCalc.varOperation.settingCavity);
		buMarbleForms.frmCavity.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
		buMarbleForms.frmCavity.Init();
		buMarbleForms.frmCavity.ShowDialog();
		if (buMarbleForms.frmCavity.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varOperation.settingCavity = new marbleCavityPars(buMarbleForms.frmCavity.varSettings);
		buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = buMarbleForms.frmCavity.ToolType;
		double ToolThickness = buMarbleCalc.activeToolSaw.Geometry.Thickness;
		clsInit.cMarble.GetToolThickness(buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool, ref ToolThickness);
		entitiesForCavity.Clear();
		for (int i = 0; i <= buMarbleCalc.varOperation.settingCavity.CavityCount - 1; i++)
		{
			int num = (int)buNumeric5.RoundToUpper((buMarbleCalc.varOperation.settingCavity.CavityHeight - ToolThickness) / (ToolThickness * 0.8));
			double num2 = 0.0;
			num2 = ((num <= 0) ? 0.0 : ((buMarbleCalc.varOperation.settingCavity.CavityHeight - ToolThickness) / (double)num));
			Entity entity = CompositeCurve.CreateRectangle(buMarbleCalc.varOperation.settingCavity.CavityLength, buMarbleCalc.varOperation.settingCavity.CavityHeight);
			entity.Translate(0.0, (double)i * buMarbleCalc.varOperation.settingCavity.CavitySpace);
			entity.Rotate(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingCavity.CavityAngle), Vector3D.AxisZ, new Point3D());
			buEntity copiedEntity = null;
			buEntity.Copy(entity, ref copiedEntity);
			entitiesForCavity.Add(copiedEntity);
			for (int j = 0; j <= num; j++)
			{
				double num3 = ToolThickness / 2.0 + (double)j * num2 + (double)i * buMarbleCalc.varOperation.settingCavity.CavitySpace;
				Point3D EndPnt = new Point3D();
				Point3D EndPnt2 = new Point3D();
				clsInit.cVector5.LineWithLengthAndAngle(EndPnt, num3, buMarbleCalc.varOperation.settingCavity.CavityAngle + 90.0, ref EndPnt);
				if (num3 != 0.0)
				{
					clsInit.cVector5.LineWithLengthAndAngle(EndPnt, buMarbleCalc.varOperation.settingCavity.CavityLength, buMarbleCalc.varOperation.settingCavity.CavityAngle, ref EndPnt2);
				}
				else
				{
					clsInit.cVector5.LineWithLengthAndAngle(EndPnt, buMarbleCalc.varOperation.settingCavity.CavityLength, buMarbleCalc.varOperation.settingCavity.CavityAngle, ref EndPnt2);
				}
				entitiesForCavity.Add(new buLine(EndPnt, EndPnt2));
			}
		}
		if (entitiesForCavity.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		if (MarbleTempVars.ItemsCavity == null)
		{
			MarbleTempVars.ItemsCavity = new List<MarbleItem>();
		}
		MarbleTempVars.ItemsCavity.Clear();
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.appMarble.activeItemType = MarbleItemType.Cavity;
		doAddItemCavity(new Point3D());
		cmdOperationCommon();
		clsInit.appMarble.entitiesForMove.Clear();
		MarbleTempVars.isSolidMove = true;
		if (MarbleTempVars.ItemsCavity.Count <= 0)
		{
			return;
		}
		for (int k = 0; k <= MarbleTempVars.ItemsCavity.Count - 1; k++)
		{
			for (int l = 0; l <= MarbleTempVars.ItemsCavity[k].ItemEntities.SourceEntities.Count - 1; l++)
			{
				Entity entity2 = null;
				List<Point3D> copiedPoint = new List<Point3D>();
				buVector5.Copy(MarbleTempVars.ItemsCavity[k].ItemEntities.SourceEntities[l].Vertices, ref copiedPoint);
				entity2 = new LinearPath(copiedPoint);
				clsInit.appMarble.entitiesForMove.Add(entity2);
			}
		}
		clsInit.cVector5.BoxSizeCalculate(clsInit.appMarble.entitiesForMove, ref MinPoint, ref MaxPoint);
		Entity rectangleEntity = null;
		clsInit.cVector5.DrawRectangle(MinPoint, MaxPoint.X - MinPoint.X, MaxPoint.Y - MinPoint.Y, Plane.XY, ref rectangleEntity);
		rectangleEntity.Translate(0.0, 0.0, buMarbleCalc.varMarbleDrawSettings.WireframeOnlineDrawZOffset);
		clsInit.appMarble.entitiesForMove.Add(rectangleEntity);
		MoveCreatedEntity = true;
	}

