		double ToolThickness = buMarbleCalc.activeToolSaw.Geometry.Thickness;
		clsInit.cMarble.GetToolThickness(buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool, ref ToolThickness);
		entitiesForDrill.Clear();
		if (buMarbleCalc.varOperation.settingTap.TapDiameter > 0.0)
		{
			buEntity item = new buCircle(Plane.XY, buMarbleCalc.varOperation.settingTap.TapDiameter / 2.0);
			entitiesForDrill.Add(item);
