			buEntity buEntity2 = new buCircle(Plane.XY, buMarbleCalc.varOperation.settingTap.TapLeftDiameter / 2.0);
			buEntity2.Translate(buMarbleCalc.varOperation.settingTap.TapLeftXOffset, buMarbleCalc.varOperation.settingTap.TapLeftYOffset, 0.0);
			entitiesForDrill.Add(buEntity2);
