		{
			buEntity buEntity3 = new buCircle(Plane.XY, buMarbleCalc.varOperation.settingTap.TapRightDiameter / 2.0);
			buEntity3.Translate(buMarbleCalc.varOperation.settingTap.TapRightXOffset, buMarbleCalc.varOperation.settingTap.TapRightYOffset, 0.0);
			entitiesForDrill.Add(buEntity3);
		}
		if (entitiesForDrill.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		clsInit.appMarble.activeItemType = MarbleItemType.Drill;
		doAddItemDrill(new Point3D());
		cmdOperationCommon();
		clsInit.appMarble.entitiesForMove.Clear();
		if (MarbleTempVars.ItemsDrill.Count <= 0)
		{
			return;
		}
		for (int i = 0; i <= MarbleTempVars.ItemsDrill.Count - 1; i++)
		{
			for (int j = 0; j <= MarbleTempVars.ItemsDrill[i].ItemEntities.DrillEntities.Count - 1; j++)
			{
				Entity copiedEntity = null;
				buEntity.Copy(MarbleTempVars.ItemsDrill[i].ItemEntities.DrillEntities[j], ref copiedEntity);
				clsInit.appMarble.entitiesForMove.Add(copiedEntity);
			}
		}
		MoveCreatedEntity = true;
	}

	public void cmdDrillMenu()
	{
		frmDrillMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmDrillMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		frmDrillMenu.ItemType = MarbleItemType.Drill;
		frmDrillMenu.MenuType = new marbleMenuType(buMarbleCalc.varMarbleRunSettings.selectedDrill);
		frmDrillMenu.Init();
		frmDrillMenu.ShowDialog();
		if (frmDrillMenu.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(frmDrillMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.selectedDrill = new marbleMenuType(frmDrillMenu.MenuType);
		DirectoryInfo directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileDrill);
		if (!directoryInfo.Exists)
		{
			buMarbleCalc.varMarbleRunSettings.pathFromFileDrill = AppPath.Base + "\\External2DFiles\\Drill";
			directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileDrill);
			if (!directoryInfo.Exists)
			{
				buMarbleCalc.varMarbleRunSettings.pathFromFileDrill = AppPath.Base;
			}
		}
		if (MarbleTempVars.ItemsDrill != null)
		{
			MarbleTempVars.ItemsDrill.Clear();
		}
		else
		{
			MarbleTempVars.ItemsDrill = new List<MarbleItem>();
		}
		entitiesForDrill.Clear();
		List<buEntity> refEntities = new List<buEntity>();
		bool flag = false;
		if (frmDrillMenu.DrillType == MarbleDrillMenuType.Editor)
		{
			if (clsItem.frmEditor == null)
			{
				clsItem.frmEditor = new F_Editor();
			}
			clsVar.varEditorRuntimeSet.isSketchMode = false;
			clsVar.varEditorRuntimeSet.isSewingMode = false;
			clsItem.frmEditor = new F_Editor();
			clsItem.frmEditor.OpenFileExtension.Clear();
			clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
			clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.frmEditor.Init();
			clsItem.frmEditor.ShowDialog(clsItem.FrmMain);
			for (int i = 0; i <= clsItem.frmEditor.viewport.Entities.Count - 1; i++)
			{
				buEntity copiedEntity = null;
				buEntity.Copy(clsItem.frmEditor.viewport.Entities[i], ref copiedEntity);
				if ((copiedEntity != null) & (clsItem.frmEditor.viewport.Entities[i].GetType() == typeof(Circle)))
				{
					copiedEntity.Marble = new MarbleInfo();
					copiedEntity.Marble.Depth = buMarbleCalc.varMarbleRunSettings.DrillDepth;
					refEntities.Add(copiedEntity);
				}
			}
		}
		if (frmDrillMenu.DrillType == MarbleDrillMenuType.FromTable)
		{
			F_MarbleHoleTable f_MarbleHoleTable = new F_MarbleHoleTable();
			f_MarbleHoleTable.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			f_MarbleHoleTable.Hole = new DiameterDepthPoint(new Point3D(buMarbleCalc.varMarbleRunSettings.DrillXPosition, buMarbleCalc.varMarbleRunSettings.DrillYPosition, buMarbleCalc.varMarbleRunSettings.DrillZPosition), buMarbleCalc.varMarbleRunSettings.DrillDiameter, buMarbleCalc.varMarbleRunSettings.DrillDepth);
			f_MarbleHoleTable.Init();
			f_MarbleHoleTable.ShowDialog();
			if (f_MarbleHoleTable.PropertiesForm.Result == DialogResult.OK)
			{
				buMarbleCalc.varMarbleRunSettings.DrillXPosition = f_MarbleHoleTable.Hole.Position.X;
				buMarbleCalc.varMarbleRunSettings.DrillYPosition = f_MarbleHoleTable.Hole.Position.Y;
				buMarbleCalc.varMarbleRunSettings.DrillZPosition = f_MarbleHoleTable.Hole.Position.Z;
				buMarbleCalc.varMarbleRunSettings.DrillDiameter = f_MarbleHoleTable.Hole.Diameter;
				buMarbleCalc.varMarbleRunSettings.DrillDepth = f_MarbleHoleTable.Hole.Depth;
				if (f_MarbleHoleTable.Holes.Count > 0)
				{
					for (int j = 0; j <= f_MarbleHoleTable.Holes.Count - 1; j++)
					{
						buCircle buCircle2 = new buCircle(f_MarbleHoleTable.Holes[j].Position, f_MarbleHoleTable.Holes[j].Diameter / 2.0);
						buCircle2.Marble = new MarbleInfo();
						buCircle2.Marble.Depth = f_MarbleHoleTable.Holes[j].Depth;
						refEntities.Add(buCircle2);
					}
					flag = true;
				}
			}
		}
		if (frmDrillMenu.DrillType == MarbleDrillMenuType.Coordinate)
		{
			F_MarbleHoleData f_MarbleHoleData = new F_MarbleHoleData();
			f_MarbleHoleData.PropertiesForm.FormCloseMode = FormCloseModeType.Dispose;
			f_MarbleHoleData.Hole = new DiameterDepthPoint(new Point3D(buMarbleCalc.varMarbleRunSettings.DrillXPosition, buMarbleCalc.varMarbleRunSettings.DrillYPosition, buMarbleCalc.varMarbleRunSettings.DrillZPosition), buMarbleCalc.varMarbleRunSettings.DrillDiameter, buMarbleCalc.varMarbleRunSettings.DrillDepth);
			f_MarbleHoleData.Init();
			f_MarbleHoleData.ShowDialog();
			if (f_MarbleHoleData.PropertiesForm.Result == DialogResult.OK)
			{
				buMarbleCalc.varMarbleRunSettings.DrillXPosition = f_MarbleHoleData.Hole.Position.X;
				buMarbleCalc.varMarbleRunSettings.DrillYPosition = f_MarbleHoleData.Hole.Position.Y;
				buMarbleCalc.varMarbleRunSettings.DrillZPosition = f_MarbleHoleData.Hole.Position.Z;
				buMarbleCalc.varMarbleRunSettings.DrillDiameter = f_MarbleHoleData.Hole.Diameter;
				buMarbleCalc.varMarbleRunSettings.DrillDepth = f_MarbleHoleData.Hole.Depth;
				buCircle buCircle3 = new buCircle(f_MarbleHoleData.Hole.Position, f_MarbleHoleData.Hole.Diameter / 2.0);
				buCircle3.Marble = new MarbleInfo();
				buCircle3.Marble.Depth = buMarbleCalc.varMarbleRunSettings.DrillDepth;
				refEntities.Add(buCircle3);
				flag = true;
			}
		}
		if (frmDrillMenu.DrillType == MarbleDrillMenuType.FromFile)
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileDrill;
			openFileDialog.Filter = "Drill Files (*.budrill)|*.budrill";
			openFileDialog.FilterIndex = 1;
			if (openFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileDrill = buFile5.GetPath(openFileDialog.FileName);
			FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
			if (!fileInfo.Exists)
			{
				return;
			}
			if (fileInfo.Extension.ToLower() == ".budrill")
			{
				OpenMarbleDrillFile(fileInfo.FullName);
				if (DrillList.Count > 0)
				{
					for (int k = 0; k <= DrillList.Count - 1; k++)
					{
						buCircle buCircle4 = new buCircle(DrillList[k].pntCenter, DrillList[k].Diameter);
						buCircle4.Marble = new MarbleInfo();
						buCircle4.Marble.Depth = DrillList[k].Depth;
						refEntities.Add(buCircle4);
					}
				}
			}
			flag = true;
			clsInit.appEditor.SaveEditorFile();
		}
		if (frmDrillMenu.DrillType == MarbleDrillMenuType.FromList)
		{
			if (clsItem.FrmFromFile == null)
			{
				clsItem.FrmFromFile = new F_AddFromFile();
			}
			clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileDrill;
			clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
			clsItem.FrmFromFile.ExtensionList.Clear();
			clsItem.FrmFromFile.ExtensionList.Add(".budrill");
			clsItem.FrmFromFile.MoveEntities = false;
			clsItem.FrmFromFile.Init();
			clsItem.FrmFromFile.ShowDialog();
			if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileDrill = clsItem.FrmFromFile.Path;
			clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
			for (int l = 0; l <= clsItem.FrmFromFile.viewport.Entities.Count - 1; l++)
			{
				buEntity copiedEntity2 = null;
				buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[l], ref copiedEntity2);
				refEntities.Add(copiedEntity2);
			}
			clsInit.appEditor.SaveEditorFile();
		}
		if (refEntities.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
		if (!flag)
		{
			clsInit.cVector5.Move(0.0 - ((buCircle)refEntities[0]).Center.X, 0.0 - ((buCircle)refEntities[0]).Center.Y, 0.0 - ((buCircle)refEntities[0]).Center.Z, ref refEntities);
		}
		for (int m = 0; m <= refEntities.Count - 1; m++)
		{
			if (refEntities[m] is buCircle)
			{
				entitiesForDrill.Add(buEntity.Copy(refEntities[m]));
			}
			if (refEntities[m] is buEllipse)
			{
				entitiesForDrill.Add(buEntity.Copy(refEntities[m]));
			}
		}
		clsInit.appMarble.activeItemType = MarbleItemType.Drill;
		doAddItemDrill(new Point3D(), flag);
		cmdOperationCommon();
		if (flag)
		{
			return;
		}
		clsInit.appMarble.entitiesForMove.Clear();
		if (MarbleTempVars.ItemsDrill.Count <= 0)
		{
			return;
		}
		for (int n = 0; n <= MarbleTempVars.ItemsDrill.Count - 1; n++)
		{
			for (int num = 0; num <= MarbleTempVars.ItemsDrill[n].ItemEntities.DrillEntities.Count - 1; num++)
			{
				Entity copiedEntity3 = null;
				buEntity.Copy(MarbleTempVars.ItemsDrill[n].ItemEntities.DrillEntities[num], ref copiedEntity3);
				clsInit.appMarble.entitiesForMove.Add(copiedEntity3);
			}
		}
		MoveCreatedEntity = true;
	}

	public void cmdTextMenu()
	{
		frmTextMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmTextMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		frmTextMenu.chk_3D.Check = buMarbleCalc.varMarbleRunSettings.Text3D;
		frmTextMenu.ItemType = MarbleItemType.Text;
		frmTextMenu.MenuType = new marbleMenuType(buMarbleCalc.varMarbleRunSettings.selectedText);
		frmTextMenu.Init();
		frmTextMenu.ShowDialog();
		if (frmTextMenu.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(frmTextMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.selectedText = new marbleMenuType(frmTextMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.Text3D = frmTextMenu.chk_3D.Check;
		if (MarbleTempVars.ItemsContour != null)
		{
			MarbleTempVars.ItemsContour.Clear();
		}
		else
		{
			MarbleTempVars.ItemsContour = new List<MarbleItem>();
		}
		entitiesForContour.Clear();
		new List<buEntity>();
		string text = "";
		if (frmTextMenu.TextType == MarbleTextMenuType.FromFile)
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathTextFile;
			openFileDialog.Filter = "Text Files (.txt)|*.txt";
			openFileDialog.FilterIndex = 1;
			openFileDialog.Multiselect = false;
			if (openFileDialog.ShowDialog() == DialogResult.OK)
			{
				buMarbleCalc.varMarbleRunSettings.pathTextFile = buFile5.GetPath(openFileDialog.FileName);
				List<string> StringList = new List<string>();
				buFile5.OpenFromFile(openFileDialog.FileName, ref StringList);
				if (StringList.Count > 0)
				{
					if (!buMarbleCalc.varMarbleSettings.TextFromFileAsWireframe)
					{
						frmTextMenu.TextType = MarbleTextMenuType.Font;
						text = StringList[0];
						clsInit.appMarble.activeItemType = MarbleItemType.Text;
					}
					else
					{
						frmTextMenu.TextType = MarbleTextMenuType.Wireframe;
						text = StringList[0];
						clsInit.appMarble.activeItemType = MarbleItemType.TextWireframe;
					}
				}
			}
		}
		if (frmTextMenu.TextType == MarbleTextMenuType.Font)
		{
			if (text.Length != 0)
			{
				buMarbleCalc.varMarbleRunSettings.textFontDrawing = text;
			}
			else
			{
				F_VectorText f_VectorText = new F_VectorText();
				f_VectorText.TextData = new TextVectorData(clsVar.varInterface.VectorTextVar);
				f_VectorText.Init();
				f_VectorText.ShowDialog();
				if (f_VectorText.Result != DialogResult.OK)
				{
					return;
				}
				clsVar.varInterface.VectorTextVar = new TextVectorData(f_VectorText.TextData);
				buMarbleCalc.varMarbleRunSettings.textFontDrawing = clsVar.varInterface.VectorTextVar.Text;
			}
			List<PointsList> CalculatedPoints = new List<PointsList>();
			clsInit.cVector5.FontToVectorConvert(new Point3D(), clsVar.varInterface.VectorTextVar.Font, buMarbleCalc.varMarbleRunSettings.textFontDrawing, Plane.XY, new Point3D(), ref CalculatedPoints);
			entitiesGroupForContour.Clear();
			for (int i = 0; i <= CalculatedPoints.Count - 1; i++)
			{
				buEntitiesGroup buEntitiesGroup2 = new buEntitiesGroup();
				for (int j = 0; j <= CalculatedPoints[i].Points.Count - 1; j++)
				{
					List<buEntity> list = new List<buEntity>();
					buLinearPath item = new buLinearPath(CalculatedPoints[i].Points[j]);
					if (j != 0)
					{
						list.Add(item);
						buEntityList item2 = new buEntityList(list);
						buEntitiesGroup2.Inside.Add(item2);
					}
					else
					{
						buEntitiesGroup2.Outside.Entities.Add(item);
					}
				}
				entitiesGroupForContour.Add(buEntitiesGroup2);
			}
			clsInit.appMarble.activeItemType = MarbleItemType.Text;
		}
		if (frmTextMenu.TextType == MarbleTextMenuType.Wireframe)
		{
			if (text.Length != 0)
			{
				buMarbleCalc.varMarbleRunSettings.TextWireframeString = text;
			}
			else
			{
				F_TextWireframe f_TextWireframe = new F_TextWireframe();
				f_TextWireframe.TextString = buMarbleCalc.varMarbleRunSettings.TextWireframeString;
				f_TextWireframe.TextHeight = buMarbleCalc.varMarbleRunSettings.TextWireframeHeight;
				f_TextWireframe.Properties.FormCloseMode = FormCloseModeType.Dispose;
				f_TextWireframe.Properties.FormPosition = FormStartPosition.CenterScreen;
				f_TextWireframe.Init();
				f_TextWireframe.ShowDialog();
				if (f_TextWireframe.Properties.Result != DialogResult.OK)
				{
					return;
				}
				buMarbleCalc.varMarbleRunSettings.TextWireframeString = f_TextWireframe.TextString;
				buMarbleCalc.varMarbleRunSettings.TextWireframeHeight = f_TextWireframe.TextHeight;
			}
			clsInit.appCommand.CustomTextCreate(buMarbleCalc.varMarbleRunSettings.TextWireframeString, ccVars.CustomTextRunVar.CharSpace, ccVars.CustomTextRunVar.SpaceValue, buMarbleCalc.varMarbleRunSettings.TextWireframeHeight, ccVars.CustomTextRunVar.Alignment, ccVars.planeActive, ref ccVars.ContourPoints5);
			if (ccVars.ContourPoints5.Count == 0)
			{
				return;
			}
			clsInit.appMarble.activeItemType = MarbleItemType.TextWireframe;
			buEntitiesGroup buEntitiesGroup3 = new buEntitiesGroup();
			buEntityList buEntityList2 = new buEntityList();
			for (int k = 0; k <= ccVars.ContourPoints5.Count - 1; k++)
			{
				List<Point3D> Points = new List<Point3D>();
				for (int l = 0; l <= ccVars.ContourPoints5[k].Outter.Count - 1; l++)
				{
					Points.Add(new Point3D(ccVars.ContourPoints5[k].Outter[l].X, ccVars.ContourPoints5[k].Outter[l].Y, ccVars.ContourPoints5[k].Outter[l].Z));
				}
				clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points);
				buLinearPath item3 = new buLinearPath(Points);
				buEntityList2.Entities.Add(item3);
				for (int m = 0; m <= ccVars.ContourPoints5[k].Inside.Count - 1; m++)
				{
					Points = new List<Point3D>();
					for (int n = 0; n <= ccVars.ContourPoints5[k].Inside[m].Count - 1; n++)
					{
						Points.Add(new Point3D(ccVars.ContourPoints5[k].Outter[m].X, ccVars.ContourPoints5[k].Outter[m].Y, ccVars.ContourPoints5[k].Outter[m].Z));
					}
					clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points);
					item3 = new buLinearPath(Points);
					buEntityList2.Entities.Add(item3);
				}
			}
			buEntitiesGroup3.OpenEntities = new List<buEntityList>();
			buEntitiesGroup3.OpenEntities.Add(buEntityList2);
			entitiesGroupForContour.Add(buEntitiesGroup3);
			buMarbleCalc.varMarbleRunSettings.Text3D = false;
		}
		if (entitiesGroupForContour.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		entityToolType toolType = entityToolType.Saw;
		bool isMilling = false;
		bool isMillingHead = false;
		bool isWaterJet = false;
		if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.Milling)
		{
			toolType = entityToolType.Milling;
			isMilling = true;
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.MillingHead)
		{
			toolType = entityToolType.MillingHead;
			isMillingHead = true;
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.WaterJet)
		{
			toolType = entityToolType.WaterJet;
			isWaterJet = true;
		}
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(entitiesGroupForContour, ref MinPoint, ref MaxPoint);
		double num = MaxPoint.X - MinPoint.X;
		double num2 = MaxPoint.Y - MinPoint.Y;
		if (!buMarbleCalc.varMarbleRunSettings.Text3D)
		{
			frmEditBaseHAndXYBorder.varRuntime = new MarbleRuntimeSettings(buMarbleCalc.varMarbleRunSettings);
			frmEditBaseHAndXYBorder.varRuntime.ScaleWidth = MaxPoint.X - MinPoint.X;
			frmEditBaseHAndXYBorder.varRuntime.ScaleHeight = MaxPoint.Y - MinPoint.Y;
			frmEditBaseHAndXYBorder.Properties.FormCloseMode = FormCloseModeType.Invisible;
			frmEditBaseHAndXYBorder.Properties.FormPosition = FormStartPosition.CenterScreen;
			frmEditBaseHAndXYBorder.Init();
			frmEditBaseHAndXYBorder.ShowDialog();
			if (frmEditBaseHAndXYBorder.Properties.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings = new MarbleRuntimeSettings(frmEditBaseHAndXYBorder.varRuntime);
		}
		else
		{
			frmEditBaseHAndXY.varRuntime = new MarbleRuntimeSettings(buMarbleCalc.varMarbleRunSettings);
			frmEditBaseHAndXY.varRuntime.ScaleWidth = MaxPoint.X - MinPoint.X;
			frmEditBaseHAndXY.varRuntime.ScaleHeight = MaxPoint.Y - MinPoint.Y;
			frmEditBaseHAndXY.Properties.FormCloseMode = FormCloseModeType.Invisible;
			frmEditBaseHAndXY.Properties.FormPosition = FormStartPosition.CenterScreen;
			frmEditBaseHAndXY.Init();
			frmEditBaseHAndXY.ShowDialog();
			if (frmEditBaseHAndXY.Properties.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings = new MarbleRuntimeSettings(frmEditBaseHAndXY.varRuntime);
			buMarbleCalc.varMarbleRunSettings.BorderEnable = false;
		}
		if (!buCompare5.EQ(num, buMarbleCalc.varMarbleRunSettings.ScaleWidth) | !buCompare5.EQ(num2, buMarbleCalc.varMarbleRunSettings.ScaleHeight))
		{
			if (!buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio)
			{
				double scaleX = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num);
				double scaleY = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleHeight / num2);
				clsInit.cVector5.Scale(MinPoint, scaleX, scaleY, 1.0, ref entitiesGroupForContour);
			}
			else
			{
				double num3 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num);
				double scaleY2 = num3;
				clsInit.cVector5.Scale(MinPoint, num3, scaleY2, 1.0, ref entitiesGroupForContour);
			}
		}
		if (buMarbleCalc.varMarbleRunSettings.BorderEnable & !buMarbleCalc.varMarbleRunSettings.Text3D)
		{
			MinPoint = new Point3D();
			MaxPoint = new Point3D();
			clsInit.cVector5.BoxSizeCalculate(entitiesGroupForContour, ref MinPoint, ref MaxPoint);
			buLine item4 = new buLine(new Point3D(MinPoint.X - buMarbleCalc.varMarbleRunSettings.BorderLeft, MinPoint.Y - buMarbleCalc.varMarbleRunSettings.BorderBottom, 0.0), new Point3D(MinPoint.X - buMarbleCalc.varMarbleRunSettings.BorderLeft, MaxPoint.Y + buMarbleCalc.varMarbleRunSettings.BorderTop, 0.0));
			buLine item5 = new buLine(new Point3D(MinPoint.X - buMarbleCalc.varMarbleRunSettings.BorderLeft, MaxPoint.Y + buMarbleCalc.varMarbleRunSettings.BorderTop, 0.0), new Point3D(MaxPoint.X + buMarbleCalc.varMarbleRunSettings.BorderRight, MaxPoint.Y + buMarbleCalc.varMarbleRunSettings.BorderTop, 0.0));
			buLine item6 = new buLine(new Point3D(MaxPoint.X + buMarbleCalc.varMarbleRunSettings.BorderRight, MaxPoint.Y + buMarbleCalc.varMarbleRunSettings.BorderTop, 0.0), new Point3D(MaxPoint.X + buMarbleCalc.varMarbleRunSettings.BorderRight, MinPoint.Y - buMarbleCalc.varMarbleRunSettings.BorderBottom, 0.0));
			buLine item7 = new buLine(new Point3D(MaxPoint.X + buMarbleCalc.varMarbleRunSettings.BorderRight, MinPoint.Y - buMarbleCalc.varMarbleRunSettings.BorderBottom, 0.0), new Point3D(MinPoint.X - buMarbleCalc.varMarbleRunSettings.BorderLeft, MinPoint.Y - buMarbleCalc.varMarbleRunSettings.BorderBottom, 0.0));
			buEntitiesGroup buEntitiesGroup4 = new buEntitiesGroup();
			buEntitiesGroup4.Outside.Entities.Add(item4);
			buEntitiesGroup4.Outside.Entities.Add(item5);
			buEntitiesGroup4.Outside.Entities.Add(item6);
			buEntitiesGroup4.Outside.Entities.Add(item7);
			entitiesGroupForContour.Insert(0, buEntitiesGroup4);
		}
		clsInit.cVector5.Move(0.0, 0.0, buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight, ref entitiesGroupForContour);
		doAddItemShapeContour(new Point3D(), isShape: false, isFinished: false, isText: true, isMilling, isMillingHead, isWaterJet, isCamCalc: false, -1);
		cmdOperationCommon();
		clsInit.appMarble.entitiesForMove.Clear();
		MarbleTempVars.isSolidMove = false;
		if (MarbleTempVars.ItemsContour.Count <= 0)
		{
			return;
		}
		for (int num4 = 0; num4 <= entitiesGroupForContour.Count - 1; num4++)
		{
			entitiesGroupForContour[num4].Outside.ToolType = toolType;
			for (int num5 = 0; num5 <= entitiesGroupForContour[num4].Outside.Entities.Count - 1; num5++)
			{
				Entity copiedEntity = null;
				buEntity.Copy(entitiesGroupForContour[num4].Outside.Entities[num5], ref copiedEntity);
				clsInit.appMarble.entitiesForMove.Add(copiedEntity);
			}
			if (entitiesGroupForContour[num4].Inside != null)
			{
				for (int num6 = 0; num6 <= entitiesGroupForContour[num4].Inside.Count - 1; num6++)
				{
					entitiesGroupForContour[num4].Inside[num6].ToolType = toolType;
					for (int num7 = 0; num7 <= entitiesGroupForContour[num4].Inside[num6].Entities.Count - 1; num7++)
					{
						Entity copiedEntity2 = null;
						buEntity.Copy(entitiesGroupForContour[num4].Inside[num6].Entities[num7], ref copiedEntity2);
						clsInit.appMarble.entitiesForMove.Add(copiedEntity2);
					}
				}
			}
			if (entitiesGroupForContour[num4].OpenEntities == null)
			{
				continue;
			}
			for (int num8 = 0; num8 <= entitiesGroupForContour[num4].OpenEntities.Count - 1; num8++)
			{
				entitiesGroupForContour[num4].OpenEntities[num8].ToolType = toolType;
				for (int num9 = 0; num9 <= entitiesGroupForContour[num4].OpenEntities[num8].Entities.Count - 1; num9++)
				{
					Entity copiedEntity3 = null;
					buEntity.Copy(entitiesGroupForContour[num4].OpenEntities[num8].Entities[num9], ref copiedEntity3);
					clsInit.appMarble.entitiesForMove.Add(copiedEntity3);
				}
			}
		}
		MoveCreatedEntity = true;
	}

	public void cmdEngravingMenu()
	{
		frmEngraveMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmEngraveMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		if ((buMarbleCalc.varMarbleRunSettings.selectedEngraving.selectedTool == MarbleToolType.Saw) | (buMarbleCalc.varMarbleRunSettings.selectedEngraving.selectedTool == MarbleToolType.WaterJet))
		{
			buMarbleCalc.varMarbleRunSettings.selectedEngraving.selectedTool = MarbleToolType.Milling;
		}
		frmEngraveMenu.ItemType = MarbleItemType.Engraving;
		frmEngraveMenu.MenuType = new marbleMenuType(buMarbleCalc.varMarbleRunSettings.selectedEngraving);
		frmEngraveMenu.chk_5Axismilling.Check = buMarbleCalc.varMarbleRunSettings.selectedEngraving5AxisMilling;
		frmEngraveMenu.Init();
		frmEngraveMenu.ShowDialog();
		if (frmEngraveMenu.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(frmEngraveMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.selectedEngraving = new marbleMenuType(frmEngraveMenu.MenuType);
		DirectoryInfo directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving);
		if (!directoryInfo.Exists)
		{
			buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving = AppPath.Base + "\\External3DFiles";
			directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving);
			if (!directoryInfo.Exists)
			{
				buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving = AppPath.Base;
			}
		}
		buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = buMarbleCalc.varMarbleRunSettings.selectedEngraving.selectedTool;
		buMarbleCalc.varMarbleRunSettings.selectedEngraving5AxisMilling = frmEngraveMenu.chk_5Axismilling.Check;
		clsInit.appMarble.entitiesForMove.Clear();
		List<Entity> EntityList = new List<Entity>();
		if (frmEngraveMenu.EngraveType != MarbleEngraveMenuType.Editor)
		{
		}
		if (frmEngraveMenu.EngraveType == MarbleEngraveMenuType.FromFile)
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving;
			openFileDialog.Filter = "3D Files (.stl  .step  .igs)|*.stl;*.step;*.stp;*.iges;*.igs";
			openFileDialog.FilterIndex = 1;
			openFileDialog.Multiselect = false;
			if (openFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving = buFile5.GetPath(openFileDialog.FileName);
			FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
			if (fileInfo.Exists)
			{
				if (fileInfo.Extension.ToLower() == ".stl")
				{
					buFile5.OpenStl(ref EntityList, fileInfo.FullName);
				}
				if ((fileInfo.Extension.ToLower() == ".stp") | (fileInfo.Extension.ToLower() == ".step"))
				{
					buFile5.OpenStep(ref EntityList, fileInfo.FullName);
				}
				if ((fileInfo.Extension.ToLower() == ".igs") | (fileInfo.Extension.ToLower() == ".iges"))
				{
					buFile5.OpenIges(ref EntityList, fileInfo.FullName);
				}
			}
			clsInit.appMarble.activeItemType = MarbleItemType.Engraving;
			clsInit.appMarble.entitiesForMove.Clear();
		}
		if (frmEngraveMenu.EngraveType == MarbleEngraveMenuType.FromList)
		{
			if (clsItem.FrmFromFile == null)
			{
				clsItem.FrmFromFile = new F_AddFromFile();
			}
			clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving;
			clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
			clsItem.FrmFromFile.ExtensionList.Clear();
			clsItem.FrmFromFile.ExtensionList.Add(".stl");
			clsItem.FrmFromFile.ExtensionList.Add(".igs");
			clsItem.FrmFromFile.ExtensionList.Add(".iges");
			clsItem.FrmFromFile.ExtensionList.Add(".step");
			clsItem.FrmFromFile.ExtensionList.Add(".stp");
			clsItem.FrmFromFile.MoveEntities = false;
			clsItem.FrmFromFile.Init();
			clsItem.FrmFromFile.ShowDialog();
			if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving = clsItem.FrmFromFile.Path;
			clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
			for (int i = 0; i <= clsItem.FrmFromFile.viewport.Entities.Count - 1; i++)
			{
				Entity copiedEntity = null;
				buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[i], ref copiedEntity);
				copiedEntity.Color = Color.WhiteSmoke;
				copiedEntity.ColorMethod = colorMethodType.byEntity;
				EntityList.Add(copiedEntity);
			}
			clsInit.appMarble.activeItemType = MarbleItemType.Engraving;
			clsInit.appMarble.entitiesForMove.Clear();
		}
		if (EntityList.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(EntityList, ref MinPoint, ref MaxPoint);
		double num = MaxPoint.X - MinPoint.X;
		double num2 = MaxPoint.Y - MinPoint.Y;
		frmEditBaseHAndXY.varRuntime = new MarbleRuntimeSettings(buMarbleCalc.varMarbleRunSettings);
		frmEditBaseHAndXY.varRuntime.ScaleWidth = MaxPoint.X - MinPoint.X;
		frmEditBaseHAndXY.varRuntime.ScaleHeight = MaxPoint.Y - MinPoint.Y;
		frmEditBaseHAndXY.Properties.FormCloseMode = FormCloseModeType.Invisible;
		frmEditBaseHAndXY.Properties.FormPosition = FormStartPosition.CenterScreen;
		frmEditBaseHAndXY.Init();
		frmEditBaseHAndXY.ShowDialog();
		if (frmEditBaseHAndXY.Properties.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varMarbleRunSettings = new MarbleRuntimeSettings(frmEditBaseHAndXY.varRuntime);
		if (!buCompare5.EQ(num, buMarbleCalc.varMarbleRunSettings.ScaleWidth) | !buCompare5.EQ(num2, buMarbleCalc.varMarbleRunSettings.ScaleHeight))
		{
			if (!buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio)
			{
				double scaleX = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num);
				double scaleY = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleHeight / num2);
				clsInit.cVector5.Scale(MinPoint, scaleX, scaleY, 1.0, ref EntityList);
			}
			else
			{
				double num3 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num);
				double scaleY2 = num3;
				clsInit.cVector5.Scale(MinPoint, num3, scaleY2, 1.0, ref EntityList);
			}
		}
		MinPoint = new Point3D();
		MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(EntityList, ref MinPoint, ref MaxPoint);
		clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref EntityList);
		CompositeCurve compositeCurve = CompositeCurve.CreateRectangle(MaxPoint.X - MinPoint.X, MaxPoint.Y - MinPoint.Y);
		compositeCurve.Translate(0.0 - MinPoint.X, 0.0 - MinPoint.Y);
		EntityList.Add(compositeCurve);
		cmdOperationCommon();
		MarbleTempVars.isSolidMove = false;
		for (int j = 0; j <= EntityList.Count - 1; j++)
		{
			Entity copiedEntity2 = null;
			buEntity.Copy(EntityList[j], ref copiedEntity2);
			clsInit.appMarble.entitiesForMove.Add(copiedEntity2);
		}
		MoveCreatedEntity = true;
	}

