				dY = buMarbleCalc.varOperation.settingLatheCut.LatheRadiusTopDistance - MaxPoint.Y;
			}
			clsInit.cVector5.Move(0.0 - MinPoint.X, dY, 0.0, ref refEntities);
			SortbuSettings sortbuSettings2 = new SortbuSettings();
			sortbuSettings2.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
			new List<buEntity>();
			clsInit.cVector5.SortEntitiesByRefPoint(new Point3D(), ref refEntities, sortbuSettings2, ref entitiesForLathe);
			clsInit.appMarble.activeItemType = MarbleItemType.LatheHorizontal;
			if (buMarbleCalc.varMarbleMachineSettings.LatheSettings.LathePosition != LeftRightType.Right)
			{
				doAddItemLathe(new Point3D(buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheXOffset + (MaxPoint.X - MinPoint.X), buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheYOffset, buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheZOffset), isFinsihed: true);
			}
			else
			{
				doAddItemLathe(new Point3D(buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheXOffset, buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheYOffset, buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheZOffset), isFinsihed: true);
			}
		}
	}

