	public void cmdExternalGCode()
	{
		OpenFileDialog openFileDialog = new OpenFileDialog();
		openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathExternalGCode;
		openFileDialog.Filter = "All GCode Files (*.cnc,*.nc,*.tap,*.gcode)|*.cnc;*.nc;*.tap;*.gcode|NC Files (*.nc)|*.nc|CNC Files (*.cnc)|*.cnc|Tap Files (*.tap)|*.tap|GCode Files (*.gcode)|*.gcode";
		openFileDialog.FilterIndex = 1;
		if (openFileDialog.ShowDialog() != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varMarbleRunSettings.pathExternalGCode = buFile5.GetPath(openFileDialog.FileName);
		FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
		if (fileInfo.Exists)
		{
			buFile5.GCodeRead gCodeRead = new buFile5.GCodeRead();
			List<GCodePoint5> GCodeList = new List<GCodePoint5>();
			gCodeRead.Settings.FilterLength = 0.0;
			gCodeRead.Settings.TrimLines = false;
			gCodeRead.Settings.UseMCode = false;
			gCodeRead.Settings.UseTCode = false;
			gCodeRead.Settings.CheckComma = false;
			gCodeRead.DecodeAxes.A = false;
			gCodeRead.DecodeAxes.B = false;
			gCodeRead.DecodeAxes.C = false;
			if (buMarbleCalc.varMarbleSettings.GCodeConversion == MarbleExternalGCode.Siemens5Axis)
			{
				gCodeRead.DecodeAxes.A = true;
				gCodeRead.DecodeAxes.C = true;
				gCodeRead.Assingment = new List<buFile5.GCodeAssingmentArgs>();
				gCodeRead.Assingment.Add(new buFile5.GCodeAssingmentArgs("G43", "G0 Z300.0"));
			}
			gCodeRead.OpenGCode(fileInfo.FullName, ref GCodeList, DontFillGCodList: true);
			cmdOperationCommon();
			doAddItemGCode(new Point3D(), gCodeRead, gCodeRead.GCodeLines);
		}
	}

