	public void cmd3DSahpeMenu()
	{
		frmSawMillingMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmSawMillingMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		buMarbleCalc.varMarbleRunSettings.selectedSawMilling.selectedTool = MarbleToolType.Saw;
		frmSawMillingMenu.ItemType = MarbleItemType.SawHorizontalMillingRough;
		frmSawMillingMenu.MenuType = new marbleMenuType(buMarbleCalc.varMarbleRunSettings.selectedSawMilling);
		frmSawMillingMenu.Init();
		frmSawMillingMenu.ShowDialog();
		if (frmSawMillingMenu.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		frmSawMillingMenu.MenuType.selectedMeshType = CamTriangularMeshType.ConstantZ;
		buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(frmSawMillingMenu.MenuType);
		buMarbleCalc.varMarbleRunSettings.selectedSawMilling = new marbleMenuType(frmSawMillingMenu.MenuType);
		DirectoryInfo directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling);
		if (!directoryInfo.Exists)
		{
			buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling = AppPath.Base + "\\External3DFiles";
			directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling);
			if (!directoryInfo.Exists)
			{
				buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling = AppPath.Base;
			}
		}
		buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = buMarbleCalc.varMarbleRunSettings.selectedSawMilling.selectedTool;
		clsInit.appMarble.entitiesForMove.Clear();
		MarbleTempVars.ImportedEntitites.Clear();
		List<Entity> EntityList = new List<Entity>();
		if (frmSawMillingMenu.EngraveType != MarbleEngraveMenuType.Editor)
		{
		}
		if (frmSawMillingMenu.EngraveType == MarbleEngraveMenuType.FromFile)
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling;
			openFileDialog.Filter = "3D Files (.stl  .step  .igs)|*.stl;*.step;*.stp;*.iges;*.igs";
			openFileDialog.FilterIndex = 1;
			openFileDialog.Multiselect = false;
			if (openFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling = buFile5.GetPath(openFileDialog.FileName);
			FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
			if (fileInfo.Exists)
			{
				if (fileInfo.Extension.ToLower() == ".stl")
				{
					buFile5.OpenStl(ref EntityList, fileInfo.FullName);
				}
				if ((fileInfo.Extension.ToLower() == ".stp") | (fileInfo.Extension.ToLower() == ".step"))
				{
					buFile5.OpenStep(ref EntityList, fileInfo.FullName);
				}
				if ((fileInfo.Extension.ToLower() == ".igs") | (fileInfo.Extension.ToLower() == ".iges"))
				{
					buFile5.OpenIges(ref EntityList, fileInfo.FullName);
				}
			}
			clsInit.appMarble.activeItemType = MarbleItemType.SawHorizontalMillingRough;
			clsInit.appMarble.entitiesForMove.Clear();
		}
		if (frmSawMillingMenu.EngraveType == MarbleEngraveMenuType.FromList)
		{
			if (clsItem.FrmFromFile == null)
			{
				clsItem.FrmFromFile = new F_AddFromFile();
			}
			clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling;
			clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
			clsItem.FrmFromFile.ExtensionList.Clear();
			clsItem.FrmFromFile.ExtensionList.Add(".stl");
			clsItem.FrmFromFile.ExtensionList.Add(".igs");
			clsItem.FrmFromFile.ExtensionList.Add(".iges");
			clsItem.FrmFromFile.ExtensionList.Add(".step");
			clsItem.FrmFromFile.ExtensionList.Add(".stp");
			clsItem.FrmFromFile.ExtensionList.Add(".obj");
			clsItem.FrmFromFile.MoveEntities = false;
			clsItem.FrmFromFile.Init();
			clsItem.FrmFromFile.ShowDialog();
			if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling = clsItem.FrmFromFile.Path;
			clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
			for (int i = 0; i <= clsItem.FrmFromFile.viewport.Entities.Count - 1; i++)
			{
				Entity copiedEntity = null;
				buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[i], ref copiedEntity);
				copiedEntity.Color = Color.WhiteSmoke;
				copiedEntity.ColorMethod = colorMethodType.byEntity;
				EntityList.Add(copiedEntity);
			}
			clsInit.appMarble.activeItemType = MarbleItemType.SawHorizontalMillingRough;
			clsInit.appMarble.entitiesForMove.Clear();
		}
		buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = MarbleToolType.Saw;
		if (EntityList.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(EntityList, ref MinPoint, ref MaxPoint);
		double num = MaxPoint.X - MinPoint.X;
		double num2 = MaxPoint.Y - MinPoint.Y;
		if (buMarbleForms.frmSawMillingHorizontal == null)
		{
			buMarbleForms.frmSawMillingHorizontal = new F_MarbleSawMillingHorizontal();
		}
		buMarbleCalc.varMarbleRunSettings.ScaleWidth = MaxPoint.X - MinPoint.X;
		buMarbleCalc.varMarbleRunSettings.ScaleHeight = MaxPoint.Y - MinPoint.Y;
		buMarbleForms.frmSawMillingHorizontal.CamMode = MarbleCamMode.Rough;
		buMarbleForms.frmSawMillingHorizontal.Properties.FormCloseMode = FormCloseModeType.Invisible;
		buMarbleForms.frmSawMillingHorizontal.Properties.FormPosition = FormStartPosition.CenterScreen;
		buMarbleForms.frmSawMillingHorizontal.Init();
		buMarbleForms.frmSawMillingHorizontal.ShowDialog();
		if (buMarbleForms.frmSawMillingHorizontal.Properties.Result != DialogResult.OK)
		{
			return;
		}
		if (!buCompare5.EQ(num, buMarbleCalc.varMarbleRunSettings.ScaleWidth) | !buCompare5.EQ(num2, buMarbleCalc.varMarbleRunSettings.ScaleHeight))
		{
			if (!buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio)
			{
				double scaleX = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num);
				double scaleY = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleHeight / num2);
				clsInit.cVector5.Scale(MinPoint, scaleX, scaleY, 1.0, ref EntityList);
			}
			else
			{
				double num3 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num);
				double scaleY2 = num3;
				clsInit.cVector5.Scale(MinPoint, num3, scaleY2, 1.0, ref EntityList);
			}
		}
		MinPoint = new Point3D(double.MaxValue, double.MaxValue, double.MaxValue);
		MaxPoint = new Point3D(double.MinValue, double.MinValue, double.MinValue);
		clsInit.cVector5.BoxSizeCalculate(EntityList, ref MinPoint, ref MaxPoint);
		clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref EntityList);
		CompositeCurve item = CompositeCurve.CreateRectangle(MaxPoint.X - MinPoint.X, MaxPoint.Y - MinPoint.Y);
		clsInit.appMarble.entitiesForMove.Add(item);
		cmdOperationCommon();
		MarbleTempVars.isSolidMove = false;
		for (int j = 0; j <= EntityList.Count - 1; j++)
		{
			Entity copiedEntity2 = null;
			buEntity.Copy(EntityList[j], ref copiedEntity2);
			MarbleTempVars.ImportedEntitites.Add(copiedEntity2);
		}
		MoveCreatedEntity = true;
		EntityList.Clear();
	}

