			clsItem.FrmFromFile.Init();
			clsItem.FrmFromFile.ShowDialog();
			if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving = clsItem.FrmFromFile.Path;
			clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
			for (int i = 0; i <= clsItem.FrmFromFile.viewport.Entities.Count - 1; i++)
			{
				Entity copiedEntity = null;
				buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[i], ref copiedEntity);
				copiedEntity.Color = Color.WhiteSmoke;
				copiedEntity.ColorMethod = colorMethodType.byEntity;
				EntityList.Add(copiedEntity);
			}
		}
		if (EntityList.Count <= 0)
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			return;
		}
		MarbleTempVars.ImportedEntitites.Clear();
		clsInit.appMarble.entitiesForMove.Clear();
		Point3D MidPoint = new Point3D();
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(EntityList, ref MinPoint, ref MidPoint, ref MaxPoint);
		if (buMarbleForms.frmShape3DBaseAndXYZ == null)
		{
			buMarbleForms.frmShape3DBaseAndXYZ = new F_MarbleEditBaseHAndXYZ();
		}
		double num = MaxPoint.X - MinPoint.X;
		double num2 = MaxPoint.Y - MinPoint.Y;
		double num3 = MaxPoint.Z - MinPoint.Z;
		buMarbleForms.frmShape3DBaseAndXYZ.varRuntime.ScaleWidth = MaxPoint.X - MinPoint.X;
		buMarbleForms.frmShape3DBaseAndXYZ.varRuntime.ScaleHeight = MaxPoint.Y - MinPoint.Y;
		buMarbleForms.frmShape3DBaseAndXYZ.varRuntime.ScaleDepth = MaxPoint.Z - MinPoint.Z;
		buMarbleForms.frmShape3DBaseAndXYZ.varRuntime.ScaleKeepRatio = buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio;
		buMarbleForms.frmShape3DBaseAndXYZ.Init();
		buMarbleForms.frmShape3DBaseAndXYZ.ShowDialog();
		if (buMarbleForms.frmShape3DBaseAndXYZ.Properties.Result != DialogResult.OK)
		{
			return;
		}
		clsInit.appMarble.activeItemType = MarbleItemType.Shape3D;
		buMarbleCalc.varMarbleRunSettings.ScaleWidth = buMarbleForms.frmShape3DBaseAndXYZ.spn_scalewidth.Value;
		buMarbleCalc.varMarbleRunSettings.ScaleHeight = buMarbleForms.frmShape3DBaseAndXYZ.spn_scaleheight.Value;
		buMarbleCalc.varMarbleRunSettings.ScaleDepth = buMarbleForms.frmShape3DBaseAndXYZ.spn_scaledepth.Value;
		buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio = buMarbleForms.frmShape3DBaseAndXYZ.chk_keepratio.Check;
		if (!buCompare5.EQ(num, buMarbleCalc.varMarbleRunSettings.ScaleWidth) | !buCompare5.EQ(num2, buMarbleCalc.varMarbleRunSettings.ScaleHeight) | !buCompare5.EQ(num3, buMarbleCalc.varMarbleRunSettings.ScaleDepth))
		{
			if (!buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio)
			{
				double num4 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num);
				double num5 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleHeight / num2);
				double num6 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleDepth / num3);
				if (num4 <= 0.0)
				{
					num4 = 1.0;
				}
				if (num5 <= 0.0)
				{
					num5 = 1.0;
				}
				if (num6 <= 0.0)
				{
					num6 = 1.0;
				}
				clsInit.cVector5.Scale(MinPoint, num4, num5, num6, ref EntityList);
			}
			else
			{
				double num7 = 1.0;
				double num8 = 1.0;
				double num9 = 1.0;
				if (buCompare5.EQ(num, buMarbleCalc.varMarbleRunSettings.ScaleWidth))
				{
					if (buCompare5.EQ(num2, buMarbleCalc.varMarbleRunSettings.ScaleHeight))
					{
						if (!buCompare5.EQ(num3, buMarbleCalc.varMarbleRunSettings.ScaleDepth))
						{
							num9 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleDepth / num3);
							num7 = num9;
							num8 = num9;
						}
					}
					else
					{
						num8 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleHeight / num2);
						num7 = num8;
						num9 = num8;
					}
				}
				else
				{
					num7 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num);
					num8 = num7;
					num9 = num7;
				}
				clsInit.cVector5.Scale(MinPoint, num7, num8, 1.0, ref EntityList);
			}
		}
		MinPoint = new Point3D(double.MaxValue, double.MaxValue, double.MaxValue);
		MaxPoint = new Point3D(double.MinValue, double.MinValue, double.MinValue);
		clsInit.cVector5.BoxSizeCalculate(EntityList, ref MinPoint, ref MaxPoint);
		clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref EntityList);
		CompositeCurve item = CompositeCurve.CreateRectangle(MaxPoint.X - MinPoint.X, MaxPoint.Y - MinPoint.Y);
		clsInit.appMarble.entitiesForMove.Add(item);
		cmdOperationCommon();
		MarbleTempVars.isSolidMove = false;
		for (int j = 0; j <= EntityList.Count - 1; j++)
		{
			Entity copiedEntity2 = null;
			buEntity.Copy(EntityList[j], ref copiedEntity2);
			MarbleTempVars.ImportedEntitites.Add(copiedEntity2);
		}
		MoveCreatedEntity = true;
		EntityList.Clear();
	}

