			return;
		}
		buMarbleCalc.varOperation.settingCutRemailMaterial = new marbleCutRemainMaterial(buMarbleForms.frmCutRemainMaterial.Settings);
		buMarbleCalc.varOperation.MaterialParameter = new marbleMaterialPars(buMarbleForms.frmCutRemainMaterial.SettingsMaterial);
		SaveMarbleFile();
		double num = buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialCutWidth + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset * 2.0;
		double num2 = buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialCutHeight + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset * 2.0;
		bool flag = buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalCutEnable;
		bool flag2 = buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalCutEnable;
		if (activeJob.Items.Count > 0)
		{
			clsInit.cMarble.GetBoxSizeJobItems(activeJob, ref activeJob.SizeOfOperations.MinPoint, ref activeJob.SizeOfOperations.MaxPoint);
			num = activeJob.SizeOfOperations.MaxPoint.X + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset;
			num2 = activeJob.SizeOfOperations.MaxPoint.Y + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset;
		}
		if (!buMarbleCalc.varOperation.settingCutRemailMaterial.UseMaterialData)
		{
			if (!buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalCutEnable)
			{
				num2 = buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialCutHeight + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset * 2.0;
			}
			if (!buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalCutEnable)
			{
				num = buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialCutWidth + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset * 2.0;
			}
		}
		else
		{
			double num3 = buMarbleCalc.varOperation.MaterialParameter.MaterialWidth - activeJob.SizeOfOperations.MaxPoint.X;
			double num4 = buMarbleCalc.varOperation.MaterialParameter.MaterialHeight - activeJob.SizeOfOperations.MaxPoint.Y;
			if (num3 < buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialHorizontalMinDistance)
			{
				flag2 = false;
			}
			if (num4 < buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialVerticalMinDistance)
			{
				flag = false;
			}
			if (!flag)
			{
				num2 = buMarbleCalc.varOperation.MaterialParameter.MaterialHeight + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset * 2.0;
			}
			if (!flag2)
			{
				num = buMarbleCalc.varOperation.MaterialParameter.MaterialWidth + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset * 2.0;
			}
		}
		if (flag)
		{
			buMarbleCalc.varOperation.settingSliceCut.CutLengthSingle = num + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset + 10.0;
			doAddItemSingleCut(new Point3D(0.0 - buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset, num2, 0.0), 0.0, 0.0, isFinished: true, 0);
		}
		if (flag2)
		{
			buMarbleCalc.varOperation.settingSliceCut.CutLengthSingle = num2 + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset + 10.0;
			doAddItemSingleCut(new Point3D(num, num2 + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset + 0.0, 0.0), 0.0, -90.0, isFinished: true, 0);
		}
	}

