	public void cmdAddCam()
	{
		if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand != MarbleOperationSelectionCommand.Item || !((buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0) & (buMarbleCalc.SelectedItem.ActiveItem.indexItem <= activeJob.Items.Count - 1)))
		{
			return;
		}
		MarbleItem Item = activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
		if (Item.ItemType == MarbleItemType.Shape3D)
		{
			if (buMarbleForms.frmCam3DCommands == null)
			{
				buMarbleForms.frmCam3DCommands = new F_MarbleCam3D();
			}
			buMarbleForms.frmCam3DCommands.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
			buMarbleForms.frmCam3DCommands.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			buMarbleForms.frmCam3DCommands.Init();
			buMarbleForms.frmCam3DCommands.ShowDialog();
			if (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.None)
			{
				return;
			}
			DialogResult dialogResult = DialogResult.Cancel;
			MarbleToolType selectedTool = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			if (!((buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.MillingRough3D) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.MillingParallelCut3D) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.MillingContantZ3D) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.MillingContantCusp3D) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.MillingPencil3D) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.MillingFlatland3D)))
			{
				if (!((buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.Rough3Plus2Front) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.Rough3Plus2Back) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.MillingParallelCut5D) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.MillingContantZ5D) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.MillingGeodesic5D) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.ProjectionRoundRough) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.ProjectionRoundFinish) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.PocketByDrilling) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.RoughRotary)))
				{
					if ((buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.SawMillingHorizontalFinish) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.SawMillingHorizontalRough) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.SawMillingRoughOutside) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.SawMillingVerticalFinish) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.SawMillingVerticalRough) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.CornerCleaning) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.Surface2D) | (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.RoughOutside))
					{
						F_MarbleToolSawMillingMillingHeadMenu f_MarbleToolSawMillingMillingHeadMenu = new F_MarbleToolSawMillingMillingHeadMenu();
						f_MarbleToolSawMillingMillingHeadMenu.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
						f_MarbleToolSawMillingMillingHeadMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Dispose;
						f_MarbleToolSawMillingMillingHeadMenu.PropertiesForm.FormPosition = FormStartPosition.CenterParent;
						f_MarbleToolSawMillingMillingHeadMenu.Init();
						f_MarbleToolSawMillingMillingHeadMenu.ShowDialog();
						selectedTool = f_MarbleToolSawMillingMillingHeadMenu.ToolType;
						dialogResult = f_MarbleToolSawMillingMillingHeadMenu.PropertiesForm.Result;
					}
				}
				else
				{
					F_MarbleToolMillingMillingHeadMenu f_MarbleToolMillingMillingHeadMenu = new F_MarbleToolMillingMillingHeadMenu();
					if ((buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.Saw) | (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.WaterJet))
					{
						buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = MarbleToolType.Milling;
					}
					f_MarbleToolMillingMillingHeadMenu.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
					f_MarbleToolMillingMillingHeadMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Dispose;
					f_MarbleToolMillingMillingHeadMenu.PropertiesForm.FormPosition = FormStartPosition.CenterParent;
					f_MarbleToolMillingMillingHeadMenu.Init();
					f_MarbleToolMillingMillingHeadMenu.ShowDialog();
					selectedTool = f_MarbleToolMillingMillingHeadMenu.ToolType;
					dialogResult = f_MarbleToolMillingMillingHeadMenu.PropertiesForm.Result;
				}
			}
			else
			{
				F_MarbleToolMillingMillingHeadMenu f_MarbleToolMillingMillingHeadMenu2 = new F_MarbleToolMillingMillingHeadMenu();
				if ((buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.Saw) | (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.WaterJet))
				{
					buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = MarbleToolType.Milling;
				}
				f_MarbleToolMillingMillingHeadMenu2.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
				f_MarbleToolMillingMillingHeadMenu2.PropertiesForm.FormCloseMode = FormCloseModeType.Dispose;
				f_MarbleToolMillingMillingHeadMenu2.PropertiesForm.FormPosition = FormStartPosition.CenterParent;
				f_MarbleToolMillingMillingHeadMenu2.Init();
				f_MarbleToolMillingMillingHeadMenu2.ShowDialog();
				selectedTool = f_MarbleToolMillingMillingHeadMenu2.ToolType;
				dialogResult = f_MarbleToolMillingMillingHeadMenu2.PropertiesForm.Result;
			}
			if (dialogResult == DialogResult.OK)
			{
				buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = selectedTool;
				if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.MillingRoughArea2D)
				{
					if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.MillingRoughInside2D)
					{
						if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.Surface2D)
						{
							if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.SawMillingHorizontalRough)
							{
								if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.SawMillingVerticalRough)
								{
									if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.SawMillingHorizontalFinish)
									{
										if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.SawMillingVerticalFinish)
										{
											if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.CornerCleaning)
											{
												if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.MillingRough3D)
												{
													if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.MillingParallelCut3D)
													{
														if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.MillingContantZ3D)
														{
															if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.MillingFlatland3D)
															{
																if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.MillingPencil3D)
																{
																	if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.MillingContantCusp3D)
																	{
																		if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.PocketByDrilling)
																		{
																			if (buMarbleForms.frmCam3DCommands.CommandType != MarbleCamType.MillingParallelCut5D)
																			{
