	public void cmdPointerSave()
	{
		SaveFileDialog saveFileDialog = new SaveFileDialog();
		saveFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathItems;
		saveFileDialog.Filter = "Dxf Files (.dxf)|*.dxf|Dwg Files (.dwg)|*.dwg|Stl Files (.stl)|*.stl";
		saveFileDialog.FilterIndex = 1;
		DialogResult dialogResult = saveFileDialog.ShowDialog();
		if (dialogResult != DialogResult.OK)
		{
			return;
		}
		string fileExtension = buFile5.getFileExtension(saveFileDialog.FileName);
		if (!((fileExtension.ToLower() == ".dxf") | (fileExtension.ToLower() == ".dwg")))
		{
			if (!(fileExtension.ToLower() == ".stl"))
			{
				return;
			}
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
			{
				Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
				if ((entity is Mesh || entity is Brep || entity is Surface) && entity.EntityData != null && entity.EntityData is CustomData)
				{
					CustomData customData = entity.EntityData as CustomData;
					if (customData.Command != null && ((customData.typeDefination == entityTypeDefination.MarbleItem) & (customData.Tags == "Solid")))
					{
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
					}
				}
			}
			buFile5.SaveStl(ccVars.Pages[ccVars.PageIndex].Form.viewportcad, saveFileDialog.FileName, 0.1, SelectedOnly: true);
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			return;
		}
		List<Entity> list = new List<Entity>();
		for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; j++)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j] is ICurve)
			{
				Entity copiedEntity = null;
				buEntity.Copy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j], ref copiedEntity);
				list.Add(copiedEntity);
			}
		}
		buFile5.SaveDxfDwg(list, saveFileDialog.FileName);
	}

	public void cmdPointerDrawEdit()
	{
		if (clsItem.frmEditor == null)
		{
			clsItem.frmEditor = new F_Editor();
		}
		clsVar.varEditorRuntimeSet.isSketchMode = false;
		clsVar.varEditorRuntimeSet.isSewingMode = false;
		clsItem.frmEditor = new F_Editor();
		clsItem.frmEditor.OpenFileExtension.Clear();
		clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
		clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dwg)|*.dwg");
		clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		clsItem.frmEditor.entitiesExisting.Clear();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (entity is ICurve && entity.EntityData != null && entity.EntityData is CustomData)
			{
				CustomData customData = entity.EntityData as CustomData;
				if (customData.typeDefination == entityTypeDefination.TempDraw)
				{
					Entity copiedEntity = null;
					buEntity.Copy(entity, ref copiedEntity);
					copiedEntity.LayerName = "Default";
					clsItem.frmEditor.entitiesExisting.Add(copiedEntity);
				}
			}
		}
		if (clsItem.frmEditor.entitiesExisting.Count > 0)
		{
			clsItem.frmEditor.Init();
			clsItem.frmEditor.ShowDialog(clsItem.FrmMain);
		}
	}

	public void cmdImportImage(ref Image image)
	{
		OpenFileDialog openFileDialog = new OpenFileDialog();
		openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathImportImage;
		openFileDialog.Filter = "All Drawing Files (*.png,*.jpg,*.bmp)|*.png;*.jpg;*.bmp;|Png Files (*.png)|*.png|Jpg Files (*.jpg)|*.jpg|Bmp Files (*.bmp)|*.bmp";
		openFileDialog.FilterIndex = 1;
		if (openFileDialog.ShowDialog() == DialogResult.OK)
		{
			buMarbleCalc.varMarbleRunSettings.pathImportImage = buFile5.GetPath(openFileDialog.FileName);
			buImage5.OpenImageAsStream(openFileDialog.FileName, ref image);
		}
	}

