	public void cmdCreateMaterial()
	{
		frmSheet.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmSheet.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		frmSheet.chk_addtonesting.Check = buMarbleCalc.varMarbleRunSettings.selectedSheetAddNesting;
		frmSheet.chk_editimage.Check = buMarbleCalc.varMarbleRunSettings.selectedSheetEdit;
		frmSheet.Init();
		frmSheet.ShowDialog();
		if (frmSheet.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varMarbleRunSettings.selectedSheetAddNesting = frmSheet.chk_addtonesting.Check;
		buMarbleCalc.varMarbleRunSettings.selectedSheetEdit = frmSheet.chk_editimage.Check;
		DirectoryInfo directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromSheet);
		if (!directoryInfo.Exists)
		{
			buMarbleCalc.varMarbleRunSettings.pathFromSheet = AppPath.Base + "\\External2DFiles\\Contour";
			directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromSheet);
			if (!directoryInfo.Exists)
			{
				buMarbleCalc.varMarbleRunSettings.pathFromSheet = AppPath.Base;
			}
		}
		List<buEntity> list = new List<buEntity>();
		if (frmSheet.SheetType == MarbleSheetMenuType.Editor)
		{
			if (clsItem.frmEditor == null)
			{
				clsItem.frmEditor = new F_Editor();
			}
			clsVar.varEditorRuntimeSet.isSketchMode = false;
			clsVar.varEditorRuntimeSet.isSewingMode = false;
			clsItem.frmEditor = new F_Editor();
			clsItem.frmEditor.OpenFileExtension.Clear();
			clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
			clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.frmEditor.ZoomOutValue = 2500;
			clsItem.frmEditor.Init();
			clsItem.frmEditor.ShowDialog(clsItem.FrmMain);
			for (int i = 0; i <= clsItem.frmEditor.viewport.Entities.Count - 1; i++)
			{
				buEntity copiedEntity = null;
				buEntity.Copy(clsItem.frmEditor.viewport.Entities[i], ref copiedEntity);
				if ((copiedEntity != null) & (clsItem.frmEditor.viewport.Entities[i] is ICurve))
				{
					list.Add(copiedEntity);
				}
			}
		}
		if (frmSheet.SheetType == MarbleSheetMenuType.FromFile)
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromSheet;
			openFileDialog.Filter = "All Drawing Files (*.Dxf,*.Dwg,*.bucadV5)|*.dxf;*.dwg;*.bucadV5;|Dxf Files (*.dxf)|*.dxf|Dwg Files (*.dwg)|*.dwg|BuCad Files (*.bucadV5)|*.bucadV5";
			openFileDialog.FilterIndex = 1;
			if (openFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromSheet = buFile5.GetPath(openFileDialog.FileName);
			FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
			if (!fileInfo.Exists)
			{
				return;
			}
			if ((fileInfo.Extension.ToLower() == ".dxf") | (fileInfo.Extension.ToLower() == ".dwg"))
			{
				List<Entity> EntityList = new List<Entity>();
				buFile5.OpenDxfDwg(ref EntityList, fileInfo.FullName);
				for (int j = 0; j <= EntityList.Count - 1; j++)
				{
					buEntity copiedEntity2 = null;
					buEntity.Copy(EntityList[j], ref copiedEntity2);
					list.Add(copiedEntity2);
				}
			}
			if (fileInfo.Extension.ToLower() == ".bucadv5")
			{
				List<Entity> refEntities = new List<Entity>();
				clsInit.appFiles.OpenBuCadFileVer5(fileInfo.FullName, Clear: true, ref refEntities);
				for (int k = 0; k <= refEntities.Count - 1; k++)
				{
					buEntity copiedEntity3 = null;
					buEntity.Copy(refEntities[k], ref copiedEntity3);
					list.Add(copiedEntity3);
				}
			}
			clsInit.appEditor.SaveEditorFile();
		}
		if (frmSheet.SheetType == MarbleSheetMenuType.FromList)
		{
			if (clsItem.FrmFromFile == null)
			{
				clsItem.FrmFromFile = new F_AddFromFile();
			}
			clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromSheet;
			clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
			clsItem.FrmFromFile.ExtensionList.Clear();
			clsItem.FrmFromFile.ExtensionList.Add(".dxf");
			clsItem.FrmFromFile.ExtensionList.Add(".dwg");
			clsItem.FrmFromFile.ExtensionList.Add(".bucad5");
			clsItem.FrmFromFile.MoveEntities = false;
			clsItem.FrmFromFile.Init();
			clsItem.FrmFromFile.ShowDialog();
			if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varMarbleRunSettings.pathFromSheet = clsItem.FrmFromFile.Path;
			clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
			for (int l = 0; l <= clsItem.FrmFromFile.viewport.Entities.Count - 1; l++)
			{
				buEntity copiedEntity4 = null;
				buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[l], ref copiedEntity4);
				list.Add(copiedEntity4);
			}
			clsInit.appEditor.SaveEditorFile();
		}
		if (frmSheet.SheetType == MarbleSheetMenuType.Data)
		{
			F_MaterialRect3D f_MaterialRect3D = new F_MaterialRect3D();
			CreateModelProperties Properties = new CreateModelProperties();
			clsInit.appCommand.EyeParameterToCreateModelProperties(clsVar.varPreviewViewport, clsVar.varMouse, ref Properties);
			Properties.CoordinateSystemIconVisible = false;
			Properties.ViewCubeIconVisible = false;
			Properties.OrigineCaptionVisible = false;
			Properties.ToolBorVisible = false;
			Properties.OrigineSize = 5;
			f_MaterialRect3D.viewportLayout = clsInit.cVector5.CreateModelControl(clsVar.UnlockKey, Properties);
			f_MaterialRect3D.viewportLayout.CompileUserInterfaceElements();
			f_MaterialRect3D.pnl_model.Controls.Add(f_MaterialRect3D.viewportLayout);
			f_MaterialRect3D.viewportLayout.Entities.Clear();
			f_MaterialRect3D.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			f_MaterialRect3D.Material = new MaterialBase5(buMarbleCalc.varOperation.MaterialParameter.MaterialWidth, buMarbleCalc.varOperation.MaterialParameter.MaterialHeight, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness);
			f_MaterialRect3D.Init(null);
			f_MaterialRect3D.StartPosition = FormStartPosition.CenterParent;
			f_MaterialRect3D.ShowDialog();
			if (f_MaterialRect3D.PropertiesForm.Result == DialogResult.OK)
			{
				buMarbleCalc.varOperation.MaterialParameter.MaterialWidth = f_MaterialRect3D.Material.Size.Width;
				buMarbleCalc.varOperation.MaterialParameter.MaterialHeight = f_MaterialRect3D.Material.Size.Height;
				buMarbleCalc.varOperation.MaterialParameter.MaterialThickness = f_MaterialRect3D.Material.Size.Depth;
				buEntity rectangleEntity = null;
				clsInit.cVector5.DrawRectangle(new Point3D(), buMarbleCalc.varOperation.MaterialParameter.MaterialWidth, buMarbleCalc.varOperation.MaterialParameter.MaterialHeight, Plane.XY, ref rectangleEntity);
				list.Add(rectangleEntity);
			}
		}
		if (list.Count <= 0)
		{
			return;
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedSheetEdit)
		{
			if (clsItem.frmEditor == null)
			{
				clsItem.frmEditor = new F_Editor();
			}
			clsVar.varEditorRuntimeSet.isSketchMode = false;
			clsVar.varEditorRuntimeSet.isSewingMode = false;
			clsItem.frmEditor = new F_Editor();
			clsItem.frmEditor.OpenFileExtension.Clear();
			clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
			clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.frmEditor.entitiesExisting.Clear();
			for (int m = 0; m <= list.Count - 1; m++)
			{
				Entity copiedEntity5 = null;
				buEntity.Copy(list[m], ref copiedEntity5);
				if (copiedEntity5 != null)
				{
					clsItem.frmEditor.entitiesExisting.Add(copiedEntity5);
				}
			}
			clsItem.frmEditor.Init();
			clsItem.frmEditor.ShowDialog(clsItem.FrmMain);
			list = new List<buEntity>();
			for (int n = 0; n <= clsItem.frmEditor.viewport.Entities.Count - 1; n++)
			{
				buEntity copiedEntity6 = null;
				buEntity.Copy(clsItem.frmEditor.viewport.Entities[n], ref copiedEntity6);
				if ((copiedEntity6 != null) & (clsItem.frmEditor.viewport.Entities[n] is ICurve))
				{
					list.Add(copiedEntity6);
				}
			}
		}
		List<buEntitiesGroup> Groups = new List<buEntitiesGroup>();
		clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), list, Plane.XY, ref Groups);
		if (Groups.Count <= 0)
		{
			return;
		}
		if (!buMarbleCalc.varMarbleRunSettings.selectedSheetAddNesting)
		{
			activeJob.SheetGroup = new buEntitiesGroup(Groups[0]);
			Entity entMarble = null;
			Entity entMarble2 = null;
			Point3D offset = new Point3D();
			activeJob.SheetSolidEntities = new List<Entity>();
			CreateMarbleMaterial(activeJob.SheetGroup, Math.Abs(buMarbleCalc.varMarbleMachineSettings.BaseWoodZOffset), offset, TopOnZero: true, MarbleTempVars.layerMarbleSheet.Name, ref entMarble);
			CreateMarbleMaterial(activeJob.SheetGroup, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, offset, TopOnZero: false, MarbleTempVars.layerMarbleSheet.Name, ref entMarble2);
			if (entMarble != null && entMarble2 != null)
			{
				entMarble2.ColorMethod = colorMethodType.byEntity;
				entMarble2.Color = Color.FromArgb(150, MarbleTempVars.layerMarbleSheet.Color);
				entMarble2.Selectable = false;
				entMarble.Translate(0.01, 0.01);
				entMarble.Selectable = false;
				activeJob.SheetSolidEntities.Add(entMarble);
				activeJob.SheetSolidEntities.Add(entMarble2);
				clsInit.cVector5.BoxSizeCalculate(activeJob.SheetGroup, ref activeJob.Material.BoxMinPoint, ref activeJob.Material.BoxMaxPoint);
				activeJob.Material.BoxMinPoint.Z = 0.0;
				activeJob.Material.BoxMaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
				activeJob.Material.Size.Width = activeJob.Material.BoxMaxPoint.X - activeJob.Material.BoxMinPoint.X;
				activeJob.Material.Size.Height = activeJob.Material.BoxMaxPoint.Y - activeJob.Material.BoxMinPoint.Y;
				activeJob.Material.Size.Depth = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
				AddOrUpdateMarbleSheet(activeJob.SheetSolidEntities, activeJob.SheetGroup);
				JobUpdate();
			}
			buEyeItems.viewportCadCam.Invalidate();
		}
		else if (clsInit.appNesting != null)
		{
			for (int num = 0; num <= Groups.Count - 1; num++)
			{
				clsInit.appNesting.doAddShapeSheet(Groups[num]);
			}
		}
	}

	public void cmdCreateMaterialFromPhoto()
	{
		string text = "";
		double width = 0.0;
		double height = 0.0;
		frmImageMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmImageMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
		frmImageMenu.chk_addtonesting.Check = buMarbleCalc.varMarbleRunSettings.selectedPhotoAddNesting;
		frmImageMenu.chk_editimage.Check = buMarbleCalc.varMarbleRunSettings.selectedPhotoEdit;
		frmImageMenu.Init();
		frmImageMenu.ShowDialog();
		if (frmImageMenu.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		buMarbleCalc.varMarbleRunSettings.selectedPhotoAddNesting = frmImageMenu.chk_addtonesting.Check;
		buMarbleCalc.varMarbleRunSettings.selectedPhotoEdit = frmImageMenu.chk_editimage.Check;
		DirectoryInfo directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromPhoto);
		if (!directoryInfo.Exists)
		{
			buMarbleCalc.varMarbleRunSettings.pathFromPhoto = AppPath.Base + "\\Materials\\Marble";
			directoryInfo = new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromPhoto);
			if (!directoryInfo.Exists)
			{
				buMarbleCalc.varMarbleRunSettings.pathFromPhoto = AppPath.Base;
			}
		}
		if (frmImageMenu.PhotoType == MarblePhotoMenuType.FromFile)
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromPhoto;
			openFileDialog.Filter = "All Image Files Files (*.Png,*.Jpg,*.Jpeg,*.Bmp)|*.png;*.jpg;*.jpeg;*.bmp|PNG Files (*.png)|*.png|JpegFiles (*.jpeg,*.jpg)|*.jpg;*.jpeg|BMP Files (*.bmp)|*.bmp";
			openFileDialog.FilterIndex = 1;
			if (openFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			text = buFile5.getFileNameWithoutExtension(openFileDialog.FileName);
			buMarbleCalc.varMarbleRunSettings.pathFromPhoto = buFile5.GetPath(openFileDialog.FileName);
			FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
			if (!fileInfo.Exists)
			{
				return;
			}
			activeJob.Material.matImage = Image.FromFile(fileInfo.FullName);
			width = (double)activeJob.Material.matImage.Width * buMarbleCalc.varImageSettings.PixelToMmX;
			height = (double)activeJob.Material.matImage.Height * buMarbleCalc.varImageSettings.PixelToMmY;
			buEntity rectangleEntity = null;
			clsInit.cVector5.DrawRectangle(new Point3D(), width, height, Plane.XY, ref rectangleEntity);
			activeJob.SheetGroup = new buEntitiesGroup();
			activeJob.SheetGroup.Outside.Entities.Add(rectangleEntity);
			clsInit.appEditor.SaveEditorFile();
		}
		if (frmImageMenu.PhotoType == MarblePhotoMenuType.FromList)
		{
			if (clsItem.FrmImageFromFile == null)
			{
				clsItem.FrmImageFromFile = new F_AddImageFromFile();
			}
			clsItem.FrmImageFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmImageFromFile.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmImageFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromPhoto;
			clsItem.FrmImageFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
			clsItem.FrmImageFromFile.ExtensionList.Clear();
			clsItem.FrmImageFromFile.ExtensionList.Add(".png");
			clsItem.FrmImageFromFile.ExtensionList.Add(".jpg");
			clsItem.FrmImageFromFile.ExtensionList.Add(".jpeg");
			clsItem.FrmImageFromFile.ExtensionList.Add(".bmp");
			clsItem.FrmImageFromFile.MoveEntities = false;
			clsItem.FrmImageFromFile.Init();
			clsItem.FrmImageFromFile.ShowDialog();
			if (clsItem.FrmImageFromFile.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			text = buFile5.getFileNameWithoutExtension(clsItem.FrmImageFromFile.FileName);
			activeJob.Material.matImage = clsItem.FrmImageFromFile.refImage;
			width = (double)activeJob.Material.matImage.Width * buMarbleCalc.varImageSettings.PixelToMmX;
			height = (double)activeJob.Material.matImage.Height * buMarbleCalc.varImageSettings.PixelToMmY;
			buEntity rectangleEntity2 = null;
			clsInit.cVector5.DrawRectangle(new Point3D(), width, height, Plane.XY, ref rectangleEntity2);
			activeJob.SheetGroup = new buEntitiesGroup();
			activeJob.SheetGroup.Outside.Entities.Add(rectangleEntity2);
			buMarbleCalc.varMarbleRunSettings.pathFromPhoto = clsItem.FrmImageFromFile.Path;
			clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmImageFromFile.KeepRatio;
			clsInit.appEditor.SaveEditorFile();
		}
		if (!((activeJob.Material.matImage != null) & (activeJob.SheetGroup != null)))
		{
			return;
		}
		if (buMarbleCalc.varMarbleRunSettings.selectedPhotoEdit)
		{
			if (clsItem.frmEditor == null)
			{
				clsItem.frmEditor = new F_Editor();
			}
			clsVar.varEditorRuntimeSet.isSketchMode = false;
			clsVar.varEditorRuntimeSet.isSewingMode = false;
			clsItem.frmEditor = new F_Editor();
			clsItem.frmEditor.OpenFileExtension.Clear();
			clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
			clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.frmEditor.refImage = (Image)activeJob.Material.matImage.Clone();
			clsItem.frmEditor.refImageSize = new SizeObject(width, height, 0.0);
			clsItem.frmEditor.ZoomOutValue = 2500;
			clsItem.frmEditor.Init();
			clsItem.frmEditor.ShowDialog(clsItem.FrmMain);
			List<buEntity> BaseRefEntities = new List<buEntity>();
			for (int i = 0; i <= clsItem.frmEditor.viewport.Entities.Count - 1; i++)
			{
				buEntity copiedEntity = null;
				buEntity.Copy(clsItem.frmEditor.viewport.Entities[i], ref copiedEntity);
				if ((copiedEntity != null) & (clsItem.frmEditor.viewport.Entities[i] is ICurve))
				{
					BaseRefEntities.Add(copiedEntity);
				}
			}
			if (BaseRefEntities.Count > 0)
			{
				SortbuSettings sortbuSettings = new SortbuSettings();
				SortbuResult Result = new SortbuResult();
				sortbuSettings.Option.IntersectionRules = SortingIntersectionRulesType.LowerIndex;
				sortbuSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
				List<buEntity> SortedEntities = new List<buEntity>();
				List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
				clsInit.cVector5.SortEntitiesByRefPoint(BaseRefEntities[0].StartPoint, ref BaseRefEntities, sortbuSettings, ref SortedEntities, ref Result);
				clsInit.cVector5.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
				for (int j = 0; j <= SplitedEntitites.Count - 1; j++)
				{
					if (clsInit.cVector5.isEntitiesClosed(SplitedEntitites[j]))
					{
						if (activeJob.SheetGroup.Inside == null)
						{
							activeJob.SheetGroup.Inside = new List<buEntityList>();
						}
						buEntityList buEntityList2 = new buEntityList();
						buEntity.Copy(SplitedEntitites[j], ref buEntityList2.Entities);
						activeJob.SheetGroup.Inside.Add(buEntityList2);
					}
				}
			}
		}
		if (!buMarbleCalc.varMarbleRunSettings.selectedPhotoAddNesting)
		{
			Entity entMarble = null;
			Entity entMarble2 = null;
			Point3D offset = new Point3D();
			activeJob.SheetSolidEntities = new List<Entity>();
			CreateMarbleMaterial(activeJob.SheetGroup, Math.Abs(buMarbleCalc.varMarbleMachineSettings.BaseWoodZOffset), offset, TopOnZero: true, MarbleTempVars.layerMarbleSheet.Name, ref entMarble);
			CreateMarbleMaterial(activeJob.SheetGroup, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, offset, TopOnZero: false, MarbleTempVars.layerMarbleSheet.Name, ref entMarble2);
			if (entMarble != null && entMarble2 != null)
			{
				entMarble2.ColorMethod = colorMethodType.byEntity;
				entMarble2.Color = Color.FromArgb(50, MarbleTempVars.layerMarbleSheet.Color);
				entMarble2.Selectable = false;
				entMarble.Translate(0.01, -0.11);
				entMarble.Selectable = false;
				entMarble2.Selectable = false;
				activeJob.SheetSolidEntities.Add(entMarble);
				activeJob.SheetSolidEntities.Add(entMarble2);
				int num = -1;
				for (int k = 0; k <= buEyeItems.viewportCadCam.Materials.Count - 1; k++)
				{
					if (text == buEyeItems.viewportCadCam.Materials[k].Name)
					{
						num = k;
					}
				}
				if (num >= 0)
				{
					buEyeItems.viewportCadCam.Materials.RemoveAt(num);
				}
				Bitmap image = new Bitmap(activeJob.Material.matImage);
				Material material = new Material(text, Color.FromArgb(100, 100, 100), Color.White, 1f, image.ToByteArray())
				{
					LinearUnits = linearUnitsType.Millimeters,
					MassUnits = massUnitsType.Kilograms,
					Density = 6E-07,
					TextureLength = 2000f,
					Environment = 0.01f
				};
				buEyeItems.viewportCadCam.Materials.Add(material);
				buEyeItems.viewportCadCam.Layers[MarbleTempVars.layerMarbleSheet.Name].MaterialName = material.Name;
				clsInit.cVector5.BoxSizeCalculate(activeJob.SheetGroup, ref activeJob.Material.BoxMinPoint, ref activeJob.Material.BoxMaxPoint);
				activeJob.Material.BoxMinPoint.Z = 0.0;
				activeJob.Material.BoxMaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
				activeJob.Material.Size.Width = activeJob.Material.BoxMaxPoint.X - activeJob.Material.BoxMinPoint.X;
				activeJob.Material.Size.Height = activeJob.Material.BoxMaxPoint.Y - activeJob.Material.BoxMinPoint.Y;
				activeJob.Material.Size.Depth = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
				AddOrUpdateMarbleSheet(activeJob.SheetSolidEntities, activeJob.SheetGroup);
				JobUpdate();
			}
			buEyeItems.viewportCadCam.Invalidate();
		}
		else if (clsInit.appNesting != null)
		{
			clsInit.appNesting.doAddShapeSheet(activeJob.SheetGroup);
		}
	}

	public void cmdMenuPageCommandExecute(object Data1, object Data2, object Data3, object Data4, object Data5)
	{
		if (Data1 == null)
		{
			return;
		}
		if (Data1.ToString() == "ContourSetting")
		{
			F_MarbleContour f_MarbleContour = new F_MarbleContour();
			f_MarbleContour.varSettings.settingMarbleCam = new marbleCamPars(buMarbleCalc.varOperation.settingMarbleCam);
			f_MarbleContour.Properties.FormCloseMode = FormCloseModeType.Dispose;
			f_MarbleContour.Properties.FormPosition = FormStartPosition.CenterParent;
			f_MarbleContour.Init();
			f_MarbleContour.ShowDialog();
			if (f_MarbleContour.Properties.Result == DialogResult.OK)
			{
				buMarbleCalc.varOperation.settingMarbleCam = new marbleCamPars(f_MarbleContour.varSettings.settingMarbleCam);
				AppBool.SaveByTick = true;
			}
		}
		if (Data1.ToString() == "ToolSetting" && Data2 != null && Data2.GetType() == typeof(MarbleToolType))
		{
			MarbleToolType marbleToolType = (MarbleToolType)Data2;
			clsInit.appCommand.cmdToolSelect();
			if (marbleToolType == MarbleToolType.Milling)
			{
				if (!((ccVars.toolActive.Purpose == ToolPurpose.General) | (ccVars.toolActive.Purpose == ToolPurpose.Milling) | (ccVars.toolActive.Purpose == ToolPurpose.Milling5Axis)))
				{
					buString5.MessageBoxWarning(AppLanguage.CadCamMessages[134]);
				}
				else
				{
					buMarbleCalc.activeToolMilling = new ToolBase5(ccVars.toolActive);
				}
			}
			if (marbleToolType == MarbleToolType.MillingHead)
			{
				if (!((ccVars.toolActive.Purpose == ToolPurpose.General) | (ccVars.toolActive.Purpose == ToolPurpose.MillingHead)))
				{
					buString5.MessageBoxWarning(AppLanguage.CadCamMessages[134]);
				}
				else
				{
					buMarbleCalc.activeToolMillingHead = new ToolBase5(ccVars.toolActive);
				}
			}
			if (marbleToolType == MarbleToolType.Saw)
			{
				if (ccVars.toolActive.Purpose != ToolPurpose.Saw)
				{
					buString5.MessageBoxWarning(AppLanguage.CadCamMessages[134]);
				}
				else
				{
					buMarbleCalc.activeToolSaw = new ToolBase5(ccVars.toolActive);
				}
			}
			if (marbleToolType == MarbleToolType.WaterJet)
			{
				if (ccVars.toolActive.Purpose != ToolPurpose.WaterJet)
				{
					buString5.MessageBoxWarning(AppLanguage.CadCamMessages[134]);
				}
				else
				{
					buMarbleCalc.activeToolWaterjet = new ToolBase5(ccVars.toolActive);
				}
			}
		}
		if (Data1.ToString() == "CamSetting" && Data2 != null && Data2.GetType() == typeof(MarbleItemType))
		{
			MarbleItemType marbleItemType = (MarbleItemType)Data2;
			if (marbleItemType == MarbleItemType.Profiling || marbleItemType == MarbleItemType.ProfileCurve)
			{
				cmdMenuPageProfileCommandExecute(marbleItemType, Data1, Data2, Data3, Data4, Data5);
			}
			if (marbleItemType == MarbleItemType.Engraving)
			{
				cmdMenuPageEngraveCommandExecute(marbleItemType, Data1, Data2, Data3, Data4, Data5);
			}
			if (marbleItemType == MarbleItemType.Milling5AxisRotary)
			{
				cmdMenuPageEngraveCommandExecute(marbleItemType, Data1, Data2, Data3, Data4, Data5);
			}
			if (marbleItemType == MarbleItemType.Contour || marbleItemType == MarbleItemType.Library || marbleItemType == MarbleItemType.Shape)
			{
				cmdMenuPageContourCommandExecute(marbleItemType, Data1, Data2, Data3, Data4, Data5);
			}
			if (marbleItemType == MarbleItemType.Text || marbleItemType == MarbleItemType.Text3D || marbleItemType == MarbleItemType.TextWireframe)
			{
				cmdMenuPageTextCommandExecute(marbleItemType, Data1, Data2, Data3, Data4, Data5);
			}
			if (marbleItemType == MarbleItemType.SawHorizontalMillingRough || marbleItemType == MarbleItemType.SawVerticalMillingRough)
			{
				cmdMenuPageSawMillingCommandExecute(marbleItemType, Data1, Data2, Data3, Data4, Data5);
			}
		}
	}

