	public void cmdShowLanguage()
	{
		if (buMarbleForms.frmLangMenu == null)
		{
			buMarbleForms.frmLangMenu = new F_MarbleLanguageMenu();
		}
		buMarbleForms.frmLangMenu.Language = clsVar.varRuntime.Language;
		buMarbleForms.frmLangMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		buMarbleForms.frmLangMenu.Init();
		buMarbleForms.frmLangMenu.StartPosition = FormStartPosition.CenterParent;
		buMarbleForms.frmLangMenu.ShowDialog(clsItem.FrmMain);
		if (buMarbleForms.frmLangMenu.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		clsVar.varRuntime.Language = buMarbleForms.frmLangMenu.Language;
		clsInit.appSystem.SetLanguage(clsVar.varRuntime.Language, AppPath.Settings + "\\Runtime.prm", Message: false);
		if (clsVar.varRuntime.Language != 0)
		{
			if (clsVar.varRuntime.Language != 1)
			{
				if (clsVar.varRuntime.Language == 2)
				{
					buLangTranslate.ChangeLanguage("Chinese");
				}
			}
			else
			{
				buLangTranslate.ChangeLanguage("Turkish");
			}
		}
		else
		{
			buLangTranslate.ChangeLanguage("English");
		}
		LoadLanguage();
	}

	public void cmdSetAngle()
	{
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (((entity.EntityData != null) & (entity.EntityData is CustomData)) && ((CustomData)entity.EntityData).Tags == "Edge")
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selectable = true;
			}
		}
		MarbleTempVars.SetAngle = true;
	}

	public void cmdShowGcode()
	{
		if (activeJob != null)
		{
			string strGCodes = "";
			if (!activeJob.CamCalculated)
			{
				doCamCalculateMarbleJob(ref activeJob);
			}
			if (!activeJob.isGCodeCreated)
			{
				doCreateGCode(activeJob, ref strGCodes);
			}
			F_Notepad f_Notepad = new F_Notepad();
			f_Notepad.Init(strGCodes);
			f_Notepad.Show();
			if (clsItem.FrmProgress != null)
			{
				clsItem.FrmProgress.Visible = false;
			}
		}
	}

	public void cmdCreateGCode()
	{
		if (activeJob == null)
		{
			return;
		}
		activeJob.CamCalculated = false;
		for (int i = 0; i <= activeJob.Items.Count - 1; i++)
		{
			for (int j = 0; j <= activeJob.Items[i].CamList.Count - 1; j++)
			{
				activeJob.Items[i].CamList[j].isCamCalculated = false;
			}
		}
		doCamCalculateMarbleJob(ref activeJob);
	}

	public void cmdStartSimulation()
	{
		if (SimIndex != -1)
		{
			timSim.Enabled = true;
			return;
		}
		lastSimToolPurpose = ToolPurpose.None;
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
		DeleteSimulationEntities();
		DrawSimulationEntities(cam: false, machine: true, DrawAllTool: true, MarbleToolType.Saw);
		if (!ccVars.Pages[ccVars.PageIndex].Form.viewportcad.IsAnimationRunning)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
		}
		SimToolIndex = 0;
		SimIndex = 0;
		SimItemIndex = 0;
		timSim.Enabled = true;
	}

	public void cmdStopSimulation()
	{
		if (!timSim.Enabled)
		{
			SimIndex = -1;
			SimItemIndex = -1;
			SimToolIndex = -1;
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
			DeleteSimulationEntities();
		}
		else
		{
			timSim.Enabled = false;
		}
	}

	public void cmdNextSimulation()
	{
		Sim_Tick(null, null);
	}

	public void cmdPreSimulation()
	{
		SimIndex -= SimStep;
		SimIndex -= SimStep;
		if (SimIndex < 0)
		{
			if (SimItemIndex > 0)
			{
				SimItemIndex--;
			}
			if (SimItemIndex >= 0)
			{
				SimIndex = activeJob.Cams[SimItemIndex].SimilationPoint.SimMove.Count - SimStep - 1;
			}
		}
		Sim_Tick(null, null);
		timSim.Enabled = false;
	}

	public void cmdCalculate()
	{
		doCamCalculateMarbleJob(ref activeJob);
	}

	public void cmdTakePhoto(Image image)
	{
		try
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i] is Picture && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData != null && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData is CustomData)
				{
					CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
					if (customData.typeDefination == entityTypeDefination.CameraImage)
					{
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
					}
				}
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
			MarbleTempVars.CameraImage = null;
			AppBool.CameraCaptured = false;
			Image image2 = null;
			if (image != null)
			{
				image2 = (Image)image.Clone();
				if (image2 == null)
				{
					return;
				}
				_ = image2.Width;
				_ = image2.Height;
				Bitmap bmp = (Bitmap)image2.Clone();
				bmp = buImage5.CropBitmap(bmp, buMarbleCalc.varMarbleSettings.CameraCropX, buMarbleCalc.varMarbleSettings.CameraCropY, buMarbleCalc.varMarbleSettings.CameraCropWidth, buMarbleCalc.varMarbleSettings.CameraCropHeight);
				byte[] image3 = bmp.ToByteArray();
				if (buMarbleCalc.varMarbleSettings.CopyImageToArchive)
				{
					DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.Base + "\\ImageArchive");
					if (!directoryInfo.Exists)
					{
						directoryInfo.Create();
					}
					string text = DateTime.Now.Year.ToString("D2") + DateTime.Now.Month.ToString("D2") + DateTime.Now.Day.ToString("D2") + "_" + DateTime.Now.Hour.ToString("D2") + DateTime.Now.Minute.ToString("D2") + DateTime.Now.Second.ToString("D2");
					bmp.Save(AppPath.Base + "\\ImageArchive\\ArciveImage_" + text + ".jpg");
				}
				double cameraImageOffsetX = buMarbleCalc.varMarbleSettings.CameraImageOffsetX;
				double cameraImageOffsetY = buMarbleCalc.varMarbleSettings.CameraImageOffsetY;
				if (!buMarbleCalc.varMarbleSettings.AutoLensCalibrationFromMaterialHeight)
				{
				}
				Picture picture = new Picture(Plane.XY, buMarbleCalc.varMarbleSettings.CameraImageWidth, buMarbleCalc.varMarbleSettings.CameraImageHeight, image3);
				if (buMarbleCalc.varMarbleSettings.ImageRotateAngle == 0.0)
				{
				}
				picture.Translate(cameraImageOffsetX, cameraImageOffsetY, buMarbleCalc.varMarbleSettings.ImageZPosition);
				picture.Selectable = false;
				picture.LayerName = MarbleTempVars.layerWood.Name;
				picture.Lighted = false;
				CustomData customData2 = new CustomData();
				customData2.typeDefination = entityTypeDefination.CameraImage;
				picture.EntityData = customData2;
				picture.Regen(0.1);
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(picture);
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
				AppBool.CameraCapturing = false;
				AppBool.CameraCaptured = true;
				image2 = null;
			}
			else
			{
				if (okCommandWithFiveDataEventHandler_0 != null)
				{
					okCommandWithFiveDataEventHandler_0(MarbleHMICommands.ShowWarning, buLangTranslate.preSentences.ImageIsNull, null, null, null);
				}
				doReset();
			}
		}
		catch (Exception)
		{
			AppBool.CameraCapturing = false;
		}
	}

