	public void cmdSettingsOperation()
	{
		string text = "cmdSettingsOperation";
		try
		{
			F_SettingsTreeView f_SettingsTreeView = new F_SettingsTreeView();
			f_SettingsTreeView.CaptionHeader.Clear();
			f_SettingsTreeView.Classes = new List<object>();
			f_SettingsTreeView.Classes.Add(new MarbleItemSettings(buMarbleCalc.varOperation));
			f_SettingsTreeView.Init();
			f_SettingsTreeView.StartPosition = FormStartPosition.CenterParent;
			f_SettingsTreeView.ShowDialog();
			if (f_SettingsTreeView.Result == DialogResult.OK)
			{
				buMarbleCalc.varOperation = new MarbleItemSettings((MarbleItemSettings)f_SettingsTreeView.Classes[0]);
				buLogVer5.addToLog(string_0, text, "Ok", "", 0.0, 0.0, AddException: true);
				SaveMarbleFile();
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void cmdSettingProgram()
	{
		clsInit.appCommand.cmdOptionsSettings(DontSave: true);
		if (!AppBool.Saving)
		{
			Task.Run(delegate
			{
				clsFiles.SaveParameterLess(AppPath.MachineSettingsCam);
			});
		}
	}

