	public void cmdMenuPopupClick(object sender, EventArgs e)
	{
		Control control = sender as Control;
		if (control == null)
		{
			sender.GetType().ToString();
			if (sender is ToolStripMenuItem)
			{
				control = new Control();
				control.Name = ((ToolStripMenuItem)sender).Name;
			}
		}
		if (control.Name == clsItem.FrmMarbleJob.mnu_camedit.Name)
		{
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if (control.Name == clsItem.FrmMarbleJob.mnu_camadd.Name)
		{
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if ((control.Name == clsItem.FrmMarbleJob.btn_deletecam.Name) | (control.Name == clsItem.FrmMarbleJob.mnu_camdeleteall.Name))
		{
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
			doDeleteCam(clsItem.FrmMarbleJob.chk_deletaallcam.Check, buMarbleCalc.SelectedItem.ActiveItem.indexItem, buMarbleCalc.SelectedItem.ActiveItem.indexCam);
		}
		if (control.Name == clsItem.FrmMarbleJob.mnu_camdelete.Name)
		{
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
			doDeleteCam(All: false, buMarbleCalc.SelectedItem.ActiveItem.indexItem, buMarbleCalc.SelectedItem.ActiveItem.indexCam);
		}
		if (control.Name == clsItem.FrmMarbleJob.btn_menu.Name)
		{
			if (clsItem.FrmMarbleJob.pnl_menu.Visible)
			{
				clsItem.FrmMarbleJob.pnl_menu.Visible = false;
			}
			else
			{
				clsItem.FrmMarbleJob.pnl_menu.Visible = true;
			}
		}
		if (control.Name == clsItem.FrmMarbleJob.btn_menuclose.Name)
		{
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if ((control.Name == clsItem.FrmMarbleJob.btn_itemremove.Name) | (control.Name == clsItem.FrmMarbleJob.mnu_OPdelete.Name))
		{
			doDeleteItems(All: false, buMarbleCalc.SelectedItem.ActiveItem.indexItem);
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if (control.Name == clsItem.FrmMarbleJob.btn_OPdelete.Name)
		{
			doDeleteItems(clsItem.FrmMarbleJob.chk_deleteall.Check, buMarbleCalc.SelectedItem.ActiveItem.indexItem);
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if (control.Name == clsItem.FrmMarbleJob.mnu_OPdeleteall.Name)
		{
			doDeleteItems(All: true, -1);
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if ((control.Name == clsItem.FrmMarbleJob.btn_OPDisable.Name) | (control.Name == clsItem.FrmMarbleJob.mnu_OPdisable.Name))
		{
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if ((control.Name == clsItem.FrmMarbleJob.btn_OPdown.Name) | (control.Name == clsItem.FrmMarbleJob.btn_itemdown.Name) | (control.Name == clsItem.FrmMarbleJob.mnu_OPdown.Name))
		{
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if ((control.Name == clsItem.FrmMarbleJob.btn_OPedit.Name) | (control.Name == clsItem.FrmMarbleJob.btn_itemedit.Name) | (control.Name == clsItem.FrmMarbleJob.mnu_OPedit.Name))
		{
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if ((control.Name == clsItem.FrmMarbleJob.btn_OPmove.Name) | (control.Name == clsItem.FrmMarbleJob.btn_itemmove.Name) | (control.Name == clsItem.FrmMarbleJob.mnu_OPMove.Name))
		{
			if (frmMove.Visible)
			{
				doMoveExecute("Close", null, null);
				frmMove.Visible = false;
			}
			else
			{
				tempJob = new MarbleJob(activeJob);
				frmMove.spn_move.Value = buMarbleCalc.varMarbleRunSettings.ManuelMove;
				frmMove.spn_rotate.Value = buMarbleCalc.varMarbleRunSettings.ManuelRotate;
				frmMove.TopMost = true;
				frmMove.Show();
			}
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if ((control.Name == clsItem.FrmMarbleJob.btn_OPup.Name) | (control.Name == clsItem.FrmMarbleJob.btn_itemup.Name) | (control.Name == clsItem.FrmMarbleJob.mnu_OPup.Name))
		{
			clsItem.FrmMarbleJob.pnl_menu.Visible = false;
		}
		if (control.Name == clsItem.FrmMarbleJob.mnu_redraw.Name)
		{
			for (int i = 0; i <= activeJob.Items.Count - 1; i++)
			{
				for (int j = 0; j <= activeJob.Items[i].CamList.Count - 1; j++)
				{
					activeJob.Items[i].CamList[j].isCamCalculated = false;
				}
			}
			activeJob.CamCalculated = false;
			doCamCalculateMarbleJob(ref activeJob);
			JobUpdate();
			doDrawActiveJob();
		}
		if (clsItem.ModelMainPreview == null)
		{
			return;
		}
		if (control.Name == clsItem.FrmMarbleJob.btn_viewfront.Name)
		{
			clsItem.ModelMainPreview.SetView(viewType.Front);
		}
		if (control.Name == clsItem.FrmMarbleJob.btn_viewleft.Name)
		{
			clsItem.ModelMainPreview.SetView(viewType.Left);
		}
		if (control.Name == clsItem.FrmMarbleJob.btn_viewtop.Name)
		{
			clsItem.ModelMainPreview.SetView(viewType.Top);
		}
		if (control.Name == clsItem.FrmMarbleJob.btn_viewtri.Name)
		{
			clsItem.ModelMainPreview.SetView(viewType.Trimetric);
		}
		if (control.Name == clsItem.FrmMarbleJob.btn_zoomfit.Name)
		{
			clsItem.ModelMainPreview.ZoomFit(5);
		}
		if (control.Name == clsItem.FrmMarbleJob.btn_preview.Name)
		{
			clsItem.FrmPreviewMulti = new F_PreviewMulti();
			for (int k = 0; k <= clsItem.ModelMainPreview.Materials.Count - 1; k++)
			{
				clsItem.FrmPreviewMulti.viewport_preview.Materials.AddOrReplace((Material)clsItem.ModelMainPreview.Materials[k].Clone());
			}
			for (int l = 0; l <= clsItem.ModelMainPreview.Layers.Count - 1; l++)
			{
				clsItem.FrmPreviewMulti.viewport_preview.Layers.AddOrReplace((Layer)clsItem.ModelMainPreview.Layers[l].Clone());
			}
			for (int m = 0; m <= clsItem.ModelMainPreview.Entities.Count - 1; m++)
			{
				clsItem.FrmPreviewMulti.viewport_preview.Entities.Add((Entity)clsItem.ModelMainPreview.Entities[m].Clone());
			}
			clsItem.FrmPreviewMulti.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmPreviewMulti.Init();
			clsItem.FrmPreviewMulti.ShowDialog();
			clsItem.FrmPreviewMulti.Dispose();
			clsItem.ModelMainPreview.ZoomFit(5);
		}
	}

	public void cmdTick(object sender, EventArgs e)
	{
		timCommand.Enabled = false;
		if ((clsInit.appMarble.activeItemType == MarbleItemType.VerticalCut) | (clsInit.appMarble.activeItemType == MarbleItemType.HorizontalCut))
