		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void AddCompositeCurvePoint(Point3D Points)
	{
		if (ccVars.pntDynamicCompositeCurve.Count != 0)
		{
			if (MarbleTempVars.DrawIsArc)
			{
				if (ccVars.pntDynamicCompositeCurve[ccVars.pntDynamicCompositeCurve.Count - 1].W != 1.0)
				{
					ccVars.pntDynamicCompositeCurve.Add(new Point4D(Points.X, Points.Y, Points.Z, 1.0));
				}
				else
				{
					ccVars.pntDynamicCompositeCurve.Add(new Point4D(Points.X, Points.Y, Points.Z, 2.0));
				}
			}
			else
			{
				ccVars.pntDynamicCompositeCurve.Add(new Point4D(Points.X, Points.Y, Points.Z, 0.0));
			}
		}
		else
		{
			ccVars.pntDynamicCompositeCurve.Add(new Point4D(Points.X, Points.Y, Points.Z, 0.0));
		}
		CheckCompositeCurvePoint();
	}

	public void CheckCompositeCurvePoint()
	{
		if (ccVars.pntDynamicCompositeCurve.Count >= 3 && buCompare5.EQ(ccVars.pntDynamicCompositeCurve[0], ccVars.pntDynamicCompositeCurve[ccVars.pntDynamicCompositeCurve.Count - 1]))
		{
			AddCompositeCurve();
		}
	}

	public void AddCompositeCurve()
	{
		if (!MarbleTempVars.DrawIsInside)
		{
			entityGroupDraw = new buEntitiesGroup();
		}
		List<buEntity> list = new List<buEntity>();
		for (int i = 1; i <= ccVars.pntDynamicCompositeCurve.Count - 1; i++)
		{
			Point4D point4D = ccVars.pntDynamicCompositeCurve[i - 1];
			Point4D point4D2 = ccVars.pntDynamicCompositeCurve[i];
			if (point4D2.W != 0.0)
			{
				if (point4D2.W != 2.0)
				{
					continue;
				}
				Point4D point4D3 = ccVars.pntDynamicCompositeCurve[i - 2];
				Entity entity = new Arc(new Point3D(point4D3.X, point4D3.Y, point4D3.Z), new Point3D(point4D.X, point4D.Y, point4D.Z), new Point3D(point4D2.X, point4D2.Y, point4D2.Z), flip: false);
				if (entity != null)
				{
					if (entity.Vertices == null)
					{
						entity.Regen(0.1);
					}
					ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(new Point3D(point4D.X, point4D.Y, point4D.Z), osnapType.Point));
					ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(new Point3D(point4D2.X, point4D2.Y, point4D2.Z), osnapType.Point));
					CustomData customData = new CustomData();
					customData.typeDefination = entityTypeDefination.TempDraw;
					entity.LayerName = MarbleTempVars.layerDrawing.Name;
					entity.Color = Color.Red;
					entity.ColorMethod = colorMethodType.byEntity;
					entity.LineWeight = 3f;
					entity.LineWeightMethod = colorMethodType.byEntity;
					entity.EntityData = customData;
					buEntity copiedEntity = null;
					buEntity.Copy(entity, ref copiedEntity);
					if (copiedEntity != null)
					{
						list.Add(copiedEntity);
					}
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(entity);
				}
				continue;
			}
			Entity entity2 = new Line(new Point3D(point4D.X, point4D.Y, point4D.Z), new Point3D(point4D2.X, point4D2.Y, point4D2.Z));
			if (entity2 != null)
			{
				if (entity2.Vertices == null)
				{
					entity2.Regen(0.1);
				}
				for (int j = 0; j <= entity2.Vertices.Length - 1; j++)
				{
					ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(entity2.Vertices[j]), osnapType.Point));
				}
				CustomData customData2 = new CustomData();
				customData2.typeDefination = entityTypeDefination.TempDraw;
				entity2.LayerName = MarbleTempVars.layerDrawing.Name;
				entity2.Color = Color.Red;
				entity2.ColorMethod = colorMethodType.byEntity;
				entity2.LineWeight = 3f;
				entity2.LineWeightMethod = colorMethodType.byEntity;
				entity2.EntityData = customData2;
				buEntity copiedEntity2 = null;
				buEntity.Copy(entity2, ref copiedEntity2);
				if (copiedEntity2 != null)
				{
					list.Add(copiedEntity2);
				}
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(entity2);
			}
		}
		if (list.Count > 0)
		{
			if (MarbleTempVars.DrawIsInside)
			{
				buEntityList buEntityList2 = new buEntityList();
				buEntity.Copy(list, ref buEntityList2.Entities);
				entityGroupDraw.Inside.Add(buEntityList2);
			}
			else
			{
				buEntity.Copy(list, ref entityGroupDraw.Outside.Entities);
			}
		}
		ccVars.pntDynamicCompositeCurve.Clear();
	}

	public void AddPolyLine(Point3D Points)
	{
		if (Points != null)
		{
			ccVars.pntBuffered.Add(buVector5.ToPoint3D(Points));
		}
		ccVars.pntDrawDynamicArr = new Point3D[ccVars.pntBuffered.Count + 1];
		for (int i = 0; i <= ccVars.pntBuffered.Count - 1; i++)
		{
			ccVars.pntDrawDynamicArr[i] = buVector5.ToPoint3D(ccVars.pntBuffered[i]);
		}
		ccVars.pntDrawDynamicArr[ccVars.pntBuffered.Count] = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
		if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
		{
			ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
		}
		if (!(Points != null))
		{
			if (ccVars.pntBuffered.Count >= 2)
			{
				LinearPath linearPath = new LinearPath(ccVars.pntBuffered);
				if (linearPath != null)
