					{
						ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(linearPath.Vertices[j]), osnapType.Point));
					}
					CustomData customData = new CustomData();
					customData.typeDefination = entityTypeDefination.TempDraw;
					linearPath.LayerName = MarbleTempVars.layerDrawing.Name;
					linearPath.Color = Color.Red;
					linearPath.ColorMethod = colorMethodType.byEntity;
					linearPath.LineWeight = 3f;
					linearPath.LineWeightMethod = colorMethodType.byEntity;
					linearPath.EntityData = customData;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(linearPath);
				}
			}
			clsInit.appCommand.Reset();
		}
		else if (clsVar.varEntities.FinishPolylineIfClosed && ccVars.pntBuffered.Count >= 3 && buCompare5.EQ(ccVars.pntBuffered[0], ccVars.pntBuffered[ccVars.pntBuffered.Count - 1], clsVar.varSelection.CompareResolution))
		{
			if (ccVars.pntBuffered.Count >= 2)
			{
				LinearPath linearPath2 = new LinearPath(ccVars.pntBuffered);
				if (linearPath2 != null)
				{
					if (linearPath2.Vertices == null)
					{
						linearPath2.Regen(0.1);
					}
					for (int k = 0; k <= linearPath2.Vertices.Length - 1; k++)
					{
						ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(linearPath2.Vertices[k]), osnapType.Point));
					}
					CustomData customData2 = new CustomData();
					customData2.typeDefination = entityTypeDefination.TempDraw;
					linearPath2.LayerName = MarbleTempVars.layerDrawing.Name;
					linearPath2.Color = Color.Red;
					linearPath2.ColorMethod = colorMethodType.byEntity;
					linearPath2.LineWeight = 3f;
					linearPath2.LineWeightMethod = colorMethodType.byEntity;
					linearPath2.EntityData = customData2;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(linearPath2);
				}
			}
			clsInit.appCommand.Reset();
		}
		if (Points != null)
		{
			ccVars.pntBase = buVector5.ToPoint3D(Points);
		}
	}

