	public void AddPolygon(Point3D Points)
	{
		List<Pnt3D> Vertices = new List<Pnt3D>();
		List<Point3D> list = new List<Point3D>();
		Plane.XY.Project(ccVars.pntBase, out var s, out var t);
		Plane.XY.Project(Points, out var s2, out var t2);
		clsInit.cVector.Length3D(new Pnt3D(s, t), new Pnt3D(s2, t2));
		clsInit.cVector.PointAngle(new Pnt3D(s2, t2), new Pnt3D(s, t));
		clsInit.cVector.PolygonCenter(new Pnt3D(s, t), new Pnt3D(s2, t2), clsVar.varInterface.PolygonVar.Side, new WorkPlane(planeType.XY, 1), ref Vertices);
		for (int i = 0; i <= Vertices.Count - 1; i++)
		{
			list.Add(new Point3D(Vertices[i].X, Vertices[i].Y, 0.0));
		}
		if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
		{
			ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
		}
		LinearPath linearPath = new LinearPath(list);
		if (linearPath != null)
		{
			if (linearPath.Vertices == null)
			{
				linearPath.Regen(0.1);
			}
			for (int j = 0; j <= linearPath.Vertices.Length - 1; j++)
			{
				ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(linearPath.Vertices[j]), osnapType.Point));
			}
			CustomData customData = new CustomData();
			customData.typeDefination = entityTypeDefination.TempDraw;
			linearPath.LayerName = MarbleTempVars.layerDrawing.Name;
			linearPath.Color = Color.Red;
			linearPath.ColorMethod = colorMethodType.byEntity;
			linearPath.LineWeight = 3f;
			linearPath.LineWeightMethod = colorMethodType.byEntity;
			linearPath.EntityData = customData;
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(linearPath);
			clsInit.appCommand.Reset();
		}
		ccVars.pntBase = buVector5.ToPoint3D(Points);
	}

	public void AddCircle(Point3D Points, double Diameter)
	{
		if (!MarbleTempVars.DrawIsInside)
		{
			entityGroupDraw = new buEntitiesGroup();
		}
		List<buEntity> list = new List<buEntity>();
		if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
		{
			ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
		}
		double num = Point3D.Distance(ccVars.pntBase, Points);
		if (Diameter > 0.0)
		{
			num = Diameter / 2.0;
		}
		if (num > 0.01)
		{
			Entity entity = new Circle(Plane.XY, ccVars.pntBase, num);
			if (entity != null)
			{
				ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(ccVars.pntBase), osnapType.Center));
				Point3D Q = null;
				Point3D Q2 = null;
				Point3D Q3 = null;
				Point3D Q4 = null;
				clsInit.cVector5.CircleQuadrantPoints(ccVars.pntBase, num, Plane.XY, ref Q, ref Q2, ref Q3, ref Q4);
				ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(Q, osnapType.Outer));
				ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(Q2, osnapType.Outer));
				ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(Q3, osnapType.Outer));
				ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(Q4, osnapType.Outer));
				CustomData customData = new CustomData();
				customData.typeDefination = entityTypeDefination.TempDraw;
				entity.LayerName = MarbleTempVars.layerDrawing.Name;
				entity.Color = Color.Red;
				entity.ColorMethod = colorMethodType.byEntity;
				entity.LineWeight = 3f;
				entity.LineWeightMethod = colorMethodType.byEntity;
				entity.EntityData = customData;
				buEntity copiedEntity = null;
				buEntity.Copy(entity, ref copiedEntity);
				if (copiedEntity != null)
				{
					list.Add(copiedEntity);
				}
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(entity);
				clsInit.appCommand.Reset();
			}
		}
		if (list.Count > 0)
		{
			if (MarbleTempVars.DrawIsInside)
			{
				buEntityList buEntityList2 = new buEntityList();
				buEntity.Copy(list, ref buEntityList2.Entities);
				entityGroupDraw.Inside.Add(buEntityList2);
			}
			else
			{
				buEntity.Copy(list, ref entityGroupDraw.Outside.Entities);
			}
		}
		ccVars.pntBase = buVector5.ToPoint3D(Points);
	}

