	public void DeleteTempDrawings()
	{
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData != null)
			{
				CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
				if (customData.typeDefination == entityTypeDefination.TempDraw)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void viewportMouseDown(Point3D Points, object sender, MouseEventArgs e)
	{
		if (e.Button != MouseButtons.Left || ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActionMode != actionType.None || ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Viewports[0].ToolBar.Contains(e.Location) || e.Button != MouseButtons.Left)
		{
			return;
		}
		AppBool.MouseDown = true;
		ccVars.pntMouseDownFirst.X = Points.X;
		ccVars.pntMouseDownFirst.Y = Points.Y;
		if (MoveCreatedEntity)
		{
			Point3D pntMove = new Point3D(Points.X, Points.Y, Points.Z);
			bool isIntersect = false;
			bool isOut = false;
			ViewportCC viewportcad = ccVars.Pages[ccVars.PageIndex].Form.viewportcad;
			ViewportOsnap(viewportcad, Points, ref pntMove, ref isIntersect, ref isOut);
			MoveCreatedEntity = false;
			for (int i = 0; i <= viewportcad.Entities.Count - 1; i++)
			{
				viewportcad.Entities[i].Selected = false;
				if ((viewportcad.Entities[i].EntityData != null) & (viewportcad.Entities[i].EntityData is CustomData))
				{
					CustomData customData = viewportcad.Entities[i].EntityData as CustomData;
					if (customData.typeDefination == entityTypeDefination.Temp)
					{
						viewportcad.Entities[i].Selected = true;
					}
				}
			}
			viewportcad.Entities.DeleteSelected();
			bool isMilling = false;
			bool isWaterJet = false;
			bool isMillingHead = false;
			if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.Milling)
			{
				isMilling = true;
			}
			if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.WaterJet)
			{
				isWaterJet = true;
			}
			if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.MillingHead)
			{
				isMillingHead = true;
			}
			if (clsInit.appMarble.activeItemType != MarbleItemType.VerticalCut)
			{
				if (clsInit.appMarble.activeItemType != MarbleItemType.HorizontalCut)
				{
					if (clsInit.appMarble.activeItemType != MarbleItemType.HorizontalVerticalCut)
					{
						if (clsInit.appMarble.activeItemType != MarbleItemType.Slices)
						{
							if (clsInit.appMarble.activeItemType != MarbleItemType.SingleCut)
							{
								if (clsInit.appMarble.activeItemType != MarbleItemType.Contour)
								{
									if (clsInit.appMarble.activeItemType != MarbleItemType.Shape)
									{
										if (clsInit.appMarble.activeItemType != MarbleItemType.Engraving)
										{
											if (clsInit.appMarble.activeItemType != MarbleItemType.Shape3D)
											{
												if (clsInit.appMarble.activeItemType != MarbleItemType.SawHorizontalMillingRough)
												{
													if (clsInit.appMarble.activeItemType != MarbleItemType.SawVerticalMillingRough)
													{
														if (clsInit.appMarble.activeItemType != MarbleItemType.Profiling)
														{
															if (clsInit.appMarble.activeItemType != MarbleItemType.ProfileCurve)
															{
																if (clsInit.appMarble.activeItemType != MarbleItemType.Sweep)
																{
																	if (clsInit.appMarble.activeItemType != MarbleItemType.Cavity)
																	{
																		if (clsInit.appMarble.activeItemType != MarbleItemType.Drill)
																		{
																			if (!((clsInit.appMarble.activeItemType == MarbleItemType.Text) | (clsInit.appMarble.activeItemType == MarbleItemType.TextWireframe) | (clsInit.appMarble.activeItemType == MarbleItemType.Text3D)))
																			{
																				if (clsInit.appMarble.activeItemType != MarbleItemType.Columns)
																				{
																					if (clsInit.appMarble.activeItemType != MarbleItemType.LatheHorizontal)
																					{
																						if (clsInit.appMarble.activeItemType != MarbleItemType.LatheVertical)
																						{
																							if (clsInit.appMarble.activeItemType != MarbleItemType.Milling5AxisRotary)
																							{
																								if (clsInit.appMarble.activeItemType == MarbleItemType.VacuumAdd)
																								{
																									if (buMarbleForms.frmVacuumMove == null)
																									{
