	public void viewportMouseUp(Point3D Points, object sender, MouseEventArgs e)
	{
		AppBool.MouseDown = false;
		ccVars.pntDrawDynamicLines.Clear();
		if (AppBool.EditMode && ccVars.SelectionOP.Selections.Count > 0)
		{
			double num = Math.Abs(Points.X - ccVars.pntMouseDownFirst.X);
			double num2 = Math.Abs(Points.Y - ccVars.pntMouseDownFirst.Y);
			if (num > 1.0 || num2 > 1.0)
			{
				clsInit.cVector5.GetSelectedEntitiesInfo(ccVars.Pages[ccVars.PageIndex].Form.viewportcad, ref ccVars.numberOfSelectedEntity, ref ccVars.pntSelectedMin, ref ccVars.pntSelectedMid, ref ccVars.pntSelectedMax);
				ccVars.lastRotatedAngle = clsInit.cVector5.PointAngle(Points, ccVars.pntSelectedMid);
				AppBool.EditMode = false;
				doDrawActiveJob();
				SetSelectedToEntities();
				AppBool.EditMode = true;
			}
		}
		if (e.Button == MouseButtons.Left && MarbleTempVars.SetAngle)
		{
			doSetAngle();
		}
	}

	public void viewportMouseMove(Point3D Points, object sender, MouseEventArgs e)
	{
		try
		{
			Point3D pntMove = new Point3D(Points.X, Points.Y, Points.Z);
			ViewportCC.textDynamical = null;
			if (okCommandWithFiveDataEventHandler_0 != null)
			{
				MarbleArg.pntMove.X = Points.X;
				MarbleArg.pntMove.Y = Points.Y;
				MarbleArg.pntMove.Z = Points.Z;
				MarbleArg.refPlane = ccVars.planeActive;
				MarbleArg.pntScreen.X = e.X;
				MarbleArg.pntScreen.Y = e.Y;
				okCommandWithFiveDataEventHandler_0(MarbleHMICommands.MoveMouse, MarbleArg, null, null, null);
			}
			if (MoveCreatedEntity)
			{
				ViewportCC viewportcad = ccVars.Pages[ccVars.PageIndex].Form.viewportcad;
				for (int i = 0; i <= viewportcad.Entities.Count - 1; i++)
				{
					viewportcad.Entities[i].Selected = false;
					if ((viewportcad.Entities[i].EntityData != null) & (viewportcad.Entities[i].EntityData is CustomData))
					{
						CustomData customData = viewportcad.Entities[i].EntityData as CustomData;
						if (customData.typeDefination == entityTypeDefination.Temp)
						{
							viewportcad.Entities[i].Selected = true;
						}
					}
				}
				viewportcad.Entities.DeleteSelected();
				bool isIntersect = false;
				bool isOut = false;
				ViewportOsnap(viewportcad, Points, ref pntMove, ref isIntersect, ref isOut);
				for (int j = 0; j <= clsInit.appMarble.entitiesForMove.Count - 1; j++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(clsInit.appMarble.entitiesForMove[j], ref copiedEntity);
					if (copiedEntity == null)
					{
						continue;
					}
					bool flag = true;
					if (!MarbleTempVars.isSolidMove)
					{
						flag = false;
						if (copiedEntity is ICurve)
						{
							flag = true;
						}
					}
					if (flag)
					{
						CustomData customData2 = new CustomData();
						customData2.typeDefination = entityTypeDefination.Temp;
						copiedEntity.EntityData = customData2;
						copiedEntity.LayerName = viewportcad.Layers[MarbleTempVars.layerMarblePart.Index].Name;
						copiedEntity.Translate(pntMove.X, pntMove.Y, 0.1);
						copiedEntity.Regen(0.5);
						if (isIntersect || isOut)
						{
							copiedEntity.Color = Color.Red;
							copiedEntity.ColorMethod = colorMethodType.byEntity;
						}
						viewportcad.Entities.Add(copiedEntity);
						if (isOut)
						{
							ViewportDynamicalText(pntMove, buLangTranslate.preSentences.OperationOutofMaterial, Color.Red, 20f);
						}
						if (isIntersect)
						{
							ViewportDynamicalText(pntMove, buLangTranslate.preSentences.OperationOnthePart, Color.Red, 20f);
						}
					}
				}
				viewportcad.Invalidate();
			}
			if (AppBool.EditMode)
			{
				if (!MoveCreatedEntity & (ccVars.Action == actionTypeBU.None) & AppBool.MouseDown & (ccVars.numberOfUnderSelectedEntity > 0) & buMarbleCalc.varOperation.settingEvent.eventMoveByMouse)
				{
					double dX = ccVars.pntMouseMove.X - ccVars.pntMouseDown.X;
					double dY = ccVars.pntMouseMove.Y - ccVars.pntMouseDown.Y;
					doMoveSelectedItem(dX, dY);
					ccVars.pntMouseDown.X = ccVars.pntMouseMove.X;
					ccVars.pntMouseDown.Y = ccVars.pntMouseMove.Y;
				}
				if (!MoveCreatedEntity & (MarbleTempVars.OperationageMode == MarbleOperationPageMode.Event) & (ccVars.Action == actionTypeBU.None) & AppBool.MouseDown & (ccVars.numberOfUnderSelectedEntity == 0) & (ccVars.numberOfSelectedEntity > 0) & buMarbleCalc.varOperation.settingEvent.eventRotateByMouse)
				{
					ccVars.pntDrawDynamicLines.Clear();
					ccVars.pntDrawDynamicLines.Add(ccVars.pntSelectedMid);
					ccVars.pntDrawDynamicLines.Add(pntMove);
					double num = clsInit.cVector5.PointAngle(pntMove, ccVars.pntSelectedMid);
					double rotation = num - ccVars.lastRotatedAngle;
					doRotateSelectedItem(rotation);
					ccVars.lastRotatedAngle = num;
				}
			}
			if (clsInit.appMarble.activeItemType == MarbleItemType.VacuumAdd)
			{
				GetVacuumLineByMouse(Points, 0.0, 0.0, Finished: false);
			}
		}
		catch (Exception)
		{
		}
	}

	public void ViewportOsnap(ViewportCC View, Point3D Points, ref Point3D pntMove, ref bool isIntersect, ref bool isOut)
	{
		if (!MoveCreatedEntity)
		{
			return;
		}
		Point3D pntOver = new Point3D();
		if (activeJob != null && activeJob.Material != null && activeJob.Material.Enable)
		{
			for (int i = 1; i <= activeJob.Material.Points.Count - 1; i++)
			{
				pntOver = new Point3D();
				if (clsInit.cVector5.isPointOverLine(activeJob.Material.Points[i - 1], activeJob.Material.Points[i], Points, buMarbleCalc.varMarbleSettings.EntityCatchDistance, ref pntOver))
				{
					pntMove.X = pntOver.X;
					pntMove.Y = pntOver.Y;
					pntMove.Z = pntOver.Z;
					ViewportDynamicalText(pntMove, buLangTranslate.preDef.Material + " " + buLangTranslate.preDef.Catch, Color.Black, 20f);
				}
			}
		}
		if (MarbleTempVars.MaterialLimits.Count > 0)
		{
			for (int j = 1; j <= MarbleTempVars.MaterialLimits.Count - 1; j++)
			{
				pntOver = new Point3D();
				if (clsInit.cVector5.isPointOverLine(MarbleTempVars.MaterialLimits[j - 1], MarbleTempVars.MaterialLimits[j], Points, buMarbleCalc.varMarbleSettings.EntityCatchDistance, ref pntOver))
				{
					pntMove.X = pntOver.X;
					pntMove.Y = pntOver.Y;
					pntMove.Z = pntOver.Z;
					ViewportDynamicalText(pntMove, buLangTranslate.preSentences.OperationCatchPart, Color.Black, 20f);
				}
			}
		}
		if (clsInit.cVector5.isPointOverLine(new Point3D(), new Point3D(buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth, 0.0, 0.0), Points, buMarbleCalc.varMarbleSettings.EntityCatchDistance, ref pntOver))
		{
			pntMove.X = pntOver.X;
			pntMove.Y = pntOver.Y;
			pntMove.Z = pntOver.Z;
			ViewportDynamicalText(pntMove, buLangTranslate.preDef.Limit + " " + buLangTranslate.preDef.Catch, Color.Black, 20f);
		}
		pntOver = new Point3D();
		if (clsInit.cVector5.isPointOverLine(new Point3D(), new Point3D(0.0, buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight, 0.0), Points, buMarbleCalc.varMarbleSettings.EntityCatchDistance, ref pntOver))
		{
			pntMove.X = pntOver.X;
			pntMove.Y = pntOver.Y;
			pntMove.Z = pntOver.Z;
			ViewportDynamicalText(pntMove, buLangTranslate.preDef.Limit + " " + buLangTranslate.preDef.Catch, Color.Black, 20f);
		}
		isIntersect = false;
		isOut = false;
		if ((buMarbleCalc.varMarbleSettings.MaterialBorderControl & activeJob.Material.Enable) && activeJob.Material.Points.Count > 0)
		{
			for (int k = 0; k <= clsInit.appMarble.entitiesForMove.Count - 1; k++)
			{
				if (clsInit.appMarble.entitiesForMove[k].Vertices == null)
				{
					continue;
				}
				for (int l = 0; l <= clsInit.appMarble.entitiesForMove[k].Vertices.Length - 1; l++)
				{
					Point3D refPoint = new Point3D(clsInit.appMarble.entitiesForMove[k].Vertices[l].X + pntMove.X, clsInit.appMarble.entitiesForMove[k].Vertices[l].Y + pntMove.Y, clsInit.appMarble.entitiesForMove[k].Vertices[l].Z);
					if (!clsInit.cVector5.IsPointInsidePolygon(activeJob.Material.Points, refPoint, Plane.XY, CheckOver: true))
					{
						isOut = true;
					}
				}
			}
		}
		if (!buMarbleCalc.varMarbleSettings.IntersectionEnable)
		{
			return;
		}
		for (int m = 0; m <= clsInit.appMarble.entitiesForMove.Count - 1; m++)
		{
			Entity copiedEntity = null;
			buEntity.Copy(clsInit.appMarble.entitiesForMove[m], ref copiedEntity);
			if (copiedEntity == null)
			{
				continue;
			}
			CustomData customData = new CustomData();
			customData.typeDefination = entityTypeDefination.Temp;
			copiedEntity.EntityData = customData;
			copiedEntity.LayerName = View.Layers[MarbleTempVars.layerMarblePart.Index].Name;
			copiedEntity.Translate(pntMove.X, pntMove.Y);
			copiedEntity.Regen(0.1);
			if (!(copiedEntity is ICurve))
			{
				continue;
			}
			for (int n = 0; n <= View.Entities.Count - 1; n++)
			{
				if (View.Entities[n] is ICurve)
				{
					Point3D[] array = ((ICurve)View.Entities[n]).IntersectWith((ICurve)copiedEntity);
					if (array != null && array.Length != 0)
					{
						isIntersect = true;
					}
				}
			}
		}
	}

	public void ViewportDynamicalText(Point3D pntMove, string Info, Color clr, float FontSize)
	{
		if (ccVars.Pages != null && ccVars.Pages.Count > 0)
		{
			clsVar.varView.DynamicTextAlignment = ContentAlignment.MiddleLeft;
			clsVar.varView.DynamicTextSize = FontSize;
			clsVar.varView.colorDynamicText = clr;
			ViewportCC.textDynamical = Info;
		}
	}

	public void DeleteSimulationEntities()
	{
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = false;
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData != null && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData is CustomData)
			{
				CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
				if (((customData.typeDefination == entityTypeDefination.MachineParts) | (customData.typeDefination == entityTypeDefination.MachineBody) | (customData.typeDefination == entityTypeDefination.ToolParts) | (customData.typeDefination == entityTypeDefination.Tool)) && ((customData.infoString == null) | (customData.infoString != null && customData.infoString != "NotDelete")))
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void GetSimulationEntities(bool cam, bool machine, int EntityCount, ref List<Entity> EntList, ref List<Block> Blocks, ref List<int> MovePartIndex)
	{
		CustomData customData = null;
		MovePartIndex.Clear();
		EntList = new List<Entity>();
		Blocks = new List<Block>();
		if (buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawHead)
		{
			int num = EntityCount;
			if (machine && ccVars.SimMachine != null && ccVars.SimMachine.MachineParts != null)
			{
				for (int i = 0; i <= ccVars.SimMachine.MachineParts.Count - 1; i++)
				{
					for (int j = 0; j <= ccVars.SimMachine.MachineParts[i].Entities.Count - 1; j++)
					{
						if (!(ccVars.SimMachine.MachineParts[i].PartType != "Lathe"))
						{
							buMachinePart buMachinePart2 = new buMachinePart(ccVars.SimMachine.MachineParts[i].PartName);
							buMachinePart2.ARotation = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.A;
							buMachinePart2.BRotation = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.B;
							buMachinePart2.CRotation = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.C;
							buMachinePart2.XMove = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.X;
							buMachinePart2.YMove = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.Y;
							buMachinePart2.ZMove = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.Z;
							buMachinePart2.centerPointOfA = new Point3D(0.0, activeKinematic.RotateCenterOffsetOfA.Y - 0.0, activeKinematic.RotateCenterOffsetOfA.Z - activeKinematic.RotateCenterOffsetOfC.Z);
							buMachinePart2.centerPointOfC = new Point3D();
							buMachinePart2.Color = ccVars.SimMachine.MachineParts[i].Color;
							buMachinePart2.ColorMethod = colorMethodType.byEntity;
							double dx = ccVars.SimMachine.MachineParts[i].PositionBaseOffset.X + ccVars.SimMachine.MachineParts[i].PositionAuxOffset.X + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetX;
							double dy = ccVars.SimMachine.MachineParts[i].PositionBaseOffset.Y + ccVars.SimMachine.MachineParts[i].PositionAuxOffset.Y + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetY;
							double dz = ccVars.SimMachine.MachineParts[i].PositionBaseOffset.Z + ccVars.SimMachine.MachineParts[i].PositionAuxOffset.Z + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetZ;
							buMachinePart2.Translate(dx, dy, dz);
							buMachinePart2.Regen(new RegenParams(0.1, ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
							customData = new CustomData();
							customData.typeDefination = entityTypeDefination.MachineParts;
							customData.OriginalEntityIndex = num;
							customData.EntityName = ccVars.SimMachine.MachineParts[i].PartName;
							buMachinePart2.EntityData = customData;
							buMachinePart2.ColorMethod = colorMethodType.byEntity;
							buMachinePart2.Color = Color.FromArgb(100, ccVars.SimMachine.MachineParts[i].Color);
							buMachinePart2.LayerName = MarbleTempVars.layerMachine.Name;
							EntList.Add(buMachinePart2);
							num++;
							continue;
						}
						buMachinePart buMachinePart3 = new buMachinePart(ccVars.SimMachine.MachineParts[i].PartName);
						buMachinePart3.ARotation = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.A;
						buMachinePart3.BRotation = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.B;
						buMachinePart3.CRotation = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.C;
						buMachinePart3.XMove = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.X;
						buMachinePart3.YMove = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.Y;
						buMachinePart3.ZMove = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.Z;
						buMachinePart3.centerPointOfA = new Point3D(0.0, activeKinematic.RotateCenterOffsetOfA.Y - 0.0, activeKinematic.RotateCenterOffsetOfA.Z - activeKinematic.RotateCenterOffsetOfC.Z);
						buMachinePart3.centerPointOfC = new Point3D();
						buMachinePart3.Color = ccVars.SimMachine.MachineParts[i].Color;
						buMachinePart3.ColorMethod = colorMethodType.byEntity;
						double num2 = ccVars.SimMachine.MachineParts[i].PositionBaseOffset.X + ccVars.SimMachine.MachineParts[i].PositionAuxOffset.X + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetX;
						double num3 = ccVars.SimMachine.MachineParts[i].PositionBaseOffset.Y + ccVars.SimMachine.MachineParts[i].PositionAuxOffset.Y + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetY;
						double num4 = ccVars.SimMachine.MachineParts[i].PositionBaseOffset.Z + ccVars.SimMachine.MachineParts[i].PositionAuxOffset.Z + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetZ;
						if (buMachinePart3.ARotation)
						{
							buMachinePart3.centerPointOfA = new Point3D();
							buMachinePart3.centerPointOfC = new Point3D(0.0, 0.0 - (activeKinematic.RotateCenterOffsetOfA.Y + activeKinematic.RotateCenterOffsetOfC.Y), 0.0);
							if (!buMarbleCalc.varMarbleMachineSettings.SimulationSettings.MovePartFromKinematicDistances)
							{
								buMachinePart3.centerPointOfA = new Point3D(0.0, activeKinematic.RotateCenterOffsetOfA.Y, activeKinematic.RotateCenterOffsetOfA.Z + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance);
								buMachinePart3.centerPointOfC = new Point3D(0.0, activeKinematic.RotateCenterOffsetOfC.Y, 0.0);
							}
							else
							{
								num3 = num3 - activeKinematic.RotateCenterOffsetOfC.Y + buMarbleCalc.activeToolSaw.Geometry.Thickness / 2.0;
								num4 -= activeKinematic.RotateCenterOffsetOfA.Z;
								buMachinePart3.centerPointOfA = new Point3D(0.0, activeKinematic.RotateCenterOffsetOfA.Y, activeKinematic.RotateCenterOffsetOfA.Z);
								buMachinePart3.centerPointOfC = new Point3D(0.0, activeKinematic.RotateCenterOffsetOfC.Y, 0.0);
							}
							if (buMarbleCalc.varMarbleMachineSettings.SimulationSettings.MovePartFromKinematicDistances)
							{
								num4 += buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance;
							}
						}
						if (ccVars.SimMachine.MachineParts[i].PartName == "Spindle")
						{
							num2 += buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetX;
							num3 += buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetY;
							num4 += buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetZ;
							buMachinePart3.centerPointOfC = new Point3D(0.0 - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetX, 0.0 - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetY);
						}
						buMachinePart3.Translate(num2, num3, num4);
						buMachinePart3.Regen(new RegenParams(0.1, ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
						customData = new CustomData();
						customData.typeDefination = entityTypeDefination.MachineParts;
						customData.OriginalEntityIndex = num;
						customData.EntityName = ccVars.SimMachine.MachineParts[i].PartName;
						buMachinePart3.EntityData = customData;
						buMachinePart3.ColorMethod = colorMethodType.byEntity;
						buMachinePart3.Color = Color.FromArgb(100, ccVars.SimMachine.MachineParts[i].Color);
						buMachinePart3.LayerName = MarbleTempVars.layerMachine.Name;
						EntList.Add(buMachinePart3);
						num++;
					}
				}
			}
		}
		DrawTool(buMarbleCalc.activeToolSaw, buMarbleCalc.activeToolMilling, buMarbleCalc.activeToolMillingHead, buMarbleCalc.activeToolWaterjet, buMarbleCalc.activeToolAirDry, buMarbleCalc.activeToolLaserPointer, activeKinematic, EntityCount, ref EntList, ref Blocks, ref MovePartIndex);
	}

	public void DrawSimulationEntities(bool cam, bool machine, bool DrawAllTool, MarbleToolType ActiveToolType)
	{
		list_0.Clear();
		List<Entity> EntList = new List<Entity>();
		List<Block> Blocks = new List<Block>();
		MarbleTempVars.DontDrawAirDry = false;
		MarbleTempVars.DontDrawLaserPointer = false;
		MarbleTempVars.DontDrawMilling = false;
		MarbleTempVars.DontDrawMillingHead = false;
		MarbleTempVars.DontDrawSaw = false;
		MarbleTempVars.DontDrawWaterJet = false;
		if (!DrawAllTool)
		{
			MarbleTempVars.DontDrawAirDry = true;
			MarbleTempVars.DontDrawLaserPointer = true;
			MarbleTempVars.DontDrawMilling = true;
			MarbleTempVars.DontDrawMillingHead = true;
			MarbleTempVars.DontDrawSaw = true;
			MarbleTempVars.DontDrawWaterJet = true;
			if (ActiveToolType == MarbleToolType.Milling)
			{
				MarbleTempVars.DontDrawMilling = false;
			}
			if (ActiveToolType == MarbleToolType.MillingHead)
			{
				MarbleTempVars.DontDrawMillingHead = false;
			}
			if (ActiveToolType == MarbleToolType.Saw)
			{
				MarbleTempVars.DontDrawSaw = false;
			}
			if (ActiveToolType == MarbleToolType.WaterJet)
			{
				MarbleTempVars.DontDrawWaterJet = false;
			}
		}
		clsInit.appMarble.GetSimulationEntities(cam, machine, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count, ref EntList, ref Blocks, ref list_0);
		for (int num = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Count - 1; num >= 0; num--)
		{
			if (!(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[num].Name == "ToolSaw"))
			{
				if (!(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[num].Name == "ToolMilling"))
				{
					if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[num].Name == "ToolMillingHead")
					{
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.RemoveAt(num);
					}
				}
				else
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.RemoveAt(num);
				}
			}
			else
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.RemoveAt(num);
			}
		}
		if (!DrawAllTool)
		{
			for (int i = 0; i <= Blocks.Count - 1; i++)
			{
				if (Blocks[i].Name == "ToolSaw" && ActiveToolType == MarbleToolType.Saw)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[i]);
				}
				if (Blocks[i].Name == "ToolMilling" && ActiveToolType == MarbleToolType.Milling)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[i]);
				}
				if (Blocks[i].Name == "ToolMillingHead" && ActiveToolType == MarbleToolType.MillingHead)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[i]);
				}
				if (Blocks[i].Name == "WaterJet" && ActiveToolType == MarbleToolType.WaterJet)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[i]);
				}
			}
		}
		else
		{
			for (int j = 0; j <= Blocks.Count - 1; j++)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[j]);
			}
		}
		for (int k = 0; k <= EntList.Count - 1; k++)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(EntList[k]);
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

