			for (int num13 = 0; num13 <= EntList.Count - 1; num13++)
			{
				CustomData customData7 = EntList[num13].EntityData as CustomData;
				if ((customData7.typeDefination == entityTypeDefination.Tool) | (customData7.typeDefination == entityTypeDefination.MachineParts) | (customData7.typeDefination == entityTypeDefination.MachineBody) | (customData7.typeDefination == entityTypeDefination.Clamper))
				{
					MovePartIndex.Add(EntityCount + num13);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Tool: " + ToolSaw.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void MoveSimPart(Pnt6DSimMove PntMove, bool SpindleDown, ToolBase5 Tool)
	{
		pnt6D_0.X = Tool.CamData.SimMoveOffset.X + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulatioOfflineMoveXOffset;
		pnt6D_0.Y = Tool.CamData.SimMoveOffset.Y + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulatioOfflineMoveYOffset;
		pnt6D_0.Z = Tool.CamData.SimMoveOffset.Z + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulatioOfflineMoveZOffset;
		if (ccVars.Pages.Count > 0 && !ccVars.Pages[ccVars.PageIndex].Form.viewportcad.IsAnimationRunning)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
		}
		for (int i = 0; i <= list_0.Count - 1; i++)
		{
			if (list_0[i] > ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
			{
				continue;
			}
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]];
			buMachinePart buMachinePart2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]] as buMachinePart;
			CustomData customData = entity.EntityData as CustomData;
			_ = list_0[i];
			if (!((list_0[i] >= 0) & (list_0[i] <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)))
			{
				continue;
			}
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			if (SpindleDown)
			{
				num = 0.0 - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetX;
				num2 = 0.0 - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetY;
				num3 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimSpindleG54OffsetZ + buMarbleCalc.activeToolMilling.Geometry.Length;
			}
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]].GetType() == typeof(buTool))
			{
				buTool buTool2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]] as buTool;
				if (!(buTool2.BlockName == "ToolMilling"))
				{
					num3 = num3 - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance + activeKinematic.RotateCenterOffsetOfA.Z;
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]]).zPos = PntMove.Z + activeKinematic.RotateCenterOffsetOfC.Z + buMarbleCalc.activeToolSaw.Geometry.Diameter / 2.0 + pnt6D_0.Z + num3;
				}
				else
				{
					if (buTool2.HeadNumber == 1)
					{
						num3 -= buMarbleCalc.activeToolMilling.Geometry.Length;
						if (SpindleDown)
						{
							num3 -= buMarbleCalc.varMarbleMachineSettings.SimulationSettings.ExternalMillingSpindleStroke;
						}
						buTool2.zPos = PntMove.Z + pnt6D_0.Z + num3;
					}
					if (buTool2.HeadNumber == 2)
					{
						buTool2.ARotation = true;
						buTool2.centerPointOfA.X = 0.0;
						buTool2.centerPointOfA.Y = 0.0;
						buTool2.centerPointOfA.Z = 0.0;
						num3 -= buMarbleCalc.activeToolMilling.Geometry.Length;
						buTool2.zPos = PntMove.Z;
					}
				}
				((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]]).xPos = PntMove.X + pnt6D_0.X + num;
				((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]]).yPos = PntMove.Y + pnt6D_0.Y + num2;
				((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]]).aPos = PntMove.A;
				((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]]).cPos = PntMove.C;
			}
			if (!(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[list_0[i]].GetType() == typeof(buMachinePart)) || !((customData.typeDefination == entityTypeDefination.MachineBody) | (customData.typeDefination == entityTypeDefination.MachineParts)) || !(customData.ActionName != "Lathe"))
			{
				continue;
			}
			buMachinePart2.xPos = PntMove.X + num;
			buMachinePart2.yPos = PntMove.Y + num2;
			buMachinePart2.aPos = PntMove.A;
			buMachinePart2.cPos = PntMove.C;
			if (!(ccVars.SimMachine.MachineParts[i].PartName != "Spindle"))
			{
				if (SpindleDown)
				{
					num3 -= buMarbleCalc.varMarbleMachineSettings.SimulationSettings.ExternalMillingSpindleStroke;
				}
				buMachinePart2.zPos = PntMove.Z + pnt6D_0.Z + num3;
			}
			else
			{
				num3 = num3 - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance + activeKinematic.RotateCenterOffsetOfA.Z;
				buMachinePart2.zPos = PntMove.Z + pnt6D_0.Z + num3 + activeKinematic.RotateCenterOffsetOfC.Z + buMarbleCalc.activeToolSaw.Geometry.Diameter / 2.0;
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void Sim_Tick(object sender, EventArgs e)
	{
		ToolBase5 toolBase = new ToolBase5();
		AppProcess.TickSave = 0;
		if (!((SimItemIndex >= 0) & (SimItemIndex <= activeJob.Cams.Count - 1)))
		{
			MarbleTempVars.SimSpindlePistonDown = false;
			SimIndex = 0;
			SimItemIndex++;
			if (SimItemIndex >= activeJob.Items.Count)
			{
				SimIndex = -1;
				SimItemIndex = -1;
				timSim.Enabled = false;
				DeleteSimulationEntities();
			}
		}
		else
		{
			camTp camTp2 = null;
			camTp2 = activeJob.Cams[SimItemIndex];
			if (lastSimToolPurpose != ToolPurpose.None)
			{
				MarbleToolType marbleToolType = MarbleToolType.Saw;
				bool flag = false;
				if ((camTp2.Tool.Purpose == ToolPurpose.WaterJet) & (lastSimToolPurpose != ToolPurpose.WaterJet))
				{
					MarbleTempVars.SimSpindlePistonDown = false;
					marbleToolType = MarbleToolType.WaterJet;
					flag = true;
				}
				if ((camTp2.Tool.Purpose == ToolPurpose.Saw) & (lastSimToolPurpose != ToolPurpose.Saw))
				{
					MarbleTempVars.SimSpindlePistonDown = false;
					MarbleTempVars.DontDrawMillingHead = true;
					MarbleTempVars.DontDrawSaw = false;
					marbleToolType = MarbleToolType.Saw;
					flag = true;
				}
				if ((camTp2.Tool.Purpose == ToolPurpose.Milling) & (lastSimToolPurpose != ToolPurpose.Milling))
				{
					MarbleTempVars.SimSpindlePistonDown = true;
					MarbleTempVars.DontDrawMillingHead = false;
					MarbleTempVars.DontDrawSaw = false;
					marbleToolType = MarbleToolType.MillingHead;
					flag = true;
				}
				if ((camTp2.Tool.Purpose == ToolPurpose.Milling5Axis) & (lastSimToolPurpose != ToolPurpose.Milling5Axis))
				{
					MarbleTempVars.SimSpindlePistonDown = false;
					MarbleTempVars.DontDrawMillingHead = false;
					MarbleTempVars.DontDrawSaw = false;
					marbleToolType = MarbleToolType.Milling;
					flag = true;
				}
				if ((camTp2.Tool.Purpose == ToolPurpose.MillingHead) & (lastSimToolPurpose != ToolPurpose.MillingHead))
				{
					MarbleTempVars.SimSpindlePistonDown = false;
					MarbleTempVars.DontDrawMillingHead = false;
					MarbleTempVars.DontDrawSaw = !buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawSawToolForMillingHeadOperation;
					marbleToolType = MarbleToolType.MillingHead;
					flag = true;
				}
				MarbleTempVars.ActiveSimulationToolType = marbleToolType;
				if (flag)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
					DeleteSimulationEntities();
					DrawSimulationEntities(cam: false, machine: true, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawAllTool, marbleToolType);
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
				}
			}
			else
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
				MarbleToolType marbleToolType2 = MarbleToolType.Saw;
				if (camTp2.Tool.Purpose != ToolPurpose.WaterJet)
				{
					if (camTp2.Tool.Purpose != ToolPurpose.Milling)
					{
						if (camTp2.Tool.Purpose != ToolPurpose.Milling5Axis)
						{
							if (camTp2.Tool.Purpose != ToolPurpose.MillingHead)
							{
								MarbleTempVars.SimSpindlePistonDown = false;
								MarbleTempVars.DontDrawMillingHead = true;
								MarbleTempVars.DontDrawSaw = false;
								marbleToolType2 = MarbleToolType.Saw;
							}
							else
							{
								MarbleTempVars.SimSpindlePistonDown = false;
								MarbleTempVars.DontDrawMillingHead = false;
								MarbleTempVars.DontDrawSaw = !buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawSawToolForMillingHeadOperation;
								marbleToolType2 = MarbleToolType.MillingHead;
							}
						}
						else
						{
							MarbleTempVars.SimSpindlePistonDown = false;
							MarbleTempVars.DontDrawMillingHead = false;
							MarbleTempVars.DontDrawSaw = false;
							marbleToolType2 = MarbleToolType.Milling;
						}
					}
					else
					{
						MarbleTempVars.SimSpindlePistonDown = true;
						MarbleTempVars.DontDrawMillingHead = false;
						MarbleTempVars.DontDrawSaw = false;
						marbleToolType2 = MarbleToolType.Milling;
					}
				}
				else
				{
					MarbleTempVars.SimSpindlePistonDown = false;
					marbleToolType2 = MarbleToolType.WaterJet;
				}
				MarbleTempVars.ActiveSimulationToolType = marbleToolType2;
				DeleteSimulationEntities();
				DrawSimulationEntities(cam: false, machine: true, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawAllTool, marbleToolType2);
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
			}
			if (camTp2 == null)
			{
				SimToolIndex++;
				SimIndex = 0;
				if (SimToolIndex >= 2)
				{
					SimToolIndex = 0;
					SimItemIndex++;
				}
			}
			else
			{
				if (!((SimIndex >= 0) & (SimIndex < camTp2.SimilationPoint.SimMove.Count - 1)))
				{
					if (camTp2.SimilationPoint.MoveCommand == SimulationMoveCommand.DrawMaterial)
					{
						if (camTp2.SimilationPoint.Obj1 != null && camTp2.SimilationPoint.Obj1.GetType() == typeof(List<MaterialBase5>))
						{
							if (MarbleTempVars.tempMaterials == null)
							{
								MarbleTempVars.tempMaterials = new List<MaterialBase5>();
							}
							MarbleTempVars.tempMaterials.Clear();
							MaterialBase5.Copy((List<MaterialBase5>)camTp2.SimilationPoint.Obj1, ref MarbleTempVars.tempMaterials);
						}
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
						DeleteAllMaterials();
						AddTempMaterials();
						DeleteSimulationEntities();
						DrawSimulationEntities(cam: false, machine: true, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawAllTool, MarbleTempVars.ActiveSimulationToolType);
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
					}
					SimItemIndex++;
					SimIndex = 0;
				}
				else
				{
					MarbleTempVars.SimulationPoint.X = camTp2.SimilationPoint.SimMove[SimIndex].X;
					MarbleTempVars.SimulationPoint.Y = camTp2.SimilationPoint.SimMove[SimIndex].Y;
					MarbleTempVars.SimulationPoint.Z = camTp2.SimilationPoint.SimMove[SimIndex].Z;
					MarbleTempVars.SimulationPoint.A = camTp2.SimilationPoint.SimMove[SimIndex].A;
					MarbleTempVars.SimulationPoint.C = camTp2.SimilationPoint.SimMove[SimIndex].C;
					if (MarbleTempVars.SimulationPoint.ToolName == null)
					{
						MarbleTempVars.SimulationPoint.ToolName = "";
					}
					for (int i = 0; i <= ccVars.Tools[0].Tools.Count - 1; i++)
					{
						if (ccVars.Tools[0].Tools[i].Data.Name == MarbleTempVars.SimulationPoint.ToolName)
						{
							toolBase = new ToolBase5(ccVars.Tools[0].Tools[i]);
							if (toolBase.Geometry.GeometryType == buClass.ToolType.Saw)
							{
							}
						}
					}
					if (MarbleTempVars.SimulationPoint.MCode == 40)
					{
						MarbleTempVars.SimSpindlePistonDown = false;
					}
					if (MarbleTempVars.SimulationPoint.MCode == 41)
					{
						MarbleTempVars.SimSpindlePistonDown = true;
					}
					MoveSimPart(MarbleTempVars.SimulationPoint, MarbleTempVars.SimSpindlePistonDown, camTp2.Tool);
					if (marbleSimCoordinateUpdated_0 != null)
					{
						marbleSimCoordinateUpdated_0(camTp2.SimilationPoint.SimMove[SimIndex], camTp2.Tool, -1);
					}
					if (SimIndex == camTp2.SimilationPoint.SimMove.Count - 1 && camTp2.SimilationPoint.MoveCommand == SimulationMoveCommand.DrawMaterial)
					{
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
						doDrawActiveJob();
					}
					SimIndex += SimStep;
				}
				lastSimToolPurpose = camTp2.Tool.Purpose;
			}
		}
		if (StepMove)
		{
			timSim.Enabled = false;
		}
	}

	public void SimulationCommand(object Data1, object Data2, object Data3)
	{
		if ((SimulationCommands)Data1 == SimulationCommands.Start)
		{
			SimStep = Convert.ToInt32(Data2.ToString());
			clsInit.appMarble.cmdStartSimulation();
		}
		if ((SimulationCommands)Data1 == SimulationCommands.Stop)
		{
			SimStep = Convert.ToInt32(Data2.ToString());
			clsInit.appMarble.cmdStopSimulation();
		}
		if ((SimulationCommands)Data1 == SimulationCommands.Pause)
		{
			SimStep = Convert.ToInt32(Data2.ToString());
			clsInit.appMarble.cmdStopSimulation();
		}
		if ((SimulationCommands)Data1 == SimulationCommands.Next)
		{
			SimStep = Convert.ToInt32(Data2.ToString());
			clsInit.appMarble.Sim_Tick(null, null);
		}
		if ((SimulationCommands)Data1 == SimulationCommands.Previous)
		{
			SimStep = Convert.ToInt32(Data2.ToString());
			clsInit.appMarble.SimIndex = clsInit.appMarble.SimIndex - SimStep * 2;
			clsInit.appMarble.Sim_Tick(null, null);
		}
		if ((SimulationCommands)Data1 == SimulationCommands.StepChanged)
		{
			SimStep = Convert.ToInt32(Data2.ToString());
		}
	}

	public void DrawPreview(List<Entity> refEntities)
	{
		if (!timSim.Enabled && clsItem.ModelMainPreview != null)
		{
			clsItem.ModelMainPreview.Entities.Clear();
			for (int i = 0; i <= refEntities.Count - 1; i++)
			{
				clsItem.ModelMainPreview.Entities.Add(refEntities[i]);
			}
			clsItem.ModelMainPreview.SetView(viewType.Trimetric);
			clsItem.ModelMainPreview.ZoomFit(10);
			clsItem.ModelMainPreview.Invalidate();
		}
	}

	public void DrawPreview(ToolBase5 Tool, int ItemIndex)
	{
		if (!timSim.Enabled)
		{
		}
		if (clsItem.ModelMainPreview == null)
		{
			return;
		}
		clsItem.ModelMainPreview.ActiveViewport.DisplayMode = displayType.Rendered;
		clsItem.ModelMainPreview.Rendered.ShadowMode = shadowType.None;
		for (int i = 0; i <= buEyeItems.viewportCadCam.Materials.Count - 1; i++)
		{
			bool flag = false;
			for (int j = 0; j <= clsItem.ModelMainPreview.Materials.Count - 1; j++)
			{
				if (buEyeItems.viewportCadCam.Materials[i].Name == clsItem.ModelMainPreview.Materials[j].Name)
				{
					flag = true;
				}
			}
			if (!flag)
			{
				Material item = (Material)buEyeItems.viewportCadCam.Materials[i].Clone();
				clsItem.ModelMainPreview.Materials.Add(item);
			}
		}
		for (int k = 0; k <= buEyeItems.viewportCadCam.Layers.Count - 1; k++)
		{
			bool flag2 = false;
			for (int l = 0; l <= clsItem.ModelMainPreview.Layers.Count - 1; l++)
			{
				if (buEyeItems.viewportCadCam.Layers[k].Name == clsItem.ModelMainPreview.Layers[l].Name)
				{
					flag2 = true;
				}
			}
			if (!flag2)
			{
				Layer item2 = (Layer)buEyeItems.viewportCadCam.Layers[k].Clone();
				clsItem.ModelMainPreview.Layers.Add(item2);
			}
		}
		if (Tool == null)
		{
			if (ItemIndex != -1)
			{
				clsItem.ModelMainPreview.Entities.Clear();
				for (int m = 0; m <= buEyeItems.viewportCadCam.Entities.Count - 1; m++)
				{
					if (buEyeItems.viewportCadCam.Entities[m].EntityData == null || !(buEyeItems.viewportCadCam.Entities[m].EntityData is CustomData))
					{
						continue;
					}
					CustomData customData = buEyeItems.viewportCadCam.Entities[m].EntityData as CustomData;
					if (customData.GroupIdIndex == ItemIndex)
					{
						Entity copiedEntity = null;
						buEntity.Copy(buEyeItems.viewportCadCam.Entities[m], ref copiedEntity);
						if ((copiedEntity.GetType() != typeof(Text)) & (copiedEntity.GetType() != typeof(BlockReference)))
						{
							clsItem.ModelMainPreview.Entities.Add(copiedEntity);
						}
					}
				}
			}
			else
			{
				clsItem.ModelMainPreview.Entities.Clear();
				for (int n = 0; n <= buEyeItems.viewportCadCam.Entities.Count - 1; n++)
				{
					if (buEyeItems.viewportCadCam.Entities[n].EntityData != null && buEyeItems.viewportCadCam.Entities[n].EntityData is CustomData)
					{
						_ = buEyeItems.viewportCadCam.Entities[n].EntityData is CustomData;
						Entity copiedEntity2 = null;
						buEntity.Copy(buEyeItems.viewportCadCam.Entities[n], ref copiedEntity2);
						if ((copiedEntity2.GetType() != typeof(Text)) & (copiedEntity2.GetType() != typeof(BlockReference)))
						{
							clsItem.ModelMainPreview.Entities.Add(copiedEntity2);
						}
					}
				}
			}
		}
		else
		{
			clsItem.ModelMainPreview.Entities.Clear();
			List<Mesh> refMeshes = new List<Mesh>();
			clsInit.appMW.CreateTool(Tool, ToolCut: true, ToolBody: false, Arbor: false, Holder: false, ref refMeshes);
			for (int num = 0; num <= refMeshes.Count - 1; num++)
			{
				clsItem.ModelMainPreview.Entities.Add(refMeshes[num]);
			}
		}
		clsItem.ModelMainPreview.SetView(viewType.Trimetric);
		clsItem.ModelMainPreview.ZoomFit();
		clsItem.ModelMainPreview.Invalidate();
	}

