	public Design doDrawCameraImage(Design Viewport)
	{
		try
		{
			for (int i = 0; i <= Viewport.Entities.Count - 1; i++)
			{
				if ((Viewport.Entities[i] is Picture) & (Viewport.Entities[i].EntityData != null))
				{
					CustomData customData = Viewport.Entities[i].EntityData as CustomData;
					if (customData.typeDefination == entityTypeDefination.CameraImage)
					{
						Viewport.Entities[i].Selected = true;
					}
				}
			}
			Viewport.Entities.DeleteSelected();
			if (MarbleTempVars.CameraImage != null)
			{
				if (MarbleTempVars.CameraImage.EntityData != null)
				{
					if (MarbleTempVars.CameraImage.EntityData.GetType() != typeof(CustomData))
					{
						CustomData customData2 = new CustomData();
						customData2.typeDefination = entityTypeDefination.CameraImage;
						MarbleTempVars.CameraImage.EntityData = customData2;
					}
				}
				else
				{
					CustomData customData3 = new CustomData();
					customData3.typeDefination = entityTypeDefination.CameraImage;
					MarbleTempVars.CameraImage.EntityData = customData3;
				}
				Viewport.Entities.Add(MarbleTempVars.CameraImage);
			}
			return Viewport;
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
			return Viewport;
		}
	}

	public void EntitiesSelectableStates(bool EdgeSelectable, bool OperationSelectable, bool CollapseSelectable, bool SlatSelectable, bool VacuumSelectable)
	{
		MarbleTempVars.selectableCollapse = CollapseSelectable;
		MarbleTempVars.selectableSlat = SlatSelectable;
		MarbleTempVars.selectableEdge = EdgeSelectable;
		MarbleTempVars.selectableOperation = OperationSelectable;
		MarbleTempVars.selectableVacuum = VacuumSelectable;
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			entity.Selectable = false;
			if (entity.EntityData != null && entity.EntityData is CustomData)
			{
				CustomData customData = entity.EntityData as CustomData;
				if (customData.Tags != null && customData.Tags == "Solid")
				{
					entity.Selectable = OperationSelectable;
				}
				if (customData.Tags != null && customData.Tags == "Edge")
				{
					entity.Selectable = EdgeSelectable;
				}
				if (customData.Tags != null && customData.Tags == "VacuumCut")
				{
					entity.Selectable = VacuumSelectable;
				}
				if (customData.Tags != null && customData.Tags == "Slat")
				{
					entity.Selectable = SlatSelectable;
				}
				if (customData.Tags != null && customData.Tags == "Collapse")
				{
					entity.Selectable = CollapseSelectable;
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.UpdateVisibleSelection();
	}

