	public void AddTempMaterials()
	{
		List<Entity> list = new List<Entity>();
		if (MarbleTempVars.tempMaterials != null && MarbleTempVars.tempMaterials.Count > 0)
		{
			for (int i = 0; i <= MarbleTempVars.tempMaterials.Count - 1; i++)
			{
				MaterialBase5 materialBase = MarbleTempVars.tempMaterials[i];
				Entity copiedEntity = null;
				buEntity.Copy(MarbleTempVars.tempMaterials[i].Entities[0], ref copiedEntity);
				copiedEntity = clsInit.cMarble.SetEntityData(copiedEntity, null, -1, i, -1, "VacuumMaterial", entityTypeDefination.Material, MarbleTempVars.layerDrawing.Name, Selectable: false, 1.0, Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemVacuumCutMaterial.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemVacuumCutMaterial.Color));
				((CustomData)copiedEntity.EntityData).Sequence = i;
				copiedEntity.Translate(materialBase.OffsetX, materialBase.OffsetY, buMarbleCalc.varMarbleSettings.ImageZPosition + 0.02);
				list.Add(copiedEntity);
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.AddRange(list);
		}
	}

	public void AddMainMaterials()
	{
		List<Entity> list = new List<Entity>();
		if (clsInit.appMarble.activeJob.Material != null && clsInit.appMarble.activeJob.Material.Enable)
		{
			CustomData customData = null;
			if (clsInit.appMarble.activeJob.Material.matImage != null)
			{
				byte[] image = clsInit.appMarble.activeJob.Material.matImage.ToByteArray();
				Picture picture = new Picture(Plane.XY, clsInit.appMarble.activeJob.Material.Size.Width, clsInit.appMarble.activeJob.Material.Size.Height, image);
				picture.Translate(0.0, 0.0, buMarbleCalc.varMarbleSettings.ImageZPosition);
				picture.Selectable = false;
				picture.LayerName = MarbleTempVars.layerMarbleSheet.Name;
				customData = new CustomData();
				customData.typeDefination = entityTypeDefination.Material;
				picture.EntityData = customData;
				picture.Selectable = false;
				list.Add(picture);
			}
			if (clsInit.appMarble.activeJob.Material.Entities.Count > 0)
			{
				for (int i = 0; i <= clsInit.appMarble.activeJob.Material.Entities.Count - 1; i++)
				{
					clsInit.appMarble.activeJob.Material.Entities[i].Selected = false;
					list.Add(clsInit.appMarble.activeJob.Material.Entities[i]);
				}
				if (buMarbleCalc.varMarbleDrawSettings.DrawMaterialDimension)
				{
					double num = clsInit.appMarble.activeJob.Material.Size.Width;
					if (clsInit.appMarble.activeJob.Material.Size.Height < num)
					{
						num = clsInit.appMarble.activeJob.Material.Size.Height;
					}
					double num2 = num * 0.08;
					if (num2 < 10.0)
					{
						num2 = 10.0;
					}
					LinearDim linearDim = new LinearDim(Plane.XY, new Point3D(), new Point3D(clsInit.appMarble.activeJob.Material.Size.Width, 0.0, 0.0), new Point3D(clsInit.appMarble.activeJob.Material.Size.Width / 2.0, -200.0, 0.0), num2);
					linearDim.TextOverride = buLangTranslate.preChar.Width + ": " + linearDim.Distance;
					customData = new CustomData();
					customData.typeDefination = entityTypeDefination.Material;
					linearDim.EntityData = customData;
					linearDim.Color = buMarbleCalc.varMarbleColorSettings.colorMaterialDimension.Color;
					list.Add(linearDim);
					Plane drawingPlane = null;
					clsInit.cVector5.LinearDimCalculate(new Point3D(0.0, 0.0), new Point3D(0.0, clsInit.appMarble.activeJob.Material.Size.Height), new Point3D(-200.0, clsInit.appMarble.activeJob.Material.Size.Height / 2.0), 100.0, Plane.XY, ref drawingPlane);
					LinearDim linearDim2 = new LinearDim(drawingPlane, new Point3D(), new Point3D(0.0, clsInit.appMarble.activeJob.Material.Size.Height, 0.0), new Point3D(-200.0, clsInit.appMarble.activeJob.Material.Size.Height / 2.0, 0.0), num2);
					linearDim2.TextOverride = buLangTranslate.preChar.Height + ": " + linearDim2.Distance;
					customData = new CustomData();
					customData.typeDefination = entityTypeDefination.Material;
					linearDim2.EntityData = customData;
					linearDim2.Color = buMarbleCalc.varMarbleColorSettings.colorMaterialDimension.Color;
					list.Add(linearDim2);
					clsInit.cVector5.LinearDimCalculate(new Point3D(0.0, 0.0, 0.0), new Point3D(0.0, 0.0, clsInit.appMarble.activeJob.Material.Size.Depth), new Point3D(-200.0, 0.0, clsInit.appMarble.activeJob.Material.Size.Depth / 2.0), 100.0, Plane.XZ, ref drawingPlane);
					LinearDim linearDim3 = new LinearDim(drawingPlane, new Point3D(0.0, 0.0, 0.0), new Point3D(0.0, 0.0, clsInit.appMarble.activeJob.Material.Size.Depth), new Point3D(-200.0, 0.0, clsInit.appMarble.activeJob.Material.Size.Depth / 2.0), num2);
					linearDim3.TextOverride = buLangTranslate.preChar.Depth + ": " + linearDim3.Distance;
					customData = new CustomData();
					customData.typeDefination = entityTypeDefination.Material;
					linearDim3.EntityData = customData;
					linearDim3.Color = buMarbleCalc.varMarbleColorSettings.colorMaterialDimension.Color;
					list.Add(linearDim3);
				}
			}
		}
		if ((MarbleTempVars.MaterialLimits.Count >= 3) & buMarbleCalc.varMarbleSettings.ShowMaterialLimits)
		{
			LinearPath linearPath = new LinearPath(MarbleTempVars.MaterialLimits);
			linearPath.LayerName = MarbleTempVars.layerMarbleSheet.Name;
			CustomData customData2 = new CustomData();
			customData2.typeDefination = entityTypeDefination.Material;
			linearPath.EntityData = customData2;
			linearPath.Selectable = false;
			linearPath.Color = Color.Cyan;
			linearPath.ColorMethod = colorMethodType.byEntity;
			linearPath.LineWeight = 3f;
			linearPath.LineWeightMethod = colorMethodType.byEntity;
			list.Add(linearPath);
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.AddRange(list);
	}

	public void AddDimension(Entity Ent, bool isLinear)
	{
		Ent.ColorMethod = colorMethodType.byEntity;
		Ent.LineTypeMethod = colorMethodType.byEntity;
		Ent.LineWeightMethod = colorMethodType.byEntity;
		Ent.Color = buMarbleCalc.varMarbleEntitiesSettings.DimensionColor;
		Ent.LineWeight = Convert.ToSingle(buMarbleCalc.varMarbleEntitiesSettings.DimensionThickness);
		Ent.LayerName = "Default";
		if (Ent.EntityData != null && Ent.EntityData is CustomData)
		{
			((CustomData)Ent.EntityData).typeDefination = entityTypeDefination.Dimension;
			if (!isLinear)
			{
				((CustomData)Ent.EntityData).infoString = buLangTranslate.preDef.Aligned;
			}
			else
			{
				((CustomData)Ent.EntityData).infoString = buLangTranslate.preDef.Linear;
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Ent);
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void DeleteAllDimension()
	{
		buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
		buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
		buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.DeleteAll, buLangTranslate.preSentences.DoYouWanttoDeleteAllDimension);
		buDialogMessageBoxYesNo2.ShowDialog();
		if (buDialogMessageBoxYesNo2.Result != DialogResult.Yes)
		{
			return;
		}
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData != null)
			{
				CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
				if (customData.typeDefination == entityTypeDefination.Dimension)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void DeleteAllMaterials()
	{
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData != null)
			{
				CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
				if (customData.typeDefination == entityTypeDefination.Material)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void DeleteDimension(int Index)
	{
		buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
		buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
		buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.DeleteAll, buLangTranslate.preSentences.DoYouWanttoDeleteAllDimension);
		buDialogMessageBoxYesNo2.ShowDialog();
		if (buDialogMessageBoxYesNo2.Result != DialogResult.Yes)
		{
			return;
		}
		int num = 0;
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData == null)
			{
				continue;
			}
			CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
			if (customData.typeDefination == entityTypeDefination.Dimension)
			{
				if (num == Index)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
				}
				num++;
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void CreateMaterialsAndLayers(string pathWood, string pathMarble, ref ViewportCC viewport)
	{
		List<string> Files = new List<string>();
		buFile5.GetFilesInDirectory(pathWood, "png", ref Files);
		buFile5.GetFilesInDirectory(pathWood, "jpg", ref Files);
		viewport.Layers.Clear();
		Layer layer;
		if (Files.Count > 0)
		{
			string text = Files[0];
			for (int i = 0; i <= Files.Count - 1; i++)
			{
				string text2 = buFile5.getFileNameWithoutExtension(Files[i]).Trim().ToLower();
				if (buMarbleCalc.varMarbleRunSettings.WoodTextureName.ToLower() == text2)
				{
					text = Files[i];
				}
			}
			buMarbleCalc.varMarbleRunSettings.WoodTextureName = buFile5.getFileNameWithoutExtension(text).Trim();
			Bitmap image = new Bitmap(text);
			Material material = new Material(buMarbleCalc.varMarbleRunSettings.WoodTextureName, Color.FromArgb(100, 100, 100), Color.White, 1f, image.ToByteArray())
			{
				LinearUnits = linearUnitsType.Millimeters,
				MassUnits = massUnitsType.Kilograms,
				Density = 6E-07,
				TextureLength = 2000f,
				Environment = 0.01f
			};
			viewport.Materials.Add(material);
			layer = new Layer(MarbleTempVars.layerWood.Name, MarbleTempVars.layerWood.Color);
			layer.LineWeight = (float)MarbleTempVars.layerWood.Thickness;
			layer.MaterialName = material.Name;
			viewport.Layers.Add(layer);
		}
		layer = new Layer(MarbleTempVars.layerMarbleSheet.Name, Color.FromArgb(buMarbleCalc.varMarbleSettings.MarbleMaterialTransparan, MarbleTempVars.layerMarbleSheet.Color));
		layer.LineWeight = (float)MarbleTempVars.layerMarbleSheet.Thickness;
		viewport.Layers.Add(layer);
		Files = new List<string>();
		buFile5.GetFilesInDirectory(pathMarble, "png", ref Files);
		buFile5.GetFilesInDirectory(pathMarble, "jpg", ref Files);
		if (Files.Count <= 0)
		{
			layer = new Layer(MarbleTempVars.layerMarblePart.Name, MarbleTempVars.layerMarblePart.Color);
			layer.LineWeight = (float)MarbleTempVars.layerDrawing.Thickness;
			viewport.Layers.Add(layer);
		}
		else
		{
			string text3 = Files[0];
			for (int j = 0; j <= Files.Count - 1; j++)
			{
				string text4 = buFile5.getFileNameWithoutExtension(Files[j]).Trim().ToLower();
				if (buMarbleCalc.varMarbleRunSettings.MarbleTextureName.ToLower() == text4)
				{
					text3 = Files[j];
				}
			}
			buMarbleCalc.varMarbleRunSettings.MarbleTextureName = buFile5.getFileNameWithoutExtension(text3).Trim();
			Bitmap image2 = new Bitmap(text3);
			Material material2 = new Material(buMarbleCalc.varMarbleRunSettings.MarbleTextureName, Color.FromArgb(100, 100, 100), Color.White, 1f, image2.ToByteArray())
			{
				LinearUnits = linearUnitsType.Millimeters,
				MassUnits = massUnitsType.Kilograms,
				Density = 6E-07,
				TextureLength = 2000f,
				Environment = 0.01f
			};
			viewport.Materials.Add(material2);
			layer = new Layer(MarbleTempVars.layerMarblePart.Name, MarbleTempVars.layerMarblePart.Color);
			layer.LineWeight = (float)MarbleTempVars.layerMarblePart.Thickness;
			layer.MaterialName = material2.Name;
			viewport.Layers.Add(layer);
		}
		layer = new Layer(MarbleTempVars.layerDrawing.Name, MarbleTempVars.layerDrawing.Color);
		layer.LineWeight = (float)MarbleTempVars.layerDrawing.Thickness;
		viewport.Layers.Add(layer);
		layer = new Layer(MarbleTempVars.layerCutting.Name, MarbleTempVars.layerCutting.Color);
		layer.LineWeight = (float)MarbleTempVars.layerCutting.Thickness;
		viewport.Layers.Add(layer);
		layer = new Layer(MarbleTempVars.layerMachine.Name, MarbleTempVars.layerMachine.Color);
		layer.LineWeight = (float)MarbleTempVars.layerMachine.Thickness;
		viewport.Layers.Add(layer);
		layer = new Layer(MarbleTempVars.layerShape.Name, MarbleTempVars.layerShape.Color);
		layer.LineWeight = (float)MarbleTempVars.layerShape.Thickness;
		viewport.Layers.Add(layer);
		layer = new Layer(MarbleTempVars.layer3D.Name, MarbleTempVars.layer3D.Color);
		layer.LineWeight = (float)MarbleTempVars.layer3D.Thickness;
		viewport.Layers.Add(layer);
		layer = new Layer(MarbleTempVars.layerCam.Name, Color.Red);
		layer.LineWeight = (float)MarbleTempVars.layerCam.Thickness;
		viewport.Layers.Add(layer);
		layer = new Layer(MarbleTempVars.layerAngle.Name, MarbleTempVars.layerAngle.Color);
		layer.LineWeight = (float)MarbleTempVars.layerAngle.Thickness;
		viewport.Layers.Add(layer);
		layer = new Layer(MarbleTempVars.layerEngrave.Name, MarbleTempVars.layerEngrave.Color);
		layer.LineWeight = (float)MarbleTempVars.layerEngrave.Thickness;
		viewport.Layers.Add(layer);
		if (viewport.Layers[0].Name == "Default")
		{
			viewport.Layers.RemoveAt(0);
		}
		ccVars.Pages[ccVars.PageIndex].Layers.Clear();
		for (int k = 0; k <= viewport.Layers.Count - 1; k++)
		{
			LayerBase5 buLayer = new LayerBase5();
			buConversion5.eyeLayerTobuLayer(viewport.Layers[k], ref buLayer);
			ccVars.Pages[ccVars.PageIndex].Layers.Add(buLayer);
		}
	}

