	public void CreateWoodMaterial(double Width, double Height, double Depth, double OffsetZ, bool TopOnZero, string LayerName, ref Entity entWood)
	{
		entWood = Brep.CreateBox(Width, Height, Depth);
		if (!TopOnZero)
		{
			entWood.Translate(0.0, 0.0, OffsetZ);
		}
		else
		{
			entWood.Translate(0.0, 0.0, 0.0 - Depth + OffsetZ);
		}
		entWood.LayerName = LayerName;
		CustomData customData = new CustomData();
		customData.ActionName = "woodbase";
		customData.infoWidth = Width;
		customData.infoHeight = Height;
		customData.infoDepth = Depth;
		customData.typeDefination = entityTypeDefination.Base;
		entWood.EntityData = customData;
	}

	public void CreateMarbleMaterial(buEntitiesGroup entGroup, double Thickness, Point3D Offset, bool TopOnZero, string LayerName, ref Entity entMarble)
	{
		clsInit.cVector5.surfaceFromOutterInner(entGroup, Thickness, ref entMarble, 0.1, buMarbleCalc.varImageSettings.SheetInnerMakeItHoleas3D, AsMesh: false);
		if (entMarble != null)
		{
			if (!TopOnZero)
			{
				entMarble.Translate(Offset.X, Offset.Y, Offset.Z);
			}
			else
			{
				entMarble.Translate(Offset.X, Offset.Y, 0.0 - Thickness + Offset.Z);
			}
			entMarble.LayerName = LayerName;
			CustomData customData = new CustomData();
			customData.ActionName = "marblematerial";
			customData.infoDepth = Thickness;
			customData.typeDefination = entityTypeDefination.Sheet;
			entMarble.EntityData = customData;
		}
	}

	public void AddOrUpdateMarbleSheet(List<Entity> entSheets, buEntitiesGroup Group)
	{
		for (int i = 0; i <= buEyeItems.viewportCadCam.Entities.Count - 1; i++)
		{
			Entity entity = buEyeItems.viewportCadCam.Entities[i];
			if (entity.EntityData != null && entity.EntityData is CustomData)
			{
				CustomData customData = entity.EntityData as CustomData;
				if (customData.typeDefination == entityTypeDefination.Sheet)
				{
					buEyeItems.viewportCadCam.Entities[i].Selected = true;
				}
			}
		}
		buEyeItems.viewportCadCam.Entities.DeleteSelected();
		for (int j = 0; j <= entSheets.Count - 1; j++)
		{
			buEyeItems.viewportCadCam.Entities.Add(entSheets[j]);
		}
		if (Group != null && Group.Inside != null)
		{
			for (int k = 0; k <= Group.Inside.Count - 1; k++)
			{
				for (int l = 0; l <= Group.Inside[k].Entities.Count - 1; l++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(Group.Inside[k].Entities[l], ref copiedEntity);
					if (copiedEntity != null)
					{
						copiedEntity.ColorMethod = colorMethodType.byEntity;
						copiedEntity.Color = Color.Red;
						copiedEntity.LineTypeMethod = colorMethodType.byEntity;
						copiedEntity.LineWeight = 3f;
						copiedEntity.Selectable = false;
						CustomData customData2 = new CustomData();
						customData2.typeDefination = entityTypeDefination.Sheet;
						copiedEntity.EntityData = customData2;
						buEyeItems.viewportCadCam.Entities.Add(copiedEntity);
					}
				}
			}
		}
		buEyeItems.viewportCadCam.Invalidate();
	}

