						tnCamBase.NodeFont = new Font("Microsoft Sans Serif", 10f, FontStyle.Bold | FontStyle.Strikeout);
					}
					tnCamList.Nodes.Add(tnCamBase);
				}
				tnPanel.Nodes.Add(tnCamList);
				for (int num4 = 0; num4 <= activeJob.TotalMessages.Count - 1; num4++)
				{
					int num5 = 0;
					num5 = ((activeJob.TotalMessages[num4].Mode == InfoTypeMode.Alarm) ? 59 : ((activeJob.TotalMessages[num4].Mode == InfoTypeMode.Warning) ? 58 : 60));
					TreeNodeSettings node5 = new TreeNodeSettings(activeJob.TotalMessages[num4].Message)
					{
						ImageIndex = num5,
						SelectedImageIndex = num5,
						Tag = "0",
						ClassIndex = 0,
						ClassSubIndex = -1,
						ClassSubSubIndex = -1,
						Command = MarbleOperationSelectionCommand.Message.ToString(),
						Checked = true
					};
					tnPanel.Nodes.Add(node5);
				}
				if (tnPanel != null)
				{
					tnPanel.Expand();
					tnCamList.Expand();
					buMarbleControls.treeJob.Nodes.Add(tnPanel);
				}
				JobUpdating = false;
			}
			else
			{
				buMarbleControls.treeJob.Nodes.Clear();
			}
		}
		catch (Exception mSException)
		{
			JobUpdating = false;
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void JobDelete()
	{
		if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand == MarbleOperationSelectionCommand.Item && ((buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0) & (buMarbleCalc.SelectedItem.ActiveItem.indexItem <= activeJob.Items.Count - 1)))
		{
			MarbleItem marbleItem = activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
			doDeleteItems(All: false, marbleItem.ID);
		}
		if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand == MarbleOperationSelectionCommand.CamNode && ((buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0) & (buMarbleCalc.SelectedItem.ActiveItem.indexItem <= activeJob.Items.Count - 1)))
		{
			MarbleItem marbleItem2 = activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
			if ((buMarbleCalc.SelectedItem.ActiveItem.indexCam >= 0) & (buMarbleCalc.SelectedItem.ActiveItem.indexCam <= marbleItem2.CamList.Count - 1))
			{
				doDeleteCam(All: false, buMarbleCalc.SelectedItem.ActiveItem.indexItem, buMarbleCalc.SelectedItem.ActiveItem.indexCam);
			}
		}
		if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand == MarbleOperationSelectionCommand.Panel)
		{
			activeJob.Material.Enable = false;
			activeJob.Material.matImage = null;
			activeJob.Material.Entities = new List<Entity>();
			JobUpdate();
		}
	}

