	public void JobCamEnableDisable()
	{
		if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand != MarbleOperationSelectionCommand.CamListNode || !((buMarbleCalc.SelectedItem.ActiveItem.indexCamList >= 0) & (buMarbleCalc.SelectedItem.ActiveItem.indexCamList <= activeJob.Cams.Count - 1)))
		{
			return;
		}
		string text = "";
		camTp camTp2 = activeJob.Cams[buMarbleCalc.SelectedItem.ActiveItem.indexCamList];
		text = (camTp2.Enable ? buLangTranslate.preDef.Disable : buLangTranslate.preDef.Enable);
		buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
		buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
		buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.Enable + " / " + buLangTranslate.preDef.Disable, camTp2.Name + Environment.NewLine + buLangTranslate.preSentences.DoYouWantToChange + ", " + text);
		buDialogMessageBoxYesNo2.ShowDialog();
		if (buDialogMessageBoxYesNo2.Result != DialogResult.Yes)
		{
			return;
		}
		if (!camTp2.Enable)
		{
			camTp2.Enable = true;
		}
		else
		{
			camTp2.Enable = false;
		}
		activeJob.isGCodeCreated = false;
		activeJob.isSimulationDone = false;
		if (tnPanel == null || tnPanel.Nodes == null)
		{
			return;
		}
		for (int i = 0; i <= tnPanel.Nodes.Count - 1; i++)
		{
			TreeNodeSettings treeNodeSettings = tnPanel.Nodes[i] as TreeNodeSettings;
			if (treeNodeSettings.Command == MarbleOperationSelectionCommand.CamList.ToString())
			{
				TreeNodeSettings treeNodeSettings2 = treeNodeSettings.Nodes[buMarbleCalc.SelectedItem.ActiveItem.indexCamList] as TreeNodeSettings;
				if (camTp2.Enable)
				{
					treeNodeSettings2.ForeColor = Color.Black;
					treeNodeSettings2.NodeFont = new Font("Microsoft Sans Serif", 10f, FontStyle.Bold);
				}
				else
				{
					treeNodeSettings2.ForeColor = Color.Red;
					treeNodeSettings2.NodeFont = new Font("Microsoft Sans Serif", 10f, FontStyle.Bold | FontStyle.Strikeout);
				}
			}
		}
	}

	public void JobCamMoveUpDown(bool Up)
	{
		if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand != MarbleOperationSelectionCommand.CamListNode || !((buMarbleCalc.SelectedItem.ActiveItem.indexCamList >= 0) & (buMarbleCalc.SelectedItem.ActiveItem.indexCamList <= activeJob.Cams.Count - 1)))
		{
			return;
		}
		string text = "";
		camTp camTp2 = activeJob.Cams[buMarbleCalc.SelectedItem.ActiveItem.indexCamList];
		text = (Up ? (buLangTranslate.preDef.Move + " " + buLangTranslate.preDef.Up) : (buLangTranslate.preDef.Move + " " + buLangTranslate.preDef.Down));
		buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
		buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
		buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.Up + " / " + buLangTranslate.preDef.Down, camTp2.Name + Environment.NewLine + buLangTranslate.preSentences.DoYouWantToChange + ", " + text);
		buDialogMessageBoxYesNo2.ShowDialog();
		if (buDialogMessageBoxYesNo2.Result != DialogResult.Yes)
		{
			return;
		}
		activeJob.isGCodeCreated = false;
		activeJob.isSimulationDone = false;
		if (!Up)
		{
			if (buMarbleCalc.SelectedItem.ActiveItem.indexCamList <= activeJob.Cams.Count - 2)
			{
				camTp item = activeJob.Cams[buMarbleCalc.SelectedItem.ActiveItem.indexCamList];
				activeJob.Cams.RemoveAt(buMarbleCalc.SelectedItem.ActiveItem.indexCamList);
				activeJob.Cams.Insert(buMarbleCalc.SelectedItem.ActiveItem.indexCamList + 1, item);
			}
		}
		else if (buMarbleCalc.SelectedItem.ActiveItem.indexCamList > 0)
		{
			camTp item2 = activeJob.Cams[buMarbleCalc.SelectedItem.ActiveItem.indexCamList];
			activeJob.Cams.RemoveAt(buMarbleCalc.SelectedItem.ActiveItem.indexCamList);
			activeJob.Cams.Insert(buMarbleCalc.SelectedItem.ActiveItem.indexCamList - 1, item2);
		}
	}

	public int JobToolImageIndex(MarbleToolType CamToolType, ToolBase5 Tool)
	{
		int result = -1;
		switch (CamToolType)
		{
		default:
			if ((CamToolType == MarbleToolType.Milling || CamToolType == MarbleToolType.MillingHead) && Tool != null)
			{
				if (Tool.Geometry.GeometryType == buClass.ToolType.Barrel)
				{
					result = 9;
				}
				if (Tool.Geometry.GeometryType == buClass.ToolType.Bullnose)
				{
					result = 8;
				}
				if (Tool.Geometry.GeometryType == buClass.ToolType.Chamfer)
				{
					result = 10;
				}
				if (Tool.Geometry.GeometryType == buClass.ToolType.ConvexTip)
				{
					result = 11;
				}
				if (Tool.Geometry.GeometryType == buClass.ToolType.Dove)
				{
					result = 12;
				}
				if (Tool.Geometry.GeometryType == buClass.ToolType.Flat)
				{
					result = 6;
				}
				if (Tool.Geometry.GeometryType == buClass.ToolType.Lollipop)
				{
					result = 13;
				}
				if (Tool.Geometry.GeometryType == buClass.ToolType.Slot)
				{
					result = 14;
				}
				if (Tool.Geometry.GeometryType == buClass.ToolType.Sphere)
				{
					result = 7;
				}
				if (Tool.Geometry.GeometryType == buClass.ToolType.Taper)
				{
					result = 15;
				}
			}
			break;
		case MarbleToolType.Saw:
			if (Tool != null)
			{
				result = 5;
			}
			break;
		case MarbleToolType.WaterJet:
			if (Tool != null)
			{
				result = 16;
			}
			break;
		}
		return result;
	}

