	public string JobToString(MarbleJob Job)
	{
		string text = Job.Name.Trim();
		if (text.Length == 0)
		{
			text = buLangTranslate.preDef.Marble + " " + buLangTranslate.preDef.Block;
		}
		if ((Job.Material.Size.Width > 0.0) & (Job.Material.Size.Height > 0.0) & (Job.Material.Size.Depth > 0.0))
		{
			text = text + "- W: " + Job.Material.Size.Width.ToString("f1") + ", H: " + Job.Material.Size.Height.ToString("f1") + ", D: " + Job.Material.Size.Depth.ToString("f1");
		}
		return text;
	}

	public void JobSelectEntityAtPageViewprt(int indexEntity)
	{
		if (!((indexEntity >= 0) & (indexEntity <= activeJob.Items.Count - 1)))
		{
			return;
		}
		buEyeItems.viewportCadCam.Entities.ClearSelection();
		for (int i = 0; i <= buEyeItems.viewportCadCam.Entities.Count - 1; i++)
		{
			if (buEyeItems.viewportCadCam.Entities[i].EntityData != null && buEyeItems.viewportCadCam.Entities[i].EntityData is CustomData)
			{
				CustomData customData = buEyeItems.viewportCadCam.Entities[i].EntityData as CustomData;
				if (customData.GroupIdIndex == indexEntity)
				{
					buEyeItems.viewportCadCam.Entities[i].Selected = true;
				}
			}
		}
		buEyeItems.viewportCadCam.Invalidate();
	}

	public void JobCamEntityAtPageViewprt(int indexItem, int indexCam)
	{
		if (!((indexItem >= 0) & (indexItem <= activeJob.Items.Count - 1)) || !((indexCam >= 0) & (indexCam <= activeJob.Items[indexItem].CamList.Count - 1)))
		{
			return;
		}
		buEyeItems.viewportCadCam.Entities.ClearSelection();
		for (int i = 0; i <= buEyeItems.viewportCadCam.Entities.Count - 1; i++)
		{
			if (buEyeItems.viewportCadCam.Entities[i].EntityData != null && buEyeItems.viewportCadCam.Entities[i].EntityData is CustomData)
			{
				CustomData customData = buEyeItems.viewportCadCam.Entities[i].EntityData as CustomData;
				if (customData.CamID == indexCam)
				{
					buEyeItems.viewportCadCam.Entities[i].Selected = true;
				}
			}
		}
		buEyeItems.viewportCadCam.Invalidate();
	}

