	public void ItemListAnalyse(marbleCuttingItems[] cutItems, ref List<marbleCuttingItems> listCutItems, double StartAngleSing = 1.0, double EndAngleSing = 1.0)
	{
		for (int i = 0; i <= cutItems.Length - 1; i++)
		{
			if ((Math.Abs(cutItems[i].Length) > 0.1) & (cutItems[i].Count > 0))
			{
				marbleCuttingItems marbleCuttingItems2 = new marbleCuttingItems(cutItems[i]);
				marbleCuttingItems2.StartAngle *= StartAngleSing;
				marbleCuttingItems2.EndAngle *= EndAngleSing;
				listCutItems.Add(marbleCuttingItems2);
			}
		}
	}

