	public void SaveMarbleFile()
	{
		if (!MarbleTempVars.SavingMarble)
		{
			Task.Run(delegate
			{
				SaveMarbleFile(AppPath.Settings + "\\Marble");
			});
		}
	}

	public void SaveMarbleFile(string Path)
	{
		try
		{
			if (MarbleTempVars.SavingMarble)
			{
				return;
			}
			MarbleTempVars.SavingMarble = true;
			if (AppBool.MachineMode)
			{
				DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.MachineSettingsCam + "\\Marble");
				if (directoryInfo.Exists)
				{
					Path = directoryInfo.FullName;
				}
			}
			string fileName = Path + "\\Marble.prm";
			ArrayList arrayList = new ArrayList();
			arrayList.Add("------------------------------------------------------------------------");
			arrayList.Add("   Marble Settings");
			arrayList.Add("------------------------------------------------------------------------");
			arrayList.Add("<varMarbleSettings>");
			arrayList.AddRange(buMarbleCalc.varMarbleSettings.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("</varMarbleSettings>");
			arrayList.Add(" ");
			arrayList.Add("<varMarbleRunSettings>");
			arrayList.AddRange(buMarbleCalc.varMarbleRunSettings.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("</varMarbleRunSettings>");
			arrayList.Add(" ");
			arrayList.Add("<varMarbleMachineSettings>");
			arrayList.AddRange(buMarbleCalc.varMarbleMachineSettings.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("</varMarbleMachineSettings>");
			arrayList.Add(" ");
			arrayList.Add("<varMarbleDisplaySettings>");
			arrayList.AddRange(buMarbleCalc.varMarbleDisplaySettings.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("</varMarbleDisplaySettings>");
			arrayList.Add(" ");
			arrayList.Add("<varMarbleDrawSettings>");
			arrayList.AddRange(buMarbleCalc.varMarbleDrawSettings.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("</varMarbleDrawSettings>");
			arrayList.Add(" ");
			arrayList.Add("<varMarbleColorSettings>");
			arrayList.AddRange(buMarbleCalc.varMarbleColorSettings.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("</varMarbleColorSettings>");
			arrayList.Add(" ");
			arrayList.Add("<varMarbleEntitiesSettings>");
			arrayList.AddRange(buMarbleCalc.varMarbleEntitiesSettings.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("</varMarbleEntitiesSettings>");
			arrayList.Add(" ");
			arrayList.Add("<varCountertopSettings>");
			arrayList.AddRange(buMarbleCalc.varCountertopSettings.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("</varCountertopSettings>");
			arrayList.Add(" ");
			arrayList.Add("<varCountertopParameter>");
			arrayList.AddRange(buMarbleCalc.varCountertopParameter.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("</varCountertopParameter>");
			arrayList.Add(" ");
			arrayList.Add("------------------------------------------------------------------------");
			arrayList.Add("   buMarbleCalc.varOperation");
			arrayList.Add("------------------------------------------------------------------------");
			arrayList.Add("<buMarbleCalc.varOperation>");
			arrayList.AddRange(buMarbleCalc.varOperation.ToDefAll("", 2, SerilizationMode5.MultiLine));
			arrayList.Add("  <buMarbleCalc.Sequence>");
			for (int i = 0; i <= buMarbleCalc.varOperation.CuttingSequence.Count - 1; i++)
			{
				arrayList.Add("    " + buMarbleCalc.varOperation.CuttingSequence[i]);
			}
			arrayList.Add("  </buMarbleCalc.Sequence>");
			arrayList.Add("</buMarbleCalc.varOperation>");
			arrayList.Add(" ");
			arrayList.Add("------------------------------------------------------------------------");
			arrayList.Add("   Geometry Resolutions");
			arrayList.Add("------------------------------------------------------------------------");
			arrayList.Add("  <GeometryResolutions>");
			for (int j = 0; j <= buMarbleCalc.CircularShapeResolutions.Count - 1; j++)
			{
				arrayList.AddRange(buMarbleCalc.CircularShapeResolutions[j].ToDefAll("", 6, SerilizationMode5.MultiLine));
			}
			arrayList.Add("  </GeometryResolutions>");
			arrayList.Add(" ");
			arrayList.Add("------------------------------------------------------------------------");
			arrayList.Add("   Circular Speed Reductions");
			arrayList.Add("------------------------------------------------------------------------");
			arrayList.Add("  <CircularSpeedReduce>");
			for (int k = 0; k <= buMarbleCalc.CircularSpeedReductions.Count - 1; k++)
			{
				arrayList.AddRange(buMarbleCalc.CircularSpeedReductions[k].ToDefAll("", 6, SerilizationMode5.MultiLine));
			}
			arrayList.Add("  </CircularSpeedReduce>");
			arrayList.Add(" ");
			arrayList.Add("");
			buFile.SaveToFile(arrayList, fileName);
			buLog.addLog("Marble Set Saved", "Ok", MethodBase.GetCurrentMethod().Name);
			buMWMarbleVars.varCamMarbleMesh5DConstantZ.mwPar.Serialize(Path + "\\mwMarbleMesh5DConstantZ.bin");
			buMWMarbleVars.varCamMarbleMesh5DParelelCut.mwPar.Serialize(Path + "\\mwMarbleMesh5DParelelCut.bin");
			buMWMarbleVars.varCamMarbleMesh5DGeodesic.mwPar.Serialize(Path + "\\mwMarbleMesh5DGeodesic.bin");
			buMWMarbleVars.varCamMarbleMeshConstantZ.mwPar.Serialize(Path + "\\mwMarbleMeshConstantZ.bin");
