	public void OpenMarbleDrillFile(string Filename)
	{
		FileInfo fileInfo = new FileInfo(Filename);
		if (!fileInfo.Exists)
		{
			return;
		}
		List<string> StringList = new List<string>();
		buFile5.OpenFromFile(fileInfo.FullName, ref StringList);
		DrillList.Clear();
		for (int i = 0; i <= StringList.Count - 1; i++)
		{
			string[] array = StringList[i].Split(';');
			if (array != null && array.Length >= 4)
			{
				marbleDrillType marbleDrillType2 = new marbleDrillType();
				if (buNumeric5.IsNumeric(array[0]) & buNumeric5.IsNumeric(array[1]) & buNumeric5.IsNumeric(array[2]) & buNumeric5.IsNumeric(array[3]))
				{
					marbleDrillType2.Depth = double.Parse(array[3]);
					marbleDrillType2.Diameter = double.Parse(array[2]);
					marbleDrillType2.pntCenter = new Point3D(double.Parse(array[0]), double.Parse(array[1]), buMarbleCalc.varOperation.MaterialParameter.MaterialThickness - marbleDrillType2.Depth);
					DrillList.Add(marbleDrillType2);
				}
			}
		}
	}

	public void SaveMarbleJob(string FileName, MarbleJob Job)
	{
		ArrayList arrayList = new ArrayList();
		arrayList.AddRange(MarbleJob.ToDef(Job, 2));
		buFile5.SaveToFile(arrayList, FileName);
	}

	public void OpenMarbleJob(string FileName, ref MarbleJob Job)
	{
		ArrayList StringList = new ArrayList();
		buFile5.OpenFromFile(FileName, ref StringList);
		activeJob = new MarbleJob();
		MarbleJob refJob = new MarbleJob();
		MarbleJob.Decode(StringList, ref refJob);
		if (refJob.VacuumCuts != null)
		{
			refJob.VacuumCuts.Clear();
		}
		if (refJob.Material.Enable)
		{
			List<Point3D> copiedPoint = new List<Point3D>();
			List<List<Point3D>> copiedPoint2 = new List<List<Point3D>>();
			buVector5.Copy(refJob.Material.Points, ref copiedPoint);
			if (refJob.Material.InnerPoints != null)
			{
				buVector5.Copy(refJob.Material.InnerPoints, ref copiedPoint2);
			}
			clsInit.cMarble.CreateMaterial(copiedPoint, copiedPoint2, refJob.Material.Shapes, refJob.Material.Size.Depth, refJob.Material.matImage, ref refJob.Material);
		}
		activeJob.Name = refJob.Name;
		activeJob.Material = new MaterialBase5(refJob.Material);
		activeJob.SizeOfOperations = new BoxSize5(refJob.SizeOfOperations);
		Entity entSurface = null;
		if (buMarbleCalc.varOperation.settingMarbleCam.Contour3DCreate)
		{
			for (int i = 0; i <= refJob.Items.Count - 1; i++)
			{
				List<Point3D> Points = new List<Point3D>();
				List<List<Point3D>> list = new List<List<Point3D>>();
				MarbleItem marbleItem = new MarbleItem(refJob.Items[i]);
				if (marbleItem.EntGroup == null)
				{
					continue;
				}
				if (marbleItem.EntGroup.Outside.Entities.Count > 0)
				{
					clsInit.cVector5.EntitiesToPointsWithCamDirection(marbleItem.EntGroup.Outside.Entities, ref Points);
					if (marbleItem.EntGroup.Inside.Count > 0)
					{
						for (int j = 0; j <= marbleItem.EntGroup.Inside.Count - 1; j++)
						{
							List<Point3D> Points2 = new List<Point3D>();
							clsInit.cVector5.EntitiesToPointsWithCamDirection(marbleItem.EntGroup.Inside[j].Entities, ref Points2);
							list.Add(Points2);
						}
					}
					clsInit.cVector5.surfaceFromOutterInner(Points, list, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref entSurface);
				}
				if (entSurface != null)
				{
					marbleItem.ItemEntities.SolidEntity = new List<Entity>();
					entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemContour.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemContour.Color);
					entSurface.ColorMethod = colorMethodType.byEntity;
					marbleItem.ItemEntities.SolidEntity.Add(entSurface);
				}
				MarbleTempVars.ItemsContour.Clear();
				MarbleTempVars.ItemsContour.Add(marbleItem);
				doAddCamItemContour(isText: false, isMilling: false, isMillingHead: false, isWaterJet: false, -1);
				MarbleItem marbleItem2 = null;
				if (activeJob.Items.Count > 0)
				{
					marbleItem2 = activeJob.Items[activeJob.Items.Count - 1];
				}
				for (int k = 0; k <= refJob.Items[i].Edges.Count - 1; k++)
				{
					if (k <= marbleItem2.Edges.Count - 1)
					{
						marbleItem2.Edges[k].CamID = refJob.Items[i].Edges[k].CamID;
						marbleItem2.Edges[k].EdgeID = refJob.Items[i].Edges[k].EdgeID;
						marbleItem2.Edges[k].ItemID = refJob.Items[i].Edges[k].ItemID;
					}
					if (refJob.Items[i].Edges[k].Slat.DataSlat.Enable)
					{
						AddSlatArgs addSlatData = new AddSlatArgs(refJob.Items[i].Edges[k].Slat.DataSlat.indexEntitiy, -1, refJob.Items[i].ID, refJob.Items[i].Edges[k].Slat.DataSlat.EdgeID, refJob.Items[i].Edges[k].Slat.DataSlat.CamID);
						doSlatAdd(addSlatData);
					}
				}
				if (refJob.Items[i].Collapses.Count <= 0)
				{
					continue;
				}
				for (int l = 0; l <= refJob.Items[i].Collapses.Count - 1; l++)
				{
					if (l <= marbleItem2.Edges.Count - 1)
					{
						marbleItem2.Edges[l].CamID = refJob.Items[i].Edges[l].CamID;
						marbleItem2.Edges[l].EdgeID = refJob.Items[i].Edges[l].EdgeID;
						marbleItem2.Edges[l].ItemID = refJob.Items[i].Edges[l].ItemID;
					}
					if (refJob.Items[i].Collapses[l].Enable)
					{
						AddCollapseArgs addCollapseData = new AddCollapseArgs(refJob.Items[i].Collapses[l].IndexInsideEntity, refJob.Items[i].Collapses[l].ItemID);
						doCollopseAdd(addCollapseData);
					}
				}
			}
		}
		doDrawActiveJob();
	}

	public void LoadLanguage()
	{
		new List<string>();
		FileInfo fileInfo = null;
		fileInfo = ((!clsVar.appModes_0.DeveloperPCMode) ? new FileInfo(AppPath.Language + "\\buMarble.lng") : new FileInfo("D:\\PCProjects\\Generation5\\CommonFolder\\Language\\buMarble.lng"));
		if (!fileInfo.Exists)
		{
			buLog.addLog("MarbleLanguage", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buString5.MessageBoxError("Laser Language File Missing");
			return;
		}
		List<string> StringList = new List<string>();
		buClass.Apps.buMarble.LangMarbleMessage = new List<string>();
		buClass.Apps.buMarble.LangMarbleCaptions = new List<string>();
		buFile.OpenFromFile(fileInfo.FullName, ref StringList);
		buString5.GetItemsAccordingToTheLang(buString5.ReadXmlItem("<Message>", "</Message>", StringList), clsVar.varRuntime.Language, ref buClass.Apps.buMarble.LangMarbleMessage);
		buString5.GetItemsAccordingToTheLang(buString5.ReadXmlItem("<Captions>", "</Captions>", StringList), clsVar.varRuntime.Language, ref buClass.Apps.buMarble.LangMarbleCaptions);
		StringList.Clear();
	}

	private void method_6(object object_0, object object_1, object object_2, object object_3, object object_4)
	{
		MarbleCadCamCommands cmd = MarbleCadCamCommands.None;
		MarbleAlingmentCommands marbleAlingmentCommands = MarbleAlingmentCommands.None;
		double value = 0.0;
		if (object_0 is MarbleCadCamCommands)
		{
			cmd = (MarbleCadCamCommands)object_0;
		}
		if (object_1 != null && buNumeric5.IsNumeric(object_1.ToString()))
		{
			value = Convert.ToDouble(object_1.ToString());
		}
		if (object_2 is MarbleAlingmentCommands)
		{
			marbleAlingmentCommands = (MarbleAlingmentCommands)object_2;
		}
		doUpdateSelectionFromSelectedItem();
		if (marbleAlingmentCommands == MarbleAlingmentCommands.Magnet)
		{
			doAlignment(cmd, value);
		}
		if (marbleAlingmentCommands == MarbleAlingmentCommands.Move)
		{
			doAlignmentMove(cmd, value);
		}
		if (marbleAlingmentCommands == MarbleAlingmentCommands.Side)
		{
			doAlignmentSide(cmd, value);
		}
	}

	private void method_7(object object_0, object object_1, object object_2, object object_3, object object_4)
	{
		MarbleCadCamCommands marbleCadCamCommands = MarbleCadCamCommands.None;
		double num = 0.0;
		if (object_0 is MarbleCadCamCommands)
		{
			marbleCadCamCommands = (MarbleCadCamCommands)object_0;
		}
		if (object_1 != null && buNumeric5.IsNumeric(object_1.ToString()))
		{
			num = Convert.ToDouble(object_1.ToString());
		}
		if (!(object_2 is MarbleVacuumCommands))
		{
		}
		double moveDistanceX = 0.0;
		double moveDistanceY = 0.0;
		switch (marbleCadCamCommands)
		{
		case MarbleCadCamCommands.MoveLeft:
			moveDistanceX = 0.0 - num;
			break;
		case MarbleCadCamCommands.MoveRight:
			moveDistanceX = num;
			break;
		case MarbleCadCamCommands.MoveUp:
			moveDistanceY = num;
			break;
		case MarbleCadCamCommands.MoveDown:
			moveDistanceY = 0.0 - num;
			break;
		case MarbleCadCamCommands.MoveLeftUp:
			moveDistanceX = 0.0 - num;
			moveDistanceY = num;
			break;
		case MarbleCadCamCommands.MoveLeftDown:
			moveDistanceX = 0.0 - num;
			moveDistanceY = 0.0 - num;
			break;
		case MarbleCadCamCommands.MoveRightUp:
			moveDistanceX = num;
			moveDistanceY = num;
			break;
		case MarbleCadCamCommands.MoveRightDown:
			moveDistanceX = num;
			moveDistanceY = 0.0 - num;
			break;
		}
		GetVacuumLineByMouse(ccVars.pntMouseDownFirst, moveDistanceX, moveDistanceY, Finished: true);
	}

	public void GetVacuumLineByMouse(Point3D pntView, double MoveDistanceX, double MoveDistanceY, bool Finished)
	{
		if (ccVars.pntDrawDynamicLines == null)
		{
			ccVars.pntDrawDynamicLines = new List<Point3D>();
		}
		ccVars.pntDrawDynamicLines.Clear();
		Point3D point3D = null;
		Point3D point3D2 = null;
		bool flag = false;
		HorizontalVertical horizontalVertical = HorizontalVertical.Horizontal;
		Point3D point3D3 = null;
		Point3D pntMax = buVector5.ToPoint3D(activeJob.SizeOfOperations.MaxPoint);
		Point3D pntMin = buVector5.ToPoint3D(activeJob.SizeOfOperations.MinPoint);
		MaterialBase5 FoundMat = null;
		double num = 0.0;
		double num2 = 0.0;
		double vacuumExtension = buMarbleCalc.varOperation.settingVacuum.VacuumExtension;
		double vacuumOffset = buMarbleCalc.varOperation.settingVacuum.VacuumOffset;
		List<MarbleItem> FoundItems = new List<MarbleItem>();
		if (activeJob.VacuumMaterials == null)
		{
			FoundMat = activeJob.Material;
		}
		else if (activeJob.VacuumMaterials.Count <= 0)
		{
			FoundMat = activeJob.Material;
		}
		else
		{
			clsInit.cMarble.FindMaterialWithPoint(activeJob.VacuumMaterials, pntView, ref FoundMat);
			if (FoundMat == null)
			{
			}
		}
		if (FoundMat == null)
		{
			FoundMat = activeJob.Material;
		}
		else
		{
			clsInit.cMarble.FindItemsInsideMaterials(FoundMat, activeJob.Items, ref FoundItems);
		}
		num = FoundMat.Size.Width;
		num2 = FoundMat.Size.Height;
		if (FoundItems.Count > 0)
		{
			clsInit.cMarble.GetBoxSizeJobItems(FoundItems, ref pntMin, ref pntMax);
		}
		for (int i = 0; i <= activeJob.Items.Count - 1; i++)
		{
			for (int j = 0; j <= activeJob.Items[i].CamList.Count - 1; j++)
			{
				for (int k = 0; k <= activeJob.Items[i].CamList[j].WireEntities.Count - 1; k++)
				{
					for (int l = 0; l <= activeJob.Items[i].CamList[j].WireEntities[k].Count - 1; l++)
					{
						if (clsInit.cVector5.isPointOverEntity(activeJob.Items[i].CamList[j].WireEntities[k][l], pntView, 10.0))
						{
							flag = true;
							point3D3 = activeJob.Items[i].CamList[j].WireEntities[k][l].StartPoint;
							double value = clsInit.cVector5.PointAngle(activeJob.Items[i].CamList[j].WireEntities[k][l].EndPoint, activeJob.Items[i].CamList[j].WireEntities[k][l].StartPoint);
							if (buCompare5.EQ(value, 90.0, 1.0) | buCompare5.EQ(value, -90.0, 1.0) | buCompare5.EQ(value, 270.0, 1.0))
							{
								horizontalVertical = HorizontalVertical.Vertical;
							}
							break;
						}
					}
				}
			}
		}
		if (flag & (point3D3 != null))
		{
			if (horizontalVertical != HorizontalVertical.Vertical)
			{
				point3D = new Point3D(pntMin.X - vacuumExtension, point3D3.Y, 0.0);
				point3D2 = new Point3D(pntMin.X + num + 2.0 * vacuumExtension, point3D3.Y, 0.0);
			}
			else
			{
				point3D = new Point3D(point3D3.X, pntMin.Y - vacuumExtension, 0.0);
				point3D2 = new Point3D(point3D3.X, pntMin.Y + num2 + 2.0 * vacuumExtension, 0.0);
			}
		}
		if (!flag)
		{
			if (!(pntView.X > pntMax.X))
			{
				if (pntView.Y > pntMax.Y)
				{
					point3D = new Point3D(pntMin.X - vacuumExtension, pntMax.Y + vacuumOffset, 0.0);
					point3D2 = new Point3D(pntMin.X + num + 2.0 * vacuumExtension, pntMax.Y + vacuumOffset, 0.0);
				}
			}
			else
			{
				point3D = new Point3D(pntMax.X + vacuumOffset, pntMin.Y - vacuumExtension, 0.0);
				point3D2 = new Point3D(pntMax.X + vacuumOffset, pntMin.Y + num2 + 2.0 * vacuumExtension, 0.0);
			}
		}
		if (activeJob.VacuumCuts == null || activeJob.VacuumCuts.Count <= 0)
		{
		}
		if (!Finished)
		{
			if (point3D != null && point3D2 != null)
			{
				ccVars.pntDrawDynamicLines.Add(point3D);
				ccVars.pntDrawDynamicLines.Add(point3D2);
			}
		}
		else
		{
			ccVars.pntDrawDynamicLines.Clear();
			if (point3D != null && point3D2 != null)
			{
				VacuumAdd(pntView, point3D, point3D2, MoveDistanceX, MoveDistanceY);
			}
		}
	}

	public void VacuumAdd(Point3D pntClick, Point3D pntStart, Point3D pntEnd, double MoveDistanceX, double MoveDistanceY)
	{
		double num = MoveDistanceX;
		double num2 = MoveDistanceY;
		MarbleVacuumCut marbleVacuumCut = new MarbleVacuumCut();
		marbleVacuumCut.StartPoint = new Point3D(pntStart.X, pntStart.Y, 0.0);
		marbleVacuumCut.EndPoint = new Point3D(pntEnd.X, pntEnd.Y, 0.0);
		double num3 = clsInit.cVector5.PointAngle(marbleVacuumCut.EndPoint, marbleVacuumCut.StartPoint);
		if (buCompare5.EQ(num3, 0.0) | buCompare5.EQ(num3, 180.0))
		{
			marbleVacuumCut.Direction = HorizontalVertical.Horizontal;
			num2 = MoveDistanceY;
		}
		if (buCompare5.EQ(num3, 90.0) | buCompare5.EQ(num3, 270.0))
		{
			marbleVacuumCut.Direction = HorizontalVertical.Vertical;
			num = MoveDistanceX;
		}
		marbleVacuumCut.VacuumCutEntity = new buLine(marbleVacuumCut.StartPoint, marbleVacuumCut.EndPoint);
		marbleVacuumCut.VacuumID = 1;
		if (activeJob.VacuumCuts == null)
		{
			activeJob.VacuumCuts = new List<MarbleVacuumCut>();
		}
		if (activeJob.VacuumMaterials == null)
		{
			activeJob.VacuumMaterials = new List<MaterialBase5>();
		}
		if (activeJob.VacuumCuts.Count != 0)
		{
			int num4 = -1;
			for (int i = 0; i <= activeJob.VacuumMaterials.Count - 1; i++)
			{
				MaterialBase5 materialBase = activeJob.VacuumMaterials[i];
				if (clsInit.cVector5.IsPointInsideBoxsize(pntClick, materialBase.BoxMinPoint, materialBase.BoxMaxPoint, Plane.XY))
				{
					num4 = i;
				}
			}
			if (num4 >= 0)
			{
				MaterialBase5 baseMaterial = activeJob.VacuumMaterials[num4];
				MaterialBase5 FirstMaterial = new MaterialBase5();
				MaterialBase5 SecondMaterial = new MaterialBase5();
				clsInit.cMarble.DevideVacuumMaterial(baseMaterial, marbleVacuumCut, num, num2, ref FirstMaterial, ref SecondMaterial);
				activeJob.VacuumMaterials.RemoveAt(num4);
				activeJob.VacuumMaterials.Add(FirstMaterial);
				activeJob.VacuumMaterials.Add(SecondMaterial);
				marbleVacuumCut.Selected = true;
				activeJob.VacuumCuts.Add(marbleVacuumCut);
				activeJob.VacuumSelectedIndex = activeJob.VacuumCuts.Count - 1;
			}
		}
		else
		{
			MaterialBase5 FirstMaterial2 = new MaterialBase5();
			MaterialBase5 SecondMaterial2 = new MaterialBase5();
			clsInit.cMarble.DevideVacuumMaterial(activeJob.Material, marbleVacuumCut, num, num2, ref FirstMaterial2, ref SecondMaterial2);
			activeJob.VacuumMaterials.Add(FirstMaterial2);
			activeJob.VacuumMaterials.Add(SecondMaterial2);
			marbleVacuumCut.Selected = true;
			activeJob.VacuumCuts.Add(marbleVacuumCut);
			activeJob.VacuumSelectedIndex = activeJob.VacuumCuts.Count - 1;
		}
		clsInit.cMarble.MoveVacuumCut(ref activeJob, num, num2, activeJob.VacuumSelectedIndex);
		buMarbleCalc.varOperation.settingSliceCut.CutLengthSingle = marbleVacuumCut.VacuumCutEntity.Length();
		doAddItemSingleCut(new Point3D(marbleVacuumCut.StartPoint.X, marbleVacuumCut.StartPoint.Y, 0.0), 0.0, num3, isFinished: true, activeJob.VacuumCuts.Count - 1, isVacuum: true);
		List<MaterialBase5> CopiedList = new List<MaterialBase5>();
		MaterialBase5.Copy(activeJob.VacuumMaterials, ref CopiedList);
		if (activeJob.SimMaterials == null)
		{
			activeJob.SimMaterials = new List<List<MaterialBase5>>();
		}
		activeJob.SimMaterials.Add(CopiedList);
		doDrawActiveJob();
	}

	public string DebugExecute(DebugCommandEventArg e)
	{
		if (!(e.DebugCommand.ToString().ToLower() == "showmwdialog"))
		{
			if (!(e.DebugCommand.ToString().ToLower() == "hidemwdialog"))
			{
				return buLangTranslate.preDef.Error;
			}
			if (clsInit.cMwCalc == null)
			{
				return buLangTranslate.preDef.Error;
			}
			clsInit.cMwCalc.Settings.ShowMwDialogBox = false;
			return buLangTranslate.preDef.Ok;
		}
		if (clsInit.cMwCalc == null)
		{
			return buLangTranslate.preDef.Error;
		}
		clsInit.cMwCalc.Settings.ShowMwDialogBox = true;
		return buLangTranslate.preDef.Ok;
	}

	public ToolBase5 FindToolFromType(MarbleToolType ToolType)
	{
		ToolBase5 result = null;
		switch (ToolType)
		{
		case MarbleToolType.Saw:
			result = new ToolBase5(buMarbleCalc.activeToolSaw);
			break;
		case MarbleToolType.Milling:
			result = new ToolBase5(buMarbleCalc.activeToolMilling);
			break;
		case MarbleToolType.WaterJet:
			result = new ToolBase5(buMarbleCalc.activeToolWaterjet);
			break;
		case MarbleToolType.MillingHead:
			result = new ToolBase5(buMarbleCalc.activeToolMillingHead);
			break;
		}
		return result;
	}

