	public void OperationControlValueChanged(object sender, double Value)
	{
		Control control = sender as Control;
		if (buMarbleControls.Inited)
		{
			if (buMarbleControls.spnMaterialThickness != null && control.Name == buMarbleControls.spnMaterialThickness.Name)
			{
				buMarbleCalc.varOperation.MaterialParameter.MaterialThickness = buMarbleControls.spnMaterialThickness.Value;
			}
			if (buMarbleControls.spnCuttingSpeed != null && control.Name == buMarbleControls.spnCuttingSpeed.Name)
			{
				buMarbleCalc.varOperation.settingMarbleCam.SawForwardCuttingVelocity = buMarbleControls.spnCuttingSpeed.Value;
			}
			if (buMarbleControls.spnForwardStep != null && control.Name == buMarbleControls.spnForwardStep.Name)
			{
				buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance = buMarbleControls.spnForwardStep.Value;
			}
			if (buMarbleControls.spnPlungeSpeed != null && control.Name == buMarbleControls.spnPlungeSpeed.Name)
			{
				buMarbleCalc.varOperation.settingMarbleCam.SawPlungeVelocity = buMarbleControls.spnPlungeSpeed.Value;
			}
			if (buMarbleControls.spnTargetZ != null && control.Name == buMarbleControls.spnTargetZ.Name)
			{
				buMarbleCalc.varOperation.settingMarbleCam.TargetZ = buMarbleControls.spnTargetZ.Value;
			}
		}
	}

