	public void UndoBuffer()
	{
		if (!MarbleTempVars.UndoApplying)
		{
			Task.Run(delegate
			{
				UndoBufferApply();
			});
		}
	}

	public void UndoBufferApply()
	{
		try
		{
			MarbleTempVars.UndoApplying = true;
			if (buMarbleCalc.varOperation.settingEvent.UndoEnable)
			{
				MarbleJob item = new MarbleJob(activeJob);
				buMarbleCalc.UndoJobList.Add(item);
				if (buMarbleCalc.UndoJobList.Count > buMarbleCalc.varOperation.settingEvent.UndoLimit)
				{
					buMarbleCalc.UndoJobList.RemoveAt(0);
				}
			}
			MarbleTempVars.UndoApplying = false;
		}
		catch (Exception)
		{
			MarbleTempVars.UndoApplying = false;
		}
	}

	public void UndoGetback()
	{
		if (buMarbleCalc.UndoJobList.Count > 0)
		{
			clsInit.appMarble.activeJob = new MarbleJob(buMarbleCalc.UndoJobList[buMarbleCalc.UndoJobList.Count - 1]);
			buMarbleCalc.UndoJobList.RemoveAt(buMarbleCalc.UndoJobList.Count - 1);
			doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
			JobUpdate();
			doDrawActiveJob();
		}
	}

	public void doNestingResult(buNestedResultEventArg NestResult)
	{
		if ((NestResult.SelectedSheet >= 0) & (NestResult.SelectedSheet <= NestResult.nestedResult.NestedResultSheets.Count - 1))
		{
			buNestedSheet buNestedSheet2 = NestResult.nestedResult.NestedResultSheets[NestResult.SelectedSheet];
			for (int i = 0; i <= buNestedSheet2.Parts.Count - 1; i++)
			{
				entitiesGroupForContour.Clear();
				buEntitiesGroup item = new buEntitiesGroup(buNestedSheet2.Parts[i].EntitiesGroup);
				entitiesGroupForContour.Add(item);
				doAddItemShapeContour(new Point3D(), isShape: false, isFinished: true, isText: false, isMilling: false, isMillingHead: false, isWaterJet: false, isCamCalc: false, -1);
			}
		}
	}

	public void Tick_New(object sender, EventArgs e)
	{
		if (NewTickCount == 0)
		{
			buEyeItems.viewportCadCam = ccVars.Pages[ccVars.PageIndex].Form.viewportcad;
			buEyeItems.viewportCadCam = (ViewportCC)CreateMaterialsAndLayers(MarbleTempVars.fileNameWood, MarbleTempVars.fileNameMarble, buEyeItems.viewportCadCam, linearUnitsType.Millimeters);
			Entity entWood = null;
			if (buMarbleCalc.varMarbleSettings.DrawWoodBase)
			{
				CreateWoodMaterial(buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth, buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight, buMarbleCalc.varMarbleMachineSettings.BaseWoodThickness, buMarbleCalc.varMarbleMachineSettings.BaseWoodZOffset + buMarbleCalc.varOperation.settingMarbleCam.TargetZ, TopOnZero: true, buEyeItems.viewportCadCam.Layers[MarbleTempVars.layerWood.Index].Name, ref entWood);
				entWood.Selectable = false;
				if (entWood != null)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(entWood);
				}
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ZoomFit(10);
			}
		}
		activeJob.Items.Clear();
		activeJob = new MarbleJob();
		activeJob.Material.BoxMinPoint.X = 0.0;
		activeJob.Material.BoxMinPoint.Y = 0.0;
		activeJob.Material.BoxMaxPoint.X = buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth;
		activeJob.Material.BoxMaxPoint.Y = buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight;
		activeJob.Material.BoxMinPoint.Z = 0.0;
		activeJob.Material.BoxMaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
		activeJob.Material.Size.Width = activeJob.Material.BoxMaxPoint.X - activeJob.Material.BoxMinPoint.X;
		activeJob.Material.Size.Height = activeJob.Material.BoxMaxPoint.Y - activeJob.Material.BoxMinPoint.Y;
		activeJob.Material.Size.Depth = activeJob.Material.BoxMaxPoint.Z - activeJob.Material.BoxMinPoint.Z;
		NewTickCount++;
		timNew.Enabled = false;
		clsInit.appMarble.InitCadCamSimulation();
		buEyeItems.viewportDialogs = CreateMaterialsAndLayers(MarbleTempVars.fileNameWood, MarbleTempVars.fileNameMarble, buEyeItems.viewportDialogs, linearUnitsType.Meters);
		clsInit.appCommand.LayerConvertFromEyeLayerToBuLayer(buEyeItems.viewportCadCam.Layers, ref ccVars.Pages[ccVars.PageIndex].Layers);
		clsInit.appCommand.LayersUpdate(ccVars.Pages[ccVars.PageIndex].Layers, FillLayer: true, -1);
		JobUpdate();
		doDrawActiveJob();
		DrawPreview(null, -1);
		clsInit.appCommand.cmdViewZoomFit(25);
	}

