	{
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
		MoveCreatedEntity = false;
		if (clsItem.pnlSettings != null)
		{
			clsItem.pnlSettings.Visible = false;
		}
		entitiesGroupForContour.Clear();
		entitiesForContour.Clear();
		entitiesForSweep.Clear();
		entitiesForDrill.Clear();
		entitiesForProfiling.Clear();
		entitiesForMove.Clear();
		AppBool.EditMode = false;
		AppBool.FileCopied = false;
		AppBool.CameraCaptured = false;
		AppBool.CameraCapturing = false;
		MarbleTempVars.VacuumIndex = -1;
		MarbleTempVars.VacuumEnable = false;
		if (buMarbleForms.frmEventVacuum != null)
		{
			buMarbleForms.frmEventVacuum.Visible = false;
		}
		MarbleTempVars.isDialogItem = false;
		MarbleTempVars.Commands = MarbleCommands.None;
		MarbleTempVars.SetAngle = false;
		MarbleTempVars.Editing = false;
		MarbleTempVars.ItemsContour.Clear();
		MarbleTempVars.ItemsSlice.Clear();
		MarbleTempVars.ItemsProfile.Clear();
		MarbleTempVars.ItemsDrill.Clear();
		MarbleTempVars.ItemsSweep.Clear();
		buMarbleCalc.SelectedItem.SelectionItems.Clear();
		clsInit.appMarble.activeItemType = MarbleItemType.None;
		ccVars.Pages[ccVars.PageIndex].Form.lbl_information.Visible = false;
		ViewportCC viewportcad = ccVars.Pages[ccVars.PageIndex].Form.viewportcad;
		for (int i = 0; i <= viewportcad.Entities.Count - 1; i++)
		{
			viewportcad.Entities[i].Selected = false;
			if ((viewportcad.Entities[i].EntityData != null) & (viewportcad.Entities[i].EntityData is CustomData))
			{
				CustomData customData = viewportcad.Entities[i].EntityData as CustomData;
