	public void doToolSelected(ToolBase5 selectedTool)
	{
		if (selectedTool == null)
		{
			return;
		}
		if (!((selectedTool.Purpose == ToolPurpose.Milling) | (selectedTool.Purpose == ToolPurpose.General) | (selectedTool.Purpose == ToolPurpose.Milling5Axis)))
		{
			if (selectedTool.Purpose != ToolPurpose.Saw)
			{
				if (selectedTool.Purpose != ToolPurpose.MillingHead)
				{
					if (selectedTool.Purpose == ToolPurpose.WaterJet)
					{
						buMarbleCalc.activeToolWaterjet = new ToolBase5(selectedTool);
					}
				}
				else
				{
					buMarbleCalc.activeToolMillingHead = new ToolBase5(selectedTool);
				}
			}
			else
			{
				buMarbleCalc.activeToolSaw = new ToolBase5(selectedTool);
			}
		}
		else
		{
			buMarbleCalc.activeToolMilling = new ToolBase5(selectedTool);
		}
	}

	public void doToolUpdate(int SelectedGroupIndex, int SelectedIndex)
	{
		if (!(SelectedGroupIndex >= 0 && SelectedIndex >= 0) || SelectedGroupIndex > ccVars.Tools.Count - 1 || SelectedIndex > ccVars.Tools[SelectedGroupIndex].Tools.Count - 1)
		{
			return;
		}
		if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose != ToolPurpose.Saw)
		{
			if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose != ToolPurpose.Milling)
			{
				if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose != ToolPurpose.Milling5Axis)
				{
					if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose != ToolPurpose.MillingHead)
					{
						if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose == ToolPurpose.WaterJet)
						{
							buMarbleCalc.activeToolWaterjet = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
						}
					}
					else
					{
						buMarbleCalc.activeToolMillingHead = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
					}
				}
				else
				{
					buMarbleCalc.activeToolMilling = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
				}
			}
			else
			{
				buMarbleCalc.activeToolMilling = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
			}
		}
		else
		{
			buMarbleCalc.activeToolSaw = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
		}
	}

