	public void CreateShape(Point3D refPoint, MarbleShapeTypes Type, double Thickness, ref MarbleItem Item, MarbleToolType ToolType)
	{
		if (Item == null)
		{
			Item = new MarbleItem();
		}
		Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
		Item.EntGroup = new buEntitiesGroup();
		Item.ItemEntities.EdgeEntities = new List<buEntity>();
		Item.ItemEntities.ExtensionEntities = new List<buEntity>();
		ICurve wireEntity = null;
		buEntity copiedEntity = null;
		Entity solidEntity = null;
		clsInit.cMarble.CreateShape(Type, Thickness, ref solidEntity, ref wireEntity);
		buEntity.Copy(wireEntity, ref copiedEntity, 0.1);
		solidEntity.Translate(refPoint.X, refPoint.Y);
		Item.ItemEntities.SolidEntity = new List<Entity>();
		solidEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemContour.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemContour.Color);
		solidEntity.ColorMethod = colorMethodType.byEntity;
		if (buMarbleCalc.varOperation.settingMarbleCam.Contour3DCreate)
		{
			Item.ItemEntities.SolidEntity.Add(solidEntity);
		}
		Item.ItemType = MarbleItemType.Shape;
		Item.ShapeType = Type;
		Item.ToolType = ToolType;
		clsInit.cVector5.BoxSizeCalculate(solidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
		ObjectSize3D.CalculateSize(ref Item.SizeItem);
		copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
		if (!(copiedEntity is buCompositeCurve))
		{
			copiedEntity.Marble = new MarbleInfo();
			Item.EntGroup.Outside.Entities.Add(copiedEntity);
			Item.EntGroup.Outside.Direction = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
		}
		else
		{
			for (int i = 0; i <= ((buCompositeCurve)copiedEntity).CurveList.Count - 1; i++)
			{
				((buCompositeCurve)copiedEntity).CurveList[i].Marble = new MarbleInfo();
				Item.EntGroup.Outside.Entities.Add(((buCompositeCurve)copiedEntity).CurveList[i]);
				Item.EntGroup.Outside.Direction = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
			}
			if (Type != MarbleShapeTypes.Arc)
			{
			}
		}
		if (Item.SizeItem.Height > Item.SizeItem.Width)
		{
			Item.isTextVertical = !MarbleTempVars.isHorizontal;
		}
		if (Item.EntGroup.Outside.Entities.Count > 0)
		{
			clsInit.cMarble.ShapeTypeAngleSet(ref Item);
		}
		if (Item.ToolType != MarbleToolType.Saw)
		{
		}
		Item.ClockDir = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
		Item.ID = MarbleTempVars.ItemID;
		Item.SortRefPoint = buVector5.ToPoint3D(copiedEntity.StartPoint);
		Item.ItemName = clsInit.cMarble.ItemShapeToName(Type);
		MarbleTempVars.ItemID++;
	}

	public void CreateTextContour(Point3D refPoint, List<buEntitiesGroup> entContour, double Thickness, ref List<MarbleItem> Items, MarbleToolType ToolType)
	{
		string text = "CreateTextContour";
		try
		{
			MarbleItem Item = new MarbleItem();
			Item.ItemEntities.GroupEntities = new List<buEntitiesGroup>();
			Item.EntGroup = new buEntitiesGroup();
			Item.EntGroup.Inside = new List<buEntityList>();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Item.ItemEntities.DrawWireEntities = new List<buEntity>();
			Item.ItemEntities.EdgeEntities = new List<buEntity>();
			Item.ItemEntities.ExtensionEntities = new List<buEntity>();
			Item.ItemEntities.WireEntities = new List<List<buEntity>>();
			Item.ItemEntities.ConcaveEntities = new List<List<buEntity>>();
			Item.ItemEntities.SolidEntity = new List<Entity>();
			Item.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
			for (int i = 0; i <= entContour.Count - 1; i++)
			{
				List<Point3D> Points = new List<Point3D>();
				List<List<Point3D>> list = new List<List<Point3D>>();
				Entity entSurface = null;
				if (buMarbleCalc.varOperation.settingMarbleCam.Contour3DCreate)
				{
					if (entContour[i].Outside.Entities.Count > 0)
					{
						clsInit.cVector5.EntitiesToPointsWithCamDirection(entContour[i].Outside.Entities, ref Points);
						if (entContour[i].Inside.Count > 0)
						{
							for (int j = 0; j <= entContour[i].Inside.Count - 1; j++)
							{
								List<Point3D> Points2 = new List<Point3D>();
								clsInit.cVector5.EntitiesToPointsWithCamDirection(entContour[i].Inside[j].Entities, ref Points2);
								list.Add(Points2);
							}
						}
						clsInit.cVector5.surfaceFromOutterInner(Points, list, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref entSurface);
					}
					if (entSurface != null)
					{
						if (refPoint != null)
						{
							entSurface.Translate(refPoint.X, refPoint.Y);
						}
						entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemText.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemText.Color);
						entSurface.ColorMethod = colorMethodType.byEntity;
						Item.ItemEntities.SolidEntity.Add(entSurface);
					}
				}
				Item.ItemType = clsInit.appMarble.activeItemType;
				Item.ToolType = MarbleToolType.Saw;
				if (ToolType != MarbleToolType.WaterJet)
				{
					if (ToolType != MarbleToolType.MillingHead)
					{
						Item.ToolType = MarbleToolType.Milling;
					}
					else
					{
						Item.ToolType = MarbleToolType.MillingHead;
					}
				}
				else
				{
					Item.ToolType = MarbleToolType.WaterJet;
				}
				if (buMarbleCalc.varMarbleRunSettings.BorderEnable)
				{
					if (i != 0)
					{
						buEntityList buEntityList2 = new buEntityList();
						for (int k = 0; k <= entContour[i].Outside.Entities.Count - 1; k++)
						{
							buEntity copiedEntity = null;
							buEntity.Copy(entContour[i].Outside.Entities[k], ref copiedEntity);
							if (refPoint != null)
							{
								copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
							}
							copiedEntity.Marble = new MarbleInfo();
							buEntityList2.Entities.Add(copiedEntity);
							buEntityList2.ToolType = entContour[i].Outside.ToolType;
							if (entContour[i].Outside.Marble == null)
							{
								buEntityList2.Marble = new marbleEntityData();
								clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, Item.ToolType, ref buEntityList2.Marble);
							}
							else
							{
								buEntityList2.Marble = new marbleEntityData(entContour[i].Outside.Marble);
							}
						}
						if (buEntityList2.Entities.Count > 0)
						{
							Item.EntGroup.Inside.Add(buEntityList2);
						}
					}
					else
					{
						for (int l = 0; l <= entContour[i].Outside.Entities.Count - 1; l++)
						{
							buEntity copiedEntity2 = null;
							buEntity.Copy(entContour[i].Outside.Entities[l], ref copiedEntity2);
							if (refPoint != null)
							{
								copiedEntity2.Translate(refPoint.X, refPoint.Y, 0.0);
							}
							copiedEntity2.Marble = new MarbleInfo();
							Item.EntGroup.Outside.Entities.Add(copiedEntity2);
							Item.EntGroup.Outside.ToolType = entContour[i].Outside.ToolType;
							if (entContour[i].Outside.Marble == null)
							{
								Item.EntGroup.Outside.Marble = new marbleEntityData();
								clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, Item.ToolType, ref Item.EntGroup.Outside.Marble);
							}
							else
							{
								Item.EntGroup.Outside.Marble = new marbleEntityData(entContour[i].Outside.Marble);
							}
						}
					}
				}
				else
				{
					for (int m = 0; m <= entContour[i].Outside.Entities.Count - 1; m++)
					{
						buEntity copiedEntity3 = null;
						buEntity.Copy(entContour[i].Outside.Entities[m], ref copiedEntity3);
						if (refPoint != null)
						{
							copiedEntity3.Translate(refPoint.X, refPoint.Y, 0.0);
						}
						copiedEntity3.Marble = new MarbleInfo();
						Item.EntGroup.Outside.Entities.Add(copiedEntity3);
						Item.EntGroup.Outside.ToolType = entContour[i].Outside.ToolType;
						if (entContour[i].Outside.Marble == null)
						{
							Item.EntGroup.Outside.Marble = new marbleEntityData();
							clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, Item.ToolType, ref Item.EntGroup.Outside.Marble);
						}
						else
						{
							Item.EntGroup.Outside.Marble = new marbleEntityData(entContour[i].Outside.Marble);
						}
					}
				}
				if (entContour[i].Inside != null && entContour[i].Inside.Count > 0)
				{
					for (int n = 0; n <= entContour[i].Inside.Count - 1; n++)
					{
						buEntityList buEntityList3 = new buEntityList();
						for (int num = 0; num <= entContour[i].Inside[n].Entities.Count - 1; num++)
						{
							buEntity copiedEntity4 = null;
							buEntity.Copy(entContour[i].Inside[n].Entities[num], ref copiedEntity4);
							if (refPoint != null)
							{
								copiedEntity4.Translate(refPoint.X, refPoint.Y, 0.0);
							}
							copiedEntity4.Marble = new MarbleInfo();
							buEntityList3.Entities.Add(copiedEntity4);
						}
						buEntityList3.ToolType = entContour[i].Inside[n].ToolType;
						if (entContour[i].Inside[n].Marble == null)
						{
							buEntityList3.Marble = new marbleEntityData();
							clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, Item.ToolType, ref buEntityList3.Marble);
						}
						else
						{
							buEntityList3.Marble = new marbleEntityData(entContour[i].Inside[n].Marble);
						}
						Item.EntGroup.Inside.Add(buEntityList3);
					}
				}
				if (entContour[i].OpenEntities != null && entContour[i].OpenEntities.Count > 0)
				{
					Item.EntGroup.OpenEntities = new List<buEntityList>();
					for (int num2 = 0; num2 <= entContour[i].OpenEntities.Count - 1; num2++)
					{
						buEntityList buEntityList4 = new buEntityList();
						for (int num3 = 0; num3 <= entContour[i].OpenEntities[num2].Entities.Count - 1; num3++)
						{
							buEntity copiedEntity5 = null;
							buEntity.Copy(entContour[i].OpenEntities[num2].Entities[num3], ref copiedEntity5);
							if (refPoint != null)
							{
								copiedEntity5.Translate(refPoint.X, refPoint.Y, 0.0);
							}
							copiedEntity5.Marble = new MarbleInfo();
							buEntityList4.Entities.Add(copiedEntity5);
						}
						buEntityList4.ToolType = entContour[i].OpenEntities[num2].ToolType;
						if (entContour[i].OpenEntities[num2].Marble == null)
						{
							buEntityList4.Marble = new marbleEntityData();
							clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, Item.ToolType, ref buEntityList4.Marble);
