						}
						Item.EntGroup.OpenEntities.Add(buEntityList4);
					}
				}
				if (Item.ItemType == MarbleItemType.TextWireframe)
				{
					if (Item.EntGroup.Outside.Entities.Count > 0)
					{
						for (int num4 = 0; num4 <= Item.EntGroup.Outside.Entities.Count - 1; num4++)
						{
							for (int num5 = 1; num5 <= Item.EntGroup.Outside.Entities[num4].Vertices.Count - 1; num5++)
							{
								List<Point3D> OffsetedPoints = new List<Point3D>();
								List<Point3D> list2 = new List<Point3D>();
								list2.Add(Item.EntGroup.Outside.Entities[num4].Vertices[num5 - 1]);
								list2.Add(Item.EntGroup.Outside.Entities[num4].Vertices[num5]);
								clsInit.cVector5.OffsetOpenContour(list2, 3.0, OffsetCornerType.Line, CamOpenContourType.Left, Plane.XY, 0.0, ref OffsetedPoints);
								LinearPath outer = new LinearPath(OffsetedPoints);
								devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer);
								Entity item = region.ExtrudeAsMesh(3.0, 0.01, Mesh.natureType.RichSmooth);
								Item.ItemEntities.SolidEntity.Add(item);
							}
						}
					}
					if (Item.EntGroup.OpenEntities != null)
					{
						for (int num6 = 0; num6 <= Item.EntGroup.OpenEntities.Count - 1; num6++)
						{
							for (int num7 = 0; num7 <= Item.EntGroup.OpenEntities[num6].Entities.Count - 1; num7++)
							{
								for (int num8 = 1; num8 <= Item.EntGroup.OpenEntities[num6].Entities[num7].Vertices.Count - 1; num8++)
								{
									List<Point3D> OffsetedPoints2 = new List<Point3D>();
									List<Point3D> list3 = new List<Point3D>();
									list3.Add(Item.EntGroup.OpenEntities[num6].Entities[num7].Vertices[num8 - 1]);
									list3.Add(Item.EntGroup.OpenEntities[num6].Entities[num7].Vertices[num8]);
									clsInit.cVector5.OffsetOpenContour(list3, 3.0, OffsetCornerType.Line, CamOpenContourType.Left, Plane.XY, 0.0, ref OffsetedPoints2);
									LinearPath outer2 = new LinearPath(OffsetedPoints2);
									devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region(outer2);
									Entity item2 = region2.ExtrudeAsMesh(3.0, 0.01, Mesh.natureType.RichSmooth);
									Item.ItemEntities.SolidEntity.Add(item2);
								}
							}
						}
					}
				}
				clsInit.cVector5.BoxSizeCalculate(Item.EntGroup, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
				Item.SizeItem.MaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
				ObjectSize3D.CalculateSize(ref Item.SizeItem);
				if (((Item.ItemEntities.SolidEntity != null) & (Item.ItemEntities.SolidEntity.Count > 0)) && Item.BaseHeight > 0.0)
				{
					Entity surfaceEntity = null;
					clsInit.cVector5.surfaceBox(Item.SizeItem.MinPoint, Item.SizeItem.MaxPoint.X - Item.SizeItem.MinPoint.X, Item.SizeItem.MaxPoint.Y - Item.SizeItem.MinPoint.Y, Item.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
					if (surfaceEntity != null)
					{
						buEntity copiedEntity6 = null;
						buEntity.Copy(surfaceEntity, ref copiedEntity6);
						copiedEntity6.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
						Item.ItemEntities.BaseEntities = new List<buEntity>();
						Item.ItemEntities.BaseEntities.Add(copiedEntity6);
					}
				}
				if (!(ToolType == MarbleToolType.Saw || ToolType == MarbleToolType.WaterJet))
				{
					continue;
				}
				if (entContour[i].Outside.Entities.Count > 0)
				{
					clsInit.cMarble.CreateEdgeEntities(entContour[i].Outside.Entities, refPoint, Outside: true, 0, 0, ref Item);
				}
				if (entContour[i].Inside.Count > 0)
				{
					for (int num9 = 0; num9 <= entContour[i].Inside.Count - 1; num9++)
					{
						clsInit.cMarble.CreateEdgeEntities(entContour[i].Inside[num9].Entities, refPoint, Outside: false, num9, 0, ref Item);
					}
				}
			}
			Item.ID = MarbleTempVars.ItemID;
			MarbleTempVars.ItemID++;
			Items.Add(Item);
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Drill Settings Decoder Error");
		}
	}

	public void CreateShapeContour(Point3D refPoint, List<buEntitiesGroup> entContour, double Thickness, ref List<MarbleItem> Items, MarbleToolType ToolType, bool isText = false)
	{
		for (int i = 0; i <= entContour.Count - 1; i++)
		{
			MarbleItem Item = new MarbleItem();
			CreateShapeContour(refPoint, entContour[i], Thickness, buMarbleCalc.varOperation.settingMarbleCam.TargetZ, ref Item, ToolType, isText);
			Items.Add(Item);
		}
	}

	public void CreateShapeContour(Point3D refPoint, buEntitiesGroup entContour, double Thickness, double TargetZ, ref MarbleItem Item, MarbleToolType ToolType, bool isText = false)
	{
		string text = "CreateShapeContour";
		try
		{
			Item = new MarbleItem();
			Item.ItemEntities.GroupEntities = new List<buEntitiesGroup>();
			Item.EntGroup = new buEntitiesGroup();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Item.ItemEntities.DrawWireEntities = new List<buEntity>();
			Item.ItemEntities.EdgeEntities = new List<buEntity>();
			Item.ItemEntities.ExtensionEntities = new List<buEntity>();
			CreateShapeEntities(refPoint, entContour, ref Item, isText);
			Item.ItemType = MarbleItemType.Contour;
			Item.ToolType = ToolType;
			Item.ItemName = buLangTranslate.preDef.Contour;
			for (int i = 0; i <= entitiesGroupForRefEntities.Count - 1; i++)
			{
				for (int j = 0; j <= entitiesGroupForRefEntities[i].Outside.Entities.Count - 1; j++)
				{
					buEntity copiedEntity = null;
					buEntity.Copy(entitiesGroupForRefEntities[i].Outside.Entities[j], ref copiedEntity);
					if (refPoint != null)
					{
						copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
					}
					Item.ItemEntities.DrawWireEntities.Add(copiedEntity);
				}
			}
			if (entContour.Outside.Marble == null)
			{
				clsInit.cMarble.MarbleEntityCamDataSet(ToolType, TargetZ, ref Item.EntGroup.Outside.Marble);
			}
			else
			{
				Item.EntGroup.Outside.Marble = new marbleEntityData(entContour.Outside.Marble);
			}
			for (int k = 0; k <= entContour.Outside.Entities.Count - 1; k++)
			{
				buEntity copiedEntity2 = null;
				buEntity.Copy(entContour.Outside.Entities[k], ref copiedEntity2);
				if (refPoint != null)
				{
					copiedEntity2.Translate(refPoint.X, refPoint.Y, 0.0);
				}
				if (copiedEntity2.Marble == null)
				{
					copiedEntity2.Marble = new MarbleInfo();
				}
				Item.EntGroup.Outside.InOutType = entContour.Outside.InOutType;
				Item.EntGroup.Outside.Entities.Add(copiedEntity2);
				Item.EntGroup.Outside.ToolType = entContour.Outside.ToolType;
			}
			if (entContour.Inside != null && entContour.Inside.Count > 0)
			{
				Item.EntGroup.Inside = new List<buEntityList>();
				for (int l = 0; l <= entContour.Inside.Count - 1; l++)
				{
					buEntityList buEntityList2 = new buEntityList();
					buEntityList2.InOutType = entContour.Inside[l].InOutType;
					if (entContour.Inside[l].Marble == null)
					{
						clsInit.cMarble.MarbleEntityCamDataSet(ToolType, TargetZ, ref buEntityList2.Marble);
					}
					else
					{
						buEntityList2.Marble = new marbleEntityData(entContour.Inside[l].Marble);
					}
					for (int m = 0; m <= entContour.Inside[l].Entities.Count - 1; m++)
					{
						buEntity copiedEntity3 = null;
						buEntity.Copy(entContour.Inside[l].Entities[m], ref copiedEntity3);
						if (refPoint != null)
						{
							copiedEntity3.Translate(refPoint.X, refPoint.Y, 0.0);
						}
						if (copiedEntity3.Marble == null)
						{
							copiedEntity3.Marble = new MarbleInfo();
						}
						buEntityList2.Entities.Add(copiedEntity3);
					}
					buEntityList2.ToolType = entContour.Inside[l].ToolType;
					if (entContour.Inside[l].Entities.Count == 1 && entContour.Inside[l].Entities[0] is buCircle)
					{
						entContour.Inside[l].ToolType = entityToolType.Milling;
					}
					Item.EntGroup.Inside.Add(buEntityList2);
				}
			}
			if (entContour.OpenEntities != null && entContour.OpenEntities.Count > 0)
			{
				Item.EntGroup.OpenEntities = new List<buEntityList>();
				for (int n = 0; n <= entContour.OpenEntities.Count - 1; n++)
				{
					buEntityList buEntityList3 = new buEntityList();
					if (entContour.OpenEntities[n].Marble == null)
					{
						clsInit.cMarble.MarbleEntityCamDataSet(ToolType, TargetZ, ref buEntityList3.Marble);
					}
					else
					{
						buEntityList3.Marble = new marbleEntityData(entContour.OpenEntities[n].Marble);
					}
					for (int num = 0; num <= entContour.OpenEntities[n].Entities.Count - 1; num++)
					{
						buEntity copiedEntity4 = null;
						buEntity.Copy(entContour.OpenEntities[n].Entities[num], ref copiedEntity4);
						if (refPoint != null)
						{
							copiedEntity4.Translate(refPoint.X, refPoint.Y, 0.0);
						}
						if (copiedEntity4.Marble == null)
						{
							copiedEntity4.Marble = new MarbleInfo();
						}
						buEntityList3.Entities.Add(copiedEntity4);
					}
					buEntityList3.ToolType = entContour.OpenEntities[n].ToolType;
					Item.EntGroup.OpenEntities.Add(buEntityList3);
				}
			}
			if (Item.ToolType != MarbleToolType.Saw)
			{
			}
			clsInit.cVector5.BoxSizeCalculate(Item.EntGroup.Outside.Entities, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
			Item.SizeItem.MaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
			Item.SizeItem.Depth = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness - Item.SizeItem.MinPoint.Z;
			Item.SizeItem.Width = Item.SizeItem.MaxPoint.X - Item.SizeItem.MinPoint.X;
			Item.SizeItem.Height = Item.SizeItem.MaxPoint.Y - Item.SizeItem.MinPoint.Y;
			Item.EntGroup.Outside.Direction = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
			clsInit.cMarble.ItemClockDirectionCheck(ref Item, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection);
			Item.ClockDir = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
			Item.ID = MarbleTempVars.ItemID;
			MarbleTempVars.ItemID++;
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Drill Settings Decoder Error");
		}
	}

	public void CreateShapeEntities(Point3D refPoint, buEntitiesGroup entContour, ref MarbleItem Item, bool isText = false)
	{
		Entity entSurface = null;
		if (!buMarbleCalc.varOperation.settingMarbleCam.Contour3DCreate)
		{
			return;
		}
		List<Point3D> Points = new List<Point3D>();
		List<List<Point3D>> list = new List<List<Point3D>>();
		if (entContour.Outside.Entities.Count > 0)
		{
			clsInit.cVector5.EntitiesToPointsWithCamDirection(entContour.Outside.Entities, ref Points);
			if (entContour.Inside.Count > 0)
			{
				for (int i = 0; i <= entContour.Inside.Count - 1; i++)
				{
					List<Point3D> Points2 = new List<Point3D>();
					clsInit.cVector5.EntitiesToPointsWithCamDirection(entContour.Inside[i].Entities, ref Points2);
					list.Add(Points2);
				}
			}
			clsInit.cVector5.surfaceFromOutterInner(Points, list, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref entSurface);
		}
		if (entSurface != null)
		{
			if (refPoint != null)
			{
				entSurface.Translate(refPoint.X, refPoint.Y);
			}
			Item.ItemEntities.SolidEntity = new List<Entity>();
			if (isText)
			{
				entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemText.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemText.Color);
				entSurface.ColorMethod = colorMethodType.byEntity;
			}
			else
			{
				entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemContour.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemContour.Color);
				entSurface.ColorMethod = colorMethodType.byEntity;
			}
			Item.ItemEntities.SolidEntity.Add(entSurface);
		}
	}

	public void doAddItem3DFile(Point3D refPoint, List<Entity> Entities)
	{
		string text = "doAddItem3DFile";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			MarbleItem Item = new MarbleItem();
			Item.ItemType = MarbleItemType.Shape3D;
			Item.ItemEntities.EngravingEntities = new List<buEntity>();
			Item.BasePoint = buVector5.ToPoint3D(refPoint);
			Item.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
			for (int i = 0; i <= Entities.Count - 1; i++)
			{
				if (!clsInit.cVector5.isEntitySolid(Entities[i]))
				{
					continue;
				}
				Entity copiedEntity = null;
				buEntity.Copy(Entities[i], ref copiedEntity);
				if (copiedEntity == null)
				{
					continue;
				}
				if (Item.ItemEntities.SolidEntity == null)
				{
					Item.ItemEntities.SolidEntity = new List<Entity>();
				}
				copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Color);
				copiedEntity.ColorMethod = colorMethodType.byEntity;
				if (!(copiedEntity is Mesh))
				{
					if (!(copiedEntity is Brep))
					{
						if (copiedEntity is Surface)
						{
							Surface surface = (Surface)copiedEntity;
							surface.Regen(0.05);
							Item.ItemEntities.SolidEntity.Add(surface.ConvertToMesh(0.01));
						}
					}
					else
					{
						Item.ItemEntities.SolidEntity.Add(((Brep)copiedEntity).ConvertToMesh(0.01));
					}
				}
				else
				{
					Item.ItemEntities.SolidEntity.Add(copiedEntity);
				}
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int j = 0; j <= Item.ItemEntities.SolidEntity.Count - 1; j++)
				{
					Entity entity = Item.ItemEntities.SolidEntity[j];
					entity.Translate(refPoint.X, refPoint.Y, refPoint.Z + Item.BaseHeight);
				}
				clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
				ObjectSize3D.CalculateSize(ref Item.SizeItem);
			}
			if (Item.ItemEntities.SolidEntity != null && Item.BaseHeight > 0.0)
			{
				Entity surfaceEntity = null;
				clsInit.cVector5.surfaceBox(Item.SizeItem.MinPoint, Item.SizeItem.MaxPoint.X - Item.SizeItem.MinPoint.X, Item.SizeItem.MaxPoint.Y - Item.SizeItem.MinPoint.Y, Item.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
				if (surfaceEntity != null)
				{
					buEntity copiedEntity2 = null;
					buEntity.Copy(surfaceEntity, ref copiedEntity2);
					copiedEntity2.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
					Item.ItemEntities.BaseEntities = new List<buEntity>();
					Item.ItemEntities.BaseEntities.Add(copiedEntity2);
				}
			}
			doAddItemCommonProps(ref Item);
			AddOperationBeforeThings();
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItem3DShape(Point3D pntActive, List<buEntity> refEntities, double Height, bool isFinished, int JobListIndex)
	{
		string text = "doAddItem3DShape";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (isFinished)
			{
				clsInit.cVector5.Move(pntActive.X, pntActive.Y, 0.0, ref clsInit.appMarble.entitiesForMove);
				MarbleItem Item = new MarbleItem();
				Item.ItemType = MarbleItemType.Shape3D;
				Item.EntGroup = new buEntitiesGroup();
				Item.EntGroupBottom = new buEntitiesGroup();
				buEntity.Copy(refEntities, ref Item.EntGroup.Outside.Entities);
				clsInit.cVector5.Move(pntActive.X, pntActive.Y, Height, ref Item.EntGroup.Outside.Entities);
				buEntity.Copy(refEntities, ref Item.EntGroupBottom.Outside.Entities);
				clsInit.cVector5.Move(pntActive.X, pntActive.Y, 0.0, ref Item.EntGroupBottom.Outside.Entities);
				Create3DShapeEntities(new Point3D(), Item.EntGroup, Item.EntGroupBottom, ref Item);
				AddOperationBeforeThings();
				doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
				buMarbleCalc.SelectedItem.ActiveItem.indexItem = activeJob.Items.Count - 1;
				clsInit.appCommand.Reset();
				AddOperationAfterThings();
			}
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Exception");
		}
	}

	public void doAddInsideOperation(Point3D pntActive, List<buEntity> refEntities, double Depth, bool isFinished, planeNames refPlane)
	{
		string text = "doAddInsideOperation";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (!isFinished || !((buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0) & (buMarbleCalc.SelectedItem.ActiveItem.indexItem <= activeJob.Items.Count - 1)))
			{
				return;
			}
			clsInit.cVector5.Move(pntActive.X, pntActive.Y, 0.0, ref clsInit.appMarble.entitiesForMove);
			MarbleItem Item = activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
			if (Item.EntGroup != null)
			{
				List<buEntity> copiedEntities = new List<buEntity>();
				buEntity.Copy(refEntities, ref copiedEntities);
				if (refPlane != planeNames.Top)
				{
					clsInit.cVector5.Move(pntActive.X, pntActive.Y, 0.0, ref copiedEntities);
				}
				else
				{
					clsInit.cVector5.Move(pntActive.X, pntActive.Y, Item.SizeItem.Depth, ref copiedEntities);
				}
				Create3DShapeInsideEntities(new Point3D(), copiedEntities, Depth, refPlane, ref Item);
			}
			clsInit.appCommand.Reset();
			AddOperationAfterThings();
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Exception");
		}
	}

	public void doContourPocketCamAdd(MarbleItem Item, MarbleToolType CuttingToolType, MarbleCamType CamType)
	{
		MarbleItemCam marbleItemCam = null;
		if (CamType != MarbleCamType.MillingRoughInside2D)
		{
			if (Item.EntGroup != null)
			{
				CamWireFrameType wireType = CamWireFrameType.Pocket;
				marbleItemCam = new MarbleItemCam();
				marbleItemCam.CamName = buLangTranslate.preDef.Pocket + " " + buLangTranslate.preDef.Inside;
				marbleItemCam.CamMarbleType = CamType;
				marbleItemCam.CamMode = MarbleCamMode.Rough;
				marbleItemCam.CamPlane = planeNames.Top;
				marbleItemCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DRough.buPar);
				marbleItemCam.setCam.Steps.StartValue = Item.SizeItem.MaxPoint.Z;
				marbleItemCam.setCam.Steps.EndValue = Item.SizeItem.MaxPoint.Z - Item.EntGroup.Outside.Depth;
				marbleItemCam.setCam.Steps.Enable = true;
				if (activeJob.Material.Enable && activeJob.Material.Size.Depth > marbleItemCam.setCam.Steps.StartValue)
				{
					marbleItemCam.setCam.Steps.StartValue = activeJob.Material.Size.Depth;
				}
				marbleItemCam.ToolType = CuttingToolType;
				marbleItemCam.WireType = wireType;
				marbleItemCam.MeshType = CamTriangularMeshType.None;
				marbleItemCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(wireType);
				marbleItemCam.ToolSelected = FindToolFromType(marbleItemCam.ToolType);
				marbleItemCam.EntityList = new buEntityList();
				buEntityList buEntityList2 = new buEntityList(Item.EntGroup.Outside);
				buEntityList2.Depth = Item.EntGroup.Outside.Depth;
				marbleItemCam.EntityList.Entities.AddRange(buEntityList2.Entities);
				if (Item.EntGroup.Inside != null)
				{
					for (int i = 0; i <= Item.EntGroup.Inside.Count - 1; i++)
					{
						buEntityList2 = new buEntityList(Item.EntGroup.Inside[i]);
						buEntityList2.Depth = Item.EntGroup.Inside[i].Depth;
						marbleItemCam.EntityList.Entities.AddRange(buEntityList2.Entities);
					}
				}
				clsInit.cMarble.GetCamID(activeJob, ref marbleItemCam.CamID);
				Item.CamList.Add(marbleItemCam);
				doShapeMillingCamCalc(ref Item, ref marbleItemCam);
			}
			if (Item.EntGroupBottom != null)
			{
				marbleItemCam = new MarbleItemCam();
				marbleItemCam.CamName = buLangTranslate.preDef.Pocket + " " + buLangTranslate.preDef.Inside;
				marbleItemCam.CamMarbleType = CamType;
				marbleItemCam.CamMode = MarbleCamMode.Rough;
				marbleItemCam.CamPlane = planeNames.Top;
				marbleItemCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DRough.buPar);
				marbleItemCam.setCam.Steps.StartValue = Item.EntGroupBottom.Outside.Depth;
				marbleItemCam.setCam.Steps.EndValue = 0.0;
				marbleItemCam.setCam.Steps.Enable = true;
				marbleItemCam.ToolType = CuttingToolType;
				marbleItemCam.WireType = CamWireFrameType.Pocket;
				marbleItemCam.MeshType = CamTriangularMeshType.None;
				marbleItemCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(CamWireFrameType.Pocket);
				marbleItemCam.ToolSelected = FindToolFromType(marbleItemCam.ToolType);
				marbleItemCam.EntityList = new buEntityList();
				buEntityList buEntityList3 = new buEntityList(Item.EntGroupBottom.Outside);
				buEntityList3.Depth = Item.EntGroupBottom.Outside.Depth;
				marbleItemCam.EntityList.Entities.AddRange(buEntityList3.Entities);
				if (Item.EntGroupBottom.Inside != null)
				{
					for (int j = 0; j <= Item.EntGroupBottom.Inside.Count - 1; j++)
					{
						buEntityList3 = new buEntityList(Item.EntGroupBottom.Inside[j]);
						buEntityList3.Depth = Item.EntGroupBottom.Inside[j].Depth;
						marbleItemCam.EntityList.Entities.AddRange(buEntityList3.Entities);
					}
				}
				clsInit.cMarble.GetCamID(activeJob, ref marbleItemCam.CamID);
				Item.CamList.Add(marbleItemCam);
				doShapeMillingCamCalc(ref Item, ref marbleItemCam);
			}
		}
		else
		{
			if (Item.EntGroup != null && Item.EntGroup.Inside != null)
			{
				for (int k = 0; k <= Item.EntGroup.Inside.Count - 1; k++)
				{
					CamWireFrameType wireType2 = CamWireFrameType.Pocket;
					marbleItemCam = new MarbleItemCam();
					marbleItemCam.CamName = buLangTranslate.preDef.Pocket + " " + buLangTranslate.preDef.Inside;
					marbleItemCam.CamMarbleType = CamType;
					marbleItemCam.CamMode = MarbleCamMode.Rough;
					marbleItemCam.CamPlane = planeNames.Top;
					marbleItemCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DRough.buPar);
					marbleItemCam.setCam.Steps.StartValue = Item.SizeItem.MaxPoint.Z;
					marbleItemCam.setCam.Steps.EndValue = Item.SizeItem.MaxPoint.Z - Item.EntGroup.Inside[k].Depth;
					marbleItemCam.setCam.Steps.Enable = true;
					if (activeJob.Material.Enable && activeJob.Material.Size.Depth > marbleItemCam.setCam.Steps.StartValue)
					{
						marbleItemCam.setCam.Steps.StartValue = activeJob.Material.Size.Depth;
					}
					marbleItemCam.ToolType = CuttingToolType;
					marbleItemCam.WireType = wireType2;
					marbleItemCam.MeshType = CamTriangularMeshType.None;
					marbleItemCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(wireType2);
					marbleItemCam.ToolSelected = FindToolFromType(marbleItemCam.ToolType);
					marbleItemCam.EntityList = new buEntityList();
					buEntityList buEntityList4 = new buEntityList(Item.EntGroup.Inside[k]);
					buEntityList4.Depth = Item.EntGroup.Inside[k].Depth;
					marbleItemCam.EntityList.Entities.AddRange(buEntityList4.Entities);
					clsInit.cMarble.GetCamID(activeJob, ref marbleItemCam.CamID);
					Item.CamList.Add(marbleItemCam);
					doShapeMillingCamCalc(ref Item, ref marbleItemCam);
				}
			}
			if (Item.EntGroupBottom != null && Item.EntGroupBottom.Inside != null)
			{
				for (int l = 0; l <= Item.EntGroupBottom.Inside.Count - 1; l++)
				{
					marbleItemCam = new MarbleItemCam();
					marbleItemCam.CamName = buLangTranslate.preDef.Pocket + " " + buLangTranslate.preDef.Inside;
					marbleItemCam.CamMarbleType = CamType;
					marbleItemCam.CamMode = MarbleCamMode.Rough;
					marbleItemCam.CamPlane = planeNames.Bottom;
					marbleItemCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DRough.buPar);
					marbleItemCam.setCam.Steps.StartValue = Item.EntGroupBottom.Inside[l].Depth;
					marbleItemCam.setCam.Steps.EndValue = 0.0;
					marbleItemCam.setCam.Steps.Enable = true;
					marbleItemCam.ToolType = CuttingToolType;
					marbleItemCam.WireType = CamWireFrameType.Pocket;
					marbleItemCam.MeshType = CamTriangularMeshType.None;
					marbleItemCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(CamWireFrameType.Pocket);
					marbleItemCam.ToolSelected = FindToolFromType(marbleItemCam.ToolType);
					marbleItemCam.EntityList = new buEntityList();
					buEntityList buEntityList5 = new buEntityList(Item.EntGroupBottom.Inside[l]);
					buEntityList5.Depth = Item.EntGroupBottom.Inside[l].Depth;
					marbleItemCam.EntityList.Entities.AddRange(buEntityList5.Entities);
					clsInit.cMarble.GetCamID(activeJob, ref marbleItemCam.CamID);
					Item.CamList.Add(marbleItemCam);
					doShapeMillingCamCalc(ref Item, ref marbleItemCam);
				}
			}
		}
		AddOperationAfterThings();
	}

	public void Create3DShapeInsideEntities(Point3D refPoint, List<buEntity> refEntities, double Depth, planeNames refPlane, ref MarbleItem Item)
	{
		List<Point3D> Points = new List<Point3D>();
		if (refEntities.Count <= 0)
		{
			return;
		}
		ICurve curve = null;
		clsInit.cVector5.EntitiesToPointsWithCamDirection(refEntities, ref Points);
		if (Points.Count >= 3)
		{
			curve = new LinearPath(Points);
		}
		if (curve != null)
		{
			if (Item.ItemEntities.SolidInsideEntity == null)
			{
				Item.ItemEntities.SolidInsideEntity = new List<Entity>();
			}
			if (refPlane == planeNames.Top)
			{
				devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(curve);
				Entity entity = null;
				entity = region.ExtrudeAsMesh(new Vector3D(0.0, 0.0, 0.0 - Depth), 0.1, Mesh.natureType.RichSmooth);
				entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemInside.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemInside.Color);
				entity.ColorMethod = colorMethodType.byEntity;
				Item.ItemEntities.SolidInsideEntity.Add(entity);
				buEntityList buEntityList2 = new buEntityList();
				buEntity.Copy(refEntities, ref buEntityList2.Entities);
				buEntityList2.Depth = Depth;
				Item.EntGroup.Outside.Depth = Depth;
				Item.EntGroup.Inside.Add(buEntityList2);
			}
			if (refPlane == planeNames.Bottom)
			{
				devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region(curve);
				Entity entity2 = null;
				entity2 = region2.ExtrudeAsMesh(new Vector3D(0.0, 0.0, Depth), 0.1, Mesh.natureType.RichSmooth);
				entity2.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemInside.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemInside.Color);
				entity2.ColorMethod = colorMethodType.byEntity;
				Item.ItemEntities.SolidInsideEntity.Add(entity2);
				buEntityList buEntityList3 = new buEntityList();
				buEntity.Copy(refEntities, ref buEntityList3.Entities);
				buEntityList3.Depth = Depth;
				Item.EntGroupBottom.Outside.Depth = Depth;
				Item.EntGroupBottom.Inside.Add(buEntityList3);
			}
		}
	}

	public void Create3DShapeEntities(Point3D refPoint, buEntitiesGroup entContourTopPlane, buEntitiesGroup entContourBottomPlane, ref MarbleItem Item)
	{
		Entity entity = null;
		List<Point3D> Points = new List<Point3D>();
		List<Point3D> Points2 = new List<Point3D>();
		List<List<Point3D>> list = new List<List<Point3D>>();
		ICurve curve = null;
		ICurve curve2 = null;
		if (entContourTopPlane.Outside.Entities.Count > 0)
		{
			clsInit.cVector5.EntitiesToPointsWithCamDirection(entContourTopPlane.Outside.Entities, ref Points);
		}
		if (entContourBottomPlane.Outside.Entities.Count > 0)
		{
			clsInit.cVector5.EntitiesToPointsWithCamDirection(entContourBottomPlane.Outside.Entities, ref Points2);
		}
		if (entContourTopPlane.Inside.Count > 0)
		{
			for (int i = 0; i <= entContourTopPlane.Inside.Count - 1; i++)
			{
				List<Point3D> Points3 = new List<Point3D>();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(entContourTopPlane.Inside[i].Entities, ref Points3);
				list.Add(Points3);
			}
		}
		if (Points.Count >= 3)
		{
			curve = new LinearPath(Points);
		}
		if (Points2.Count >= 3)
		{
			curve2 = new LinearPath(Points2);
		}
		if (curve != null && curve2 != null)
		{
			devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(curve);
			devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region(curve2);
			Surface bottom = region.ConvertToSurface();
			Surface top = region2.ConvertToSurface();
			entity = Brep.Ruled(bottom, top).ConvertToMesh(0.1);
		}
		if (entity != null)
		{
			if (refPoint != null)
			{
				entity.Translate(refPoint.X, refPoint.Y);
			}
			Item.ItemEntities.SolidEntity = new List<Entity>();
			entity.Regen(0.1);
			entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemContour.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemContour.Color);
			entity.ColorMethod = colorMethodType.byEntity;
			Item.ItemEntities.SolidEntity.Add(entity);
			Item.SizeItem.Width = entity.BoxMax.X - entity.BoxMin.X;
			Item.SizeItem.Height = entity.BoxMax.Y - entity.BoxMin.Y;
			Item.SizeItem.Depth = entity.BoxMax.Z - entity.BoxMin.Z;
			Item.SizeItem.MinPoint = buVector5.ToPoint3D(entity.BoxMin);
			Item.SizeItem.MaxPoint = buVector5.ToPoint3D(entity.BoxMax);
			Item.SizeItem.MidPoint = clsInit.cVector5.MiddlePointOfLine(Item.SizeItem.MinPoint, Item.SizeItem.MaxPoint);
		}
	}

	public void doAddItemVerHorMainForm(Point3D refPoint, double AngleC, double Length, bool isFinished = false)
	{
		string text = "doAddItemVerHorV3";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (!(refPoint == null))
			{
				MarbleTempVars.HorizontalStartPos.X = refPoint.X;
				MarbleTempVars.HorizontalStartPos.Y = refPoint.Y;
				MarbleTempVars.VerticalStartPos.X = refPoint.X;
				MarbleTempVars.VerticalStartPos.Y = refPoint.Y;
			}
			else
			{
				MarbleTempVars.HorizontalStartPos.X = buMarbleForms.frmHorizontal.spn_xoffset.Value;
				MarbleTempVars.HorizontalStartPos.Y = buMarbleForms.frmHorizontal.spn_yoffset.Value;
				MarbleTempVars.VerticalStartPos.X = buMarbleForms.frmVertical.spn_xoffset.Value;
				MarbleTempVars.VerticalStartPos.Y = buMarbleForms.frmVertical.spn_yoffset.Value;
			}
			activeJob.CamCalculated = false;
			List<string> list = new List<string>();
			MarbleTempVars.listHorizontalItems.Clear();
			MarbleTempVars.listHorizontalItems = new List<marbleCuttingItems>();
			if (MarbleTempVars.isHorizontal)
			{
				ItemListAnalyse(MarbleTempVars.cutItemsHor, ref MarbleTempVars.listHorizontalItems, -1.0, -1.0);
			}
			if (MarbleTempVars.listHorizontalItems.Count > 0)
			{
				if (buMarbleCalc.varMarbleRunSettings.HorCornerType == MarbleCorners.LeftTop)
				{
					for (int i = 0; i <= MarbleTempVars.listHorizontalItems.Count - 1; i++)
					{
						MarbleTempVars.listHorizontalItems[i].Length = 0.0 - MarbleTempVars.listHorizontalItems[i].Length;
					}
				}
				if (buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal <= 0.0)
				{
					list.Add(buLangTranslate.preSentencesMarble.CuttingLengthis0);
				}
				if (((MarbleTempVars.HorizontalStartPos.C > 45.0) & (MarbleTempVars.HorizontalStartPos.C < 135.0)) | ((MarbleTempVars.HorizontalStartPos.C > 225.0) & (MarbleTempVars.HorizontalStartPos.C < 315.0)))
				{
					buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.ThisCanBeVerticalCut);
				}
			}
			MarbleTempVars.listVerticalItems.Clear();
			MarbleTempVars.listVerticalItems = new List<marbleCuttingItems>();
			if (!MarbleTempVars.isHorizontal)
			{
				ItemListAnalyse(MarbleTempVars.cutItemsVer, ref MarbleTempVars.listVerticalItems, -1.0, -1.0);
			}
			if (MarbleTempVars.listVerticalItems.Count > 0)
			{
				if (buMarbleCalc.varMarbleRunSettings.VerCornerType == MarbleCorners.LeftTop)
				{
					for (int j = 0; j <= MarbleTempVars.listVerticalItems.Count - 1; j++)
					{
						MarbleTempVars.listVerticalItems[j].Length = 0.0 - MarbleTempVars.listVerticalItems[j].Length;
					}
				}
				if (buMarbleCalc.varMarbleRunSettings.CutLengthVertical <= 0.0)
				{
					list.Add(buLangTranslate.preSentencesMarble.CuttingLengthis0);
				}
			}
			for (int k = 0; k <= MarbleTempVars.listHorizontalItems.Count - 1; k++)
			{
				if (Math.Abs(MarbleTempVars.listHorizontalItems[k].StartAngle) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
				{
					list.Add(buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit + " - [" + (k + 1) + "] " + buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.StartAngle + " " + MarbleTempVars.listHorizontalItems[k].StartAngle);
				}
				if (Math.Abs(MarbleTempVars.listHorizontalItems[k].EndAngle) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
				{
					list.Add(buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit + " - [" + (k + 1) + "] " + buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.EndAngle + " " + MarbleTempVars.listHorizontalItems[k].EndAngle);
				}
			}
			for (int l = 0; l <= MarbleTempVars.listVerticalItems.Count - 1; l++)
			{
				if (Math.Abs(MarbleTempVars.listVerticalItems[l].StartAngle) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
				{
					list.Add(buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit + " - [" + (l + 1) + "] " + buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.StartAngle + " " + MarbleTempVars.listVerticalItems[l].StartAngle);
				}
				if (Math.Abs(MarbleTempVars.listVerticalItems[l].EndAngle) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
				{
					list.Add(buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit + " - [" + (l + 1) + "] " + buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.EndAngle + " " + MarbleTempVars.listVerticalItems[l].EndAngle);
				}
			}
			if (buMarbleCalc.varOperation.settingMarbleCam.TargetZ >= buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
			{
				list.Add(buLangTranslate.preSentencesMarble.DepthValueCantBeBiggerThenMAterialThickness);
			}
			if (Length <= 0.0)
			{
				string text2 = buLangTranslate.preDef.Horizontal;
				if (!MarbleTempVars.isHorizontal)
				{
					text2 = buLangTranslate.preDef.Vertical;
				}
				list.Add(text2 + " " + buLangTranslate.preSentencesMarble.CuttingLengthis0 + " = " + Length.ToString("f1"));
			}
			if ((Length > buMarbleCalc.varOperation.settingSliceCut.MaxSliceLength) & (MarbleTempVars.listHorizontalItems.Count > 0))
			{
				string text3 = buLangTranslate.preDef.Horizontal;
				if (!MarbleTempVars.isHorizontal)
				{
					text3 = buLangTranslate.preDef.Vertical;
				}
				list.Add(text3 + " " + buLangTranslate.preSentencesMarble.LengthisNotSuitable + " = " + Length.ToString("f1"));
