								marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar);
								marbleCam.ToolType = MarbleToolType.Saw;
								marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
								marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
								marbleCam.CamType = CamType.Contour;
								marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
								marbleCam.isCamCalculated = true;
								clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
								marbleItem.CamList.Add(marbleCam);
								marbleItem.ToolType = MarbleToolType.Saw;
								marbleItem.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
								if (MarbleTempVars.isHorizontal)
								{
									marbleItem.CamPoint = new Pnt6D(MarbleTempVars.HorizontalStartPos);
								}
								else
								{
									marbleItem.CamPoint = new Pnt6D(MarbleTempVars.VerticalStartPos);
								}
								bool isLast = false;
								if (num4 == MarbleTempVars.ItemsSlice.Count - 1)
								{
									isLast = true;
								}
								clsInit.cMarble.MarblecalcItemCam(marbleCam.ToolSelected, activeKinematic, activeJob, num4, isLast, LastP, marbleItem, ref marbleCam);
								if (marbleCam.CamBase != null)
								{
									marbleCam.CamBase.Obj1 = marbleItem;
									marbleCam.CamBase.Obj2 = marbleCam;
								}
								clsInit.cMarble.GetLastCamPointOfItem(marbleItem, ref LastP);
								if (marbleItem.ItemEntities.SolidEntity != null)
								{
									for (int num5 = 0; num5 <= marbleItem.ItemEntities.SolidEntity.Count - 1; num5++)
									{
										if (!MarbleTempVars.isHorizontal)
										{
											marbleItem.ItemEntities.SolidEntity[num5].ColorMethod = colorMethodType.byEntity;
											marbleItem.ItemEntities.SolidEntity[num5].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Color);
										}
										else
										{
											marbleItem.ItemEntities.SolidEntity[num5].ColorMethod = colorMethodType.byEntity;
											marbleItem.ItemEntities.SolidEntity[num5].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Color);
										}
									}
									clsInit.cVector5.BoxSizeCalculate(marbleItem.ItemEntities.SolidEntity, ref marbleItem.SizeItem.MinPoint, ref marbleItem.SizeItem.MidPoint, ref marbleItem.SizeItem.MaxPoint);
									ObjectSize3D.CalculateSize(ref marbleItem.SizeItem);
									new buText(new Point3D(marbleItem.SizeItem.MidPoint.X, marbleItem.SizeItem.MidPoint.Y, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + 0.2), (activeJob.Items.Count + 1).ToString(), 50.0);
								}
								doAddItemToJob(marbleItem, OperationAfterThings: false, IncreaseID: true);
							}
						}
					}
				}
				else
				{
					num = 0.0;
					num2 = 0.0;
					buEyeItems.viewportDialogs.ActiveViewport.DisplayMode = displayType.Rendered;
					buEyeItems.viewportDialogs.Entities.Clear();
					if (buMarbleForms.frmHorVerDialog.Visible)
					{
						for (int num6 = 0; num6 <= MarbleTempVars.ItemsSlice.Count - 1; num6++)
						{
							MarbleItem marbleItem2 = MarbleTempVars.ItemsSlice[num6];
							for (int num7 = 0; num7 <= marbleItem2.ItemEntities.SolidEntity.Count - 1; num7++)
							{
								Entity copiedEntity = null;
								buEntity.Copy(marbleItem2.ItemEntities.SolidEntity[num7], ref copiedEntity);
								if (copiedEntity != null)
								{
									copiedEntity.Regen(0.1);
									((CustomData)copiedEntity.EntityData).ActionName = marbleItem2.ItemType.ToString() + marbleItem2.ID + "-Solid";
									((CustomData)copiedEntity.EntityData).EntityName = marbleItem2.ItemType.ToString() + marbleItem2.ID + "-Solid";
									((CustomData)copiedEntity.EntityData).typeDefination = entityTypeDefination.MarbleItem;
									((CustomData)copiedEntity.EntityData).ID = marbleItem2.ID.ToString();
									((CustomData)copiedEntity.EntityData).Tags = "Solid";
									copiedEntity.LayerName = "Default";
									copiedEntity.ColorMethod = colorMethodType.byEntity;
									copiedEntity.Color = Color.WhiteSmoke;
									buEyeItems.viewportDialogs.Entities.Add(copiedEntity);
								}
							}
						}
						buEyeItems.viewportDialogs.SetView(viewType.Top);
						buEyeItems.viewportDialogs.ZoomFit();
						buEyeItems.viewportDialogs.Invalidate();
					}
				}
			}
			else
			{
				DialogBoxList dialogBoxList = new DialogBoxList();
				dialogBoxList.Caption = buLangTranslate.preDef.Marble + " " + buLangTranslate.preDef.Error;
				dialogBoxList.Width = 700;
				for (int num8 = 0; num8 <= list.Count - 1; num8++)
				{
					dialogBoxList.Items.Add(list[num8]);
				}
				dialogBoxList.Init("", 0);
				dialogBoxList.ShowDialog();
			}
			activeJob.CamCalculated = false;
			AddOperationAfterThings();
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItemSingleCut(Point3D refPoint, double AngleA, double AngleC, bool isFinished = false, int AddIndex = -1, bool isVacuum = false)
	{
		string text = "doAddItemSingleCut";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			List<string> list = new List<string>();
			MarbleTempVars.listVerticalItems.Clear();
			MarbleTempVars.listVerticalItems = new List<marbleCuttingItems>();
			if (!MarbleTempVars.isHorizontal)
			{
				ItemListAnalyse(MarbleTempVars.cutItemsVer, ref MarbleTempVars.listVerticalItems);
			}
			if (MarbleTempVars.listVerticalItems.Count > 0)
			{
				if (buMarbleCalc.varOperation.settingSliceCut.CutLengthSingle <= 0.0)
				{
					list.Add(buLangTranslate.preSentencesMarble.CuttingLengthis0);
				}
				if (MarbleTempVars.VerticalSetStartPositionDone)
				{
				}
			}
			if (buMarbleCalc.varOperation.settingMarbleCam.TargetZ >= buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
			{
				list.Add(buLangTranslate.preSentencesMarble.DepthValueCantBeBiggerThenMAterialThickness);
			}
			activeJob.CamCalculated = false;
			if (list.Count <= 0)
			{
				MarbleTempVars.SingleCutPos.X = refPoint.X;
				MarbleTempVars.SingleCutPos.Y = refPoint.Y;
				MarbleTempVars.SingleCutPos.A = AngleA;
				MarbleTempVars.SingleCutPos.C = AngleC;
				MarbleTempVars.ItemsSlice.Clear();
				buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = MarbleToolType.Saw;
				clsInit.cMarble.doSingleCut(MarbleTempVars.SingleCutPos, buMarbleCalc.activeToolSaw, buMarbleCalc.varOperation, activeKinematic, new EntitiesResolution(), ref MarbleTempVars.ItemsSlice, MarbleSliceType.HorizontalVertical, isFinished);
				if (isFinished)
				{
					if (MarbleTempVars.ItemsSlice.Count > 0)
					{
						AddOperationBeforeThings();
						TpPnt9D LastP = null;
						for (int i = 0; i <= MarbleTempVars.ItemsSlice.Count - 1; i++)
						{
							MarbleItem marbleItem = new MarbleItem(MarbleTempVars.ItemsSlice[i]);
							marbleItem.isVacuumCut = isVacuum;
							marbleItem.ItemEntities.EdgeEntities = new List<buEntity>();
							marbleItem.ItemEntities.DrawWireEntities = new List<buEntity>();
							marbleItem.ItemEntities.ConcaveEntities = new List<List<buEntity>>();
							marbleItem.ItemEntities.ExtensionEntities = new List<buEntity>();
							clsInit.cMarble.GetIDs(activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
							marbleItem.ID = MarbleTempVars.ItemID;
							marbleItem.EntGroup = new buEntitiesGroup();
							marbleItem.DontCheckPartLimits = true;
							MarbleItemCam marbleCam = new MarbleItemCam();
							buEntity.Copy(MarbleTempVars.ItemsSlice[i].ItemEntities.WireEntities, ref marbleCam.WireEntities);
							marbleCam.ID = MarbleTempVars.MarbleCamID;
							if (!clsInit.cMarble.isVertical(AngleC))
							{
								marbleCam.CamName = buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.Single + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.Saw + "]";
								marbleCam.CamMarbleType = MarbleCamType.HorizontalSawSingleCutting;
							}
							else
							{
								marbleCam.CamName = buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.Single + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.Saw + "]";
								marbleCam.CamMarbleType = MarbleCamType.VerticalSawSingleCutting;
							}
							marbleCam.CamMode = MarbleCamMode.Contour;
							marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar);
							marbleCam.ToolType = MarbleToolType.Saw;
							marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
							marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
							marbleCam.CamType = CamType.Contour;
							marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
							clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
							marbleItem.CamList.Add(marbleCam);
							marbleItem.ToolType = MarbleToolType.Saw;
							marbleItem.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
							if (MarbleTempVars.isHorizontal)
							{
								marbleItem.CamPoint = new Pnt6D(MarbleTempVars.HorizontalStartPos);
							}
							else
							{
								marbleItem.CamPoint = new Pnt6D(MarbleTempVars.VerticalStartPos);
							}
							bool isLast = false;
							if (i == MarbleTempVars.ItemsSlice.Count - 1)
							{
								isLast = true;
							}
							clsInit.cMarble.MarblecalcItemCam(marbleCam.ToolSelected, activeKinematic, activeJob, i, isLast, LastP, marbleItem, ref marbleCam);
							if (marbleCam.CamBase != null)
							{
								marbleCam.CamBase.Obj1 = marbleItem;
								marbleCam.CamBase.Obj2 = marbleCam;
								if (marbleItem.isVacuumCut)
								{
									marbleCam.CamBase.MaterialIndex = activeJob.VacuumCuts.Count - 1;
								}
							}
							clsInit.cMarble.GetLastCamPointOfItem(marbleItem, ref LastP);
							if (marbleItem.ItemEntities.SolidEntity != null)
							{
								for (int j = 0; j <= marbleItem.ItemEntities.SolidEntity.Count - 1; j++)
								{
									if (!MarbleTempVars.isHorizontal)
									{
										marbleItem.ItemEntities.SolidEntity[j].ColorMethod = colorMethodType.byEntity;
										marbleItem.ItemEntities.SolidEntity[j].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Color);
									}
									else
									{
										marbleItem.ItemEntities.SolidEntity[j].ColorMethod = colorMethodType.byEntity;
										marbleItem.ItemEntities.SolidEntity[j].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Color);
									}
								}
								clsInit.cVector5.BoxSizeCalculate(marbleItem.ItemEntities.SolidEntity, ref marbleItem.SizeItem.MinPoint, ref marbleItem.SizeItem.MidPoint, ref marbleItem.SizeItem.MaxPoint);
								ObjectSize3D.CalculateSize(ref marbleItem.SizeItem);
							}
							doAddItemToJob(marbleItem, OperationAfterThings: false, IncreaseID: true, AddIndex);
						}
					}
					AddOperationAfterThings();
				}
				else
				{
					buEyeItems.viewportDialogs.ActiveViewport.DisplayMode = displayType.Rendered;
					buEyeItems.viewportDialogs.Entities.Clear();
					if (buMarbleForms.frmSingle.Visible)
					{
						for (int k = 0; k <= MarbleTempVars.ItemsSlice.Count - 1; k++)
						{
							MarbleItem marbleItem2 = MarbleTempVars.ItemsSlice[k];
							for (int l = 0; l <= marbleItem2.ItemEntities.SolidEntity.Count - 1; l++)
							{
								Entity copiedEntity = null;
								buEntity.Copy(marbleItem2.ItemEntities.SolidEntity[l], ref copiedEntity);
								if (copiedEntity != null)
								{
									((CustomData)copiedEntity.EntityData).ActionName = marbleItem2.ItemType.ToString() + marbleItem2.ID + "-Solid";
									((CustomData)copiedEntity.EntityData).EntityName = marbleItem2.ItemType.ToString() + marbleItem2.ID + "-Solid";
									((CustomData)copiedEntity.EntityData).typeDefination = entityTypeDefination.MarbleItem;
									((CustomData)copiedEntity.EntityData).ID = marbleItem2.ID.ToString();
									((CustomData)copiedEntity.EntityData).Tags = "Solid";
									copiedEntity.LayerName = MarbleTempVars.layerMarblePart.Name;
									buEyeItems.viewportDialogs.Entities.Add(copiedEntity);
								}
							}
						}
						Entity entWood = null;
						if (buMarbleCalc.varMarbleSettings.DrawWoodBase)
						{
							CreateWoodMaterial(buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth, buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight, buMarbleCalc.varMarbleMachineSettings.BaseWoodThickness, buMarbleCalc.varMarbleMachineSettings.BaseWoodZOffset + buMarbleCalc.varOperation.settingMarbleCam.TargetZ, TopOnZero: true, buEyeItems.viewportCadCam.Layers[MarbleTempVars.layerWood.Index].Name, ref entWood);
							entWood.Selectable = false;
							buEyeItems.viewportDialogs.Entities.Add(entWood);
						}
						buEyeItems.viewportDialogs.Entities.Regen();
						buEyeItems.viewportDialogs.SetView(viewType.vcFrontFaceTop);
						buEyeItems.viewportDialogs.ZoomFit();
						buEyeItems.viewportDialogs.Invalidate();
					}
				}
			}
			else
			{
				DialogBoxList dialogBoxList = new DialogBoxList();
				dialogBoxList.Caption = "Marble Errors";
				dialogBoxList.Width = 500;
				for (int m = 0; m <= list.Count - 1; m++)
				{
					dialogBoxList.Items.Add(list[m]);
				}
				dialogBoxList.Init("", 0);
				dialogBoxList.ShowDialog();
			}
			activeJob.CamCalculated = false;
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItemSlice(Point3D refPoint, double AngleC, bool isFinished = false)
	{
		string text = "doAddItemSlice";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			List<string> list = new List<string>();
			if (MarbleTempVars.listHorizontalItems == null)
			{
				MarbleTempVars.listHorizontalItems = new List<marbleCuttingItems>();
			}
			if (MarbleTempVars.listVerticalItems == null)
			{
				MarbleTempVars.listVerticalItems = new List<marbleCuttingItems>();
			}
			activeJob.CamCalculated = false;
			if (list.Count <= 0)
			{
				if (isFinished)
				{
					MarbleTempVars.HorizontalStartPos.X = refPoint.X;
					MarbleTempVars.HorizontalStartPos.Y = refPoint.Y;
					MarbleTempVars.VerticalStartPos.X = refPoint.X;
					MarbleTempVars.VerticalStartPos.Y = refPoint.Y;
				}
				else if (!(refPoint == null))
				{
					MarbleTempVars.HorizontalStartPos.X = refPoint.X;
					MarbleTempVars.HorizontalStartPos.Y = refPoint.Y;
					MarbleTempVars.VerticalStartPos.X = refPoint.X;
					MarbleTempVars.VerticalStartPos.Y = refPoint.Y;
				}
				else
				{
					MarbleTempVars.HorizontalStartPos.X = 0.0;
					MarbleTempVars.HorizontalStartPos.Y = 0.0;
					MarbleTempVars.VerticalStartPos.X = 0.0;
					MarbleTempVars.VerticalStartPos.Y = 0.0;
				}
				MarbleTempVars.listHorizontalItems.Clear();
				MarbleTempVars.listVerticalItems.Clear();
				buMarbleCalc.varMarbleRunSettings.SliceWidth = buMarbleForms.frmSlice.spn_itemwidth.Value;
				buMarbleCalc.varMarbleRunSettings.SliceLength = buMarbleForms.frmSlice.spn_itemlength.Value;
				buMarbleCalc.varMarbleRunSettings.SliceStartAngle = buMarbleForms.frmSlice.spn_itemSA.Value;
				buMarbleCalc.varMarbleRunSettings.SliceEndAngle = buMarbleForms.frmSlice.spn_itemEA.Value;
				buMarbleCalc.varMarbleRunSettings.SliceCount = (int)buMarbleForms.frmSlice.spn_itemcount.Value;
				if (!buMarbleForms.frmSlice.chk_horizontal.Check)
				{
					buMarbleCalc.varMarbleRunSettings.SliceType = HorizontalVertical.Vertical;
					MarbleTempVars.isHorizontal = false;
				}
				else
				{
					buMarbleCalc.varMarbleRunSettings.SliceType = HorizontalVertical.Horizontal;
					MarbleTempVars.isHorizontal = true;
				}
				MarbleSliceType marbleSliceType = MarbleSliceType.Horizontal;
				if (buMarbleCalc.varMarbleRunSettings.SliceType != HorizontalVertical.Vertical)
				{
					marbleSliceType = MarbleSliceType.Horizontal;
					MarbleTempVars.listHorizontalItems.Add(new marbleCuttingItems(buMarbleCalc.varMarbleRunSettings.SliceWidth, buMarbleCalc.varMarbleRunSettings.SliceCount, buMarbleCalc.varMarbleRunSettings.SliceStartAngle, buMarbleCalc.varMarbleRunSettings.SliceEndAngle));
					MarbleTempVars.VerticalStartPos.C = 0.0;
					buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal = buMarbleCalc.varMarbleRunSettings.SliceLength;
				}
				else
				{
					marbleSliceType = MarbleSliceType.Vertical;
					MarbleTempVars.listVerticalItems.Add(new marbleCuttingItems(buMarbleCalc.varMarbleRunSettings.SliceWidth, buMarbleCalc.varMarbleRunSettings.SliceCount, buMarbleCalc.varMarbleRunSettings.SliceStartAngle, buMarbleCalc.varMarbleRunSettings.SliceEndAngle));
					MarbleTempVars.VerticalStartPos.C = 90.0;
					buMarbleCalc.varMarbleRunSettings.CutLengthVertical = buMarbleCalc.varMarbleRunSettings.SliceLength;
				}
				MarbleTempVars.ItemsSlice.Clear();
				buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = MarbleToolType.Saw;
				clsInit.cMarble.doMultiCut(MarbleTempVars.HorizontalStartPos, MarbleTempVars.VerticalStartPos, buMarbleCalc.activeToolSaw, MarbleTempVars.listHorizontalItems, MarbleTempVars.listVerticalItems, buMarbleCalc.varOperation, activeKinematic, new EntitiesResolution(), ref MarbleTempVars.ItemsSlice, marbleSliceType, buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal, buMarbleCalc.varMarbleRunSettings.CutLengthVertical, isFinished);
				if (isFinished)
				{
					if (MarbleTempVars.ItemsSlice.Count > 0)
					{
						AddOperationBeforeThings();
						TpPnt9D LastP = null;
						for (int i = 0; i <= MarbleTempVars.ItemsSlice.Count - 1; i++)
						{
							MarbleItem Item = new MarbleItem(MarbleTempVars.ItemsSlice[i]);
							Item.ItemEntities.EdgeEntities = new List<buEntity>();
							if (Item.ItemEntities.DrawWireEntities == null)
							{
								Item.ItemEntities.DrawWireEntities = new List<buEntity>();
							}
							Item.ItemEntities.ConcaveEntities = new List<List<buEntity>>();
							Item.ItemEntities.ExtensionEntities = new List<buEntity>();
							Item.EntGroup = new buEntitiesGroup();
							new EntitiesCopySettings(addPoint: false, addDimension: false, addCurve: true, addCircular: true, addCompositeCurve: true, addEllipse: true, compositeCurveToEntities: true, buMarbleCalc.varOperation.settingMarbleCam.RegenDeviation, 0.0);
							buEntity.Copy(Item.ItemEntities.DrawWireEntities, ref Item.EntGroup.Outside.Entities);
							clsInit.cMarble.ItemClockDirectionCheck(ref Item, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection);
							clsInit.cMarble.GetIDs(activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
							Item.ID = MarbleTempVars.ItemID;
							MarbleItemCam marbleCam = new MarbleItemCam();
							buEntity.Copy(MarbleTempVars.ItemsSlice[i].ItemEntities.WireEntities, ref marbleCam.WireEntities);
							marbleCam.ID = MarbleTempVars.MarbleCamID;
							marbleCam.CamName = buLangTranslate.preDef.Saw + " " + buLangTranslate.preDef.Slice + " " + buLangTranslate.preDef.Cut;
							marbleCam.CamMarbleType = MarbleCamType.Slices;
							marbleCam.CamMode = MarbleCamMode.Contour;
							marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar);
							marbleCam.ToolType = MarbleToolType.Saw;
							marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
							marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
							marbleCam.CamType = CamType.Contour;
							marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
							clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
							Item.CamList.Add(marbleCam);
							Item.ToolType = MarbleToolType.Saw;
							Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
							if (MarbleTempVars.isHorizontal)
							{
								Item.CamPoint = new Pnt6D(MarbleTempVars.HorizontalStartPos);
							}
							else
							{
								Item.CamPoint = new Pnt6D(MarbleTempVars.VerticalStartPos);
							}
							bool isLast = false;
							if (i == MarbleTempVars.ItemsSlice.Count - 1)
							{
								isLast = true;
							}
							clsInit.cMarble.MarblecalcItemCam(marbleCam.ToolSelected, activeKinematic, activeJob, i, isLast, LastP, Item, ref marbleCam);
							clsInit.cMarble.GetLastCamPointOfItem(Item, ref LastP);
							if (Item.ItemEntities.SolidEntity != null)
							{
								for (int j = 0; j <= Item.ItemEntities.SolidEntity.Count - 1; j++)
								{
									if (!MarbleTempVars.isHorizontal)
									{
										Item.ItemEntities.SolidEntity[j].ColorMethod = colorMethodType.byEntity;
										Item.ItemEntities.SolidEntity[j].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Color);
									}
									else
									{
										Item.ItemEntities.SolidEntity[j].ColorMethod = colorMethodType.byEntity;
										Item.ItemEntities.SolidEntity[j].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Color);
									}
								}
								clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
								ObjectSize3D.CalculateSize(ref Item.SizeItem);
							}
							doAddItemToJob(Item, OperationAfterThings: false, IncreaseID: true);
							if (buMarbleCalc.varMarbleSettings.AutoMagnet)
							{
								MarbleSelectionItems marbleSelectionItems = new MarbleSelectionItems();
								marbleSelectionItems.ItemID = Item.ID;
								marbleSelectionItems.indexItem = activeJob.Items.Count - 1;
								marbleSelectionItems.pntMin = buVector5.ToPoint3D(Item.SizeItem.MinPoint);
								marbleSelectionItems.pntMax = buVector5.ToPoint3D(Item.SizeItem.MaxPoint);
								marbleSelectionItems.MI = Item;
								buMarbleCalc.SelectedItem.SelectionItems.Add(marbleSelectionItems);
							}
						}
						if (buMarbleCalc.varMarbleSettings.AutoMagnet)
						{
							doAlignment(MarbleCadCamCommands.MagnetLeftDown, 0.0);
						}
					}
					AddOperationAfterThings();
				}
				else
				{
					buEyeItems.viewportDialogs.ActiveViewport.DisplayMode = displayType.Rendered;
					buEyeItems.viewportDialogs.Entities.Clear();
					if (buMarbleForms.frmSlice.Visible)
					{
						for (int k = 0; k <= MarbleTempVars.ItemsSlice.Count - 1; k++)
						{
							MarbleItem marbleItem = MarbleTempVars.ItemsSlice[k];
							for (int l = 0; l <= marbleItem.ItemEntities.SolidEntity.Count - 1; l++)
							{
								Entity copiedEntity = null;
								buEntity.Copy(marbleItem.ItemEntities.SolidEntity[l], ref copiedEntity);
								if (copiedEntity != null)
								{
									copiedEntity.Regen(0.1);
									((CustomData)copiedEntity.EntityData).ActionName = marbleItem.ItemType.ToString() + marbleItem.ID + "-Solid";
									((CustomData)copiedEntity.EntityData).EntityName = marbleItem.ItemType.ToString() + marbleItem.ID + "-Solid";
									((CustomData)copiedEntity.EntityData).typeDefination = entityTypeDefination.MarbleItem;
									((CustomData)copiedEntity.EntityData).ID = marbleItem.ID.ToString();
									((CustomData)copiedEntity.EntityData).Tags = "Solid";
									copiedEntity.LayerName = "Default";
									copiedEntity.ColorMethod = colorMethodType.byEntity;
									copiedEntity.Color = Color.WhiteSmoke;
									buEyeItems.viewportDialogs.Entities.Add(copiedEntity);
								}
							}
						}
						buEyeItems.viewportDialogs.SetView(viewType.Top);
						buEyeItems.viewportDialogs.ZoomFit();
						buEyeItems.viewportDialogs.Invalidate();
					}
				}
			}
			else
			{
				DialogBoxList dialogBoxList = new DialogBoxList();
				dialogBoxList.Caption = "Marble Errors";
				dialogBoxList.Width = 500;
				for (int m = 0; m <= list.Count - 1; m++)
				{
					dialogBoxList.Items.Add(list[m]);
				}
				dialogBoxList.Init("", 0);
				dialogBoxList.ShowDialog();
			}
			activeJob.CamCalculated = false;
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

