	public void doAddItemLathe(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
	{
		string text = "doAddItemLathe";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (entitiesForLathe.Count == 0)
			{
				return;
			}
			MarbleItem Item = new MarbleItem();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Entity entSurface = null;
			Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			doLatheCut(entitiesForLathe, ref entSurface, ref Item);
			Item.ItemType = MarbleItemType.LatheHorizontal;
			Item.ToolType = MarbleToolType.Saw;
			if (isFinsihed)
			{
				Item.Settings.MaterialParameter.MaterialThickness = entSurface.BoxMax.Z;
				Item.BasePoint = buVector5.ToPoint3D(refPoint);
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int i = 0; i <= Item.ItemEntities.SolidEntity.Count - 1; i++)
				{
					Item.ItemEntities.SolidEntity[i].Translate(refPoint.X, refPoint.Y, refPoint.Z + buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheZOffset);
				}
			}
			if (Item.ItemEntities.SourceEntities != null)
			{
				for (int j = 0; j <= Item.ItemEntities.SourceEntities.Count - 1; j++)
				{
					buEntity buEntity2 = Item.ItemEntities.SourceEntities[j];
					buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z + buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheZOffset);
					buEntity2.Marble = new MarbleInfo();
				}
			}
			if (!isFinsihed)
			{
				MarbleTempVars.ItemsLathe.Add(Item);
				return;
			}
			for (int k = 0; k <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; k++)
			{
				if (!(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[k] is buMachinePart))
				{
					continue;
				}
				buMachinePart buMachinePart2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[k] as buMachinePart;
				if (buMachinePart2.EntityData != null && buMachinePart2.EntityData is CustomData)
				{
					CustomData customData = buMachinePart2.EntityData as CustomData;
					if (customData.ActionName != null && ((customData.ActionName == "Lathe") & buMachinePart2.XMove))
					{
						buMachinePart2.xPos = buMarbleCalc.varMarbleRunSettings.LathePartLength - buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheLeftRightSideDistance;
					}
				}
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			AddOperationBeforeThings();
			clsInit.cMarble.GetIDs(activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
			Item.ID = MarbleTempVars.ItemID;
			doAddItemCommonProps(ref Item);
			MarbleItemCam marbleCam = new MarbleItemCam();
			marbleCam.ID = MarbleTempVars.MarbleCamID;
			marbleCam.CamName = buLangTranslate.preDef.Saw + " " + buLangTranslate.preDef.Lathe + " " + buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = MarbleCamType.Lathe;
			marbleCam.CamMode = MarbleCamMode.Contour;
			marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
			marbleCam.CamType = CamType.Contour;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleLatheHor.buPar);
			marbleCam.isFinish = true;
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			Item.CamList.Add(marbleCam);
			if (isCamCalc)
			{
				doLatheCamCalcCut(ref Item, ref marbleCam);
			}
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItemLatheVertical(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
	{
		string text = "doAddItemLatheVertical";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (entitiesForLathe.Count == 0)
			{
				return;
			}
			MarbleItem Item = new MarbleItem();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Entity entSurface = null;
			Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			doLatheVerticalCut(entitiesForLathe, ref entSurface, ref Item);
			Item.BasePoint = buVector5.ToPoint3D(refPoint);
			Item.ItemType = MarbleItemType.LatheVertical;
			Item.isVerticalItem = true;
			if (isFinsihed)
			{
				doAddItemCommonProps(ref Item);
				Item.Settings.MaterialParameter.MaterialThickness = entSurface.BoxMax.Z;
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int i = 0; i <= Item.ItemEntities.SolidEntity.Count - 1; i++)
				{
					Item.ItemEntities.SolidEntity[i].Translate(refPoint.X, refPoint.Y, refPoint.Z);
				}
			}
			if (Item.ItemEntities.SourceEntities != null)
			{
				for (int j = 0; j <= Item.ItemEntities.SourceEntities.Count - 1; j++)
				{
					buEntity buEntity2 = Item.ItemEntities.SourceEntities[j];
					buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z);
					buEntity2.Marble = new MarbleInfo();
				}
			}
			if (!isFinsihed)
			{
				MarbleTempVars.ItemsLathe.Add(Item);
				return;
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
				ObjectSize3D.CalculateSize(ref Item.SizeItem);
			}
			AddOperationBeforeThings();
			if (Item.Settings.settingLatheVerticalCut.LatheBaseHeight > 0.0 && ((Item.SizeItem.Width > 0.0) & (Item.SizeItem.Height > 0.0) & (Item.SizeItem.Depth > 0.0)))
			{
				Brep brep = Brep.CreateBox(Item.SizeItem.Width, Item.SizeItem.Height, Item.Settings.settingLatheVerticalCut.LatheBaseHeight);
				brep.Regen(0.1);
				Mesh mesh = brep.ConvertToMesh();
				if (mesh != null)
				{
					mesh.Translate(Item.SizeItem.MidPoint.X - Item.SizeItem.Width / 2.0, Item.SizeItem.MidPoint.Y - Item.SizeItem.Height / 2.0);
					buEntity copiedEntity = null;
					buEntity.Copy(mesh, ref copiedEntity);
					copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
					Item.ItemEntities.BaseEntities = new List<buEntity>();
					Item.ItemEntities.BaseEntities.Add(copiedEntity);
				}
			}
			MarbleItemCam marbleCam = new MarbleItemCam();
			marbleCam.CamName = buLangTranslate.preDef.Saw + " " + buLangTranslate.preDef.Lathe + " " + buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = MarbleCamType.Lathe;
			marbleCam.CamMode = MarbleCamMode.Contour;
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleColumns.buPar);
			marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
			marbleCam.CamType = CamType.Contour;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.isFinish = true;
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			Item.CamList.Add(marbleCam);
			if (isCamCalc)
			{
				doLatheVerticalCamCalcCut(ref Item, ref marbleCam);
			}
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doLatheCut(List<buEntity> RefEntities, ref Entity entSurface, ref MarbleItem Item)
	{
		string text = "doLatheCut";
		try
		{
			List<Point3D> list = new List<Point3D>();
			Point3D MinPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			new Point3D();
			if (RefEntities.Count > 0)
			{
				clsInit.cVector5.BoxSizeCalculate(RefEntities, ref MinPoint, ref MaxPoint);
				buMarbleCalc.varMarbleRunSettings.LathePartLength = MaxPoint.X - MinPoint.X;
				clsInit.cVector5.Move(0.0 - MaxPoint.X, 0.0, 0.0, ref RefEntities);
				list = new List<Point3D>();
				for (int i = 0; i <= RefEntities.Count - 1; i++)
				{
					List<Point3D> Points = new List<Point3D>();
					clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[i], buMarbleCalc.varMarbleEntitiesSettings.LatheDeviationResolution, ref Points);
					list.AddRange(Points);
					buEntity copiedEntity = null;
					buEntity.Copy(RefEntities[i], ref copiedEntity);
					clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref copiedEntity);
					Item.ItemEntities.SourceEntities.Add(copiedEntity);
				}
				clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref list);
				Entity entTop = null;
				Entity entBottom = null;
				LinearPath linearPath = new LinearPath(list);
				linearPath.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
				CompositeCurve refCurve = new CompositeCurve(linearPath);
				clsInit.cVector5.surfaceRevolveByPath(refCurve, Vector3D.AxisX, new Point3D(), 0.0, 360.0, ref entSurface, ref entTop, ref entBottom);
				entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheHorizontal.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheHorizontal.Color);
				entSurface.ColorMethod = colorMethodType.byEntity;
				Item.ItemEntities.SolidEntity = new List<Entity>();
				Item.ItemEntities.SolidEntity.Add(entSurface);
				entTop.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
				entTop.ColorMethod = colorMethodType.byEntity;
				Item.ItemEntities.SolidEntity.Add(entTop);
				entBottom.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
				entBottom.ColorMethod = colorMethodType.byEntity;
				Item.ItemEntities.SolidEntity.Add(entBottom);
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doLatheVerticalCut(List<buEntity> RefEntities, ref Entity entSurface, ref MarbleItem Item)
	{
		string text = "doLatheVerticalCut";
		try
		{
			List<Point3D> list = new List<Point3D>();
			if (RefEntities.Count > 0)
			{
				list = new List<Point3D>();
				for (int i = 0; i <= RefEntities.Count - 1; i++)
				{
					List<Point3D> Points = new List<Point3D>();
					clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[i], buMarbleCalc.varMarbleEntitiesSettings.LatheDeviationResolution, ref Points);
					list.AddRange(Points);
					buEntity copiedEntity = null;
					buEntity.Copy(RefEntities[i], ref copiedEntity);
					clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref copiedEntity);
					copiedEntity.Translate(0.0, 0.0, Item.Settings.settingLatheVerticalCut.LatheBaseHeight);
					Item.ItemEntities.SourceEntities.Add(copiedEntity);
				}
				clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref list);
				LinearPath linearPath = new LinearPath(list);
				linearPath.Rotate(buConversion5.DegreeToRadian(90.0), Vector3D.AxisX);
				linearPath.Translate(0.0, 0.0, Item.Settings.settingLatheVerticalCut.LatheBaseHeight);
				linearPath.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
				Entity entTop = null;
				Entity entBottom = null;
				CompositeCurve refCurve = new CompositeCurve(linearPath);
				clsInit.cVector5.surfaceRevolveByPath(refCurve, Vector3D.AxisZ, new Point3D(), 0.0, 360.0, ref entSurface, ref entTop, ref entBottom);
				Item.ItemEntities.SolidEntity = new List<Entity>();
				entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
				entSurface.ColorMethod = colorMethodType.byEntity;
				Item.ItemEntities.SolidEntity.Add(entSurface);
				entTop.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
				entTop.ColorMethod = colorMethodType.byEntity;
				Item.ItemEntities.SolidEntity.Add(entTop);
				entBottom.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
				entBottom.ColorMethod = colorMethodType.byEntity;
				Item.ItemEntities.SolidEntity.Add(entBottom);
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doLatheCamCalcCut(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doLatheCamCalcCut";
		try
		{
			clsMW.Containment2DEntities.Clear();
			Point3D MinPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Entity entSureface = null;
			List<Point3D> list = new List<Point3D>();
			Item.ItemEntities.WireEntities = new List<List<buEntity>>();
			for (int i = 0; i <= Item.ItemEntities.SourceEntities.Count - 1; i++)
			{
				List<Point3D> Points = new List<Point3D>();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.ItemEntities.SourceEntities[i], buMarbleCalc.varMarbleEntitiesSettings.LatheDeviationResolution, ref Points);
				list.AddRange(Points);
			}
			clsInit.cVector5.SurfaceExturudeByPoints(list, Vector3D.AxisY, marbleCam.ToolSelected.Geometry.Thickness / 2.0, ref entSureface);
			clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint, ref MaxPoint);
			MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
			mWCalculationOptions.NumberofAxis = 3;
			mWCalculationOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
			mWCalculationOptions.Mode = CamMode.TriangularMesh;
			mWCalculationOptions.isRough = true;
			mWCalculationOptions.DontApplyReset = true;
			mWCalculationOptions.AddToCamListInLocalCalculation = false;
			mWCalculationOptions.AddToCamListInMWCalculation = false;
			mWCalculationOptions.DontShowbuDialogBox = true;
			ToolBase5 toolBase = new ToolBase5();
			toolBase.Geometry.Diameter = marbleCam.ToolSelected.Geometry.Thickness;
			toolBase.Geometry.Length = 500.0;
			toolBase.Geometry.GeometryType = buClass.ToolType.Flat;
			clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshParelelCut.mwPar, buMWMarbleVars.varCamMarbleMeshParelelCut.buPar, out clsMW.varbuCamMeshParallelPars);
			clsMW.varMWCamMeshParalelPars.MachParam.ParallelMachAngleInYX = 90.0;
			clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.ApproachFeedPlaneIncremental = 0.0;
			clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.FeedPlaneIncremental = 0.0;
			clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.RetractPlaneIncremental = 0.0;
			clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.ClearancePlaneHeight = MaxPoint.Z + 50.0;
			clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
			clsMW.varMWCamMeshParalelPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Thickness;
			clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
			clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
			clsMW.varMWCamMeshParalelPars.MachParam.DistanceFlag = true;
			clsMW.varMWCamMeshParalelPars.MachParam.Distance = 20.0;
			clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
			clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
			clsMW.CamEntities.Clear();
			if (!(entSureface is Brep))
			{
				clsMW.CamEntities.Add(entSureface);
			}
			else
			{
				clsMW.CamEntities.Add(((Brep)entSureface).ConvertToMesh(0.1));
			}
			mWCalculationOptions.DontShowDialogBox = true;
			camTp Cam = new camTp();
			camResult Result = new camResult();
			clsInit.appMW.doTriangularMesh3D(mWCalculationOptions, toolBase, ref Cam, ref Result);
			List<Point3D> refPoints = new List<Point3D>();
			List<Point3D> list2 = new List<Point3D>();
			List<Point3D> list3 = new List<Point3D>();
			if (Cam.CamPoints.Count != 1)
			{
				if (Cam.CamPoints.Count > 1)
				{
				}
			}
			else if (Cam.EntitiesG1Orj.Count > 0)
			{
				for (int j = 0; j <= Cam.EntitiesG1Orj.Count - 1; j++)
				{
					for (int k = 0; k <= Cam.EntitiesG1Orj[j].Vertices.Length - 1; k++)
					{
						refPoints.Add(buVector5.ToPoint3D(Cam.EntitiesG1Orj[j].Vertices[k]));
					}
				}
			}
			if (refPoints.Count == 0)
			{
				return;
			}
			marbleCam.isCamCalculated = true;
			clsInit.cVector5.BoxSizeCalculate(refPoints, ref MinPoint, ref MidPoint, ref MaxPoint);
			clsInit.cVector5.Move(0.0, buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheYOffset - MinPoint.Y, 0.0, ref refPoints);
			if (Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MaxToMin)
			{
				refPoints.Reverse();
			}
			if ((Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MidToLeftThenRight) | (Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MidToRightThenLEft))
			{
				int num = -1;
				for (int l = 0; l <= refPoints.Count - 1; l++)
				{
					if (refPoints[l].X > MidPoint.X)
					{
						num = l;
						l = refPoints.Count;
					}
				}
				if (num >= 0)
				{
					for (int m = 0; m <= num; m++)
					{
						list2.Add(buVector5.ToPoint3D(refPoints[m]));
					}
					for (int n = num; n <= refPoints.Count - 1; n++)
					{
						list3.Add(buVector5.ToPoint3D(refPoints[n]));
					}
				}
			}
			Item.ItemEntities.WireEntities = new List<List<buEntity>>();
			List<buEntity> list4 = new List<buEntity>();
			if (!((list2.Count > 0) & (list3.Count > 0)))
			{
				buLinearPath item = new buLinearPath(refPoints);
				list4.Add(item);
				Item.ItemEntities.WireEntities.Add(list4);
			}
			else
			{
				if (Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MidToLeftThenRight)
				{
					list2.Reverse();
					buLinearPath item2 = new buLinearPath(list2);
					list4.Add(item2);
					Item.ItemEntities.WireEntities.Add(list4);
					item2 = new buLinearPath(list3);
					list4 = new List<buEntity>();
					list4.Add(item2);
					Item.ItemEntities.WireEntities.Add(list4);
				}
				if (Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MidToRightThenLEft)
				{
					buLinearPath item3 = new buLinearPath(list3);
					list4.Add(item3);
					Item.ItemEntities.WireEntities.Add(list4);
					list2.Reverse();
					item3 = new buLinearPath(list2);
					list4 = new List<buEntity>();
					list4.Add(item3);
					Item.ItemEntities.WireEntities.Add(list4);
				}
			}
			Item.Settings.settingMarbleCam.DontCheckZValues = true;
			Item.Settings.settingMarbleCam.OffsetAngleC = 90.0;
			if (!Item.Settings.settingLatheCut.LatheZSafeDistanceFromTopSurface)
			{
				Item.Settings.settingMarbleCam.SawSafeDistance = Item.Settings.settingLatheCut.LatheSafeDistance;
			}
			else
			{
				Item.Settings.settingMarbleCam.SawSafeDistance = MaxPoint.Z + Item.Settings.settingLatheCut.LatheSafeDistance;
			}
			Item.Settings.settingMarbleCam.SawPlungeVelocity = Item.Settings.settingLatheCut.LathePlungeFeed;
			Item.Settings.settingMarbleCam.SawForwardCuttingVelocity = Item.Settings.settingLatheCut.LatheCutFeed;
			Item.Settings.settingMarbleCam.SawBackwardCuttingVelocity = Item.Settings.settingLatheCut.LatheCutFeed;
			Item.Settings.settingMarbleCam.AlwaysSafeDistance = true;
			Item.Settings.settingMarbleCam.NoAngleCAxisCheck = true;
			marbleCam.setCam.Strategy.UseTangentLimit = true;
			marbleCam.setCam.Options.AxesLimit.MaxLimit.C = 370.0;
			marbleCam.setCam.Options.AxesLimit.MinLimit.C = -370.0;
			marbleCam.setCam.Speeds.Feed = Item.Settings.settingLatheCut.LatheCutFeed;
			marbleCam.setCam.Speeds.Plunge = Item.Settings.settingLatheCut.LathePlungeFeed;
			marbleCam.setCam.Distances.Safe = Item.Settings.settingLatheCut.LatheSafeDistance;
			if (Item.Settings.settingLatheCut.LatheCAxisFollowDirection)
			{
				Item.Settings.settingMarbleCam.UseConstantCAngle = false;
			}
			else
			{
				Item.Settings.settingMarbleCam.UseConstantCAngle = true;
				Item.Settings.settingMarbleCam.ConstantAngleC = 270.0;
			}
			if (Item.ItemEntities.WireEntities != null && Item.ItemEntities.WireEntities.Count > 0)
			{
				marbleCam.WireEntities = new List<List<buEntity>>();
				for (int num2 = 0; num2 <= Item.ItemEntities.WireEntities.Count - 1; num2++)
				{
					list4 = new List<buEntity>();
					buEntity.Copy(Item.ItemEntities.WireEntities[num2], ref list4);
					marbleCam.WireEntities.Add(list4);
				}
			}
			clsInit.cMarble.CalculateMarbleWireFrameWithSaw(activeKinematic, marbleCam.ToolSelected, activeJob, 0, isLast: true, null, ref Item, ref marbleCam);
			if (marbleCam.CamBase != null && marbleCam.CamBase.CamPoints.Count > 0)
			{
				for (int num3 = 0; num3 <= marbleCam.CamBase.CamPoints.Count - 1; num3++)
				{
					if (!Item.Settings.settingLatheCut.LatheZSafeDistanceFromTopSurface && marbleCam.CamBase.CamPoints[num3].Points.Count > 0)
					{
						TpPnt9D tpPnt9D = marbleCam.CamBase.CamPoints[num3].Points[0];
						TpPnt9D tpPnt9D2 = marbleCam.CamBase.CamPoints[num3].Points[marbleCam.CamBase.CamPoints[num3].Points.Count - 1];
						TpPnt9D tpPnt9D3 = marbleCam.CamBase.CamPoints[num3].Points[marbleCam.CamBase.CamPoints[num3].Points.Count - 2];
						if (tpPnt9D2.P9.Z - tpPnt9D.P9.Z > 5.0 && buCompare5.EQ(tpPnt9D3.P9.Z, tpPnt9D.P9.Z, 1.0))
						{
							marbleCam.CamBase.CamPoints[num3].Points.RemoveAt(marbleCam.CamBase.CamPoints[num3].Points.Count - 1);
						}
					}
				}
			}
			if (marbleCam.CamBase == null)
			{
				return;
			}
			marbleCam.isCamCalculated = true;
			camTp camTp2 = marbleCam.CamBase;
			camTp2.OperationData = new MarbleItemSettings(Item.Settings);
			camTp2.TypeCam = CamType.ContourClosedOutside;
			camTp2.AxisCount = 5;
			camTp2.Explanation = buLangTranslate.preDef.Lathe + " " + buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.Cutting;
			camTp2.Name = buLangTranslate.preDef.Lathe + " " + buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.Cutting;
			camTp2.CamID = Item.ID;
			camTp2.Post = new PostProcessor(ccVars.PostActive);
			camTp2.Post.RepetitionDef.Tool = false;
			camTp2.UsedCamPost = true;
			camTp2.Parameter = new camParameters5(marbleCam.setCam);
			camTp2.Post.ToolDef.ToolData.PreCode.Clear();
			if (marbleCam.ToolSelected.Purpose != ToolPurpose.Saw)
			{
				camTp2.Post.SpindleDef.UseSpindle = true;
				camTp2.Post.AxesUsing.Z = true;
				camTp2.Post.AxesUsing.A = true;
				camTp2.Post.AxesUsing.C = true;
			}
			else
			{
				camTp2.Post.SpindleDef.UseSpindle = false;
				camTp2.Post.AxesUsing.Z = true;
				camTp2.Post.AxesUsing.A = true;
				camTp2.Post.AxesUsing.C = true;
			}
			if (!buSystem.Canceled)
			{
				camTp2.Name = "Lathe Cut (" + marbleCam.ToolSelected.Purpose.ToString() + ") - [Marble]";
				if (marbleCam.ToolSelected.Purpose != ToolPurpose.Saw)
				{
				}
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doLatheVerticalCamCalcCut(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doLatheVerticalCamCalcCut";
		try
		{
			clsMW.Containment2DEntities.Clear();
			Entity entSureface = null;
			Point3D MinPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			new Point3D();
			List<Point3D> Points = new List<Point3D>();
			Item.ItemEntities.WireEntities = new List<List<buEntity>>();
			for (int i = 0; i <= Item.ItemEntities.SourceEntities.Count - 1; i++)
			{
				List<Point3D> Points2 = new List<Point3D>();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.ItemEntities.SourceEntities[i], buMarbleCalc.varMarbleEntitiesSettings.LatheDeviationResolution, ref Points2);
				Points.AddRange(Points2);
			}
			if (Points.Count > 0)
			{
				clsInit.cVector5.Rotate(Item.BasePoint, 90.0, Plane.XZ, ref Points);
			}
			clsInit.cVector5.SurfaceExturudeByPoints(Points, Vector3D.AxisY, 2.0, ref entSureface);
			clsInit.cVector5.BoxSizeCalculate(Points, ref MinPoint, ref MaxPoint);
			MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
			mWCalculationOptions.NumberofAxis = 3;
			mWCalculationOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
			mWCalculationOptions.Mode = CamMode.TriangularMesh;
			mWCalculationOptions.isRough = true;
			mWCalculationOptions.DontApplyReset = true;
			mWCalculationOptions.AddToCamListInLocalCalculation = false;
			mWCalculationOptions.AddToCamListInMWCalculation = false;
			mWCalculationOptions.DontShowbuDialogBox = true;
			ToolBase5 toolBase = new ToolBase5();
			toolBase.Geometry.Diameter = marbleCam.ToolSelected.Geometry.Thickness;
			toolBase.Geometry.Length = 500.0;
			toolBase.Geometry.GeometryType = buClass.ToolType.Flat;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.ParallelMachAngleInYX = 90.0;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.ApproachFeedPlaneIncremental = 0.0;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.FeedPlaneIncremental = 0.0;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.RetractPlaneIncremental = 0.0;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.ClearancePlaneHeight = MaxPoint.Z + 50.0;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Thickness / 2.0;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.DistanceFlag = true;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.Distance = marbleCam.ToolSelected.Geometry.Thickness * 0.8;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
			buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.CutTolerance = 0.1;
			clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleLatheVer.mwPar, buMWMarbleVars.varCamMarbleLatheVer.buPar, out clsMW.varbuCamMeshParallelPars);
			clsMW.CamEntities.Clear();
			if (!(entSureface is Brep))
			{
				clsMW.CamEntities.Add(entSureface);
			}
			else
			{
				clsMW.CamEntities.Add(((Brep)entSureface).ConvertToMesh(0.1));
			}
			mWCalculationOptions.DontShowDialogBox = true;
			camTp Cam = new camTp();
			camResult Result = new camResult();
			clsInit.appMW.doTriangularMesh3D(mWCalculationOptions, toolBase, ref Cam, ref Result);
			List<Point3D> Points3 = new List<Point3D>();
			if (Cam.CamPoints.Count != 1)
			{
				if (Cam.CamPoints.Count > 1)
				{
				}
			}
			else if (Cam.EntitiesG1Orj.Count > 0)
			{
				for (int j = 0; j <= Cam.EntitiesG1Orj.Count - 1; j++)
				{
					for (int k = 0; k <= Cam.EntitiesG1Orj[j].Vertices.Length - 1; k++)
					{
						Points3.Add(buVector5.ToPoint3D(Cam.EntitiesG1Orj[j].Vertices[k]));
					}
				}
			}
			if (Points3.Count == 0)
			{
				return;
			}
			clsInit.cVector5.Rotate(Item.BasePoint, -90.0, Plane.XZ, ref Points3);
			Points3.Insert(0, new Point3D(Points3[0].X + Item.Settings.settingLatheVerticalCut.LatheSafeDistance, Points3[0].Y, Points3[0].Z));
			Points3.Add(new Point3D(Points3[Points3.Count - 1].X + Item.Settings.settingLatheVerticalCut.LatheSafeDistance, Points3[Points3.Count - 1].Y, Points3[Points3.Count - 1].Z));
			clsInit.cVector5.BoxSizeCalculate(Points3, ref MinPoint, ref MaxPoint);
			Item.ItemEntities.WireEntities = new List<List<buEntity>>();
			List<buEntity> list = new List<buEntity>();
			buLinearPath buLinearPath2 = new buLinearPath(Points3);
			buLinearPath2.Orientation.A = 90.0;
			list.Add(buLinearPath2);
			Item.ItemEntities.WireEntities.Add(list);
			marbleCam.CamBase = new camTp();
			camTpPoint camTpPoint2 = new camTpPoint();
			List<Point3D> list2 = new List<Point3D>();
			List<Point3D> list3 = new List<Point3D>();
			List<Point3D> list4 = new List<Point3D>();
			for (int l = 0; l <= Points3.Count - 1; l++)
			{
				List<Pnt6D> list5 = new List<Pnt6D>();
				double length = clsInit.cVector5.Length3D(Item.BasePoint, Points3[l], Plane.XY);
				Point3D EndPnt = new Point3D();
				clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[l].Z), length, 0.0, ref EndPnt);
				list5.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, 90.0));
				if (l > 1)
				{
					if (l != Points3.Count - 1)
					{
						list2.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
					}
					else
					{
						if (list2.Count > 0)
						{
							list3.Add(new Point3D(list2[list2.Count - 1].X, list2[list2.Count - 1].Y, list2[list2.Count - 1].Z));
						}
						list3.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
					}
				}
				else
				{
					list4.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
					if (l == 1)
					{
						list2.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
					}
				}
				List<Pnt6D> calcPoints = new List<Pnt6D>();
				clsInit.cMarble.CalculatePointsWithKinematic(list5, activeKinematic, marbleCam.ToolSelected, ref calcPoints);
				for (int m = 0; m <= calcPoints.Count - 1; m++)
				{
					TpPnt9D item = new TpPnt9D(calcPoints[m], 20.0, 1);
					camTpPoint2.Points.Add(item);
				}
			}
			camTpPoint2.ToolCam = new ToolBase5(buMarbleCalc.activeToolSaw);
			if (list2.Count > 0)
			{
				LinearPath item2 = new LinearPath(list2);
				marbleCam.CamBase.EntitiesG1.Add(item2);
			}
			if (list3.Count > 0)
			{
				LinearPath item3 = new LinearPath(list3);
				marbleCam.CamBase.EntitiesLeave.Add(item3);
			}
			if (list4.Count > 0)
			{
				LinearPath item4 = new LinearPath(list4);
				marbleCam.CamBase.EntitiesPlunge.Add(item4);
			}
			marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolSaw);
			marbleCam.CamBase.CamPoints.Add(camTpPoint2);
			if (marbleCam.CamBase != null)
			{
				marbleCam.isCamCalculated = true;
				camTp camTp2 = marbleCam.CamBase;
				camTp2.OperationData = new MarbleItemSettings(Item.Settings);
				camTp2.TypeCam = CamType.ContourClosedOutside;
				camTp2.AxisCount = 5;
				camTp2.Explanation = buLangTranslate.preDef.Lathe + " " + buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.Cutting;
				camTp2.Name = buLangTranslate.preDef.Lathe + " " + buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.Cutting;
				camTp2.CamID = Item.ID;
				camTp2.Post = new PostProcessor(ccVars.PostActive);
				camTp2.Post.RepetitionDef.Tool = false;
				camTp2.UsedCamPost = true;
				camTp2.Parameter = new camParameters5(marbleCam.setCam);
				camTp2.Post.ToolDef.ToolData.PreCode.Clear();
				if (marbleCam.ToolSelected.Purpose != ToolPurpose.Saw)
				{
					camTp2.Post.SpindleDef.UseSpindle = true;
					camTp2.Post.AxesUsing.Z = true;
					camTp2.Post.AxesUsing.A = true;
					camTp2.Post.AxesUsing.C = true;
				}
				else
				{
					camTp2.Post.SpindleDef.UseSpindle = false;
					camTp2.Post.AxesUsing.Z = true;
					camTp2.Post.AxesUsing.A = true;
					camTp2.Post.AxesUsing.C = true;
				}
				if (!buSystem.Canceled && marbleCam.ToolSelected.Purpose != ToolPurpose.Saw)
				{
				}
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItemColumns(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
	{
		string text = "doAddItemColumns";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (entitiesForColumns.Count == 0)
			{
				return;
			}
			MarbleItem Item = new MarbleItem();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Entity entSurface = null;
			Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			doColumnsCut(entitiesForColumns, ref entSurface, ref Item);
			Item.BasePoint = buVector5.ToPoint3D(refPoint);
			Item.ItemType = MarbleItemType.Columns;
			Item.BaseHeight = Item.Settings.settingColoumnsCut.ColoumsBaseHeight;
			Item.isVerticalItem = true;
			if (isFinsihed)
			{
				doAddItemCommonProps(ref Item);
				Item.Settings.MaterialParameter.MaterialThickness = entSurface.BoxMax.Z;
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int i = 0; i <= Item.ItemEntities.SolidEntity.Count - 1; i++)
				{
					Item.ItemEntities.SolidEntity[i].Translate(refPoint.X, refPoint.Y, refPoint.Z);
				}
			}
			if (Item.ItemEntities.SourceEntities != null)
			{
				for (int j = 0; j <= Item.ItemEntities.SourceEntities.Count - 1; j++)
				{
					buEntity buEntity2 = Item.ItemEntities.SourceEntities[j];
					buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z);
					buEntity2.Marble = new MarbleInfo();
				}
			}
			if (!isFinsihed)
			{
				MarbleTempVars.ItemsColumns.Add(Item);
				return;
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
				ObjectSize3D.CalculateSize(ref Item.SizeItem);
			}
			if (Item.Settings.settingColoumnsCut.ColoumsBaseHeight > 0.0 && ((Item.SizeItem.Width > 0.0) & (Item.SizeItem.Height > 0.0) & (Item.SizeItem.Depth > 0.0)))
			{
				Brep brep = Brep.CreateBox(Item.SizeItem.Width, Item.SizeItem.Height, Item.Settings.settingColoumnsCut.ColoumsBaseHeight);
				brep.Regen(0.1);
				Mesh mesh = brep.ConvertToMesh();
				if (mesh != null)
				{
					mesh.Translate(Item.SizeItem.MidPoint.X - Item.SizeItem.Width / 2.0, Item.SizeItem.MidPoint.Y - Item.SizeItem.Height / 2.0);
					buEntity copiedEntity = null;
					buEntity.Copy(mesh, ref copiedEntity);
					copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
					Item.ItemEntities.BaseEntities = new List<buEntity>();
					Item.ItemEntities.BaseEntities.Add(copiedEntity);
				}
			}
			MarbleItemCam marbleCam = new MarbleItemCam();
			marbleCam.CamName = buLangTranslate.preDef.Saw + " " + buLangTranslate.preDef.Columns + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = MarbleCamType.Columns;
			marbleCam.CamMode = MarbleCamMode.Contour;
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleColumns.buPar);
			marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
			marbleCam.CamType = CamType.Contour;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.isFinish = true;
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			Item.CamList.Add(marbleCam);
			AddOperationBeforeThings();
			if (isCamCalc)
			{
				doColumnsCamCalcCut(ref Item, ref marbleCam);
			}
			Item.ID = MarbleTempVars.ItemID;
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doColumnsCut(List<buEntity> RefEntities, ref Entity entSurface, ref MarbleItem Item)
	{
		string text = "doColumnsCut";
		try
		{
			List<Point3D> list = new List<Point3D>();
			if (RefEntities.Count <= 0)
			{
				clsInit.appCommand.Reset(ClearSelection: true, ReDraw: true);
				return;
			}
			list = new List<Point3D>();
			for (int i = 0; i <= RefEntities.Count - 1; i++)
			{
				List<Point3D> Points = new List<Point3D>();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[i], buMarbleCalc.varMarbleEntitiesSettings.ColumnsDeviationResolution, ref Points);
				list.AddRange(Points);
				buEntity copiedEntity = null;
				buEntity.Copy(RefEntities[i], ref copiedEntity);
				clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref copiedEntity);
				copiedEntity.Translate(0.0, 0.0, Item.Settings.settingColoumnsCut.ColoumsBaseHeight);
				Item.ItemEntities.SourceEntities.Add(copiedEntity);
			}
			clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref list);
			LinearPath linearPath = new LinearPath(list);
			linearPath.Rotate(buConversion5.DegreeToRadian(90.0), Vector3D.AxisX);
			linearPath.Translate(0.0, 0.0, Item.Settings.settingColoumnsCut.ColoumsBaseHeight);
			linearPath.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
			Entity entTop = null;
			Entity entBottom = null;
			CompositeCurve refCurve = new CompositeCurve(linearPath);
			clsInit.cVector5.surfaceRevolveByPath(refCurve, Vector3D.AxisZ, new Point3D(), 0.0, 360.0, ref entSurface, ref entTop, ref entBottom);
			entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemColumn.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemColumn.Color);
			entSurface.ColorMethod = colorMethodType.byEntity;
			Item.ItemEntities.SolidEntity = new List<Entity>();
			Item.ItemEntities.SolidEntity.Add(entSurface);
			entTop.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
			entTop.ColorMethod = colorMethodType.byEntity;
			Item.ItemEntities.SolidEntity.Add(entTop);
			entBottom.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
			entBottom.ColorMethod = colorMethodType.byEntity;
			Item.ItemEntities.SolidEntity.Add(entBottom);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doColumnsCamCalcCut(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doColumnsCamCalcCut";
		try
		{
			clsMW.Containment2DEntities.Clear();
			Entity entSureface = null;
			Point3D MinPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			new Point3D();
			List<Point3D> Points = new List<Point3D>();
			Item.ItemEntities.WireEntities = new List<List<buEntity>>();
			for (int i = 0; i <= Item.ItemEntities.SourceEntities.Count - 1; i++)
			{
				List<Point3D> Points2 = new List<Point3D>();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.ItemEntities.SourceEntities[i], buMarbleCalc.varMarbleEntitiesSettings.ColumnsDeviationResolution, ref Points2);
				Points.AddRange(Points2);
			}
			if (Points.Count > 0)
			{
				clsInit.cVector5.Rotate(Item.BasePoint, 90.0, Plane.XZ, ref Points);
			}
			clsInit.cVector5.SurfaceExturudeByPoints(Points, Vector3D.AxisY, 2.0, ref entSureface);
			clsInit.cVector5.BoxSizeCalculate(Points, ref MinPoint, ref MaxPoint);
			MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
			mWCalculationOptions.NumberofAxis = 3;
			mWCalculationOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
			mWCalculationOptions.Mode = CamMode.TriangularMesh;
			mWCalculationOptions.isRough = true;
			mWCalculationOptions.DontApplyReset = true;
			mWCalculationOptions.AddToCamListInLocalCalculation = false;
			mWCalculationOptions.AddToCamListInMWCalculation = false;
			mWCalculationOptions.DontShowbuDialogBox = true;
			ToolBase5 toolBase = new ToolBase5();
			toolBase.Geometry.Diameter = marbleCam.ToolSelected.Geometry.Thickness;
			toolBase.Geometry.Length = 500.0;
			toolBase.Geometry.GeometryType = buClass.ToolType.Flat;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.ParallelMachAngleInYX = 90.0;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.ApproachFeedPlaneIncremental = 0.0;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.FeedPlaneIncremental = 0.0;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.RetractPlaneIncremental = 0.0;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.ClearancePlaneHeight = MaxPoint.Z + Item.Settings.settingColoumnsCut.ColoumsSafeDistance;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.MaxStepoverDistance = Item.Settings.settingColoumnsCut.ColoumsZStep;
			if (buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.MaxStepoverDistance > marbleCam.ToolSelected.Geometry.Thickness)
			{
				buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Thickness;
			}
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.UndercutsFlg = false;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.DistanceFlag = true;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.Distance = buMarbleCalc.activeToolSaw.Geometry.Thickness * 0.8;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = false;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.CutTolerance = 0.1;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
			buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
			clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleColumns.mwPar, buMWMarbleVars.varCamMarbleColumns.buPar, out clsMW.varbuCamMeshParallelPars);
			clsMW.CamEntities.Clear();
			if (!(entSureface is Brep))
			{
				clsMW.CamEntities.Add(entSureface);
			}
			else
			{
				clsMW.CamEntities.Add(((Brep)entSureface).ConvertToMesh(0.1));
			}
			mWCalculationOptions.DontShowDialogBox = true;
			camTp Cam = new camTp();
			camResult Result = new camResult();
			clsInit.appMW.doTriangularMesh3D(mWCalculationOptions, toolBase, ref Cam, ref Result);
			List<Point3D> Points3 = new List<Point3D>();
			if (Cam.CamPoints.Count != 1)
			{
				if (Cam.CamPoints.Count > 1)
				{
				}
			}
			else if (Cam.EntitiesG1Orj.Count > 0)
			{
				for (int j = 0; j <= Cam.EntitiesG1Orj.Count - 1; j++)
				{
					for (int k = 0; k <= Cam.EntitiesG1Orj[j].Vertices.Length - 1; k++)
					{
						Points3.Add(buVector5.ToPoint3D(Cam.EntitiesG1Orj[j].Vertices[k]));
					}
				}
			}
			if (Points3.Count == 0)
			{
				return;
			}
			clsInit.cVector5.Rotate(Item.BasePoint, -90.0, Plane.XZ, ref Points3);
			clsInit.cVector5.BoxSizeCalculate(Points3, ref MinPoint, ref MaxPoint);
			Item.ItemEntities.WireEntities = new List<List<buEntity>>();
			List<buEntity> list = new List<buEntity>();
			buLinearPath item = new buLinearPath(Points3);
			list.Add(item);
			Item.ItemEntities.WireEntities.Add(list);
			Item.Settings.settingMarbleCam.OffsetAngleC = 0.0;
			Item.Settings.settingMarbleCam.SawSafeDistance = MaxPoint.Z + Item.Settings.settingColoumnsCut.ColoumsSafeDistance;
			Item.Settings.settingMarbleCam.SawPlungeVelocity = Item.Settings.settingColoumnsCut.ColoumsPlungeFeed;
			Item.Settings.settingMarbleCam.SawForwardCuttingVelocity = Item.Settings.settingColoumnsCut.ColoumsCutFeed;
			Item.Settings.settingMarbleCam.SawBackwardCuttingVelocity = Item.Settings.settingColoumnsCut.ColoumsCutFeed;
			marbleCam.setCam.Strategy.UseTangentLimit = true;
			marbleCam.setCam.Options.AxesLimit.MaxLimit.C = Item.Settings.settingMarbleCam.AngleCMax;
			marbleCam.setCam.Options.AxesLimit.MinLimit.C = Item.Settings.settingMarbleCam.AngleCMin;
			marbleCam.setCam.Speeds.Feed = Item.Settings.settingColoumnsCut.ColoumsCutFeed;
			marbleCam.setCam.Speeds.Plunge = Item.Settings.settingColoumnsCut.ColoumsPlungeFeed;
			marbleCam.setCam.Distances.Safe = Item.Settings.settingColoumnsCut.ColoumsSafeDistance;
			marbleCam.isCamCalculated = true;
			marbleCam.CamBase = new camTp();
			int num = 0;
			for (int l = 0; l <= Points3.Count - 1; l++)
			{
				if (!((Points3[l].Z < MaxPoint.Z - 0.1) & (Points3[l].Z > MinPoint.Z + 0.1)))
				{
					continue;
				}
				List<Pnt6D> list2 = new List<Pnt6D>();
				double num2 = clsInit.cVector5.Length3D(Item.BasePoint, Points3[l], Plane.XY);
				List<Point3D> list3 = new List<Point3D>();
				new List<Point3D>();
				new List<Point3D>();
				Point3D EndPnt = new Point3D();
				clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[l].Z), num2 + Item.Settings.settingColoumnsCut.ColoumsSafeDistance, -90.0, ref EndPnt);
				list2.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, 0.0));
				list3.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
				if (!Item.Settings.settingColoumnsCut.ColoumsZigzagMode)
				{
					for (double num3 = 0.0; num3 <= 360.0; num3 += Item.Settings.settingColoumnsCut.ColoumsCRotationStep)
					{
						EndPnt = new Point3D();
						clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[l].Z), num2, num3 - 90.0, ref EndPnt);
						list2.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, num3 + 0.0));
						list3.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
					}
				}
				else if (num % 2 != 0)
				{
					for (double num4 = 360.0; num4 >= 0.0; num4 -= Item.Settings.settingColoumnsCut.ColoumsCRotationStep)
					{
						EndPnt = new Point3D();
						clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[l].Z), num2, num4 - 90.0, ref EndPnt);
						list2.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, num4 + 0.0));
						list3.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
					}
				}
				else
				{
					for (double num5 = 0.0; num5 <= 360.0; num5 += Item.Settings.settingColoumnsCut.ColoumsCRotationStep)
					{
						EndPnt = new Point3D();
						clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[l].Z), num2, num5 - 90.0, ref EndPnt);
						list2.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, num5 + 0.0));
						list3.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
					}
				}
				EndPnt = new Point3D();
				clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[l].Z), num2 + Item.Settings.settingColoumnsCut.ColoumsSafeDistance, 270.0, ref EndPnt);
				list2.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, 360.0));
				list3.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
				List<Pnt6D> calcPoints = new List<Pnt6D>();
				clsInit.cMarble.CalculatePointsWithKinematic(list2, activeKinematic, marbleCam.ToolSelected, ref calcPoints);
				camTpPoint camTpPoint2 = new camTpPoint();
				for (int m = 0; m <= calcPoints.Count - 1; m++)
				{
					int type = 1;
					double feed = Item.Settings.settingColoumnsCut.ColoumsCutFeed;
					if ((m == 0) | (m == calcPoints.Count - 1))
					{
						type = 0;
					}
					if (m == 1)
					{
						feed = Item.Settings.settingColoumnsCut.ColoumsPlungeFeed;
					}
					TpPnt9D item2 = new TpPnt9D(calcPoints[m], feed, type);
					camTpPoint2.Points.Add(item2);
				}
				camTpPoint2.ToolCam = new ToolBase5(buMarbleCalc.activeToolSaw);
				LinearPath item3 = new LinearPath(list3);
				marbleCam.CamBase.EntitiesG1.Add(item3);
				marbleCam.CamBase.CamPoints.Add(camTpPoint2);
				num++;
			}
			marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolSaw);
			if (marbleCam.CamBase != null)
			{
				marbleCam.isCamCalculated = true;
				camTp camTp2 = marbleCam.CamBase;
				camTp2.CamID = Item.ID;
				camTp2.OperationData = new MarbleItemSettings(Item.Settings);
				camTp2.TypeCam = CamType.ContourClosedOutside;
				camTp2.AxisCount = 5;
				camTp2.Explanation = buLangTranslate.preDef.Columns + " " + buLangTranslate.preDef.Cutting;
				camTp2.Name = buLangTranslate.preDef.Columns + " " + buLangTranslate.preDef.Cutting;
				camTp2.Post = new PostProcessor(ccVars.PostActive);
				camTp2.Post.RepetitionDef.Tool = false;
				camTp2.UsedCamPost = true;
				camTp2.Parameter = new camParameters5(marbleCam.setCam);
				camTp2.Post.ToolDef.ToolData.PreCode.Clear();
				if (marbleCam.ToolSelected.Purpose != ToolPurpose.Saw)
				{
					camTp2.Post.SpindleDef.UseSpindle = true;
					camTp2.Post.AxesUsing.Z = true;
					camTp2.Post.AxesUsing.A = true;
					camTp2.Post.AxesUsing.C = true;
				}
				else
				{
					camTp2.Post.SpindleDef.UseSpindle = false;
					camTp2.Post.AxesUsing.Z = true;
					camTp2.Post.AxesUsing.A = true;
					camTp2.Post.AxesUsing.C = true;
				}
				if (buSystem.Canceled)
				{
				}
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItemEngraving(Point3D refPoint, List<Entity> Entities, bool isText = false, bool isCamCalc = false)
	{
		string text = "doAddItemEngraving";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			MarbleItem Item = new MarbleItem();
			Item.ItemEntities.EngravingEntities = new List<buEntity>();
			Item.ItemType = MarbleItemType.Engraving;
			if (isText)
			{
				Item.ItemType = MarbleItemType.Text3D;
			}
			Item.BasePoint = buVector5.ToPoint3D(refPoint);
			Item.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
			for (int i = 0; i <= Entities.Count - 1; i++)
			{
				if (!(Entities[i] is Brep))
				{
					if (!(Entities[i] is Mesh))
					{
						if (Entities[i] is Surface)
						{
							buEntity copiedEntity = null;
							Surface surface = (Surface)Entities[i];
							surface.Regen(0.05);
							Mesh refEntity = surface.ConvertToMesh();
							buEntity.Copy(refEntity, ref copiedEntity);
							Item.ItemEntities.EngravingEntities.Add(copiedEntity);
						}
					}
					else
					{
						buEntity copiedEntity2 = null;
						buEntity.Copy(Entities[i], ref copiedEntity2);
						Item.ItemEntities.EngravingEntities.Add(copiedEntity2);
					}
				}
				else
				{
					buEntity copiedEntity3 = null;
					Brep brep = (Brep)Entities[i];
					brep.Regen(0.05);
					buEntity.Copy(brep.ConvertToMesh(), ref copiedEntity3);
					Item.ItemEntities.EngravingEntities.Add(copiedEntity3);
				}
			}
			for (int j = 0; j <= Entities.Count - 1; j++)
			{
				if (!clsInit.cVector5.isEntitySolid(Entities[j]))
				{
					continue;
				}
				Entity copiedEntity4 = null;
				buEntity.Copy(Entities[j], ref copiedEntity4);
				if (copiedEntity4 != null)
				{
					if (Item.ItemEntities.SolidEntity == null)
					{
						Item.ItemEntities.SolidEntity = new List<Entity>();
					}
					copiedEntity4.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Color);
					copiedEntity4.ColorMethod = colorMethodType.byEntity;
					Item.ItemEntities.SolidEntity.Add(copiedEntity4);
				}
			}
			for (int k = 0; k <= Item.ItemEntities.EngravingEntities.Count - 1; k++)
			{
				buEntity buEntity2 = Item.ItemEntities.EngravingEntities[k];
				buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z + Item.BaseHeight);
				buEntity2.Marble = new MarbleInfo();
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int l = 0; l <= Item.ItemEntities.SolidEntity.Count - 1; l++)
				{
					Entity entity = Item.ItemEntities.SolidEntity[l];
					entity.Translate(refPoint.X, refPoint.Y, refPoint.Z + Item.BaseHeight);
				}
				clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
				ObjectSize3D.CalculateSize(ref Item.SizeItem);
			}
			if (Item.ItemEntities.SolidEntity != null && Item.BaseHeight > 0.0)
			{
				Entity surfaceEntity = null;
				clsInit.cVector5.surfaceBox(Item.SizeItem.MinPoint, Item.SizeItem.MaxPoint.X - Item.SizeItem.MinPoint.X, Item.SizeItem.MaxPoint.Y - Item.SizeItem.MinPoint.Y, Item.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
				if (surfaceEntity != null)
				{
					buEntity copiedEntity5 = null;
					buEntity.Copy(surfaceEntity, ref copiedEntity5);
					copiedEntity5.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
					Item.ItemEntities.BaseEntities = new List<buEntity>();
					Item.ItemEntities.BaseEntities.Add(copiedEntity5);
				}
			}
			for (int m = 0; m <= 1; m++)
			{
				MarbleItemCam marbleCam = new MarbleItemCam();
				marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
				if (m != 0)
				{
					if (m == 1)
					{
						marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType2;
					}
				}
				else
				{
					marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
				}
				if (marbleCam.MeshType != CamTriangularMeshType.Rough)
				{
					if (marbleCam.MeshType != CamTriangularMeshType.ParallelCuts)
					{
						if (marbleCam.MeshType != CamTriangularMeshType.ConstantZ)
						{
							if (marbleCam.MeshType != CamTriangularMeshType.Flatlands)
							{
								if (marbleCam.MeshType == CamTriangularMeshType.Pencil)
								{
									doAddItemCommonProps(ref Item);
									marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshPencil.buPar);
									marbleCam.CamType = CamType.Pencil;
									marbleCam.CamName = buLangTranslate.preDef.Engraving + " " + buLangTranslate.preDef.Pencil + " " + buLangTranslate.preDef.Cut;
									marbleCam.CamMarbleType = MarbleCamType.MillingPencil3D;
								}
							}
							else
							{
								doAddItemCommonProps(ref Item);
								marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshFlatland.buPar);
								marbleCam.CamType = CamType.Flatlands;
								marbleCam.CamName = buLangTranslate.preDef.Engraving + " " + buLangTranslate.preDef.Flatlands + " " + buLangTranslate.preDef.Cut;
								marbleCam.CamMarbleType = MarbleCamType.MillingFlatland3D;
							}
						}
						else
						{
							doAddItemCommonProps(ref Item);
							marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
							marbleCam.CamType = CamType.ConstantZ;
							marbleCam.CamName = buLangTranslate.preDef.Engraving + " " + buLangTranslate.preDef.ConstantZ + " " + buLangTranslate.preDef.Cut;
							marbleCam.CamMarbleType = MarbleCamType.MillingContantZ3D;
						}
					}
					else
					{
						doAddItemCommonProps(ref Item);
						marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshParelelCut.buPar);
						marbleCam.CamType = CamType.ParallelCut;
						marbleCam.CamName = buLangTranslate.preDef.Engraving + " " + buLangTranslate.preDef.ParalelCuts + " " + buLangTranslate.preDef.Cut;
						marbleCam.CamMarbleType = MarbleCamType.MillingParallelCut3D;
					}
				}
				else
				{
					doAddItemCommonProps(ref Item);
					marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshRough.buPar);
					marbleCam.CamType = CamType.Rough;
					marbleCam.CamName = buLangTranslate.preDef.Engraving + " " + buLangTranslate.preDef.Rough + " " + buLangTranslate.preDef.Cut;
					marbleCam.CamMarbleType = MarbleCamType.MillingRough3D;
				}
				marbleCam.CamMode = MarbleCamMode.Rough;
				marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
				if ((marbleCam.ToolType == MarbleToolType.Saw) | (marbleCam.ToolType == MarbleToolType.WaterJet))
				{
					marbleCam.ToolType = MarbleToolType.Milling;
				}
				marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
				marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
				clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
				if (marbleCam.MeshType != CamTriangularMeshType.None)
				{
					Item.CamList.Add(marbleCam);
				}
				if (!isCamCalc)
				{
					marbleCam.isCamCalculated = false;
					activeJob.CamCalculated = false;
				}
				else if (marbleCam.MeshType != CamTriangularMeshType.None)
				{
					MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
					mWCalculationOptions.NumberofAxis = 3;
					mWCalculationOptions.CamWireframeType = CamWireFrameType.Contour;
					mWCalculationOptions.CamTriMeshType = marbleCam.MeshType;
					mWCalculationOptions.Mode = CamMode.TriangularMesh;
					mWCalculationOptions.DontApplyReset = true;
					mWCalculationOptions.isBuWireframeCalculation = false;
					mWCalculationOptions.AddToCamListInLocalCalculation = false;
					mWCalculationOptions.ShowLeadInOutPage = false;
					mWCalculationOptions.DontShowDialogBox = true;
					mWCalculationOptions.DontShowbuDialogBox = true;
					doEngraveCamCalc(mWCalculationOptions, Item, ref marbleCam);
					marbleCam.isCamCalculated = true;
				}
			}
			AddOperationBeforeThings();
			Item.ID = MarbleTempVars.ItemID;
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
			if (buMarbleCalc.varMarbleSettings.AutoMagnet)
			{
				doAlignment(MarbleCadCamCommands.MagnetLeftDown, 0.0);
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doEngravingCamAdd(ref MarbleItem Item, MarbleToolType CuttingToolType, MarbleCamType CamType, bool ShowDialog, bool Edit, ref MarbleItemCam marbleCam)
	{
		if (ShowDialog)
		{
			if (buMarbleForms.frmTriMeshSet == null)
			{
				buMarbleForms.frmTriMeshSet = new F_CamTriMeshSettings();
			}
			buMarbleForms.frmTriMeshSet.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
			buMarbleForms.frmTriMeshSet.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			if (!(CamType == MarbleCamType.MillingRough3D || CamType == MarbleCamType.Rough3Plus2Front || CamType == MarbleCamType.Rough3Plus2Back))
			{
				if (CamType != MarbleCamType.MillingParallelCut3D)
				{
					if (CamType != MarbleCamType.MillingContantZ3D)
					{
						if (CamType != MarbleCamType.MillingFlatland3D)
						{
							if (CamType != MarbleCamType.MillingPencil3D)
							{
								if (CamType != MarbleCamType.MillingContantCusp3D)
								{
									if (CamType != MarbleCamType.ProjectionRoundRough)
									{
										if (CamType != MarbleCamType.ProjectionRoundFinish)
										{
											if (CamType != MarbleCamType.MillingParallelCut5D)
											{
												if (CamType != MarbleCamType.MillingContantZ5D)
												{
													if (CamType == MarbleCamType.MillingGeodesic5D)
													{
														buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DGeodesic.buPar);
														buMarbleForms.frmTriMeshSet.Init(buClass.CamType.Geodesic, is5Axis: false);
													}
												}
												else
												{
													buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DConstantZ.buPar);
													buMarbleForms.frmTriMeshSet.Init(buClass.CamType.ConstantZ, is5Axis: false);
												}
											}
											else
											{
												buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DParelelCut.buPar);
												buMarbleForms.frmTriMeshSet.Init(buClass.CamType.ParallelCut, is5Axis: false);
											}
										}
										else
										{
											buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshProjectionAroundFinish.buPar);
											buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineX = Item.SizeItem.MidPoint.X;
											buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineY = Item.SizeItem.MidPoint.Y;
											buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineZ = Item.SizeItem.MinPoint.Z;
											if (!(Item.SizeItem.Width > Item.SizeItem.Height))
											{
												buMarbleForms.frmTriMeshSet.Settings.Strategy.CylinderRadiusAroundLine = Item.SizeItem.Height;
											}
											else
											{
												buMarbleForms.frmTriMeshSet.Settings.Strategy.CylinderRadiusAroundLine = Item.SizeItem.Width;
											}
											buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionEndHeight = Item.SizeItem.MaxPoint.Z - Item.SizeItem.MinPoint.Z;
											buMarbleForms.frmTriMeshSet.Init(buClass.CamType.Projection, is5Axis: false);
										}
									}
									else
									{
										buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshProjectionAroundRough.buPar);
										buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineX = Item.SizeItem.MidPoint.X;
										buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineY = Item.SizeItem.MidPoint.Y;
										buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineZ = Item.SizeItem.MinPoint.Z;
										if (!(Item.SizeItem.Width > Item.SizeItem.Height))
										{
											buMarbleForms.frmTriMeshSet.Settings.Strategy.CylinderRadiusAroundLine = Item.SizeItem.Height;
										}
										else
										{
