										}
										buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionEndHeight = Item.SizeItem.MaxPoint.Z - Item.SizeItem.MinPoint.Z;
										buMarbleForms.frmTriMeshSet.Init(buClass.CamType.Projection, is5Axis: false);
									}
								}
