			marbleCam.CamName = buLangTranslate.preDef.Engrave + " 5X " + buLangTranslate.preDef.ParalelCuts + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.ParallelCut;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DParelelCut.buPar);
		}
		if (CamType == MarbleCamType.MillingContantZ3D)
		{
			marbleCam.MeshType = CamTriangularMeshType.ConstantZ;
			marbleCam.CamName = buLangTranslate.preDef.Engrave + " " + buLangTranslate.preDef.ConstantZ + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.ConstantZ;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
		}
		if (CamType == MarbleCamType.MillingContantZ5D)
		{
			marbleCam.MeshType = CamTriangularMeshType.ConstantZ;
			marbleCam.CamName = buLangTranslate.preDef.Engrave + " 5X " + buLangTranslate.preDef.ConstantZ + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.ConstantZ;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DConstantZ.buPar);
		}
		if (CamType == MarbleCamType.MillingFlatland3D)
		{
			marbleCam.MeshType = CamTriangularMeshType.Flatlands;
			marbleCam.CamName = buLangTranslate.preDef.Engrave + " " + buLangTranslate.preDef.Flatlands + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.Flatlands;
