			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshFlatland.buPar);
		}
		if (CamType == MarbleCamType.MillingPencil3D)
		{
			marbleCam.MeshType = CamTriangularMeshType.Pencil;
			marbleCam.CamName = buLangTranslate.preDef.Engrave + " " + buLangTranslate.preDef.Pencil + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.Pencil;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshPencil.buPar);
		}
		if (CamType == MarbleCamType.MillingContantCusp3D)
		{
			marbleCam.MeshType = CamTriangularMeshType.ConstantCusp;
			marbleCam.CamName = buLangTranslate.preDef.Engrave + " " + buLangTranslate.preDef.ConstantCusp + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.ConstantCusp;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantCusp.buPar);
		}
		if (CamType == MarbleCamType.ProjectionRoundFinish)
		{
			marbleCam.MeshType = CamTriangularMeshType.ProjectionAround;
			marbleCam.CamName = buLangTranslate.preDef.Projection + " " + buLangTranslate.preDef.Around + " " + buLangTranslate.preDef.Finish + " " + buLangTranslate.preDef.Cut + " 3 + 2";
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.Finish;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshProjectionAroundFinish.buPar);
		}
		if (CamType == MarbleCamType.ProjectionRoundRough)
		{
			marbleCam.MeshType = CamTriangularMeshType.ProjectionAround;
			marbleCam.CamName = buLangTranslate.preDef.Projection + " " + buLangTranslate.preDef.Around + " " + buLangTranslate.preDef.Rough + " " + buLangTranslate.preDef.Cut + " 3 + 2";
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Rough;
			marbleCam.CamType = buClass.CamType.Rough;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshProjectionAroundRough.buPar);
		}
		if (CamType == MarbleCamType.MillingGeodesic5D)
		{
			marbleCam.MeshType = CamTriangularMeshType.Geodesic;
			marbleCam.CamName = buLangTranslate.preDef.Engrave + " 5X " + buLangTranslate.preDef.Geodesic + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.Geodesic;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DGeodesic.buPar);
		}
		MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
		mWCalculationOptions.NumberofAxis = 3;
		mWCalculationOptions.CamTriMeshType = marbleCam.MeshType;
		mWCalculationOptions.Mode = CamMode.TriangularMesh;
		mWCalculationOptions.DontApplyReset = true;
		mWCalculationOptions.isBuWireframeCalculation = false;
		mWCalculationOptions.AddToCamListInLocalCalculation = false;
		mWCalculationOptions.ShowLeadInOutPage = false;
		mWCalculationOptions.DontShowDialogBox = true;
		mWCalculationOptions.DontShowbuDialogBox = true;
		clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
		if (Item.ItemEntities.EngravingEntities == null)
		{
			Item.ItemEntities.EngravingEntities = new List<buEntity>();
		}
		if (Item.ItemEntities.EngravingEntities.Count == 0 && Item.ItemEntities.SolidEntity != null && Item.ItemEntities.SolidEntity.Count > 0)
		{
			buEntity.Copy(Item.ItemEntities.SolidEntity, ref Item.ItemEntities.EngravingEntities);
		}
		int num = 0;
		num = ((CamType == MarbleCamType.MillingParallelCut5D || CamType == MarbleCamType.MillingContantZ5D || CamType == MarbleCamType.MillingGeodesic5D) ? doEngrave5DCamCalc(mWCalculationOptions, Item, ref marbleCam) : doEngraveCamCalc(mWCalculationOptions, Item, ref marbleCam));
		if (!Edit && num > 0)
		{
			Item.CamList.Add(marbleCam);
		}
		AddOperationAfterThings();
	}

	public int doEngraveCamCalc(MWCalculationOptions MWCalcoptions, MarbleItem Item, ref MarbleItemCam marbleCam, bool isText = false)
	{
		string text = "doEngraveCamCalc";
		try
		{
			clsMW.Containment2DEntities.Clear();
			clsMW.StockEntities.Clear();
			if (Item.ItemEntities.EngravingEntities != null)
			{
				if (Item.ItemEntities.EngravingEntities.Count != 0)
				{
					if (activeJob.Material.Enable & (activeJob.Material.Points.Count > 0))
					{
						List<Point3D> copiedPoint = new List<Point3D>();
						buVector5.Copy(activeJob.Material.Points, ref copiedPoint);
						LinearPath linearPath = new LinearPath(copiedPoint);
