									buMWMarbleVars.varCamMarbleMeshConstantCusp.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantCuspPars, clsMW.varbuCamMeshConstantCuspPars, out buMWMarbleVars.varCamMarbleMeshConstantCusp.buPar);
