								Cam.CamTriMeshType = MWCalcoptions.CamTriMeshType;
								Cam.NumberOfAxis = MWCalcoptions.NumberofAxis;
								Cam.Tool = new ToolBase5(marbleCam.ToolSelected);
								if (MWCalcoptions.CamTriMeshType != CamTriangularMeshType.Rough3Plus2)
								{
									if (MWCalcoptions.CamTriMeshType != CamTriangularMeshType.ProjectionAround)
									{
										marbleCam.CamBase = new camTp(Cam);
									}
									else
									{
										Cam.TypeCam = CamType.MillingCut;
										marbleCam.CamBase = new camTp(Cam);
										for (int k = 0; k <= marbleCam.CamBase.CamPoints.Count - 1; k++)
										{
											for (int l = 0; l <= marbleCam.CamBase.CamPoints[k].Points.Count - 1; l++)
											{
												TpPnt9D tpPnt9D = marbleCam.CamBase.CamPoints[k].Points[l];
												tpPnt9D.P9.C = clsInit.cVector5.PointAngle(new Point3D(tpPnt9D.P9.A, tpPnt9D.P9.B, 0.0), new Point3D(), Plane.XY) + 90.0;
												if (l > 0)
												{
													TpPnt9D tpPnt9D2 = marbleCam.CamBase.CamPoints[k].Points[l - 1];
													double num5 = tpPnt9D.P9.C - tpPnt9D2.P9.C;
													if (Math.Abs(num5) > 180.0)
													{
														if (!(num5 > 0.0))
														{
															tpPnt9D.P9.C += 360.0;
														}
														else
														{
															tpPnt9D.P9.C -= 360.0;
														}
													}
												}
												tpPnt9D.P9.A = 90.0;
											}
										}
									}
								}
								else
								{
									marbleCam.CamBase = new camTp(Cam);
									for (int m = 0; m <= marbleCam.CamBase.CamPoints.Count - 1; m++)
									{
										for (int n = 0; n <= marbleCam.CamBase.CamPoints[m].Points.Count - 1; n++)
										{
											TpPnt9D tpPnt9D3 = marbleCam.CamBase.CamPoints[m].Points[n];
											tpPnt9D3.P9.A = 90.0;
											if (marbleCam.CamMarbleType == MarbleCamType.Rough3Plus2Front)
											{
												tpPnt9D3.P9.C = 0.0;
											}
											if (marbleCam.CamMarbleType == MarbleCamType.Rough3Plus2Back)
											{
												tpPnt9D3.P9.C = 180.0;
											}
										}
									}
								}
								marbleCam.CamBase.Obj1 = Item;
								marbleCam.CamBase.Obj2 = marbleCam;
								marbleCam.CamBase.Name = marbleCam.CamName;
								marbleCam.isCamCalculated = true;
