	public void doAddItemSawMilling(Point3D refPoint, List<Entity> Entities, bool isHorizontal, bool isRough, bool isCamCalc = false)
	{
		string text = "doAddItemSawMilling";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			MarbleItem marbleItem = new MarbleItem();
			marbleItem.ItemType = MarbleItemType.Shape3D;
			marbleItem.ItemEntities.EngravingEntities = new List<buEntity>();
			marbleItem.BasePoint = buVector5.ToPoint3D(refPoint);
			marbleItem.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
			for (int i = 0; i <= Entities.Count - 1; i++)
			{
				if (!(Entities[i] is Brep))
				{
					if (!(Entities[i] is Mesh))
					{
						if (Entities[i] is Surface)
						{
							buEntity copiedEntity = null;
							Surface surface = (Surface)Entities[i];
							surface.Regen(0.05);
							Mesh refEntity = surface.ConvertToMesh();
							buEntity.Copy(refEntity, ref copiedEntity);
							marbleItem.ItemEntities.EngravingEntities.Add(copiedEntity);
						}
					}
					else
					{
						buEntity copiedEntity2 = null;
						buEntity.Copy(Entities[i], ref copiedEntity2);
						marbleItem.ItemEntities.EngravingEntities.Add(copiedEntity2);
					}
				}
				else
				{
					buEntity copiedEntity3 = null;
					Brep brep = (Brep)Entities[i];
					brep.Regen(0.05);
					buEntity.Copy(brep.ConvertToMesh(), ref copiedEntity3);
					marbleItem.ItemEntities.EngravingEntities.Add(copiedEntity3);
				}
			}
			for (int j = 0; j <= Entities.Count - 1; j++)
			{
				if (!clsInit.cVector5.isEntitySolid(Entities[j]))
				{
					continue;
				}
				Entity copiedEntity4 = null;
				buEntity.Copy(Entities[j], ref copiedEntity4);
				if (copiedEntity4 != null)
				{
					if (marbleItem.ItemEntities.SolidEntity == null)
					{
						marbleItem.ItemEntities.SolidEntity = new List<Entity>();
					}
					copiedEntity4.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Color);
					copiedEntity4.ColorMethod = colorMethodType.byEntity;
					marbleItem.ItemEntities.SolidEntity.Add(copiedEntity4);
				}
			}
			for (int k = 0; k <= marbleItem.ItemEntities.EngravingEntities.Count - 1; k++)
			{
				buEntity buEntity2 = marbleItem.ItemEntities.EngravingEntities[k];
				buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z + marbleItem.BaseHeight);
				buEntity2.Marble = new MarbleInfo();
			}
			if (marbleItem.ItemEntities.SolidEntity != null)
			{
				for (int l = 0; l <= marbleItem.ItemEntities.SolidEntity.Count - 1; l++)
				{
					Entity entity = marbleItem.ItemEntities.SolidEntity[l];
					entity.Translate(refPoint.X, refPoint.Y, refPoint.Z + marbleItem.BaseHeight);
				}
				clsInit.cVector5.BoxSizeCalculate(marbleItem.ItemEntities.SolidEntity, ref marbleItem.SizeItem.MinPoint, ref marbleItem.SizeItem.MidPoint, ref marbleItem.SizeItem.MaxPoint);
				ObjectSize3D.CalculateSize(ref marbleItem.SizeItem);
			}
			if (marbleItem.ItemEntities.SolidEntity != null && marbleItem.BaseHeight > 0.0)
			{
				Entity surfaceEntity = null;
				clsInit.cVector5.surfaceBox(marbleItem.SizeItem.MinPoint, marbleItem.SizeItem.MaxPoint.X - marbleItem.SizeItem.MinPoint.X, marbleItem.SizeItem.MaxPoint.Y - marbleItem.SizeItem.MinPoint.Y, marbleItem.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
				if (surfaceEntity != null)
				{
					buEntity copiedEntity5 = null;
					buEntity.Copy(surfaceEntity, ref copiedEntity5);
					copiedEntity5.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
					marbleItem.ItemEntities.BaseEntities = new List<buEntity>();
					marbleItem.ItemEntities.BaseEntities.Add(copiedEntity5);
				}
			}
			AddOperationBeforeThings();
			doAddItemToJob(marbleItem, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doSawMillingCamAdd(ref MarbleItem Item, MarbleToolType CuttingToolType, MarbleCamType CamType, bool ShowDialog, bool Edit, ref MarbleItemCam marbleCam)
	{
		if (ShowDialog)
		{
			if (buMarbleForms.frmSawMillingCam == null)
			{
				buMarbleForms.frmSawMillingCam = new F_MarbleSawMillingCam();
			}
			buMarbleForms.frmSawMillingCam.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
			buMarbleForms.frmSawMillingCam.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			buMarbleForms.frmSawMillingCam.varSettings = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
			buMarbleForms.frmSawMillingCam.Init(CamType);
			buMarbleForms.frmSawMillingCam.ShowDialog();
			if (buMarbleForms.frmSawMillingCam.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varOperation.settingSawMilling = new marbleSawMillingPars(buMarbleForms.frmSawMillingCam.varSettings);
		}
		AppBool.SaveByTick = true;
		if (marbleCam == null || !Edit)
		{
			marbleCam = new MarbleItemCam();
		}
		if (Item.ItemEntities.EngravingEntities == null)
		{
			Item.ItemEntities.EngravingEntities = new List<buEntity>();
		}
		Item.ItemEntities.EngravingEntities.Clear();
		Item.Settings.settingSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
		buEntity.Copy(Item.ItemEntities.SolidEntity, ref Item.ItemEntities.EngravingEntities);
		marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
		marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
		marbleCam.MeshType = CamTriangularMeshType.ParallelCuts;
		if (!(CamType == MarbleCamType.SawMillingVerticalFinish || CamType == MarbleCamType.SawMillingVerticalRough))
		{
			if (CamType != MarbleCamType.SawMillingHorizontalRough)
			{
				marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingHorizontalFinish.buPar);
				marbleCam.CamMarbleType = CamType;
				marbleCam.CamName = buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.Finish;
				marbleCam.CamType = buClass.CamType.Finish;
				marbleCam.CamMode = MarbleCamMode.Finish;
			}
			else
			{
				marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.buPar);
				marbleCam.CamMarbleType = CamType;
				marbleCam.CamName = buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.Rough;
				marbleCam.CamType = buClass.CamType.Rough;
				marbleCam.CamMode = MarbleCamMode.Rough;
			}
			marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolSaw);
			clsInit.appMarble.doSawMillingHorizontalCamCalc(ref Item, ref marbleCam);
		}
		else
		{
			if (CamType != MarbleCamType.SawMillingVerticalRough)
			{
				marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingVerticalFinish.buPar);
				marbleCam.CamMarbleType = CamType;
				marbleCam.CamName = buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.Finish;
				marbleCam.CamType = buClass.CamType.Finish;
				marbleCam.CamMode = MarbleCamMode.Finish;
			}
			else
			{
				marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingVerticalRough.buPar);
				marbleCam.setCam.Steps.DepthStep = buMarbleForms.frmSawMillingCam.varSettings.SawMillingRoughVerZDownStep;
				marbleCam.CamMarbleType = CamType;
				marbleCam.CamName = buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.Rough;
				marbleCam.CamType = buClass.CamType.Rough;
				marbleCam.CamMode = MarbleCamMode.Rough;
			}
			marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolSaw);
			clsInit.appMarble.doSawMillingVerticalCamCalc(ref Item, ref marbleCam);
		}
		marbleCam.isCamCalculated = true;
		clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
		Item.CamList.Add(marbleCam);
		AddOperationAfterThings();
	}

