							}
							marbleCam.CamBase = new camTp();
							marbleCam.WireEntities = new List<List<buEntity>>();
							marbleCam.WireEntities.Clear();
							if (!flag)
							{
								MeshToSurfacePointsSettings meshToSurfacePointsSettings = new MeshToSurfacePointsSettings();
								meshToSurfacePointsSettings.RotationStep = Item.Settings.settingSawMilling.SawMillingFinishVerAngleStep;
								meshToSurfacePointsSettings.isInside = false;
