								clsInit.cVector5.GetMeshSurfacePointsFromDepth(clsMW.CamEntities, Item.Settings.settingSawMilling.SawMillingFinishVerTopOffset, Item.Settings.settingSawMilling.SawMillingFinishVerBottomOffset, Item.Settings.settingSawMilling.SawMillingFinishVerZDownStep, Plane.XY, meshToSurfacePointsSettings, ref Outside, ref Insides);
