									Point3DList point3DList = new Point3DList();
									int index = Cam.CamPoints[j].Points.Count / 2;
									double z = Cam.CamPoints[j].Points[index].P9.Z;
									for (int k = 0; k <= Cam.CamPoints[j].Points.Count - 1; k++)
									{
										Pnt9D p = Cam.CamPoints[j].Points[k].P9;
										if (buCompare5.EQ(p.Z, z, 0.001))
										{
											point3DList.Points.Add(new Point3D(p.X, p.Y, p.Z));
										}
									}
									if (point3DList.Points.Count <= 0)
									{
										continue;
									}
									if (!clsInit.cVector5.IsClosed(point3DList.Points))
									{
										if (!buCompare5.EQ(point3DList.Points[0], point3DList.Points[point3DList.Points.Count - 2]))
										{
											if (!buCompare5.EQ(point3DList.Points[0], point3DList.Points[point3DList.Points.Count - 3]))
											{
												point3DList.Points.Add(buVector5.ToPoint3D(point3DList.Points[0]));
											}
											else
											{
												point3DList.Points.RemoveAt(point3DList.Points.Count - 1);
												point3DList.Points.RemoveAt(point3DList.Points.Count - 1);
											}
										}
										else
										{
											point3DList.Points.RemoveAt(point3DList.Points.Count - 1);
										}
									}
									list.Add(point3DList);
								}
								new List<Point3D>();
								new List<Point3D>();
