								buMWMarbleVars.varCamMarbleMeshConstantZ.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
								Cam.TypeCam = CamType.ConstantZ;
							}
						}
						if (Result == null || Result.Errors.Count <= 0)
						{
							if (flag)
							{
								buMWMarbleVars.varCamMarbleSawMillingVerticalRough.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleSawMillingVerticalRough.buPar);
