	public void doSawMillingRoughCamAdd(ref MarbleItem Item, MarbleToolType CuttingToolType, MarbleCamType CamType, bool ShowDialog, bool Edit, ref MarbleItemCam marbleCam)
	{
		if (ShowDialog)
		{
			if (buMarbleForms.frmSawMillingRough == null)
			{
				buMarbleForms.frmSawMillingRough = new F_MarbleSawMillingRough();
			}
			buMarbleForms.frmSawMillingRough.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
			buMarbleForms.frmSawMillingRough.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			buMarbleForms.frmSawMillingRough.varSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
			buMarbleForms.frmSawMillingRough.Init();
			buMarbleForms.frmSawMillingRough.ShowDialog();
			if (buMarbleForms.frmSawMillingRough.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varOperation.settingSawMilling = new marbleSawMillingPars(buMarbleForms.frmSawMillingRough.varSawMilling);
			Item.Settings.settingSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
		}
		if (marbleCam == null || !Edit)
		{
			marbleCam = new MarbleItemCam();
		}
		marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
		marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
		if (CamType == MarbleCamType.SawMillingRoughOutside)
		{
			marbleCam.CamName = buLangTranslate.preDef.Saw + " " + buLangTranslate.preDef.Rough + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Rough;
			marbleCam.CamType = buClass.CamType.Rough;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.buPar);
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			if (!Edit)
			{
				Item.CamList.Add(marbleCam);
			}
		}
		doSawMillingRoughtOutsideCamCalc(ref Item, ref marbleCam);
		AddOperationAfterThings();
	}

