						buMarbleForms.frmSawMillingCam.varSettings = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
						buMarbleForms.frmSawMillingCam.Init(CamType);
						buMarbleForms.frmSawMillingCam.ShowDialog();
						if (buMarbleForms.frmSawMillingCam.PropertiesForm.Result != DialogResult.OK)
						{
							return;
						}
						buMarbleCalc.varOperation.settingSawMilling = new marbleSawMillingPars(buMarbleForms.frmSawMillingCam.varSettings);
					}
				}
				else
				{
					if (buMarbleForms.frmCornerCleanBySaw == null)
					{
						buMarbleForms.frmCornerCleanBySaw = new F_MarbleSawCornerClean();
					}
					buMarbleForms.frmCornerCleanBySaw.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
					buMarbleForms.frmCornerCleanBySaw.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
					buMarbleForms.frmCornerCleanBySaw.varSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
					buMarbleForms.frmCornerCleanBySaw.Init(FormStartPosition.Manual);
					buMarbleForms.frmCornerCleanBySaw.ShowDialog();
					if (buMarbleForms.frmCornerCleanBySaw.PropertiesForm.Result != DialogResult.OK)
					{
						return;
					}
					buMarbleCalc.varOperation.settingSawMilling = new marbleSawMillingPars(buMarbleForms.frmCornerCleanBySaw.varSawMilling);
				}
			}
			AppBool.SaveByTick = true;
			if (marbleCam == null || !Edit)
			{
				marbleCam = new MarbleItemCam();
			}
			if (Item.ItemEntities.EngravingEntities == null)
			{
				Item.ItemEntities.EngravingEntities = new List<buEntity>();
			}
			Item.ItemEntities.EngravingEntities.Clear();
			Item.Settings.settingSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
			buEntity.Copy(Item.ItemEntities.SolidEntity, ref Item.ItemEntities.EngravingEntities);
			marbleCam.ToolType = CuttingToolType;
			marbleCam.WireType = CamWireFrameType.None;
			marbleCam.MeshType = CamTriangularMeshType.None;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			if (CamType != MarbleCamType.CornerCleaning)
			{
				if (CamType != MarbleCamType.SawMillingVerticalRough)
				{
					if (CamType == MarbleCamType.SawMillingHorizontalRough)
					{
						marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.buPar);
						marbleCam.CamMarbleType = CamType;
						marbleCam.CamName = buLangTranslate.preDef.Horizontal + " " + buLangTranslate.preDef.Rough;
						marbleCam.CamType = buClass.CamType.Rough;
						marbleCam.CamMode = MarbleCamMode.Rough;
						clsInit.appMarble.doSawMillingHorizontalCamCalc(ref Item, ref marbleCam);
					}
				}
				else
				{
					marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingVerticalRough.buPar);
					marbleCam.CamMarbleType = CamType;
					marbleCam.CamName = buLangTranslate.preDef.Vertical + " " + buLangTranslate.preDef.Rough;
					marbleCam.CamType = buClass.CamType.Rough;
					marbleCam.CamMode = MarbleCamMode.Rough;
					clsInit.appMarble.doSawMillingVerticalCamCalc(ref Item, ref marbleCam);
				}
			}
			else
			{
				marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawCornerCleaning.buPar);
				marbleCam.CamMarbleType = CamType;
				marbleCam.CamName = buLangTranslate.preDef.Corner + " " + buLangTranslate.preDef.Cleaning;
				marbleCam.CamType = buClass.CamType.Rough;
				marbleCam.CamMode = MarbleCamMode.Rough;
				clsInit.appMarble.doCornerCleaningCamCalc(ref Item, ref marbleCam);
			}
			marbleCam.isCamCalculated = true;
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			Item.CamList.Add(marbleCam);
			AddOperationAfterThings();
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

