									buVector5.Copy(OffsetedPoints2[0], ref copiedPoint8, 3);
									Point3DList point3DList6 = new Point3DList();
									point3DList6.Points.AddRange(copiedPoint8);
									PLLFill.Add(point3DList6);
									l = num6;
								}
								copiedPoint2 = new List<Point3D>();
								buVector5.Copy(OffsetedPoints2[0], ref copiedPoint2);
							}
							marbleSawCalcParameters = new MarbleSawCalcParameters();
							marbleSawCalcParameters.DevideLength = 100.0;
							marbleSawCalcParameters.ShiftPoint = new Point3D((MinPoint.X + MaxPoint.X) / 2.0, MinPoint.Y, MinPoint.Z);
							marbleSawCalcParameters.ShiftEnable = false;
							marbleSawCalcParameters.SplineEnable = Item.Settings.settingSawMilling.SawMillingVerCornerSplineEnable;
							if (PLLFill.Count > 0)
