					AppBool.SaveByTick = true;
					if (clsItem.FrmProgress != null)
					{
						clsItem.FrmProgress.Visible = false;
					}
					return 1;
				}
				return -2;
			}
			return -2;
		}
		catch (Exception mSException)
		{
			if (clsItem.FrmProgress != null)
			{
				clsItem.FrmProgress.Visible = false;
			}
