	}

	public void doAddItemMilling5AxisRotary(Point3D refPoint, List<Entity> Entities, bool isCamCalc = false)
	{
		string text = "doAddItemMilling5AxisRotary";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			MarbleItem Item = new MarbleItem();
			Item.ItemEntities.EngravingEntities = new List<buEntity>();
			Item.ItemType = MarbleItemType.Milling5AxisRotary;
			Item.BasePoint = buVector5.ToPoint3D(refPoint);
			Item.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
			for (int i = 0; i <= Entities.Count - 1; i++)
			{
				if (!(Entities[i] is Brep))
				{
					if (!(Entities[i] is Mesh))
					{
						if (Entities[i] is Surface)
						{
							buEntity copiedEntity = null;
							Surface surface = (Surface)Entities[i];
							surface.Regen(0.05);
							Mesh refEntity = surface.ConvertToMesh();
							buEntity.Copy(refEntity, ref copiedEntity);
							Item.ItemEntities.EngravingEntities.Add(copiedEntity);
						}
					}
					else
					{
						buEntity copiedEntity2 = null;
						buEntity.Copy(Entities[i], ref copiedEntity2);
						Item.ItemEntities.EngravingEntities.Add(copiedEntity2);
					}
				}
				else
				{
					buEntity copiedEntity3 = null;
					Brep brep = (Brep)Entities[i];
					brep.Regen(0.05);
					buEntity.Copy(brep.ConvertToMesh(), ref copiedEntity3);
					Item.ItemEntities.EngravingEntities.Add(copiedEntity3);
				}
			}
			for (int j = 0; j <= Entities.Count - 1; j++)
			{
				if (!clsInit.cVector5.isEntitySolid(Entities[j]))
				{
					continue;
				}
				Entity copiedEntity4 = null;
				buEntity.Copy(Entities[j], ref copiedEntity4);
				if (copiedEntity4 != null)
				{
					if (Item.ItemEntities.SolidEntity == null)
					{
						Item.ItemEntities.SolidEntity = new List<Entity>();
					}
					copiedEntity4.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Color);
					copiedEntity4.ColorMethod = colorMethodType.byEntity;
					Item.ItemEntities.SolidEntity.Add(copiedEntity4);
				}
			}
			for (int k = 0; k <= Item.ItemEntities.EngravingEntities.Count - 1; k++)
			{
				buEntity buEntity2 = Item.ItemEntities.EngravingEntities[k];
				buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z + Item.BaseHeight);
				buEntity2.Marble = new MarbleInfo();
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int l = 0; l <= Item.ItemEntities.SolidEntity.Count - 1; l++)
				{
					Entity entity = Item.ItemEntities.SolidEntity[l];
					entity.Translate(refPoint.X, refPoint.Y, refPoint.Z + Item.BaseHeight);
				}
				clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
				ObjectSize3D.CalculateSize(ref Item.SizeItem);
			}
			if (Item.ItemEntities.SolidEntity != null && Item.BaseHeight > 0.0)
			{
				Entity surfaceEntity = null;
				clsInit.cVector5.surfaceBox(Item.SizeItem.MinPoint, Item.SizeItem.MaxPoint.X - Item.SizeItem.MinPoint.X, Item.SizeItem.MaxPoint.Y - Item.SizeItem.MinPoint.Y, Item.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
				if (surfaceEntity != null)
				{
					buEntity copiedEntity5 = null;
					buEntity.Copy(surfaceEntity, ref copiedEntity5);
					copiedEntity5.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
					Item.ItemEntities.BaseEntities = new List<buEntity>();
					Item.ItemEntities.BaseEntities.Add(copiedEntity5);
				}
			}
			for (int m = 0; m <= 1; m++)
			{
				MarbleItemCam marbleCam = new MarbleItemCam();
				marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
				marbleCam.AxesNumber = MarbleTempVars.AxesNumber;
				if (m != 0)
				{
					if (m == 1)
					{
						marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMesh5AxisType2;
					}
				}
				else
				{
					marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMesh5AxisType;
				}
				if (marbleCam.MeshType != CamTriangularMeshType.Rough)
				{
					if (marbleCam.MeshType != CamTriangularMeshType.ParallelCuts)
					{
						if (marbleCam.MeshType == CamTriangularMeshType.ConstantZ)
						{
							doAddItemCommonProps(ref Item);
							marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
							marbleCam.CamType = CamType.ConstantZ;
							marbleCam.CamName = buLangTranslate.preDef.Engraving + " " + buLangTranslate.preDef.ConstantZ + " " + buLangTranslate.preDef.Cut;
							marbleCam.CamMarbleType = MarbleCamType.MillingContantZ3D;
							marbleCam.CamMode = MarbleCamMode.Finish;
						}
					}
					else
					{
						doAddItemCommonProps(ref Item);
						marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshParelelCut.buPar);
						marbleCam.CamType = CamType.ParallelCut;
						marbleCam.CamName = buLangTranslate.preDef.Engraving + " " + buLangTranslate.preDef.ParalelCuts + " " + buLangTranslate.preDef.Cut;
						marbleCam.CamMarbleType = MarbleCamType.MillingParallelCut3D;
						marbleCam.CamMode = MarbleCamMode.Finish;
					}
				}
				else
				{
					doAddItemCommonProps(ref Item);
					marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshRough.buPar);
					marbleCam.CamType = CamType.Rough;
					marbleCam.CamName = buLangTranslate.preDef.Engraving + " " + buLangTranslate.preDef.Rough + " " + buLangTranslate.preDef.Cut;
					marbleCam.CamMarbleType = MarbleCamType.MillingRough3D;
					marbleCam.CamMode = MarbleCamMode.Rough;
				}
				marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
				if ((marbleCam.ToolType == MarbleToolType.Saw) | (marbleCam.ToolType == MarbleToolType.WaterJet))
				{
					marbleCam.ToolType = MarbleToolType.MillingHead;
				}
				marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
				marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
				clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
				if (marbleCam.MeshType != CamTriangularMeshType.None)
				{
					Item.CamList.Add(marbleCam);
				}
				if (!isCamCalc)
				{
					marbleCam.isCamCalculated = false;
					activeJob.CamCalculated = false;
				}
				else
				{
					if (marbleCam.MeshType == CamTriangularMeshType.None)
					{
						continue;
					}
					MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
					mWCalculationOptions.NumberofAxis = 5;
					mWCalculationOptions.CamTriMeshType = marbleCam.MeshType;
					mWCalculationOptions.Mode = CamMode.TriangularMesh5AX;
					mWCalculationOptions.DontApplyReset = true;
					mWCalculationOptions.isBuWireframeCalculation = false;
					mWCalculationOptions.AddToCamListInLocalCalculation = false;
					mWCalculationOptions.ShowLeadInOutPage = false;
					mWCalculationOptions.DontShowDialogBox = true;
					mWCalculationOptions.DontShowbuDialogBox = true;
					if ((Item.ItemType == MarbleItemType.Milling5AxisRotary) & (marbleCam.CamType == CamType.Rough))
					{
						if (marbleCam.AxesNumber == 3)
						{
							doMilling3AxisRotaryCamCalc(mWCalculationOptions, Item, ref marbleCam);
						}
						if (marbleCam.AxesNumber == 4)
						{
							doMilling4AxisRotaryCamCalc(mWCalculationOptions, Item, ref marbleCam);
						}
					}
					marbleCam.isCamCalculated = true;
				}
			}
			AddOperationBeforeThings();
			Item.ID = MarbleTempVars.ItemID;
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
			if (buMarbleCalc.varMarbleSettings.AutoMagnet)
			{
				doAlignment(MarbleCadCamCommands.MagnetLeftDown, 0.0);
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public int doMilling3AxisRotaryCamCalc(MWCalculationOptions MWCalcoptions, MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doMilling3AxisRotaryCamCalc";
		try
		{
			clsMW.Containment2DEntities.Clear();
			if (Item.ItemEntities.EngravingEntities != null)
			{
				if (Item.ItemEntities.EngravingEntities.Count != 0)
				{
					camTp camTp2 = null;
					clsMW.CamEntities.Clear();
					clsMW.CamEntities = new List<Entity>();
					Point3D MinPoint = new Point3D();
					Point3D MaxPoint = new Point3D();
					clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.EngravingEntities, ref MinPoint, ref MaxPoint);
					List<List<Entity>> list = new List<List<Entity>>();
					List<Entity> list2 = new List<Entity>();
					MWCalcoptions.CamTriMesh5AXType = CamTriangularMesh5AxType.Rough;
					MWCalcoptions.CamTriMeshType = CamTriangularMeshType.Rough;
					for (int i = 0; i <= Item.ItemEntities.EngravingEntities.Count - 1; i++)
					{
						Entity copiedEntity = null;
						buEntity.Copy(Item.ItemEntities.EngravingEntities[i], ref copiedEntity);
						clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref copiedEntity);
						list2.Add(copiedEntity);
					}
					list.Add(list2);
					list2 = new List<Entity>();
					for (int j = 0; j <= Item.ItemEntities.EngravingEntities.Count - 1; j++)
					{
						Entity copiedEntity2 = null;
						buEntity.Copy(Item.ItemEntities.EngravingEntities[j], ref copiedEntity2);
						clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisX, ref copiedEntity2);
						list2.Add(copiedEntity2);
					}
					list.Add(list2);
					Point3D MinPoint2 = new Point3D();
					Point3D MidPoint = new Point3D();
					Point3D MaxPoint2 = new Point3D();
					clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint2, ref MidPoint, ref MaxPoint2);
					double num = MaxPoint2.Z - MidPoint.Z;
					double safe = buMWMarbleVars.varCamMarbleMeshRough.buPar.Distances.Safe;
					if (marbleCam.setCam.Distances.Safe < MaxPoint2.Z)
					{
						marbleCam.setCam.Distances.Safe = num + buMWMarbleVars.varCamMarbleMeshRough.buPar.Distances.Rapid;
					}
					if (list.Count != 0)
					{
						marbleCam.setCam.Steps.DepthStepMode = CamStepDepthMode.ConstantDepthStep;
						marbleCam.setCam.Steps.StartValue = MaxPoint2.Z;
						marbleCam.setCam.Steps.EndValue = MidPoint.Z - 1.0;
						MWCalcoptions.NumberofAxis = 3;
						if (marbleCam.CamType == CamType.Rough)
						{
							clsMW.varMWCamMeshRoughPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshRough.mwPar, marbleCam.setCam, out clsMW.varbuCamMeshRoughPars);
							clsMW.varMWCamMeshRoughPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshRoughPars, marbleCam.setCam);
							clsMW.varMWCamMeshRoughPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
							clsMW.varMWCamMeshRoughPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshRoughPars.Pockets.StepOverPersentage / 100.0;
						}
						if (marbleCam.CamType == CamType.ParallelCut)
						{
							clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshParelelCut.mwPar, marbleCam.setCam, out clsMW.varbuCamMeshParallelPars);
							clsMW.varMWCamMeshParalelPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshParalelPars, marbleCam.setCam);
							clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
							clsMW.varMWCamMeshParalelPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshRoughPars.Pockets.StepOverPersentage / 100.0;
						}
						camResult Result = null;
						if (list.Count > 0)
						{
							for (int k = 0; k <= list.Count - 1; k++)
							{
								clsMW.CamEntities.Clear();
								clsMW.CamEntities.AddRange(list[k]);
								clsInit.cVector5.BoxSizeCalculate(clsMW.CamEntities, ref MinPoint2, ref MidPoint, ref MaxPoint2);
								marbleCam.setCam.Steps.StartValue = MaxPoint2.Z + 5.0;
								marbleCam.setCam.Steps.EndValue = MidPoint.Z - 5.0;
								if (marbleCam.setCam.Distances.Safe < MinPoint2.Z)
								{
									marbleCam.setCam.Distances.Safe = num + buMWMarbleVars.varCamMarbleMeshRough.buPar.Distances.Rapid;
								}
								marbleCam.setCam.Distances.Safe = MaxPoint2.Z + buMWMarbleVars.varCamMarbleMeshRough.buPar.Distances.Rapid;
								camTp2 = new camTp();
								if (marbleCam.CamType == CamType.Rough)
								{
									MWCalcoptions.CamTriMeshType = CamTriangularMeshType.Rough;
									clsMW.varMWCamMeshRoughPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshRoughPars, marbleCam.setCam);
									clsInit.appMW.doTriangularMesh3D(MWCalcoptions, marbleCam.ToolSelected, ref camTp2, ref Result);
								}
								if (marbleCam.CamType == CamType.ParallelCut)
								{
									MWCalcoptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
									clsMW.varMWCamMeshParalelPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshParalelPars, marbleCam.setCam);
									clsInit.appMW.doTriangularMesh3D(MWCalcoptions, marbleCam.ToolSelected, ref camTp2, ref Result);
								}
								if (Result == null || Result.Errors.Count <= 0)
								{
									double num2 = -90.0;
									if (k == 1)
									{
										num2 = 90.0;
									}
									for (int l = 0; l <= camTp2.CamPoints.Count - 1; l++)
									{
										for (int m = 0; m <= camTp2.CamPoints[l].Points.Count - 1; m++)
										{
											TpPnt9D Points = camTp2.CamPoints[l].Points[m];
											clsInit.cVector5.Rotate(new Point3D(), num2, Plane.YZ, ref Points);
											if (k != 0)
											{
												double num3 = 0.0 - activeKinematic.RotateCenterOffsetOfC.Y + (activeKinematic.RotateCenterOffsetOfA.Y + marbleCam.ToolSelected.Geometry.Length - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingHeadToolYOffset);
												Points.P9.Y = Points.P9.Y - num3;
											}
											else
											{
												Points.P9.Y = Points.P9.Y + (activeKinematic.RotateCenterOffsetOfA.Y + marbleCam.ToolSelected.Geometry.Length - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingHeadToolYOffset);
											}
											Points.P9.Z = Points.P9.Z - (activeKinematic.RotateCenterOffsetOfA.Y + marbleCam.ToolSelected.Geometry.Length - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingHeadToolYOffset) + activeKinematic.RotateCenterOffsetOfA.Z;
											Points.P9.A = 0.0;
											if (k == 1)
											{
												Points.P9.C = 180.0;
											}
										}
									}
									clsInit.cVector5.Rotate(new Point3D(), num2, Vector3D.AxisX, ref camTp2.EntitiesG1);
									clsInit.cVector5.Rotate(new Point3D(), num2, Vector3D.AxisX, ref camTp2.EntitiesG0);
									clsInit.cVector5.Rotate(new Point3D(), num2, Vector3D.AxisX, ref camTp2.EntitiesLeave);
									clsInit.cVector5.Rotate(new Point3D(), num2, Vector3D.AxisX, ref camTp2.EntitiesPlunge);
									camTp2.Mode = MWCalcoptions.Mode;
									camTp2.CamWireframeType = MWCalcoptions.CamWireframeType;
									camTp2.CamTriMeshType = MWCalcoptions.CamTriMeshType;
									camTp2.NumberOfAxis = MWCalcoptions.NumberofAxis;
									camTp2.Tool = new ToolBase5(marbleCam.ToolSelected);
									camTp2.TypeCam = CamType.Rough;
									if (k != 0)
									{
										marbleCam.CamBase.EntitiesG1.AddRange(camTp2.EntitiesG1);
										marbleCam.CamBase.EntitiesG0.AddRange(camTp2.EntitiesG0);
										marbleCam.CamBase.EntitiesLeave.AddRange(camTp2.EntitiesLeave);
										marbleCam.CamBase.EntitiesPlunge.AddRange(camTp2.EntitiesPlunge);
										for (int n = 0; n <= camTp2.CamPoints.Count - 1; n++)
										{
											marbleCam.CamBase.CamPoints.Add(camTp2.CamPoints[n]);
										}
									}
									else
									{
										marbleCam.CamBase = new camTp(camTp2);
										camTpPoint camTpPoint2 = camTp2.CamPoints[camTp2.CamPoints.Count - 1];
										TpPnt9D tpPnt9D = new TpPnt9D(camTpPoint2.Points[camTpPoint2.Points.Count - 1]);
										tpPnt9D.P9.Z = tpPnt9D.P9.Z + MaxPoint.Z;
										camTpPoint2.Points.Add(tpPnt9D);
									}
									continue;
								}
								F_ErrorList f_ErrorList = new F_ErrorList();
								f_ErrorList.Init(Result.Errors);
								f_ErrorList.ShowDialog();
								clsInit.appCommand.Reset();
								return -2;
							}
						}
						if (marbleCam.CamType == CamType.Rough)
						{
							buMWMarbleVars.varCamMarbleMeshRough.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshRoughPars, clsMW.varbuCamMeshRoughPars, out buMWMarbleVars.varCamMarbleMeshRough.buPar);
							buMWMarbleVars.varCamMarbleMeshRough.buPar.Distances.Safe = safe;
						}
						if (marbleCam.CamType == CamType.ParallelCut)
						{
							buMWMarbleVars.varCamMarbleMeshParelelCut.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshParalelPars, clsMW.varbuCamMeshParallelPars, out buMWMarbleVars.varCamMarbleMeshParelelCut.buPar);
							buMWMarbleVars.varCamMarbleMeshParelelCut.buPar.Distances.Safe = safe;
						}
						marbleCam.isCamCalculated = true;
						marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
						if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.MillingHead)
						{
							Item.ToolType = MarbleToolType.Milling;
						}
						else
						{
							Item.ToolType = MarbleToolType.MillingHead;
						}
						AppBool.SaveByTick = true;
						return 1;
					}
					return -2;
				}
				return -2;
			}
			return -2;
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
			return -1;
		}
	}

	public int doMilling4AxisRotaryCamCalc(MWCalculationOptions MWCalcoptions, MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doMilling4AxisRotaryCamCalc";
		try
		{
			clsMW.Containment2DEntities.Clear();
			if (Item.ItemEntities.EngravingEntities != null)
			{
				if (Item.ItemEntities.EngravingEntities.Count != 0)
				{
					camTp camTp2 = null;
					clsMW.CamEntities.Clear();
					clsMW.CamEntities = new List<Entity>();
					Point3D MinPoint = new Point3D();
					Point3D MaxPoint = new Point3D();
					clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.EngravingEntities, ref MinPoint, ref MaxPoint);
					List<List<Entity>> list = new List<List<Entity>>();
					List<Entity> list2 = new List<Entity>();
					MWCalcoptions.CamTriMesh5AXType = CamTriangularMesh5AxType.Rough;
					MWCalcoptions.CamTriMeshType = CamTriangularMeshType.Rough;
					for (int i = 0; i <= Item.ItemEntities.EngravingEntities.Count - 1; i++)
					{
						Entity copiedEntity = null;
						buEntity.Copy(Item.ItemEntities.EngravingEntities[i], ref copiedEntity);
						list2.Add(copiedEntity);
					}
					list.Add(list2);
					if (list.Count != 0)
					{
						MWCalcoptions.NumberofAxis = 4;
						if (marbleCam.CamType == CamType.ConstantZ)
						{
							marbleCam.setCam.Steps.DepthStep = marbleCam.ToolSelected.Geometry.Diameter / 2.0;
							clsMW.varMWCamMeshContantZPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshConstantZ.mwPar, marbleCam.setCam, out clsMW.varbuCamMeshConstantZPars);
							clsMW.varMWCamMeshContantZPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshContantZPars, marbleCam.setCam);
							clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.UndercutsFlg = false;
							clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
							clsMW.varMWCamMeshContantZPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshConstantZPars.Pockets.StepOverPersentage / 100.0;
							clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SharedMiscParams.MaintainCuttingDirectionForClosedCutsFlg = false;
						}
						if (marbleCam.CamType == CamType.ParallelCut)
						{
							clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshParelelCut.mwPar, marbleCam.setCam, out clsMW.varbuCamMeshParallelPars);
							clsMW.varMWCamMeshParalelPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshParalelPars, marbleCam.setCam);
							clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.UndercutsFlg = false;
							clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
							clsMW.varMWCamMeshParalelPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshParallelPars.Pockets.StepOverPersentage / 100.0;
						}
						camResult Result = null;
						marbleCam.ToolSelected.Geometry.GeometryType = buClass.ToolType.Sphere;
						if (list.Count > 0)
						{
							for (int j = 0; j <= list.Count - 1; j++)
							{
								clsMW.CamEntities.Clear();
								clsMW.CamEntities.AddRange(list[j]);
								marbleCam.setCam.Steps.StartValue = MaxPoint.Z + 5.0;
								marbleCam.setCam.Steps.EndValue = MinPoint.Z - 5.0;
								marbleCam.setCam.Distances.Safe = MaxPoint.Z + buMWMarbleVars.varCamMarbleMeshConstantZ.buPar.Distances.Rapid;
								camTp2 = new camTp();
								if (marbleCam.CamType == CamType.ParallelCut)
								{
									MWCalcoptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
									clsMW.varMWCamMeshParalelPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshParalelPars, marbleCam.setCam);
									clsInit.appMW.doTriangularMesh3D(MWCalcoptions, marbleCam.ToolSelected, ref camTp2, ref Result);
								}
								if (marbleCam.CamType == CamType.ConstantZ)
								{
									MWCalcoptions.CamTriMeshType = CamTriangularMeshType.ConstantZ;
									clsMW.varMWCamMeshContantZPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshContantZPars, marbleCam.setCam);
									clsInit.appMW.doTriangularMesh3D(MWCalcoptions, marbleCam.ToolSelected, ref camTp2, ref Result);
								}
								if (Result == null || Result.Errors.Count <= 0)
								{
									camTp2.Mode = MWCalcoptions.Mode;
									camTp2.CamWireframeType = MWCalcoptions.CamWireframeType;
									camTp2.CamTriMeshType = MWCalcoptions.CamTriMeshType;
									camTp2.NumberOfAxis = MWCalcoptions.NumberofAxis;
									camTp2.Tool = new ToolBase5(marbleCam.ToolSelected);
									camTp2.TypeCam = CamType.Rough;
									for (int k = 0; k <= camTp2.CamPoints.Count - 1; k++)
									{
										for (int l = 0; l <= camTp2.CamPoints[k].Points.Count - 1; l++)
										{
											TpPnt9D tpPnt9D = camTp2.CamPoints[k].Points[l];
											tpPnt9D.P9.C = clsInit.cVector5.PointAngle(new Point3D(tpPnt9D.P9.A, tpPnt9D.P9.B, 0.0), new Point3D()) - 90.0;
											double num = activeKinematic.RotateCenterOffsetOfA.Y + marbleCam.ToolSelected.Geometry.Length - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingHeadToolYOffset;
											num -= activeKinematic.RotateCenterOffsetOfA.Y - activeKinematic.RotateCenterOffsetOfC.Y;
											double num2 = num * Math.Cos(buConversion5.DegreeToRadian(tpPnt9D.P9.C + 90.0));
											double num3 = num * Math.Sin(buConversion5.DegreeToRadian(tpPnt9D.P9.C + 90.0));
											tpPnt9D.P9.X = tpPnt9D.P9.X + num2;
											tpPnt9D.P9.Y = tpPnt9D.P9.Y + num3;
											tpPnt9D.P9.Z = tpPnt9D.P9.Z - (activeKinematic.RotateCenterOffsetOfA.Y + marbleCam.ToolSelected.Geometry.Length - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingHeadToolYOffset) + activeKinematic.RotateCenterOffsetOfA.Z;
											tpPnt9D.P9.A = 0.0;
										}
									}
									if (j == 0)
									{
										marbleCam.CamBase = new camTp(camTp2);
									}
									continue;
								}
								F_ErrorList f_ErrorList = new F_ErrorList();
								f_ErrorList.Init(Result.Errors);
								f_ErrorList.ShowDialog();
								clsInit.appCommand.Reset();
								return -2;
							}
						}
						if (marbleCam.CamType == CamType.ParallelCut)
						{
							buMWMarbleVars.varCamMarbleMeshParelelCut.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshParalelPars, clsMW.varbuCamMeshParallelPars, out buMWMarbleVars.varCamMarbleMeshParelelCut.buPar);
						}
						if (marbleCam.CamType == CamType.ConstantZ)
						{
							buMWMarbleVars.varCamMarbleMeshConstantZ.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
						}
						marbleCam.isCamCalculated = true;
						marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
						if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.MillingHead)
						{
							Item.ToolType = MarbleToolType.Milling;
						}
						else
						{
							Item.ToolType = MarbleToolType.MillingHead;
						}
						AppBool.SaveByTick = true;
						return 1;
					}
					return -2;
				}
				return -2;
			}
			return -2;
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
			return -1;
		}
	}

