						clsMW.varMWCamMeshRoughPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshRoughPars.Pockets.StepOverPersentage / 100.0;
						clsMW.varMWCamMeshContantZPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshConstantZPars.Pockets.StepOverPersentage / 100.0;
						clsMW.varMWCamMeshPencilPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshPencilPars.Pockets.StepOverPersentage / 100.0;
						clsMW.varMWCamMeshFlatlandPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshFlatlandsPars.Pockets.StepOverPersentage / 100.0;
