							double num2 = 0.0;
							marbleCam.CamBase = new camTp(Cam);
							for (int l = 0; l <= marbleCam.CamBase.CamPoints.Count - 1; l++)
							{
								for (int m = 0; m <= marbleCam.CamBase.CamPoints[l].Points.Count - 1; m++)
