									double double_2 = 0.0;
									IJK ijk = new IJK(tpPnt9D.P9.A, tpPnt9D.P9.B, tpPnt9D.P9.C);
									Point3D movePoint = new Point3D(tpPnt9D.P9.X, tpPnt9D.P9.Y, tpPnt9D.P9.Z);
									Pnt6D CalcPoint = new Pnt6D();
									double a = tpPnt9D.P9.A;
									double b = tpPnt9D.P9.B;
									double c = tpPnt9D.P9.C;
									Class5.smethod_185(ref double_, b, ref double_2, a, c);
									OrientationAngle orientation = new OrientationAngle(0.0, double_, double_2);
									clsInit.cKinematic5.ForwardKinematix5AxMilling(marbleCam.CamBase.Tool.Geometry.Length, ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Y - ccVars.KinematicOrjinal.RotateCenterOffsetOfC.Y, ijk, orientation, movePoint, ref CalcPoint);
									tpPnt9D.P9.X = CalcPoint.X;
									tpPnt9D.P9.Y = CalcPoint.Y;
									tpPnt9D.P9.Z = CalcPoint.Z;
									tpPnt9D.P9.B = CalcPoint.A;
									tpPnt9D.P9.A = 90.0 - CalcPoint.B;
									tpPnt9D.P9.C = CalcPoint.C - 90.0;
									if (num > 0)
									{
										double num3 = num2 - tpPnt9D.P9.C;
										if (num3 > 180.0 || num3 < -180.0)
										{
											if (!(num3 < 0.0))
											{
												tpPnt9D.P9.C += 360.0;
											}
											else
											{
												tpPnt9D.P9.C -= 360.0;
											}
										}
									}
									num2 = tpPnt9D.P9.C;
									num++;
								}
							}
						}
						else
						{
							marbleCam.CamBase = new camTp(Cam);
						}
						marbleCam.isCamCalculated = true;
						new marbleMillingAnalyzePars();
						marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
						if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.MillingHead)
						{
							Item.ToolType = MarbleToolType.Milling;
						}
						else
						{
							Item.ToolType = MarbleToolType.MillingHead;
						}
						AppBool.SaveByTick = true;
						return 1;
					}
