	public void doAddItemSweep(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
	{
		string text = "doAddItemSweep";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (entitiesForSweep.Count == 0)
			{
				return;
			}
			MarbleItem Item = new MarbleItem();
			Item.ItemEntities.DrawWireEntities = new List<buEntity>();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Entity entSurface = null;
			Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			doSweepCut(entitiesForSweep[0], isFinsihed, ref entSurface, ref Item);
			Item.ItemType = MarbleItemType.Sweep;
			Item.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			Item.BaseHeight = 0.0;
			Item.BasePoint = buVector5.ToPoint3D(refPoint);
			if (!isFinsihed)
			{
				MarbleTempVars.ItemsSweep.Add(Item);
				return;
			}
			doAddItemCommonProps(ref Item);
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int i = 0; i <= Item.ItemEntities.SolidEntity.Count - 1; i++)
				{
					Item.ItemEntities.SolidEntity[i].Translate(refPoint.X, refPoint.Y, refPoint.Z);
				}
			}
			for (int j = 0; j <= Item.ItemEntities.DrawWireEntities.Count - 1; j++)
			{
				buEntity buEntity2 = Item.ItemEntities.DrawWireEntities[j];
				buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z);
			}
			for (int k = 0; k <= Item.ItemEntities.SourceEntities.Count - 1; k++)
			{
				buEntity buEntity3 = Item.ItemEntities.SourceEntities[k];
				buEntity3.Translate(refPoint.X, refPoint.Y, refPoint.Z);
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
				ObjectSize3D.CalculateSize(ref Item.SizeItem);
			}
			MarbleItemCam marbleCam = new MarbleItemCam();
			marbleCam.CamName = buLangTranslate.preDef.Sweep + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = MarbleCamType.Sweep;
			marbleCam.CamMode = MarbleCamMode.Contour;
			marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
			marbleCam.CamType = CamType.Contour;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSweep.buPar);
			marbleCam.isRough = false;
			marbleCam.isFinish = true;
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			Item.CamList.Add(marbleCam);
			if (isCamCalc)
			{
				doSweepCamCalc(ref Item, ref marbleCam);
			}
			marbleCam.isCamCalculated = isCamCalc;
			AddOperationBeforeThings();
			Item.ID = MarbleTempVars.ItemID;
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doSweepCut(List<buEntity> refEntities, bool isFinished, ref Entity entSurface, ref MarbleItem Item)
	{
		string text = "doSweepCut";
		try
		{
			buEntity SweepEntity = new buEntity();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Item.ItemEntities.DrawWireEntities = new List<buEntity>();
			if (MarbleTempVars.SweepZFormEntities == null || !((Item.Settings.settingSweepCut.SawRampType == CamZRampType.FromFile) & (MarbleTempVars.SweepZFormEntities.Count > 0)))
			{
				clsInit.cVector5.EntitiesToSweep(refEntities, buMarbleCalc.varOperation.settingSweepCut.SweepRampHeight, buMarbleCalc.varOperation.settingSweepCut.SweepRampWidth, buMarbleCalc.varOperation.settingSweepCut.SweepTargetZ, buMarbleCalc.varOperation.settingSweepCut.SawRampType, ref SweepEntity, buMarbleCalc.varOperation.settingSweepCut.SweepResolution);
			}
			else
			{
				List<Point3D> Points = new List<Point3D>();
				for (int i = 0; i <= refEntities.Count - 1; i++)
				{
					List<Point3D> pntDevided = new List<Point3D>();
					clsInit.cVector5.EntityDevideByCamDir(refEntities[i], 1.0, ref pntDevided);
					Points.AddRange(pntDevided);
				}
				clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points);
				if (Points.Count > 2)
				{
					double Length = 0.0;
					clsInit.cVector5.EntitiesLength(MarbleTempVars.SweepZFormEntities, ref Length);
					double devideLength = Length / (double)Points.Count;
					List<Point3D> Points2 = new List<Point3D>();
					Point3D MinPoint = new Point3D();
					Point3D MaxPoint = new Point3D();
					clsInit.cVector5.BoxSizeCalculate(MarbleTempVars.SweepZFormEntities, ref MinPoint, ref MaxPoint);
					clsInit.cVector5.Move(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref MarbleTempVars.SweepZFormEntities);
					SortbuSettings sortbuSettings = new SortbuSettings();
					sortbuSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
					List<buEntity> SortedEntities = new List<buEntity>();
					clsInit.cVector5.SortEntitiesByRefPoint(new Point3D(), ref MarbleTempVars.SweepZFormEntities, sortbuSettings, ref SortedEntities);
					for (int j = 0; j <= SortedEntities.Count - 1; j++)
					{
						List<Point3D> pntDevided2 = new List<Point3D>();
						clsInit.cVector5.EntityDevide(SortedEntities[j], devideLength, ref pntDevided2);
						if (SortedEntities[j].sortDirection == entitySortDirection.Reverse)
						{
							pntDevided2.Reverse();
						}
						Points2.AddRange(pntDevided2);
					}
					clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points2);
					if (Points2.Count > 0)
					{
						if (Points2.Count <= Points.Count)
						{
							if (Points2.Count < Points.Count)
							{
							}
						}
						else
						{
							int num = Points2.Count - Points.Count;
							int num2 = Convert.ToInt32((double)Points2.Count / ((double)num + 1.0));
							for (int num3 = num; num3 >= 1; num3--)
							{
								int num4 = num3 * num2;
								if ((num4 >= 0) & (num4 <= Points2.Count - 1))
								{
									Points2.RemoveAt(num4);
								}
							}
						}
						if (Points2.Count == Points.Count)
						{
							for (int k = 0; k <= Points.Count - 1; k++)
							{
								Points[k].Z = Points2[k].Y;
							}
						}
						if (Points.Count > 0)
						{
							SweepEntity = new buLinearPath(Points);
						}
					}
				}
			}
			if (!((Item.Settings.settingSweepCut.SweepWidth == 0.0) | (Item.Settings.settingSweepCut.SweepWidth < Item.Settings.settingSweepCut.SweepYStep)))
			{
				double num5 = buNumeric5.RoundToUpper(Item.Settings.settingSweepCut.SweepWidth / Item.Settings.settingSweepCut.SweepYStep);
				double num6 = Item.Settings.settingSweepCut.SweepWidth / num5;
				for (double num7 = 0.0; num7 <= num5 - 1.0; num7 += 1.0)
				{
					buEntity copiedEntity = null;
					buEntity.Copy(SweepEntity, ref copiedEntity);
					copiedEntity.Translate(0.0, num7 * num6, 0.0);
					Item.ItemEntities.SourceEntities.Add(copiedEntity);
					if (copiedEntity is buLinearPath)
					{
						Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity));
					}
				}
				if (!isFinished)
				{
					return;
				}
				List<Point3D> copiedPoint = new List<Point3D>();
				List<Point3D> copiedPoint2 = new List<Point3D>();
				if (Item.ItemEntities.SourceEntities.Count >= 2)
				{
					buVector5.Copy(Item.ItemEntities.SourceEntities[0].Vertices, ref copiedPoint);
					buVector5.Copy(Item.ItemEntities.SourceEntities[Item.ItemEntities.SourceEntities.Count - 1].Vertices, ref copiedPoint2);
					new List<Point3D>();
					List<ICurve> list = new List<ICurve>();
					list.Add(new LinearPath(copiedPoint));
					list.Add(new LinearPath(copiedPoint2));
					Surface[] array = Surface.Loft(list, 2);
					if (array.Length != 0)
					{
						entSurface = array[0].ConvertToMesh(0.2);
						entSurface.EntityData = new CustomData();
						Item.ItemEntities.SolidEntity = new List<Entity>();
						entSurface.ColorMethod = colorMethodType.byEntity;
						entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSweep.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSweep.Color);
						Item.ItemEntities.SolidEntity.Add(entSurface);
					}
				}
				return;
			}
			Item.ItemEntities.SourceEntities.Add(SweepEntity);
			if (SweepEntity is buLinearPath)
			{
				List<Point3D> list2 = new List<Point3D>();
				for (int l = 0; l <= SweepEntity.Vertices.Count - 1; l++)
				{
					list2.Add(new Point3D(SweepEntity.Vertices[l].X, SweepEntity.Vertices[l].Y, 0.0));
				}
				if (isFinished)
				{
					LinearPath linearPath = new LinearPath(list2);
					Mesh mesh = linearPath.Inflate(20.0, 20.0, Utility.DegToRad(30.0), 80.0);
					entSurface = mesh;
					entSurface.EntityData = new CustomData();
					Item.ItemEntities.SolidEntity = new List<Entity>();
					entSurface.ColorMethod = colorMethodType.byEntity;
					entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSweep.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSweep.Color);
					Item.ItemEntities.SolidEntity.Add(entSurface);
					Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(SweepEntity));
				}
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doSweepCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doSweepCamCalc";
		try
		{
			clsMW.Containment2DEntities.Clear();
			Item.Settings.settingMarbleCam.UseCZero = false;
			if (marbleCam.ToolType != MarbleToolType.Saw)
			{
				marbleCam.WireType = CamWireFrameType.Profile3Axis;
				MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
				mWCalculationOptions.NumberofAxis = 3;
				mWCalculationOptions.CamWireframeType = marbleCam.WireType;
				mWCalculationOptions.CamTriMeshType = marbleCam.MeshType;
				mWCalculationOptions.Mode = CamMode.WireFrame;
				mWCalculationOptions.DontApplyReset = true;
				mWCalculationOptions.isBuWireframeCalculation = false;
				mWCalculationOptions.AddToCamListInLocalCalculation = false;
				mWCalculationOptions.ShowLeadInOutPage = false;
				mWCalculationOptions.DontShowDialogBox = true;
				clsMW.CamEntities.Clear();
				clsMW.CamEntities = new List<Entity>();
				for (int i = 0; i <= Item.ItemEntities.SourceEntities.Count - 1; i++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(Item.ItemEntities.SourceEntities[i], ref copiedEntity);
					clsMW.CamEntities.Add(copiedEntity);
				}
				if (clsMW.CamEntities.Count > 0)
				{
					clsMW.varbuCamWFProfile3AxisPars.Distances.Safe = Item.Settings.settingSweepCut.SafeDistance;
					ToolBase5 toolBase = null;
					toolBase = ((marbleCam.ToolType == MarbleToolType.Milling) ? new ToolBase5(buMarbleCalc.activeToolMilling) : ((marbleCam.ToolType == MarbleToolType.MillingHead) ? new ToolBase5(buMarbleCalc.activeToolMillingHead) : new ToolBase5(marbleCam.ToolSelected)));
					marbleCam.CamBase = null;
					doWireframeCamCalc(mWCalculationOptions, ref marbleCam, toolBase, ref marbleCam.CamBase);
					if (marbleCam.CamBase != null)
					{
						marbleCam.CamBase.OperationData = new MarbleItemSettings(Item.Settings);
						marbleCam.CamBase.TypeCam = CamType.MillingCut;
						marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
					}
					marbleMillingAnalyzePars analyzeSet = new marbleMillingAnalyzePars();
					AnalyzeMillingCam(analyzeSet, ref marbleCam.CamBase);
					marbleCam.isCamCalculated = true;
				}
			}
			else
			{
				Item.Settings.settingMarbleCam.UseTangentLimit = true;
				Item.Settings.settingMarbleCam.AngleCMax = buMarbleCalc.varOperation.settingMarbleCam.AngleCMax;
				Item.Settings.settingMarbleCam.AngleCMin = buMarbleCalc.varOperation.settingMarbleCam.AngleCMin;
				Item.Settings.settingMarbleCam.OffsetAngleC = Item.Settings.settingSweepCut.SweepFollowOffset;
				Item.Settings.settingMarbleCam.DontCheckZValues = true;
				if (Item.ItemEntities.SourceEntities.Count > 0)
				{
					marbleCam.WireEntities = new List<List<buEntity>>();
					Item.ItemEntities.WireEntities = new List<List<buEntity>>();
					for (int j = 0; j <= Item.ItemEntities.SourceEntities.Count - 1; j++)
					{
						List<buEntity> list = new List<buEntity>();
						buEntity copiedEntity2 = null;
						buEntity.Copy(Item.ItemEntities.SourceEntities[j], ref copiedEntity2);
						list.Add(copiedEntity2);
						marbleCam.WireEntities.Add(list);
					}
				}
				clsInit.cMarble.CalculateMarbleWireFrameWithSaw(activeKinematic, marbleCam.ToolSelected, activeJob, 0, isLast: true, null, ref Item, ref marbleCam);
				if (marbleCam.CamBase != null)
				{
					camTp camTp2 = marbleCam.CamBase;
					camTp2.CamID = Item.ID;
					camTp2.OperationData = new MarbleItemSettings(Item.Settings);
					camTp2.TypeCam = CamType.SawCut;
					camTp2.AxisCount = 5;
					camTp2.Explanation = buLangTranslate.preDef.Contour + " " + buLangTranslate.preDef.Cutting;
					camTp2.Parameter = new camParameters5(marbleCam.setCam);
					marbleCam.isCamCalculated = true;
				}
			}
			doCamPointsOffsets(ref marbleCam);
			AppBool.SaveByTick = true;
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItemCavity(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
	{
		string text = "doAddItemCavity";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (entitiesForCavity.Count == 0)
			{
				return;
			}
			MarbleItem Item = new MarbleItem();
			Item.ItemEntities.DrawWireEntities = new List<buEntity>();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Entity entSurface = null;
			Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			doCavityCut(entitiesForCavity, isFinsihed, ref entSurface, ref Item);
			Item.ItemType = MarbleItemType.Cavity;
			Item.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			Item.BaseHeight = 0.0;
			Item.BasePoint = buVector5.ToPoint3D(refPoint);
			if (!isFinsihed)
			{
				MarbleTempVars.ItemsCavity.Add(Item);
				return;
			}
			doAddItemCommonProps(ref Item);
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int i = 0; i <= Item.ItemEntities.SolidEntity.Count - 1; i++)
				{
					Item.ItemEntities.SolidEntity[i].Translate(refPoint.X, refPoint.Y, refPoint.Z);
				}
			}
			for (int j = 0; j <= Item.ItemEntities.DrawWireEntities.Count - 1; j++)
			{
				buEntity buEntity2 = Item.ItemEntities.DrawWireEntities[j];
				buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z);
			}
			for (int k = 0; k <= Item.ItemEntities.SourceEntities.Count - 1; k++)
			{
				buEntity buEntity3 = Item.ItemEntities.SourceEntities[k];
				buEntity3.Translate(refPoint.X, refPoint.Y, refPoint.Z);
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
				ObjectSize3D.CalculateSize(ref Item.SizeItem);
			}
			MarbleItemCam marbleCam = new MarbleItemCam();
			marbleCam.CamName = buLangTranslate.preDef.Cavity + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = MarbleCamType.Cavity;
			marbleCam.CamMode = MarbleCamMode.Contour;
			marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
			marbleCam.CamType = CamType.Contour;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSweep.buPar);
			marbleCam.isRough = false;
			marbleCam.isFinish = true;
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			Item.CamList.Add(marbleCam);
			if (isCamCalc)
			{
				doCavityCamCalc(ref Item, ref marbleCam);
			}
			marbleCam.isCamCalculated = isCamCalc;
			AddOperationBeforeThings();
			Item.ID = MarbleTempVars.ItemID;
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doCavityCut(List<buEntity> refEntities, bool isFinished, ref Entity entSurface, ref MarbleItem Item)
	{
		string text = "doCavityCut";
		try
		{
			new buEntity();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Item.ItemEntities.DrawWireEntities = new List<buEntity>();
			if (!isFinished)
			{
				for (int i = 0; i <= refEntities.Count - 1; i++)
				{
					buEntity copiedEntity = null;
					buEntity.Copy(refEntities[i], ref copiedEntity);
					Item.ItemEntities.SourceEntities.Add(copiedEntity);
					Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity));
				}
				return;
			}
			if (Item.ItemEntities.SolidEntity == null)
			{
				Item.ItemEntities.SolidEntity = new List<Entity>();
			}
			Item.ItemEntities.SolidEntity.Clear();
			for (int j = 0; j <= refEntities.Count - 1; j++)
			{
				if (!(refEntities[j] is buLine))
				{
					if (refEntities[j] is buCompositeCurve)
					{
						Entity copiedEntity2 = null;
						buEntity.Copy(refEntities[j], ref copiedEntity2);
						copiedEntity2.Translate(0.0, 0.0, Item.Settings.settingCavity.CavityDepth);
						devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((ICurve)copiedEntity2);
						Entity entity = region.ExtrudeAsMesh(Item.Settings.MaterialParameter.MaterialThickness, 9.1, Mesh.natureType.RichSmooth);
						entity.EntityData = new CustomData();
						entity.ColorMethod = colorMethodType.byEntity;
						entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSweep.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSweep.Color);
						Item.ItemEntities.SolidEntity.Add(entity);
					}
				}
				else
				{
					buEntity copiedEntity3 = null;
					buEntity.Copy(refEntities[j], ref copiedEntity3);
					copiedEntity3.Translate(0.0, 0.0, Item.Settings.settingCavity.CavityDepth);
					Item.ItemEntities.SourceEntities.Add(copiedEntity3);
					Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity3));
				}
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

