	public void doAddItemProfiling(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
	{
		string text = "doAddItemProfiling";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (entitiesForProfiling.Count == 0)
			{
				return;
			}
			MarbleItem Item = new MarbleItem();
			Item.ItemEntities.SourceEntities = new List<buEntity>();
			Entity entSurface = null;
			Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			doProfileCut(entitiesForProfiling, ref entSurface, ref Item);
			Item.ItemType = MarbleItemType.Profiling;
			Item.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			Item.BaseHeight = 0.0;
			if (isFinsihed)
			{
				doAddItemCommonProps(ref Item);
				Item.Settings.MaterialParameter.MaterialThickness = entSurface.BoxMax.Z;
				Item.BasePoint = buVector5.ToPoint3D(refPoint);
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int i = 0; i <= Item.ItemEntities.SolidEntity.Count - 1; i++)
				{
					Item.ItemEntities.SolidEntity[i].Translate(refPoint.X, refPoint.Y, refPoint.Z + Item.BaseHeight);
				}
			}
			if (Item.ItemEntities.SourceEntities != null)
			{
				for (int j = 0; j <= Item.ItemEntities.SourceEntities.Count - 1; j++)
				{
					buEntity buEntity2 = Item.ItemEntities.SourceEntities[j];
					buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z + Item.BaseHeight);
					buEntity2.Marble = new MarbleInfo();
				}
			}
			if (Item.ItemEntities.DrawWireEntities != null)
			{
				for (int k = 0; k <= Item.ItemEntities.DrawWireEntities.Count - 1; k++)
				{
					buEntity buEntity3 = Item.ItemEntities.DrawWireEntities[k];
					buEntity3.Translate(refPoint.X, refPoint.Y, refPoint.Z + Item.BaseHeight);
					buEntity3.Marble = new MarbleInfo();
				}
			}
			if (!isFinsihed)
			{
				MarbleTempVars.ItemsProfile.Add(Item);
				return;
			}
			clsInit.cMarble.GetIDs(activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
			Item.ID = MarbleTempVars.ItemID;
