	public void doProfileCut(List<buEntity> RefEntities, ref Entity entSurface, ref MarbleItem Item)
	{
		string text = "doProfileCut";
		try
		{
			List<Point3D> list = new List<Point3D>();
			ToolBase5 toolBase = new ToolBase5(buMarbleCalc.activeToolSaw);
			if (toolBase.Geometry.GeometryType != buClass.ToolType.Saw)
			{
				toolBase.Geometry.Thickness = toolBase.Geometry.Diameter;
			}
			if (RefEntities.Count <= 0)
			{
				clsInit.appCommand.Reset(ClearSelection: true, ReDraw: true);
				return;
			}
			list = new List<Point3D>();
			for (int i = 0; i <= RefEntities.Count - 1; i++)
			{
				List<Point3D> Points = new List<Point3D>();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[i], buMarbleCalc.varMarbleEntitiesSettings.ProfileDeviationResolution, ref Points);
				list.AddRange(Points);
				buEntity copiedEntity = null;
				buEntity.Copy(RefEntities[i], ref copiedEntity);
				clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref copiedEntity);
				clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisZ, ref copiedEntity);
				Item.ItemEntities.SourceEntities.Add(copiedEntity);
			}
			clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref list);
			clsInit.cVector5.Rotate(new Point3D(), 90.0, Plane.YZ, ref list);
			clsInit.cVector5.Rotate(new Point3D(), 90.0, Plane.XY, ref list);
			if (!clsInit.cVector5.IsClosed(list))
			{
				list.Add(buVector5.ToPoint3D(list[0]));
			}
			if (!buMarbleCalc.varOperation.settingProfileCut.TwistEnable)
			{
				clsInit.cVector5.RoundPoints(ref list);
				clsInit.cVector5.SurfaceExturudeByPoints(list, Vector3D.AxisX, buMarbleCalc.varOperation.settingProfileCut.Length, ref entSurface, AsMesh: true);
				entSurface.Rotate(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingProfileCut.RotationAngle), Vector3D.AxisZ, new Point3D());
				entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
				Entity copiedEntity2 = null;
				buEntity.Copy(entSurface, ref copiedEntity2);
				Item.ItemEntities.SolidEntity = new List<Entity>();
				copiedEntity2.ColorMethod = colorMethodType.byEntity;
				copiedEntity2.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemProfile.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemProfile.Color);
				Item.ItemEntities.SolidEntity.Add(copiedEntity2);
				return;
			}
			List<ICurve> list2 = new List<ICurve>();
			int num = Convert.ToInt32(Math.Abs(buMarbleCalc.varOperation.settingProfileCut.TwistStartAngle - buMarbleCalc.varOperation.settingProfileCut.TwistEndAngle) / buMarbleCalc.varOperation.settingProfileCut.TwisStepAngle);
			Convert.ToInt32(buMarbleCalc.varOperation.settingProfileCut.Length / (double)num);
			List<double> Values = new List<double>();
			List<double> Values2 = new List<double>();
			buNumeric5.DevideMinMaxValueByNumber(buMarbleCalc.varOperation.settingProfileCut.TwistStartAngle, buMarbleCalc.varOperation.settingProfileCut.TwistEndAngle, num + 1, ref Values);
			buNumeric5.DevideMinMaxValueByNumber(0.0, buMarbleCalc.varOperation.settingProfileCut.Length, num + 1, ref Values2);
			double degrees = buMarbleCalc.varOperation.settingProfileCut.TwistStartAngle;
			int num2 = 0;
			Point3D MinPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint, ref MidPoint, ref MaxPoint);
			Entity copiedEntity3 = null;
			Entity copiedEntity4 = null;
			for (int j = 0; j <= Values2.Count - 1; j++)
			{
				List<Point3D> copiedPoint = new List<Point3D>();
				buVector5.Copy(list, ref copiedPoint);
				LinearPath linearPath = new LinearPath(copiedPoint);
				if (num2 <= Values.Count - 1)
				{
					degrees = Values[num2];
				}
				if (buMarbleCalc.varOperation.settingProfileCut.TwistEnable)
				{
					linearPath.Rotate(Utility.DegToRad(degrees), Vector3D.AxisX, MidPoint);
				}
				linearPath.Translate(Values2[j], 0.0);
				list2.Add(linearPath);
				num2++;
			}
			if (list2.Count > 0)
			{
				buEntity.Copy((Entity)list2[0], ref copiedEntity3);
				buEntity.Copy((Entity)list2[list2.Count - 1], ref copiedEntity4);
			}
			Surface[] array = Surface.Loft(list2);
			entSurface = array[0];
			entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
			Entity entity = ((Surface)entSurface).ConvertToMesh();
			if (entSurface.BoxMin == null)
			{
				entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
			}
			if (copiedEntity3 != null)
			{
				devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((ICurve)copiedEntity3);
				devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region((ICurve)copiedEntity4);
				Mesh mesh = region.ConvertToMesh();
				Mesh mesh2 = region2.ConvertToMesh();
				((Mesh)entity).MergeWith(mesh);
				((Mesh)entity).MergeWith(mesh2);
			}
			Item.ItemEntities.DrawWireEntities = new List<buEntity>();
			Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity3));
			Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity4));
			Item.ItemEntities.SolidEntity = new List<Entity>();
			entity.ColorMethod = colorMethodType.byEntity;
			entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemProfile.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemProfile.Color);
			Item.ItemEntities.SolidEntity.Add(entity);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doProfileCurveCut(List<buEntity> RefEntities, ref Entity entSurface, ref MarbleItem Item)
	{
		string text = "doProfileCurveCut";
		try
		{
			List<Point3D> list = new List<Point3D>();
			ToolBase5 toolBase = new ToolBase5(buMarbleCalc.activeToolSaw);
			if (toolBase.Geometry.GeometryType != buClass.ToolType.Saw)
			{
				toolBase.Geometry.Thickness = toolBase.Geometry.Diameter;
			}
			if (RefEntities.Count <= 0)
			{
				clsInit.appCommand.Reset(ClearSelection: true, ReDraw: true);
				return;
			}
			list = new List<Point3D>();
			for (int i = 0; i <= RefEntities.Count - 1; i++)
			{
				List<Point3D> Points = new List<Point3D>();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[i], buMarbleCalc.varMarbleEntitiesSettings.ProfileDeviationResolution, ref Points);
				list.AddRange(Points);
				buEntity copiedEntity = null;
				buEntity.Copy(RefEntities[i], ref copiedEntity);
				clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref copiedEntity);
				Item.ItemEntities.SourceEntities.Add(copiedEntity);
			}
			clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref list);
			clsInit.cVector5.Rotate(new Point3D(), 90.0, Plane.YZ, ref list);
			if (!clsInit.cVector5.IsClosed(list))
			{
				list.Add(buVector5.ToPoint3D(list[0]));
			}
			List<ICurve> list2 = new List<ICurve>();
			int num = Convert.ToInt32(buMarbleCalc.varOperation.settingProfileCurveCut.SweepAngle / buMarbleCalc.varOperation.settingProfileCurveCut.CurveAngleStep);
			double num2 = buMarbleCalc.varOperation.settingProfileCurveCut.SweepAngle / (double)num;
			List<double> Values = new List<double>();
			buNumeric5.DevideMinMaxValueByNumber(buMarbleCalc.varOperation.settingProfileCurveCut.TwistStartAngle, buMarbleCalc.varOperation.settingProfileCurveCut.TwistEndAngle, num + 1, ref Values);
			double degrees = buMarbleCalc.varOperation.settingProfileCurveCut.TwistStartAngle;
			int num3 = 0;
			Point3D MinPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint, ref MidPoint, ref MaxPoint);
			Entity copiedEntity2 = null;
			Entity copiedEntity3 = null;
			for (int j = 0; j <= num; j++)
			{
				List<Point3D> copiedPoint = new List<Point3D>();
				buVector5.Copy(list, ref copiedPoint);
				LinearPath linearPath = new LinearPath(copiedPoint);
				if (num3 <= Values.Count - 1)
				{
					degrees = Values[num3];
				}
				double degrees2 = buMarbleCalc.varOperation.settingProfileCurveCut.StartAngle + (double)j * num2;
				if (buMarbleCalc.varOperation.settingProfileCurveCut.TwistEnable)
				{
					linearPath.Rotate(Utility.DegToRad(degrees), Vector3D.AxisY, MidPoint);
				}
				linearPath.Translate(Item.Settings.settingProfileCurveCut.Radius, 0.0);
				linearPath.Rotate(Utility.DegToRad(degrees2), Vector3D.AxisZ, new Point3D(0.0, 0.0, 0.0));
				list2.Add(linearPath);
				num3++;
			}
			if (list2.Count > 0)
			{
				buEntity.Copy((Entity)list2[0], ref copiedEntity2);
				buEntity.Copy((Entity)list2[list2.Count - 1], ref copiedEntity3);
			}
			Surface[] array = Surface.Loft(list2);
			entSurface = array[0];
			entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
			Entity entity = ((Surface)entSurface).ConvertToMesh();
			if (entSurface.BoxMin == null)
			{
				entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
			}
			if (copiedEntity2 != null)
			{
				devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((ICurve)copiedEntity2);
				devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region((ICurve)copiedEntity3);
				Mesh mesh = region.ConvertToMesh();
				Mesh mesh2 = region2.ConvertToMesh();
				((Mesh)entity).MergeWith(mesh);
				((Mesh)entity).MergeWith(mesh2);
			}
			_ = buMarbleCalc.varOperation.settingProfileCurveCut.Radius * Math.Cos(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingProfileCurveCut.StartAngle + buMarbleCalc.varOperation.settingProfileCurveCut.SweepAngle));
			double x = buMarbleCalc.varOperation.settingProfileCurveCut.Radius - buMarbleCalc.varOperation.settingProfileCurveCut.Radius * Math.Cos(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingProfileCurveCut.StartAngle + buMarbleCalc.varOperation.settingProfileCurveCut.SweepAngle));
			double y = buMarbleCalc.varOperation.settingProfileCurveCut.Radius - buMarbleCalc.varOperation.settingProfileCurveCut.Radius * Math.Sin(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingProfileCurveCut.StartAngle));
			Item.CalcMovePoint = new Point3D(x, y, 0.0 - entSurface.BoxMin.Z);
			entity.Translate(0.0 - entSurface.BoxMin.X, 0.0 - entSurface.BoxMin.Y, 0.0 - entSurface.BoxMin.Z);
			Item.ItemEntities.SolidEntity = new List<Entity>();
			entity.ColorMethod = colorMethodType.byEntity;
			entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemProfile.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemProfile.Color);
			Item.ItemEntities.SolidEntity.Add(entity);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

