			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Rough;
			marbleCam.CamType = buClass.CamType.Rough;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileRough.buPar);
			clsInit.cMarble.ProfileCurveSettingToCamSetting(Item.Settings.settingProfileCurveCut, isFinish: false, ref marbleCam.setCam);
		}
		if (CamType == MarbleCamType.ProfileCurveFinish)
		{
			marbleCam.CamName = buLangTranslate.preDef.Profile + " " + buLangTranslate.preDef.Curve + " " + buLangTranslate.preDef.Finish + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.Finish;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileFinish.buPar);
			clsInit.cMarble.ProfileCurveSettingToCamSetting(Item.Settings.settingProfileCurveCut, isFinish: false, ref marbleCam.setCam);
		}
		if (CamType == MarbleCamType.ProfileOffset)
		{
			marbleCam.CamName = buLangTranslate.preDef.Profile + " " + buLangTranslate.preDef.Curve + " " + buLangTranslate.preDef.Offset + " " + buLangTranslate.preDef.Cut;
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.CamType = buClass.CamType.Finish;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileFinish.buPar);
			clsInit.cMarble.ProfileCurveSettingToCamSetting(Item.Settings.settingProfileCurveCut, isFinish: false, ref marbleCam.setCam);
		}
		clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
		int num = doProfileCurveCamCalc(ref Item, ref marbleCam);
		if (!Edit && num > 0)
		{
			Item.CamList.Add(marbleCam);
		}
		AddOperationAfterThings();
	}

