	public int doProfilingCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doProfilingCamCalc";
		try
		{
			marbleCam.CamBase = new camTp();
			clsMW.Containment2DEntities.Clear();
			if (marbleCam.ToolType != MarbleToolType.Saw)
			{
				if (marbleCam.CamMode == MarbleCamMode.Rough)
				{
					marbleCam.MeshType = CamTriangularMeshType.Rough;
					MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
					mWCalculationOptions.NumberofAxis = 3;
					mWCalculationOptions.CamTriMeshType = marbleCam.MeshType;
					mWCalculationOptions.Mode = CamMode.TriangularMesh;
					mWCalculationOptions.DontApplyReset = true;
					mWCalculationOptions.isBuWireframeCalculation = false;
					mWCalculationOptions.AddToCamListInLocalCalculation = false;
					mWCalculationOptions.ShowLeadInOutPage = false;
					mWCalculationOptions.DontShowDialogBox = true;
					mWCalculationOptions.DontShowbuDialogBox = true;
					doEngraveCamCalc(mWCalculationOptions, Item, ref marbleCam);
				}
				if (marbleCam.CamMode == MarbleCamMode.Finish)
				{
					marbleCam.MeshType = CamTriangularMeshType.ParallelCuts;
					MWCalculationOptions mWCalculationOptions2 = new MWCalculationOptions();
					mWCalculationOptions2.NumberofAxis = 3;
					mWCalculationOptions2.CamTriMeshType = marbleCam.MeshType;
					mWCalculationOptions2.Mode = CamMode.TriangularMesh;
					mWCalculationOptions2.DontApplyReset = true;
					mWCalculationOptions2.isBuWireframeCalculation = false;
					mWCalculationOptions2.AddToCamListInLocalCalculation = false;
					mWCalculationOptions2.ShowLeadInOutPage = false;
					mWCalculationOptions2.DontShowDialogBox = true;
					mWCalculationOptions2.DontShowbuDialogBox = true;
					doEngraveCamCalc(mWCalculationOptions2, Item, ref marbleCam);
				}
			}
			else
			{
				if (marbleCam.CamMarbleType == MarbleCamType.ProfileRough)
				{
					marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileRough.buPar);
					List<Point3D> devidedPoints = new List<Point3D>();
					List<Point3D> calcPoints = new List<Point3D>();
					new List<Point3D>();
					List<Pnt6DS> list = new List<Pnt6DS>();
					List<buEntity> copiedEntities = new List<buEntity>();
					CurveToSurfaceSettingsType curveToSurfaceSettingsType = new CurveToSurfaceSettingsType(Item.Settings.settingProfileCut.RoughSurfOffset, Item.Settings.settingProfileCut.RoughStepover, 0.0, silhouetteToPartEnd: true);
					curveToSurfaceSettingsType.MaxDistance = 3.0;
					curveToSurfaceSettingsType.isVertical = Item.Settings.settingProfileCut.VerticalCut;
					buEntity.Copy(Item.ItemEntities.SourceEntities, ref copiedEntities);
					curveToSurfaceSettingsType.MaxZ = Item.SizeItem.MaxPoint.Z + 0.1 - Item.Settings.settingProfileCut.RoughTopOffset;
					curveToSurfaceSettingsType.MinZ = Item.SizeItem.MinPoint.Z - 0.1 + Item.Settings.settingProfileCut.RoughBottomOffset;
					curveToSurfaceSettingsType.InsideOffset = Item.Settings.settingProfileCut.RoughInsideOffset;
					curveToSurfaceSettingsType.OutsideOffset = Item.Settings.settingProfileCut.RoughOutsideOffset;
					doCurveToSurfaceGetPoints(copiedEntities, buMarbleCalc.activeToolSaw, curveToSurfaceSettingsType, ref calcPoints);
					clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref calcPoints);
					devidedPoints.Clear();
					clsInit.cMarble.DevideProfileCutPoints(calcPoints, Item.Settings.settingProfileCut.RoughMinZ, Item.Settings.settingProfileCut.RoughStepover, Item.Settings.settingProfileCut.RoughVerticalDevideLen, isCurveProfilie: true, isRough: true, ref devidedPoints);
					calcPoints.Clear();
					calcPoints.Add(buVector5.ToPoint3D(devidedPoints[0]));
					for (int i = 1; i <= devidedPoints.Count - 2; i++)
					{
						if (calcPoints.Count != 0)
						{
							if (!((calcPoints.Count >= 2) & buCompare5.EQ(calcPoints[calcPoints.Count - 1].X, devidedPoints[i].X, 0.1) & buCompare5.EQ(calcPoints[calcPoints.Count - 1].Y, devidedPoints[i].Y, 0.1)))
							{
								calcPoints.Add(buVector5.ToPoint3D(devidedPoints[i]));
							}
							else if (devidedPoints[i].Z > calcPoints[calcPoints.Count - 1].Z)
							{
								calcPoints[calcPoints.Count - 1].Z = devidedPoints[i].Z;
							}
						}
						else
						{
							calcPoints.Add(buVector5.ToPoint3D(devidedPoints[i]));
						}
					}
					calcPoints.Add(buVector5.ToPoint3D(devidedPoints[devidedPoints.Count - 1]));
					List<List<Point3D>> list2 = new List<List<Point3D>>();
					if (devidedPoints.Count > 0)
					{
						list2.Add(calcPoints);
					}
					List<double> ZPositions = new List<double>();
					if (!activeJob.Material.Enable)
					{
						clsInit.cMarble.GetSawCutStepDistances(Item.Settings.settingProfileCut.RoughMinZ, Item.SizeItem.MaxPoint.Z, Item.Settings.settingProfileCut.RoughZForwardDownStep, ref ZPositions);
					}
					else
					{
						clsInit.cMarble.GetSawCutStepDistances(Item.Settings.settingProfileCut.RoughMinZ, activeJob.Material.Size.Depth, Item.Settings.settingProfileCut.RoughZForwardDownStep, ref ZPositions);
					}
					for (int j = 0; j <= calcPoints.Count - 1; j++)
					{
