					clsInit.cMarble.DevideProfileCutPoints(calcPoints5, Item.Settings.settingProfileCurveCut.RoughMinZ, Item.Settings.settingProfileCurveCut.RoughStepover, Item.Settings.settingProfileCurveCut.RoughVerticalDevideLen, isCurveProfilie: true, isRough: false, ref devidedPoints3);
					clsInit.cVector5.Rotate(Item.BasePoint, Item.Settings.settingProfileCurveCut.StartAngle + Item.Settings.settingProfileCurveCut.SweepAngle, Plane.XY, ref devidedPoints3);
					camStep5 camStep7 = new camStep5();
					camStep7.StepType = CamStepType.StartToEndByStep;
					camStep7.StartValue = Item.SizeItem.MaxPoint.Z;
					camStep7.EndValue = Item.SizeItem.MinPoint.Z;
					camStep7.Step = Item.Settings.settingProfileCut.CutProfileDepthStep;
					camStep7.Enable = true;
					List<double> CalcValues2 = new List<double>();
					clsInit.cCam5.CamStepCalculation(camStep7, ref CalcValues2);
					for (int n = 0; n <= CalcValues2.Count - 1; n++)
					{
						Point3D point3D3 = new Point3D(devidedPoints3[0].X, devidedPoints3[0].Y, CalcValues2[n]);
						Point3D point3D4 = new Point3D(devidedPoints3[devidedPoints3.Count - 1].X, devidedPoints3[devidedPoints3.Count - 1].Y, CalcValues2[n]);
						List<Pnt6D> list8 = new List<Pnt6D>();
