						List<Pnt6D> calcPoints6 = new List<Pnt6D>();
						clsInit.cMarble.CalculatePointsWithKinematic(list8, activeKinematic, marbleCam.ToolSelected, ref calcPoints6);
						camTpPoint camTpPoint3 = new camTpPoint();
						if (calcPoints6.Count > 0)
