							tpPnt9D2 = new TpPnt9D(calcPoints6[0], Item.Settings.settingProfileCut.RoughPlungeFeed, 1);
							camTpPoint3.Points.Add(tpPnt9D2);
							for (int num = 1; num <= calcPoints6.Count - 1; num++)
							{
								double roughCutForwardFeed2 = Item.Settings.settingProfileCut.RoughCutForwardFeed;
