							}
							tpPnt9D2 = new TpPnt9D(calcPoints6[calcPoints6.Count - 1], 100.0, 0);
							tpPnt9D2.P9.Z = tpPnt9D2.P9.Z + Item.SizeItem.MaxPoint.Z + Item.Settings.settingProfileCut.RoughRapid;
							camTpPoint3.Points.Add(tpPnt9D2);
							camTpPoint3.ToolCam = new ToolBase5(buMarbleCalc.activeToolSaw);
