					}
					marbleCam.CamBase.Obj1 = marbleCam;
					marbleCam.CamBase.Obj2 = Item;
					marbleCam.CamBase.Name = marbleCam.CamName;
				}
			}
			doCamPointsOffsets(ref marbleCam);
			AppBool.SaveByTick = true;
			return 1;
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
			return -1;
		}
	}

	public void doDrillPocketCamAdd(ref MarbleItem Item, MarbleToolType CuttingToolType, MarbleCamType CamType, bool ShowDialog, bool Edit, ref MarbleItemCam marbleCam)
	{
		if (!ShowDialog)
		{
		}
		if (ShowDialog)
		{
			if (buMarbleForms.frmDrillPocket == null)
			{
				buMarbleForms.frmDrillPocket = new F_MarbleDrillPocketCam();
			}
			buMarbleForms.frmDrillPocket.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
			buMarbleForms.frmDrillPocket.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			buMarbleForms.frmDrillPocket.varDrill = new marbleDrillPars(buMarbleCalc.varOperation.settingDrillCut);
			buMarbleForms.frmDrillPocket.Init(0);
			buMarbleForms.frmDrillPocket.ShowDialog();
			if (buMarbleForms.frmDrillPocket.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varOperation.settingDrillCut = new marbleDrillPars(buMarbleForms.frmDrillPocket.varDrill);
		}
		AppBool.SaveByTick = true;
		if (marbleCam == null || !Edit)
		{
			marbleCam = new MarbleItemCam();
		}
		if (Item.ItemEntities.EngravingEntities == null)
		{
			Item.ItemEntities.EngravingEntities = new List<buEntity>();
		}
		Item.ItemEntities.EngravingEntities.Clear();
		Item.Settings.settingDrillCut = new marbleDrillPars(buMarbleCalc.varOperation.settingDrillCut);
		buEntity.Copy(Item.ItemEntities.SolidEntity, ref Item.ItemEntities.EngravingEntities);
		marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
		marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
		marbleCam.MeshType = CamTriangularMeshType.ParallelCuts;
		if (CamType == MarbleCamType.PocketByDrilling)
		{
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleHole.buPar);
			marbleCam.CamMarbleType = CamType;
			marbleCam.CamName = buLangTranslate.preDef.Pocket + " " + buLangTranslate.preDef.Drill;
			marbleCam.CamType = buClass.CamType.Rough;
			marbleCam.CamMode = MarbleCamMode.Rough;
		}
		marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
		if (Item.ItemEntities.SolidInsideEntity == null)
		{
			Item.ItemEntities.SolidInsideEntity = new List<Entity>();
		}
		Item.ItemEntities.SolidInsideEntity.Clear();
		if (Item.ItemEntities.DrawWireEntities == null)
		{
			Item.ItemEntities.DrawWireEntities = new List<buEntity>();
		}
		Item.ItemEntities.DrawWireEntities.Clear();
		if (marbleCam.SolidEntities == null)
		{
			marbleCam.SolidEntities = new List<Entity>();
		}
		marbleCam.SolidEntities.Clear();
		clsInit.appMarble.doDrillPocketCamCalc(ref Item, ref marbleCam);
		marbleCam.isCamCalculated = true;
		clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
		Item.CamList.Add(marbleCam);
		AddOperationAfterThings();
	}

	public int doDrillPocketCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doDrillPocketCamCalc";
		try
		{
			if (Item.ItemEntities.EngravingEntities != null)
			{
				if (Item.ItemEntities.EngravingEntities.Count != 0)
				{
					bool flag = false;
					bool flag2 = false;
					clsMW.Containment2DEntities.Clear();
					new camTp();
					clsMW.CamEntities.Clear();
					clsMW.CamEntities = new List<Entity>();
					Point3D MinPoint = new Point3D();
					Point3D MaxPoint = new Point3D();
					new Point3D();
					new Point3D();
					clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.EngravingEntities, ref MinPoint, ref MaxPoint);
					double num = MaxPoint.Z - MinPoint.Z - Item.Settings.settingDrillCut.HoleTopOffset - Item.Settings.settingDrillCut.HoleBottomOffset;
					int num2 = (int)buNumeric5.RoundToUpper(num / Item.Settings.settingDrillCut.HoleZDepthStep);
					double num3 = num / (double)num2;
					camResult camResult2 = null;
					marbleCam.CamBase = new camTp();
					marbleCam.WireEntities = new List<List<buEntity>>();
					marbleCam.WireEntities.Clear();
					marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
					Item.ItemEntities.DrawWireEntities = new List<buEntity>();
					for (int i = 1; i <= num2; i++)
					{
						Entity[][] OffsetSectionsByLayer = null;
						clsInit.cVector5.GetMeshZContours(Item.ItemEntities.SolidEntity, Item.SizeItem.MaxPoint.Z - num3 * (double)i, Simplify: true, Item.Settings.settingDrillCut.HoleContourOffset, ref OffsetSectionsByLayer);
						List<Entity> list = new List<Entity>();
						List<Entity> refEntities = new List<Entity>();
						List<Entity> refEntities2 = new List<Entity>();
						List<Point3D> list2 = new List<Point3D>();
						if (OffsetSectionsByLayer != null && OffsetSectionsByLayer.Length != 0 && OffsetSectionsByLayer[0].Length != 0)
						{
							list2.AddRange(OffsetSectionsByLayer[0][OffsetSectionsByLayer[0].Length - 1].Vertices.ToList());
							list.Add(OffsetSectionsByLayer[0][OffsetSectionsByLayer[0].Length - 1]);
						}
						if (list2.Count <= 0)
						{
							continue;
						}
						List<Point3D> OffsetedPoints = new List<Point3D>();
						clsInit.cVector5.OffsetContour(list2, -20.0, OffsetCornerType.Line, CamOpenContourType.Center, Plane.XY, 0.0, ref OffsetedPoints);
						for (int j = 0; j <= list.Count - 1; j++)
						{
							Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(list[j]));
						}
						Point3D MinPoint2 = new Point3D();
						Point3D MaxPoint2 = new Point3D();
						clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint2, ref MaxPoint2);
						if (OffsetedPoints.Count > 0)
						{
							List<buEntity> calcLines = new List<buEntity>();
							clsInit.cVector5.HatchLinear(OffsetedPoints, Item.SizeItem.MaxPoint.Z - num3 * (double)i, Item.Settings.settingDrillCut.HoleScanYStep, HorizontalVertical.Horizontal, Plane.XY, ref calcLines);
							if (marbleCam.DrillEntities == null)
							{
								marbleCam.DrillEntities = new List<buEntity>();
							}
							marbleCam.DrillEntities.Clear();
							for (int k = 0; k <= calcLines.Count - 1; k++)
							{
								List<Point3D> pntDevided = new List<Point3D>();
								clsInit.cVector5.EntityDevide(calcLines[k], Item.Settings.settingDrillCut.HoleScanXStep, ref pntDevided);
								for (int l = 1; l <= pntDevided.Count - 2; l++)
								{
									Circle refEntity = new Circle(pntDevided[l], marbleCam.ToolSelected.Geometry.Diameter);
									marbleCam.DrillEntities.Add(buEntity.Copy(refEntity));
								}
							}
							doDrillCamCalc(marbleCam.DrillEntities, Item, ref marbleCam);
							if (marbleCam.CamBase != null)
							{
								marbleCam.CamBase.TypeCam = CamType.CornerCleanByDrill;
							}
							for (int m = 0; m <= marbleCam.DrillEntities.Count - 1; m++)
							{
								Entity copiedEntity = null;
								buEntity.Copy(marbleCam.DrillEntities[m], ref copiedEntity);
								ICurve[] array = ((ICurve)copiedEntity).Offset(-4.0, Vector3D.AxisZ);
								if (array == null || array.Length == 0)
								{
									buEntity copiedEntity2 = null;
									buEntity.Copy(marbleCam.DrillEntities[m], ref copiedEntity2);
									continue;
								}
								List<ICurve> list3 = new List<ICurve>();
								list3.Add((ICurve)copiedEntity);
								devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(list3, Plane.XY, sortAndOrient: true);
								region.Regen(0.1);
								if (region.Vertices != null && !buCompare5.EQ(region.Vertices[0].Z, region.BoxMin.Z))
								{
									double dz = marbleCam.DrillEntities[m].Vertices[0].Z - region.Vertices[0].Z;
									region.Translate(0.0, 0.0, dz);
								}
								Mesh mesh = region.ExtrudeAsMesh(100.0, 0.05, Mesh.natureType.RichSmooth);
								mesh.Selectable = false;
								mesh.Color = buMarbleCalc.varMarbleColorSettings.colorItemHole.Color;
								CustomData customData = new CustomData();
								customData.typeDefination = entityTypeDefination.MarbleItem;
								mesh.EntityData = customData;
								marbleCam.SolidEntities.Add(mesh);
							}
						}
						List<Entity> LineEntities = new List<Entity>();
						List<Entity> LineEntities2 = new List<Entity>();
						clsInit.cVector5.LineaPathToLine(refEntities, Item.Settings.settingDrillCut.HoleScanXStep * 0.9, HorizontalVertical.Horizontal, ref LineEntities);
						clsInit.cVector5.LineaPathToLine(refEntities2, Item.Settings.settingDrillCut.HoleScanYStep * 0.9, HorizontalVertical.Vertical, ref LineEntities2);
						new List<List<Point3D>>();
						new List<Entity>();
					}
					if (camResult2 == null || camResult2.Errors.Count <= 0)
					{
						if (!flag)
						{
							if (flag2)
							{
								buMWMarbleVars.varCamMarbleSawMillingVerticalRough.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleSawMillingVerticalRough.buPar);
							}
						}
						else if (flag2)
						{
							buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.buPar);
						}
						if (marbleCam.CamBase.CamPoints.Count > 0)
						{
							marbleMillingAnalyzePars analyzeSet = new marbleMillingAnalyzePars();
							AnalyzeSawCam(analyzeSet, ref marbleCam.CamBase);
							marbleCam.isCamCalculated = true;
						}
						Item.ToolType = MarbleToolType.Saw;
						AppBool.SaveByTick = true;
						return 1;
					}
					F_ErrorList f_ErrorList = new F_ErrorList();
					f_ErrorList.Init(camResult2.Errors);
					f_ErrorList.ShowDialog();
					clsInit.appCommand.Reset();
					return -2;
				}
				return -2;
			}
			return -2;
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
			return -1;
		}
	}

	public void doAddItemDrill(Point3D refPoint, bool isFinished = false, bool isCamCalc = false)
	{
		string text = "doAddItemDrill";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			if (entitiesForDrill.Count == 0)
			{
				return;
			}
			List<MarbleItem> Items = new List<MarbleItem>();
			doDrillCut(refPoint, entitiesForDrill, isFinished, ref Items);
			for (int i = 0; i <= Items.Count - 1; i++)
			{
				MarbleItem Item = Items[i];
				Item.ItemType = MarbleItemType.Drill;
				if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.MillingHead)
				{
					Item.ToolType = MarbleToolType.Milling;
				}
				else
				{
					Item.ToolType = MarbleToolType.MillingHead;
				}
				if (isFinished)
				{
					doAddItemCommonProps(ref Item);
				}
				if (!isFinished)
				{
					MarbleTempVars.ItemsDrill.Add(Item);
					continue;
				}
				MarbleItemCam marbleCam = new MarbleItemCam();
				marbleCam.CamName = buLangTranslate.preDef.Drill + " " + buLangTranslate.preDef.Cut;
				marbleCam.CamMarbleType = MarbleCamType.MillingDrill2D;
				marbleCam.CamMode = MarbleCamMode.Drill;
				marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleDrill.buPar);
				marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
				marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
				marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
				marbleCam.CamType = CamType.Drill;
				marbleCam.isFinish = true;
				marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
				if (isCamCalc)
				{
					doDrillCamCalc(ref Item, ref marbleCam);
				}
				marbleCam.isCamCalculated = isCamCalc;
				clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
				Item.CamList.Add(marbleCam);
				if (Item.ItemEntities.SolidEntity != null)
				{
					clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
					ObjectSize3D.CalculateSize(ref Item.SizeItem);
				}
				AddOperationBeforeThings();
				doAddItemToJob(Item, OperationAfterThings: false, IncreaseID: false);
			}
			if (isFinished)
			{
				MarbleTempVars.ItemID++;
				AddOperationAfterThings();
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doDrillCut(Point3D refPoint, List<buEntity> refEntities, bool isFinished, ref List<MarbleItem> Items)
	{
		string text = "doDrillCut";
		try
		{
			Items.Clear();
			for (int i = 0; i <= refEntities.Count - 1; i++)
			{
				MarbleItem marbleItem = new MarbleItem();
				marbleItem.ItemType = MarbleItemType.Drill;
				marbleItem.ItemEntities.SourceEntities = new List<buEntity>();
				marbleItem.ItemEntities.DrawWireEntities = new List<buEntity>();
				marbleItem.ItemEntities.DrillEntities = new List<buEntity>();
				double num = marbleItem.Settings.MaterialParameter.MaterialThickness;
				if (refEntities[i].Marble != null && refEntities[i].Marble.Depth > 0.0)
				{
					num = refEntities[i].Marble.Depth;
				}
				Point3D point3D = new Point3D();
				Entity entity = null;
				double radius = buMarbleCalc.varOperation.settingDrillCut.HoleDiameter / 2.0;
				if (refEntities[i] is buCircle)
				{
					radius = ((buCircle)refEntities[i]).Radius;
					point3D = new Point3D(((buCircle)refEntities[i]).Center.X + refPoint.X, ((buCircle)refEntities[i]).Center.Y + refPoint.Y, marbleItem.Settings.MaterialParameter.MaterialThickness - num);
					entity = new Circle(Plane.XY, new Point3D(point3D.X, point3D.Y), ((buCircle)refEntities[i]).Radius);
					marbleItem.BasePoint = buVector5.ToPoint3D(point3D);
				}
				if (entity != null)
				{
					entity.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
					devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((ICurve)entity);
					region.Regen(buMarbleCalc.varMarbleEntitiesSettings.ProfileDeviationResolution);
					marbleItem.ItemEntities.SolidEntity = new List<Entity>();
					Entity entity2 = region.ExtrudeAsMesh(num, buMarbleCalc.varMarbleEntitiesSettings.ProfileDeviationResolution, Mesh.natureType.RichSmooth);
					entity2.ColorMethod = colorMethodType.byEntity;
					entity2.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemHole.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemHole.Color);
					marbleItem.ItemEntities.DrillEntities.Add(new buCircle(new Point3D(point3D.X, point3D.Y, 0.0), radius));
					if (isFinished)
					{
						marbleItem.ItemEntities.SolidEntity.Add(entity2);
						marbleItem.ItemEntities.DrawWireEntities.Add(new buCircle(new Point3D(point3D.X, point3D.Y, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness), radius));
						marbleItem.ItemEntities.SourceEntities.Add(new buCircle(new Point3D(point3D.X, point3D.Y, 0.0), radius));
					}
					Items.Add(marbleItem);
				}
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doDrillCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doDrillCamCalc";
		marbleCam.CamBase = new camTp();
		camTp camTp2 = new camTp();
		try
		{
			double num = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
			double num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
			double feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadDrillVelocity;
			if (marbleCam.ToolType == MarbleToolType.Milling)
			{
				num = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
				num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
				feed = buMarbleCalc.varOperation.settingMarbleCam.MillingDrillVelocity;
			}
			if (num2 < buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + num2)
			{
				num2 = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + num2;
			}
			if (num < num2)
			{
				num = num2 + 5.0;
			}
			if (!((buMarbleCalc.varOperation.settingMarbleCam.DefaultDrillTool == MarbleMillingToolType.MillingHead) & (marbleCam.ToolType == MarbleToolType.MillingHead)))
			{
				if ((buMarbleCalc.varOperation.settingMarbleCam.DefaultDrillTool == MarbleMillingToolType.Milling) & (marbleCam.ToolType == MarbleToolType.Milling))
				{
					List<Pnt6D> list = new List<Pnt6D>();
					list.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num, 0.0, 0.0, 0.0));
					list.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z, 0.0, 0.0, 0.0));
					list.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num, 0.0, 0.0, 0.0));
					List<Point3D> list2 = new List<Point3D>();
					list2.Add(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num));
					list2.Add(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, buMarbleCalc.varOperation.settingMarbleCam.TargetZDrill));
					camTpPoint camTpPoint2 = new camTpPoint();
					for (int i = 0; i <= list.Count - 1; i++)
					{
						int type = 0;
						if (i == 1)
						{
							type = 1;
						}
						TpPnt9D item = new TpPnt9D(list[i], feed, type);
						camTpPoint2.Points.Add(item);
					}
					camTpPoint2.ToolCam = new ToolBase5(buMarbleCalc.activeToolMilling);
					LinearPath item2 = new LinearPath(list2);
					camTp2.Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
					camTp2.EntitiesG1.Add(item2);
					camTp2.CamPoints.Add(camTpPoint2);
					marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMilling);
					marbleCam.ToolType = MarbleToolType.Milling;
				}
			}
			else
			{
				List<Pnt6D> list3 = new List<Pnt6D>();
				list3.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num, 0.0, 0.0, 0.0));
				list3.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z, 0.0, 0.0, 0.0));
				list3.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num, 0.0, 0.0, 0.0));
				List<Point3D> list4 = new List<Point3D>();
				list4.Add(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num));
				list4.Add(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, buMarbleCalc.varOperation.settingMarbleCam.TargetZDrill));
				camTpPoint camTpPoint3 = new camTpPoint();
				for (int j = 0; j <= list3.Count - 1; j++)
				{
					list3[j].A = 90.0;
					int type2 = 0;
					if (j == 1)
					{
						type2 = 1;
					}
					TpPnt9D item3 = new TpPnt9D(list3[j], feed, type2);
					camTpPoint3.Points.Add(item3);
				}
				camTpPoint3.ToolCam = new ToolBase5(buMarbleCalc.activeToolMillingHead);
				LinearPath item4 = new LinearPath(list4);
				camTp2.Tool = new ToolBase5(buMarbleCalc.activeToolMillingHead);
				camTp2.EntitiesG1.Add(item4);
				camTp2.CamPoints.Add(camTpPoint3);
				marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMillingHead);
				marbleCam.ToolType = MarbleToolType.MillingHead;
			}
			camTp2.TypeCam = CamType.Drill;
			marbleCam.CamBase = new camTp(camTp2);
			marbleCam.isCamCalculated = true;
			marbleMillingAnalyzePars analyzeSet = new marbleMillingAnalyzePars();
			AnalyzeMillingCam(analyzeSet, ref marbleCam.CamBase);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doDrillCamCalc(List<buEntity> DrillEntities, MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doDrillCamCalc";
		marbleCam.CamBase = new camTp();
		camTp camTp2 = new camTp();
		try
		{
			double num = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
			double num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
			double feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadDrillVelocity;
			double feed2 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadDrillLeaveVelocity;
			if (marbleCam.ToolType == MarbleToolType.Milling)
			{
				num = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
				num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
				feed = buMarbleCalc.varOperation.settingMarbleCam.MillingDrillVelocity;
				feed2 = buMarbleCalc.varOperation.settingMarbleCam.MillingDrillLeaveVelocity;
			}
			if (num2 < buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + num2)
			{
				num2 = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + num2;
			}
			if (num < num2)
			{
				num = num2 + 5.0;
			}
			List<Point3D> list = new List<Point3D>();
			for (int i = 0; i <= DrillEntities.Count - 1; i++)
			{
				if (!(DrillEntities[i] is buCircle))
				{
					continue;
				}
				if (list.Count != 0)
				{
					Point3D point3D = new Point3D(((buCircle)DrillEntities[i]).Center.X, ((buCircle)DrillEntities[i]).Center.Y, ((buCircle)DrillEntities[i]).Center.Z);
					bool flag = false;
					for (int j = 0; j <= list.Count - 1; j++)
					{
						if (buCompare5.EQ(list[j], point3D, 0.01))
						{
							flag = true;
						}
					}
					if (!flag)
					{
						list.Add(point3D);
					}
				}
				else
				{
					list.Add(new Point3D(((buCircle)DrillEntities[i]).Center.X, ((buCircle)DrillEntities[i]).Center.Y, ((buCircle)DrillEntities[i]).Center.Z));
				}
			}
			double a = 90.0;
			if (marbleCam.ToolType == MarbleToolType.Milling)
			{
				a = 0.0;
			}
			for (int k = 0; k <= list.Count - 1; k++)
			{
				camTpPoint camTpPoint2 = new camTpPoint();
				TpPnt9D tpPnt9D = null;
				if (k == 0)
				{
					tpPnt9D = new TpPnt9D(list[k], feed2, 0);
					tpPnt9D.P9.Z = tpPnt9D.P9.Z + num;
					tpPnt9D.P9.A = 0.0;
					tpPnt9D.LeaveAxisMovement = true;
					tpPnt9D.Type = 0;
					camTpPoint2.Points.Add(tpPnt9D);
					if (marbleCam.ToolType == MarbleToolType.MillingHead)
					{
						tpPnt9D = new TpPnt9D(list[k], feed2, 0);
						tpPnt9D.P9.Z = tpPnt9D.P9.Z + num;
						tpPnt9D.P9.A = a;
						tpPnt9D.P9.C = 0.0;
						tpPnt9D.Type = 0;
						camTpPoint2.Points.Add(tpPnt9D);
					}
				}
				tpPnt9D = new TpPnt9D(list[k], feed2, 0);
				tpPnt9D.P9.Z = tpPnt9D.P9.Z + num2;
				tpPnt9D.P9.A = a;
				tpPnt9D.P9.C = 0.0;
				tpPnt9D.Type = 0;
				camTpPoint2.Points.Add(tpPnt9D);
				tpPnt9D = new TpPnt9D(list[k], feed, 0);
				tpPnt9D.P9.Z = buMarbleCalc.varOperation.settingMarbleCam.TargetZDrill;
				tpPnt9D.P9.A = a;
				tpPnt9D.P9.C = 0.0;
				tpPnt9D.Type = 1;
				camTpPoint2.Points.Add(tpPnt9D);
				tpPnt9D = new TpPnt9D(list[k], feed2, 0);
				tpPnt9D.P9.Z = tpPnt9D.P9.Z + num2;
				tpPnt9D.P9.A = a;
				tpPnt9D.P9.C = 0.0;
				tpPnt9D.Type = 0;
				camTpPoint2.Points.Add(tpPnt9D);
				if (k == list.Count - 1)
				{
					tpPnt9D = new TpPnt9D(list[k], feed2, 0);
					tpPnt9D.P9.Z = tpPnt9D.P9.Z + num;
					tpPnt9D.P9.A = 0.0;
					tpPnt9D.P9.C = 0.0;
					tpPnt9D.Type = 0;
					camTpPoint2.Points.Add(tpPnt9D);
				}
				if (marbleCam.ToolType != MarbleToolType.MillingHead)
				{
					camTpPoint2.ToolCam = new ToolBase5(buMarbleCalc.activeToolMilling);
				}
				else
				{
					camTpPoint2.ToolCam = new ToolBase5(buMarbleCalc.activeToolMillingHead);
				}
				List<Point3D> list2 = new List<Point3D>();
				list2.Add(new Point3D(list[k].X, list[k].Y, list[k].Z + num2));
				list2.Add(new Point3D(list[k].X, list[k].Y, list[k].Z));
				LinearPath item = new LinearPath(list2);
				camTp2.EntitiesG1.Add(item);
				camTp2.CamPoints.Add(camTpPoint2);
			}
			if (marbleCam.ToolType != MarbleToolType.MillingHead)
			{
				camTp2.Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
			}
			else
			{
				camTp2.Tool = new ToolBase5(buMarbleCalc.activeToolMillingHead);
			}
			camTp2.Sequnce = CamSequence.ContourConcaveDrill;
			camTp2.TypeCam = CamType.Drill;
			camTp2.Name = marbleCam.CamName;
			camTp2.Obj1 = Item;
			camTp2.Obj2 = marbleCam;
			marbleCam.CamBase = new camTp(camTp2);
			marbleCam.isCamCalculated = true;
			marbleMillingAnalyzePars analyzeSet = new marbleMillingAnalyzePars();
			AnalyzeMillingCam(analyzeSet, ref marbleCam.CamBase);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doSurfaceClearCamAdd(MarbleItem Item, MarbleToolType CuttingToolType, bool ShowDialog)
	{
		if (ShowDialog)
		{
			if (buMarbleForms.frmStockClear == null)
			{
				buMarbleForms.frmStockClear = new F_MarbleStockClear();
			}
			buMarbleForms.frmStockClear.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
			buMarbleForms.frmStockClear.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			buMarbleForms.frmStockClear.varSurfaceClean = new marbleSurfaceCleanPars(buMarbleCalc.varOperation.settingSurfaceClean);
			buMarbleForms.frmStockClear.Init();
			buMarbleForms.frmStockClear.ShowDialog();
			if (buMarbleForms.frmStockClear.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buMarbleCalc.varOperation.settingSurfaceClean = new marbleSurfaceCleanPars(buMarbleForms.frmStockClear.varSurfaceClean);
		}
		Entity entity = null;
		if (!activeJob.Material.Enable)
		{
			List<Point3D> Points = new List<Point3D>();
			if (Item.EntGroup != null)
			{
				clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.EntGroup.Outside.Entities, 0.1, ref Points);
				for (int i = 0; i <= Points.Count - 1; i++)
				{
					Points[i].Z = 0.0;
				}
			}
			if (Points.Count < 1)
			{
				Points.Add(new Point3D(Item.SizeItem.MinPoint.X, Item.SizeItem.MinPoint.Y));
				Points.Add(new Point3D(Item.SizeItem.MaxPoint.X, Item.SizeItem.MinPoint.Y));
				Points.Add(new Point3D(Item.SizeItem.MaxPoint.X, Item.SizeItem.MaxPoint.Y));
				Points.Add(new Point3D(Item.SizeItem.MinPoint.X, Item.SizeItem.MaxPoint.Y));
				Points.Add(new Point3D(Item.SizeItem.MinPoint.X, Item.SizeItem.MinPoint.Y));
			}
			LinearPath linearPath = new LinearPath(Points);
			linearPath.Translate(0.0, 0.0, Item.SizeItem.Depth + buMarbleCalc.varOperation.settingSurfaceClean.ZOffset);
			devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(linearPath);
			entity = region.ExtrudeAsMesh(0.1, 0.01, Mesh.natureType.RichSmooth);
		}
		else
		{
			List<Point3D> copiedPoint = new List<Point3D>();
			buVector5.Copy(activeJob.Material.Points, ref copiedPoint);
			LinearPath linearPath2 = new LinearPath(copiedPoint);
			linearPath2.Translate(0.0, 0.0, Item.SizeItem.Depth + buMarbleCalc.varOperation.settingSurfaceClean.ZOffset);
			devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region(linearPath2);
			entity = region2.ExtrudeAsMesh(0.1, 0.01, Mesh.natureType.RichSmooth);
		}
		MarbleItemCam marbleCam = null;
		ToolBase5 tool = clsInit.cMarble.FindToolFromType(CuttingToolType);
		doSurfaceClearCamCalcCut(entity, CuttingToolType, tool, AddAsNew: true, ref Item, ref marbleCam);
	}

	public void doSurfaceClearCamCalcCut(Entity refEntity, MarbleToolType CuttingToolType, ToolBase5 Tool, bool AddAsNew, ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doSurfaceClearCamCalcCut";
		try
		{
			bool flag = false;
			if (refEntity == null)
			{
				return;
			}
			if (refEntity.BoxMax == null)
			{
				refEntity.Regen(0.1);
			}
			if (AddAsNew | (marbleCam == null))
			{
				marbleCam = new MarbleItemCam();
			}
			marbleCam.CamName = buLangTranslate.preDef.Surface + " " + buLangTranslate.preDef.Cleaning;
			marbleCam.CamMarbleType = MarbleCamType.Surface2D;
			marbleCam.CamMode = MarbleCamMode.Rough;
			marbleCam.ToolType = CuttingToolType;
			marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
			marbleCam.CamType = CamType.Rough;
			marbleCam.ToolSelected = new ToolBase5(Tool);
			marbleCam.isFinish = true;
			clsMW.Containment2DEntities.Clear();
			clsMW.CamEntities.Clear();
			clsMW.CamEntities.Add(refEntity);
			MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
			mWCalculationOptions.NumberofAxis = 3;
			mWCalculationOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
			mWCalculationOptions.Mode = CamMode.TriangularMesh;
			mWCalculationOptions.isRough = true;
			mWCalculationOptions.DontApplyReset = true;
			mWCalculationOptions.AddToCamListInLocalCalculation = false;
			mWCalculationOptions.AddToCamListInMWCalculation = false;
			mWCalculationOptions.DontShowbuDialogBox = true;
			ToolBase5 toolBase = new ToolBase5();
			if (CuttingToolType != MarbleToolType.Milling)
			{
				if (CuttingToolType != MarbleToolType.Milling)
				{
					if (CuttingToolType != MarbleToolType.MillingHead)
					{
						if (CuttingToolType == MarbleToolType.Saw)
						{
							toolBase.Geometry.Diameter = Tool.Geometry.Thickness;
							toolBase.Purpose = ToolPurpose.Saw;
						}
					}
					else
					{
						toolBase.Geometry.Diameter = Tool.Geometry.Diameter;
						toolBase.Purpose = ToolPurpose.MillingHead;
						flag = true;
					}
				}
				else
				{
					toolBase.Geometry.Diameter = Tool.Geometry.Diameter;
					toolBase.Purpose = ToolPurpose.Milling5Axis;
					flag = true;
				}
			}
			else
			{
				toolBase.Geometry.Diameter = Tool.Geometry.Diameter;
				toolBase.Purpose = ToolPurpose.Milling;
				flag = true;
			}
			toolBase.Geometry.Length = 30.0;
			toolBase.Geometry.GeometryType = buClass.ToolType.Flat;
			double num = Item.SizeItem.MaxPoint.Z + Item.Settings.settingSurfaceClean.ZOffset;
			double num2 = 0.0;
			double num3 = 1.0;
			buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.DepthStepMode = CamStepDepthMode.ConstantDepthStep;
			buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue = num;
			buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.EndValue = num;
			if (!activeJob.Material.Enable)
			{
				buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
			}
			else
			{
				buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtUserDefined;
				if (!(activeJob.Material.Size.Depth > num))
				{
					buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.EndValue = num;
					buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue = num;
					buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
				}
				else
				{
					buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.EndValue = num;
					buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue = activeJob.Material.Size.Depth;
					num2 = activeJob.Material.Size.Depth - num;
					buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.DepthStep = buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance;
					if (!(num2 > buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance))
					{
						buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.EndValue = num;
						buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue = num;
						buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
					}
					else
					{
						num3 = buNumeric5.RoundToUpper(num2 / buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance);
						buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.DepthStep = Math.Round(num2 / num3, 3) - 0.1;
						mWCalculationOptions.CamTriMeshType = CamTriangularMeshType.Rough;
						buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Pockets.PocketType = CamPocketType.WfbRghtParallel;
					}
				}
			}
			if (!flag)
			{
				mWCalculationOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
			}
			else
			{
				mWCalculationOptions.CamTriMeshType = CamTriangularMeshType.Rough;
				buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Pockets.PocketType = CamPocketType.WfbRghtParallel;
			}
			buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.EntryAndExit = Item.Settings.settingSurfaceClean.RapidDistance;
			buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Rapid = Item.Settings.settingMaterialClean.RapidDistance;
			buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Safe = Item.Settings.settingSurfaceClean.SafeDistance;
			if (buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Safe < buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue)
			{
				buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Safe = buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue + buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Rapid;
			}
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSurfaceClean.buPar);
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(buMWMarbleVars.varCamMarbleSurfaceClean.mwPar, marbleCam.setCam);
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.ParallelMachAngleInYX = 90.0;
			if (buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.ClearancePlaneHeight < refEntity.BoxMax.Z + 2.0)
			{
				buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.ClearancePlaneHeight = refEntity.BoxMax.Z + 20.0;
			}
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.MaxStepoverDistance = toolBase.Geometry.Diameter * Item.Settings.settingSurfaceClean.ToolDiameterUsagePersentage / 100.0;
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeOneway;
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.FeedRate = Item.Settings.settingSurfaceClean.CuttingFeed;
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.PlungeFeedRate = Item.Settings.settingSurfaceClean.PlungeFeed;
			((InterlinkHandeler)buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.GapsAlongCut).SmallMoveHandling.Action = MoveHandlingAction.ActionGapBrokenFeedRap;
			((InterlinkHandeler)buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.LinkBetweenSlices).SmallMoveHandling.Action = MoveHandlingAction.ActionGapBrokenFeedRap;
			((InterlinkHandeler)buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.LinkBetweenSlices).LargeMoveHandling.Action = MoveHandlingAction.ActionGapBrokenFeedRap;
			((InterlinkHandeler)buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.LinkBetweenSlices).GetGapSize();
			((InterlinkHandeler)buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.LinkBetweenSlices).SetGapSize(5.0);
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.CutTolerance = 0.1;
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
			buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeOneway;
			if (Item.Settings.settingSurfaceClean.ZigzagMode)
			{
				buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeZigzag;
			}
			if (mWCalculationOptions.CamTriMeshType != CamTriangularMeshType.Rough)
			{
				clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleSurfaceClean.mwPar, buMWMarbleVars.varCamMarbleSurfaceClean.buPar, out clsMW.varbuCamMeshParallelPars);
			}
			else
			{
				clsMW.varMWCamMeshRoughPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleSurfaceClean.mwPar, buMWMarbleVars.varCamMarbleSurfaceClean.buPar, out clsMW.varbuCamMeshRoughPars);
			}
			new camTpPoint();
			mWCalculationOptions.DontShowDialogBox = true;
			camResult Result = new camResult();
			camTp Cam = new camTp();
			int num4 = clsInit.appMW.doTriangularMesh3D(mWCalculationOptions, toolBase, ref Cam, ref Result);
			if (num4 == -1)
			{
				return;
			}
			if (!flag && num3 > 1.0)
			{
				camTp camTp2 = new camTp(Cam);
				double num5 = Math.Round(num2 / num3, 3);
				for (int i = 1; (double)i < num3; i++)
				{
					List<Entity> copiedEntity = new List<Entity>();
					List<Entity> copiedEntity2 = new List<Entity>();
					List<Entity> copiedEntity3 = new List<Entity>();
					List<Entity> copiedEntity4 = new List<Entity>();
					buEntity.Copy(camTp2.EntitiesG1, ref copiedEntity2);
					clsInit.cVector5.Move(0.0, 0.0, (double)i * num5, ref copiedEntity2);
					buEntity.Copy(camTp2.EntitiesG0, ref copiedEntity);
					clsInit.cVector5.Move(0.0, 0.0, (double)i * num5, ref copiedEntity);
					buEntity.Copy(camTp2.EntitiesLeave, ref copiedEntity3);
					clsInit.cVector5.Move(0.0, 0.0, (double)i * num5, ref copiedEntity3);
					buEntity.Copy(camTp2.EntitiesPlunge, ref copiedEntity4);
					clsInit.cVector5.Move(0.0, 0.0, (double)i * num5, ref copiedEntity4);
					for (int j = 0; j <= camTp2.CamPoints.Count - 1; j++)
					{
						camTpPoint camTpPoint2 = new camTpPoint();
						for (int k = 0; k <= camTp2.CamPoints[j].Points.Count - 1; k++)
						{
							TpPnt9D tpPnt9D = new TpPnt9D(camTp2.CamPoints[j].Points[k].P9);
							tpPnt9D.P9.Z = tpPnt9D.P9.Z + (double)i * num5;
							camTpPoint2.Points.Add(tpPnt9D);
						}
						Cam.CamPoints.Insert(0, camTpPoint2);
					}
					Cam.EntitiesG1.AddRange(copiedEntity2);
					Cam.EntitiesG0.AddRange(copiedEntity);
					Cam.EntitiesLeave.AddRange(copiedEntity3);
					Cam.EntitiesPlunge.AddRange(copiedEntity4);
				}
			}
			marbleCam.CamBase = new camTp(Cam);
			if (marbleCam.CamBase != null)
			{
				marbleMillingAnalyzePars marbleMillingAnalyzePars2 = new marbleMillingAnalyzePars();
				if (marbleCam.ToolType == MarbleToolType.MillingHead)
				{
					marbleMillingAnalyzePars2.Apply90DegreeToMillingHead = true;
				}
				AnalyzeMillingCam(marbleMillingAnalyzePars2, ref marbleCam.CamBase);
				camTp camTp3 = marbleCam.CamBase;
				camTp3.CamID = Item.ID;
				camTp3.OperationData = new MarbleItemSettings(Item.Settings);
				camTp3.TypeCam = CamType.SawCut;
				if ((marbleCam.ToolType == MarbleToolType.Milling) | (marbleCam.ToolType == MarbleToolType.MillingHead))
				{
					camTp3.TypeCam = CamType.MillingCut;
				}
				camTp3.AxisCount = 5;
				camTp3.Explanation = buLangTranslate.preDef.Surface + " " + buLangTranslate.preDef.Cleaning;
				camTp3.Parameter = new camParameters5(marbleCam.setCam);
				camTp3.Tool = new ToolBase5(marbleCam.ToolSelected);
				doCamPointsOffsets(ref marbleCam);
				if (CuttingToolType == MarbleToolType.Saw)
				{
					for (int l = 0; l <= marbleCam.CamBase.CamPoints.Count - 1; l++)
					{
						for (int m = 0; m <= marbleCam.CamBase.CamPoints[l].Points.Count - 1; m++)
						{
							TpPnt9D tpPnt9D2 = marbleCam.CamBase.CamPoints[l].Points[m];
							tpPnt9D2.P9.Y = tpPnt9D2.P9.Y + activeKinematic.RotateCenterOffsetOfC.Y;
						}
					}
				}
				clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
				marbleCam.isCamCalculated = true;
				if (AddAsNew | (Item.CamList.Count == 0))
				{
					Item.CamList.Add(marbleCam);
				}
			}
			AddOperationAfterThings();
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItemMaterialClean(bool isCamCalc = false)
	{
		string text = "doAddItemMaterialClean";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			MarbleItem Item = new MarbleItem();
			Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			Item.ItemType = MarbleItemType.MaterialClean;
			doAddItemCommonProps(ref Item);
			Point3D point3D = new Point3D(Item.Settings.settingMaterialClean.StartX, Item.Settings.settingMaterialClean.StartY, Item.Settings.settingMaterialClean.OperationZ);
			Point3D point3D2 = new Point3D(Item.Settings.settingMaterialClean.StartX + Item.Settings.settingMaterialClean.BaseWidth, Item.Settings.settingMaterialClean.StartY + Item.Settings.settingMaterialClean.BaseHegiht, Item.Settings.settingMaterialClean.OperationZ);
			CompositeCurve compositeCurve = CompositeCurve.CreateRectangle(point3D2.X - point3D.X, point3D2.Y - point3D.Y);
			compositeCurve.Translate(point3D.X, point3D.Y, Item.Settings.settingMaterialClean.OperationZ - 0.1);
			devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(compositeCurve);
			Mesh mesh = region.ExtrudeAsMesh(2.0 - Item.Settings.settingMaterialClean.OperationZ, 0.01, Mesh.natureType.RichSmooth);
			Item.ItemEntities.SolidEntity = new List<Entity>();
			mesh.ColorMethod = colorMethodType.byEntity;
			mesh.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemMaterialClean.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemMaterialClean.Color);
			Item.ItemEntities.SolidEntity.Add(mesh);
			MarbleItemCam marbleCam = new MarbleItemCam();
			marbleCam.CamName = buLangTranslate.preDef.Saw + " " + buLangTranslate.preDef.Material + " " + buLangTranslate.preDef.Cleaning;
			marbleCam.CamMarbleType = MarbleCamType.MaterialClean;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMaterialClean.buPar);
			marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
			marbleCam.CamType = CamType.Contour;
			marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolSaw);
			if (marbleCam.ToolType != MarbleToolType.Milling)
			{
				if (marbleCam.ToolType == MarbleToolType.MillingHead)
				{
					marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMillingHead);
				}
			}
			else
			{
				marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMilling);
			}
			marbleCam.ToolSelected.CamData.SpindleSpeed = Item.Settings.settingMaterialClean.SpindleSpeed;
			marbleCam.isFinish = true;
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			Item.CamList.Add(marbleCam);
			if (isCamCalc)
			{
				doMaterialClearCamCalcCut(ref Item, ref marbleCam);
				marbleCam.isCamCalculated = true;
			}
			AddOperationBeforeThings();
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doMaterialClearCamCalcCut(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doMaterialClearCamCalcCut";
		try
		{
			clsMW.Containment2DEntities.Clear();
			camTp camTp2 = new camTp();
			Point3D point3D = new Point3D(Item.Settings.settingMaterialClean.StartX, Item.Settings.settingMaterialClean.StartY, Item.Settings.settingMaterialClean.OperationZ);
			Point3D point3D2 = new Point3D(Item.Settings.settingMaterialClean.StartX + Item.Settings.settingMaterialClean.BaseWidth, Item.Settings.settingMaterialClean.StartY + Item.Settings.settingMaterialClean.BaseHegiht, Item.Settings.settingMaterialClean.OperationZ);
			new Point3D();
			clsMW.CamEntities.Clear();
			new List<Point3D>();
