			compositeCurve.Translate(point3D.X, point3D.Y, Item.Settings.settingMaterialClean.OperationZ - 0.1);
			devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(compositeCurve);
