			mWCalculationOptions.Mode = CamMode.TriangularMesh;
			mWCalculationOptions.isRough = true;
			mWCalculationOptions.DontApplyReset = true;
			mWCalculationOptions.AddToCamListInLocalCalculation = false;
			mWCalculationOptions.AddToCamListInMWCalculation = false;
			mWCalculationOptions.DontShowbuDialogBox = true;
			ToolBase5 toolBase = new ToolBase5();
			toolBase.Geometry.Diameter = Item.Settings.settingMaterialClean.StepDistance;
			toolBase.Geometry.Length = 30.0;
			toolBase.Geometry.GeometryType = buClass.ToolType.Flat;
			if (marbleCam.ToolType == MarbleToolType.Saw)
			{
				Item.Settings.settingMaterialClean.StartHeight = Item.Settings.settingMaterialClean.OperationZ;
			}
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.ParallelMachAngleInYX = 90.0;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.LinkParams.ApproachFeedPlaneIncremental = Item.Settings.settingMaterialClean.RapidDistance;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.LinkParams.FeedPlaneIncremental = Item.Settings.settingMaterialClean.RapidDistance;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.LinkParams.RetractPlaneIncremental = Item.Settings.settingMaterialClean.RapidDistance;
			if (Item.Settings.settingMaterialClean.SafeDistance <= Item.Settings.settingMaterialClean.OperationZ + Item.Settings.settingMaterialClean.RapidDistance)
			{
				Item.Settings.settingMaterialClean.SafeDistance = Item.Settings.settingMaterialClean.OperationZ + Item.Settings.settingMaterialClean.RapidDistance + 10.0;
			}
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.LinkParams.ClearancePlaneHeight = Item.Settings.settingMaterialClean.SafeDistance;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.RapidRetractFlg = true;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.MaxStepoverDistance = toolBase.Geometry.Diameter * 0.9;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.FeedRate = Item.Settings.settingMaterialClean.CuttingFeed;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.PlungeFeedRate = Item.Settings.settingMaterialClean.PlungeFeed;
			((InterlinkHandeler)buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.LinkParams.GapsAlongCut).SmallMoveHandling.Action = MoveHandlingAction.ActionGapBrokenFeedRap;
			((InterlinkHandeler)buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.LinkParams.LinkBetweenSlices).SmallMoveHandling.Action = MoveHandlingAction.ActionGapBrokenFeedRap;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.CutTolerance = 0.1;
			if (!(Item.Settings.settingMaterialClean.StartHeight > Item.Settings.settingMaterialClean.OperationZ))
			{
				buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
			}
			else
			{
				buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtUserDefined;
				buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.StartHeight = Item.Settings.settingMaterialClean.StartHeight;
				buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.EndHeight = Item.Settings.settingMaterialClean.OperationZ;
				buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.RoughType = WireframeBasedTpCalcParamsRoughType.WfbRghtParallel;
				buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.DepthStep = Item.Settings.settingMaterialClean.ZDownStep;
				buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.DepthStepMode = MachiningAreaRoughingParamsDepthStepMode.DsmConstantDepthStep;
				buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseLeadOutsFlg = false;
				mWCalculationOptions.Mode = CamMode.WireFrame;
				mWCalculationOptions.CamWireframeType = CamWireFrameType.Pocket;
			}
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
			buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeOneway;
			if (Item.Settings.settingMaterialClean.ZigzagMode)
			{
				buMWMarbleVars.varCamMarbleMaterialClean.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeZigzag;
			}
			new camTpPoint();
			mWCalculationOptions.DontShowDialogBox = true;
			camTp2 = new camTp();
			camResult Result = new camResult();
			if (mWCalculationOptions.Mode != CamMode.TriangularMesh)
			{
				clsMW.varMWCamWFPocketPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMaterialClean.mwPar, buMWMarbleVars.varCamMarbleMaterialClean.buPar, out clsMW.varbuCamWFPocketPars);
				clsMW.CamEntities.Clear();
				clsMW.CamEntities.Add(compositeCurve);
				clsInit.appMW.doWireframeContour(mWCalculationOptions, toolBase, ref camTp2, ref Result);
			}
			else
			{
				clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMaterialClean.mwPar, buMWMarbleVars.varCamMarbleMaterialClean.buPar, out clsMW.varbuCamMeshParallelPars);
				clsInit.appMW.doTriangularMesh3D(mWCalculationOptions, toolBase, ref camTp2, ref Result);
			}
			marbleCam.CamBase = new camTp(camTp2);
			if (marbleCam.CamBase == null)
			{
				return;
			}
			camTp camTp3 = marbleCam.CamBase;
			camTp3.CamID = Item.ID;
			camTp3.OperationData = new MarbleItemSettings(Item.Settings);
			camTp3.TypeCam = CamType.SawCut;
			if ((marbleCam.ToolType == MarbleToolType.Milling) | (marbleCam.ToolType == MarbleToolType.MillingHead))
			{
				camTp3.TypeCam = CamType.MillingCut;
			}
			camTp3.AxisCount = 5;
			camTp3.Explanation = buLangTranslate.preDef.Material + " " + buLangTranslate.preDef.Cleaning;
			camTp3.Parameter = new camParameters5(marbleCam.setCam);
			camTp3.Tool = new ToolBase5(marbleCam.ToolSelected);
			camTp3.Tool.CamData.SpindleSpeed = Item.Settings.settingMaterialClean.SpindleSpeed;
			doCamPointsOffsets(ref marbleCam);
			for (int i = 0; i <= marbleCam.CamBase.CamPoints.Count - 1; i++)
			{
				for (int j = 0; j <= marbleCam.CamBase.CamPoints[i].Points.Count - 1; j++)
				{
					TpPnt9D tpPnt9D = marbleCam.CamBase.CamPoints[i].Points[j];
					if (marbleCam.ToolType != MarbleToolType.Saw)
					{
						if (marbleCam.ToolType != MarbleToolType.MillingHead)
						{
							if (marbleCam.ToolType == MarbleToolType.Milling)
							{
								tpPnt9D.P9.A = 0.0;
								tpPnt9D.P9.C = Item.Settings.settingMaterialClean.CAxisAngle;
							}
						}
						else
						{
							tpPnt9D.P9.A = 90.0;
						}
					}
					else
					{
						tpPnt9D.P9.Y = tpPnt9D.P9.Y + activeKinematic.RotateCenterOffsetOfC.Y;
					}
				}
			}
			marbleCam.isCamCalculated = true;
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItemAirDry(bool isCamCalc = false)
	{
