						entity2 = region2.ExtrudeAsMesh(1.0, 0.1, Mesh.natureType.RichSmooth);
					}
					else
					{
						CompositeCurve compositeCurve2 = CompositeCurve.CreateRectangle(activeJob.Material.BoxMaxPoint.X - activeJob.Material.BoxMinPoint.X, activeJob.Material.BoxMaxPoint.Y - activeJob.Material.BoxMinPoint.Y);
