						entity2 = region3.ExtrudeAsMesh(1.0, 0.1, Mesh.natureType.RichSmooth);
					}
				}
				else
				{
					Point3D MinPoint = new Point3D();
					Point3D MaxPoint = new Point3D();
					clsInit.cVector5.BoxSizeCalculate(activeJob.SheetSolidEntities, ref MinPoint, ref MaxPoint);
					CompositeCurve compositeCurve3 = CompositeCurve.CreateRectangle(MaxPoint.X - MinPoint.X, MaxPoint.Y - MinPoint.Y);
					compositeCurve3.Translate(activeJob.Material.BoxMinPoint.X, activeJob.Material.BoxMinPoint.Y);
					devDept.Eyeshot.Entities.Region region4 = new devDept.Eyeshot.Entities.Region(compositeCurve3);
					entity2 = region4.ExtrudeAsMesh(1.0, 0.1, Mesh.natureType.RichSmooth);
				}
				if (entity2 != null)
				{
					entity2.Translate(0.0, 0.0, activeJob.Material.BoxMaxPoint.Z + Item.Settings.settingAirDry.Height);
					entity2.ColorMethod = colorMethodType.byEntity;
					entity2.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemAirDry.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemAirDry.Color);
					Item.ItemEntities.SolidEntity = new List<Entity>();
					Item.ItemEntities.SolidEntity.Add(entity2);
				}
			}
			doAddItemCommonProps(ref Item);
			MarbleItemCam marbleCam = new MarbleItemCam();
			marbleCam.ID = MarbleTempVars.MarbleCamID;
			marbleCam.CamName = buLangTranslate.preDef.Air + " " + buLangTranslate.preDef.Dry;
			marbleCam.CamMarbleType = MarbleCamType.AirDry;
			marbleCam.CamMode = MarbleCamMode.Finish;
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleAirDry.buPar);
			marbleCam.ToolType = MarbleToolType.Milling;
			marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
			marbleCam.CamType = CamType.Contour;
			marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMilling);
			marbleCam.isFinish = true;
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			Item.CamList.Add(marbleCam);
			if (isCamCalc)
			{
				doAirDryCamCalcCut(ref Item, ref marbleCam);
			}
			AddOperationBeforeThings();
			marbleCam.isCamCalculated = isCamCalc;
			Item.ID = MarbleTempVars.ItemID;
			doAddItemToJob(Item, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAirDryCamCalcCut(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doAirDryCamCalcCut";
		try
		{
			clsMW.Containment2DEntities.Clear();
			if (Item.ItemEntities.SolidEntity == null || Item.ItemEntities.SolidEntity.Count == 0)
			{
				return;
			}
			camTp camTp2 = new camTp();
			Point3D MinPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			new Point3D();
			clsMW.CamEntities.Clear();
			clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref MinPoint, ref MaxPoint);
			for (int i = 0; i <= Item.ItemEntities.SolidEntity.Count - 1; i++)
			{
				Entity copiedEntity = null;
				buEntity.Copy(Item.ItemEntities.SolidEntity[i], ref copiedEntity);
				if (copiedEntity != null)
				{
					clsMW.CamEntities.Add(copiedEntity);
				}
			}
			camTp2 = new camTp();
			MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
			mWCalculationOptions.NumberofAxis = 3;
			mWCalculationOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
			mWCalculationOptions.Mode = CamMode.TriangularMesh;
			mWCalculationOptions.isRough = true;
			mWCalculationOptions.DontApplyReset = true;
			mWCalculationOptions.AddToCamListInLocalCalculation = false;
			mWCalculationOptions.AddToCamListInMWCalculation = false;
			mWCalculationOptions.DontShowbuDialogBox = true;
			ToolBase5 toolBase = new ToolBase5();
			toolBase.Geometry.Diameter = Item.Settings.settingAirDry.StepDistance;
			toolBase.Geometry.Length = 30.0;
			toolBase.Geometry.GeometryType = buClass.ToolType.Flat;
			if (Item.Settings.settingAirDry.Direction != HorizontalVertical.Horizontal)
			{
				buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.ParallelMachAngleInYX = 0.0;
			}
			else
			{
				buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.ParallelMachAngleInYX = 90.0;
			}
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.ApproachFeedPlaneIncremental = 0.0;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.FeedPlaneIncremental = 0.0;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.RetractPlaneIncremental = 0.0;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.ClearancePlaneHeight = MaxPoint.Z + Item.Settings.settingAirDry.RapidDistance;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.MaxStepoverDistance = toolBase.Geometry.Diameter * 0.9;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.CutTolerance = 0.1;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
			buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
			clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleAirDry.mwPar, buMWMarbleVars.varCamMarbleAirDry.buPar, out clsMW.varbuCamMeshParallelPars);
			new camTpPoint();
			mWCalculationOptions.DontShowDialogBox = true;
			camTp2 = new camTp();
			camResult Result = new camResult();
			clsInit.appMW.doTriangularMesh3D(mWCalculationOptions, toolBase, ref camTp2, ref Result);
			marbleCam.CamBase = new camTp(camTp2);
			if (marbleCam.CamBase != null)
			{
				marbleCam.isCamCalculated = true;
				camTp camTp3 = marbleCam.CamBase;
				camTp3.CamID = marbleCam.ID;
				camTp3.OperationData = new MarbleItemSettings(Item.Settings);
				camTp3.TypeCam = CamType.AreaScan;
				camTp3.AxisCount = 3;
				camTp3.Explanation = buLangTranslate.preDef.Air + " " + buLangTranslate.preDef.Dry;
				camTp3.Post = new PostProcessor(ccVars.PostActive);
				camTp3.UsedCamPost = true;
				camTp3.Post.RepetitionDef.Tool = false;
				camTp3.Parameter = new camParameters5(marbleCam.setCam);
				camTp3.Tool = new ToolBase5(marbleCam.ToolSelected);
				doCamPointsOffsets(ref marbleCam);
				marbleCam.isCamCalculated = true;
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doAddItemGCode(Point3D refPoint, buFile5.GCodeRead GCodes, List<string> GCodeLine)
	{
		string text = "doAddItemGCode";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			MarbleItem MI = new MarbleItem();
			MI.ItemEntities.DrawWireEntities = new List<buEntity>();
			MI.ItemType = MarbleItemType.GCode;
			MI.BasePoint = buVector5.ToPoint3D(refPoint);
			MI.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
			buEntity.Add(GCodes.EntitiesG1, ref MI.ItemEntities.DrawWireEntities);
			for (int i = 0; i <= MI.ItemEntities.DrawWireEntities.Count - 1; i++)
			{
				buEntity buEntity2 = MI.ItemEntities.DrawWireEntities[i];
				buEntity2.Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
				buEntity2.Marble = new MarbleInfo();
			}
			clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.DrawWireEntities, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
			ObjectSize3D.CalculateSize(ref MI.SizeItem);
			if (MI.BaseHeight > 0.0)
			{
				Entity surfaceEntity = null;
				clsInit.cVector5.surfaceBox(MI.SizeItem.MinPoint, MI.SizeItem.MaxPoint.X - MI.SizeItem.MinPoint.X, MI.SizeItem.MaxPoint.Y - MI.SizeItem.MinPoint.Y, MI.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
				if (surfaceEntity != null)
				{
					buEntity copiedEntity = null;
					buEntity.Copy(surfaceEntity, ref copiedEntity);
					copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
					MI.ItemEntities.BaseEntities = new List<buEntity>();
				}
			}
			MarbleItemCam marbleCam = new MarbleItemCam();
			List<string> GCodeLineConverted = new List<string>();
			clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
			ConvertGCodeToGCode(buMarbleCalc.activeToolMilling, 0.0, GCodeLine, GCodes.Coordinates, ref GCodeLineConverted, ref MI, ref marbleCam);
			AddOperationBeforeThings();
			doAddItemToJob(MI, OperationAfterThings: true, IncreaseID: true);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void ConvertGCodeToGCode(ToolBase5 Tool, double ZOffset, List<string> GCodeLine, List<GCodePoint5> Coordinates, ref List<string> GCodeLineConverted, ref MarbleItem MI, ref MarbleItemCam marbleCam)
	{
		if (GCodeLineConverted == null)
		{
			GCodeLineConverted = new List<string>();
		}
		GCodeLineConverted.Clear();
		int num = 10;
		if (buMarbleCalc.varMarbleSettings.GCodeConversion != MarbleExternalGCode.AspireGCode)
		{
			if (buMarbleCalc.varMarbleSettings.GCodeConversion != MarbleExternalGCode.ArtCamMode1)
			{
				if (buMarbleCalc.varMarbleSettings.GCodeConversion != MarbleExternalGCode.Siemens5Axis)
				{
					if (buMarbleCalc.varMarbleSettings.GCodeConversion != MarbleExternalGCode.SolidCam3AxisNoToolChange)
					{
						GCodeLineConverted.AddRange(GCodeLine);
