						{
							MI.CamList.Add(marbleCam);
						}
						marbleCam.isCamCalculated = true;
					}
					else
					{
						double num2 = 3500.0;
						bool flag = false;
						bool flag2 = false;
						for (int i = 0; i <= GCodeLine.Count - 1; i++)
						{
							bool flag3 = true;
							if ((GCodeLine[i].IndexOf("O1") >= 0) | (GCodeLine[i].IndexOf("(") >= 0) | (GCodeLine[i].IndexOf("G90") >= 0) | (GCodeLine[i].IndexOf("G91") >= 0) | (GCodeLine[i].IndexOf("G5") >= 0))
							{
								flag3 = false;
							}
							if ((GCodeLine[i].IndexOf("G54") >= 0) | (GCodeLine[i].IndexOf("G80") >= 0) | (GCodeLine[i].IndexOf("M6") >= 0) | (GCodeLine[i].IndexOf("M30") >= 0) | (GCodeLine[i].IndexOf("M1") >= 0))
							{
								flag3 = false;
							}
							if ((GCodeLine[i].IndexOf("M3") >= 0) & (GCodeLine[i].IndexOf("S") >= 0))
							{
								double Value = 0.0;
