								if (Value > 10.0)
								{
									num2 = Value;
								}
								flag3 = false;
							}
							if (GCodeLine[i].IndexOf("G43") >= 0)
							{
								flag3 = false;
								GCodeLineConverted.Add("G53");
								GCodeLineConverted.Add("G0 Z0 A90");
								GCodeLineConverted.Add("G54 X$G54.X$ Y$G54.Y$ Z$G54.Z$");
