								if (((GCodeLine[i].IndexOf("X") < 0) & (GCodeLine[i].IndexOf("Y") < 0) & (GCodeLine[i].IndexOf("Z") >= 0)) && num3 > 50.0)
								{
									num3 = 50.0;
								}
								GCodeLine[i] = GCodeLine[i].Replace("F" + Value2, "F" + num3);
