								if (GCodeLine[i].IndexOf("G0") >= 0 && !flag)
								{
									GCodeLineConverted.Add("M101");
									flag = true;
									flag2 = false;
								}
								if (((GCodeLine[i].IndexOf("G1") >= 0) | (GCodeLine[i].IndexOf("G2") >= 0) | (GCodeLine[i].IndexOf("G3") >= 0)) && !flag2)
								{
									GCodeLineConverted.Add("M102");
									flag = false;
									flag2 = true;
								}
								GCodeLineConverted.Add(GCodeLine[i].Trim());
							}
						}
						GCodeLineConverted.Add("M35");
						GCodeLineConverted.Add("M2");
						marbleCam.CamBase = new camTp();
