			{
				marbleCam.ToolType = MarbleToolType.MillingHead;
			}
			marbleCam.CamBase.TypeCam = CamType.MillingCut;
			marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleCam.ToolSelected = FindToolFromType(marbleCam.ToolType);
			if (marbleCam.MeshType != CamTriangularMeshType.None)
			{
				MI.CamList.Add(marbleCam);
			}
			marbleCam.isCamCalculated = true;
		}
		marbleCam.CamType = CamType.MillingCut;
	}

	public void GCode5AxisRTCPConversion(ref MarbleItem MI, ref MarbleItemCam marbleCam, ToolBase5 Tool, List<GCodePoint5> GCodePoits)
	{
		marbleCam.ToolType = MarbleToolType.Saw;
		marbleCam.ToolSelected = new ToolBase5(Tool);
		new List<Pnt6DS>();
		List<Pnt6DList> list = new List<Pnt6DList>();
		Pnt6DList pnt6DList = new Pnt6DList();
		for (int i = 0; i <= GCodePoits.Count - 1; i++)
		{
			pnt6DList.Points.Add(new Pnt6D(GCodePoits[i].Positions.X, GCodePoits[i].Positions.Y, GCodePoits[i].Positions.Z, GCodePoits[i].Positions.A + 90.0, 0.0, GCodePoits[i].Positions.C));
		}
		list.Add(pnt6DList);
		MarbleSawCalcParameters marbleSawCalcParameters = new MarbleSawCalcParameters();
		marbleSawCalcParameters.DevideLength = 0.0;
		marbleSawCalcParameters.ShiftEnable = false;
		marbleSawCalcParameters.SplineEnable = false;
		marbleCam.CamBase = new camTp();
		clsInit.cMarble.SawExistingToolPointCamCenterCalc(ref MI, ref marbleCam, marbleSawCalcParameters, list, UseKinematic: true, activeKinematic);
		marbleCam.CamBase.Tool = new ToolBase5(Tool);
		marbleCam.CamBase.TypeCam = CamType.MillingCut;
		MI.CamList.Add(marbleCam);
		marbleCam.isCamCalculated = true;
	}

	public void doAddCamItemContour(bool isText, bool isMilling, bool isMillingHead, bool isWaterJet, int JobListIndex)
	{
		bool flag = true;
		if (isText & buMarbleCalc.varMarbleRunSettings.BorderEnable)
		{
			if (MarbleTempVars.ItemsContour.Count > 0 && MarbleTempVars.ItemsContour[0].ItemEntities.SolidEntity.Count > 0)
			{
				MarbleTempVars.ItemsContour[0].ItemEntities.SolidEntity.RemoveAt(0);
			}
			flag = false;
		}
		AddOperationBeforeThings();
		if (!flag)
		{
			if (MarbleTempVars.ItemsContour.Count <= 0)
			{
				return;
			}
			MarbleItem Item = new MarbleItem(MarbleTempVars.ItemsContour[0]);
			Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			MarbleItemCam marbleItemCam = new MarbleItemCam();
			Item.ItemType = MarbleItemType.Text;
			Item.EntGroup = new buEntitiesGroup();
			Item.EntGroup.Inside = new List<buEntityList>();
			int num = 0;
			for (int i = 0; i <= MarbleTempVars.ItemsContour.Count - 1; i++)
			{
				if (num != 0)
				{
					Item.EntGroup.Inside.Add(new buEntityList(MarbleTempVars.ItemsContour[i].EntGroup.Outside));
				}
				else
				{
					Item.EntGroup.Outside = new buEntityList(MarbleTempVars.ItemsContour[i].EntGroup.Outside);
				}
				if (MarbleTempVars.ItemsContour[i].EntGroup.Inside != null)
				{
					for (int j = 0; j <= MarbleTempVars.ItemsContour[i].EntGroup.Inside.Count - 1; j++)
					{
						Item.EntGroup.Inside.Add(new buEntityList(MarbleTempVars.ItemsContour[i].EntGroup.Inside[j]));
					}
				}
				if (MarbleTempVars.ItemsContour[i].EntGroup.OpenEntities != null)
				{
					if (Item.EntGroup.OpenEntities == null)
					{
						Item.EntGroup.OpenEntities = new List<buEntityList>();
					}
					for (int k = 0; k <= MarbleTempVars.ItemsContour[i].EntGroup.OpenEntities.Count - 1; k++)
					{
						Item.EntGroup.OpenEntities.Add(new buEntityList(MarbleTempVars.ItemsContour[i].EntGroup.OpenEntities[k]));
					}
				}
				num++;
			}
			CamWireFrameType selectedWireframeType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			new CustomData();
			marbleItemCam = new MarbleItemCam();
			marbleItemCam.CamName = buLangTranslate.preDef.Milling + " " + clsInit.cCam5.CamWireframeTypeToString(selectedWireframeType) + " " + buLangTranslate.preDef.Cut;
			marbleItemCam.CamMarbleType = MarbleCamType.Contour;
			marbleItemCam.CamMode = MarbleCamMode.Contour;
			marbleItemCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DContour.buPar);
			marbleItemCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
			marbleItemCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			marbleItemCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
			marbleItemCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(selectedWireframeType);
			marbleItemCam.ToolSelected = FindToolFromType(marbleItemCam.ToolType);
			clsInit.cMarble.GetCamID(activeJob, ref marbleItemCam.CamID);
			Item.CamList.Add(marbleItemCam);
			Item.ToolType = MarbleToolType.Milling;
			doShapeCutCalculation(ref Item);
			doAddItemCommonProps(ref Item);
			if (Item.ItemEntities.SolidEntity != null)
			{
				clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
			}
			if (JobListIndex != -1)
			{
				if (JobListIndex <= activeJob.Items.Count - 1)
				{
					activeJob.Items[JobListIndex] = Item;
				}
				return;
			}
			doAddItemToJob(Item, OperationAfterThings: false, IncreaseID: true);
			doCamCalculateMarbleItem(activeJob.Items.Count - 1, isLast: false, null, ref Item);
			if (buMarbleCalc.varMarbleSettings.AutoMagnet)
			{
				MarbleSelectionItems marbleSelectionItems = new MarbleSelectionItems();
				marbleSelectionItems.ItemID = Item.ID;
				marbleSelectionItems.indexItem = activeJob.Items.Count - 1;
				marbleSelectionItems.pntMin = buVector5.ToPoint3D(Item.SizeItem.MinPoint);
				marbleSelectionItems.pntMax = buVector5.ToPoint3D(Item.SizeItem.MaxPoint);
				marbleSelectionItems.MI = Item;
				buMarbleCalc.SelectedItem.SelectionItems.Add(marbleSelectionItems);
				doAlignment(MarbleCadCamCommands.MagnetLeftDown, 0.0);
			}
			return;
		}
		for (int l = 0; l <= MarbleTempVars.ItemsContour.Count - 1; l++)
		{
			MarbleItem MI = new MarbleItem(MarbleTempVars.ItemsContour[l]);
			MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			new CustomData();
			if (!isText)
			{
				MI.ItemType = MarbleItemType.Contour;
			}
			else
			{
				MI.ItemType = MarbleItemType.Text;
			}
			CamWireFrameType selectedWireframeType2 = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
			MarbleItemCam marbleItemCam2 = null;
			if (!(isMilling || isMillingHead))
			{
				if (!isWaterJet)
				{
					if (buMarbleCalc.varOperation.settingMarbleCam.isInsideFirst)
					{
						ToolBase5 toolSaw = FindToolFromType(MarbleToolType.Saw);
						clsInit.cMarble.CreateInsideCutCamItem(activeJob, ref MI, toolSaw, buMWMarbleVars.varCamMarbleMilling2DContour.buPar);
					}
					marbleItemCam2 = new MarbleItemCam();
					marbleItemCam2.CamName = buLangTranslate.preDef.Outside + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.Saw + "]";
					marbleItemCam2.CamMarbleType = MarbleCamType.ContourSawOutsideCut;
					marbleItemCam2.CamMode = MarbleCamMode.Contour;
					marbleItemCam2.setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar);
					clsInit.cMarble.GetCamID(activeJob, MI.CamList, ref marbleItemCam2.CamID);
					marbleItemCam2.ItemID = MI.ID;
					marbleItemCam2.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
					marbleItemCam2.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
					marbleItemCam2.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
					marbleItemCam2.CamType = clsInit.cCam5.CamWireframeTypeToCamType(CamWireFrameType.Contour);
					marbleItemCam2.ToolSelected = FindToolFromType(marbleItemCam2.ToolType);
					marbleItemCam2.Direction = InOutCenterType.Outside;
					marbleItemCam2.EntityList = new buEntityList(MarbleTempVars.ItemsContour[l].EntGroup.Outside);
					marbleItemCam2.EntityList.InOutType = entityInOutDirectionType.Outside;
					clsInit.cMarble.CreateEdgesFromEntities(marbleItemCam2.EntityList.Entities, activeJob, MI, marbleItemCam2, Outside: true, MI.MaterialThickness, marbleItemCam2.ToolSelected.Geometry.Diameter, -1, ref MI.Edges);
					MI.CamList.Add(marbleItemCam2);
					MI.ToolType = MarbleToolType.Saw;
					if (!buMarbleCalc.varOperation.settingMarbleCam.isInsideFirst)
					{
						clsInit.cMarble.CreateInsideCutCamItem(activeJob, ref MI, marbleItemCam2.ToolSelected, buMWMarbleVars.varCamMarbleMilling2DContour.buPar);
					}
				}
				else
				{
					marbleItemCam2 = new MarbleItemCam();
					marbleItemCam2.CamName = buLangTranslate.preDef.WaterJet + " " + buLangTranslate.preDef.Contour + " " + buLangTranslate.preDef.Cut;
					marbleItemCam2.CamMarbleType = MarbleCamType.ContourWaterJet;
					marbleItemCam2.CamMode = MarbleCamMode.Contour;
					marbleItemCam2.setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar);
					marbleItemCam2.ItemID = MI.ID;
					marbleItemCam2.ID = MI.ID;
					marbleItemCam2.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
					marbleItemCam2.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
					marbleItemCam2.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
					marbleItemCam2.CamType = clsInit.cCam5.CamWireframeTypeToCamType(CamWireFrameType.Contour);
					marbleItemCam2.ToolSelected = FindToolFromType(marbleItemCam2.ToolType);
					clsInit.cMarble.GetCamID(activeJob, ref marbleItemCam2.CamID);
					MI.CamList.Add(marbleItemCam2);
					MI.ToolType = MarbleToolType.WaterJet;
				}
			}
			else
			{
				marbleItemCam2 = new MarbleItemCam();
				if (!isMilling)
				{
					marbleItemCam2.CamName = buLangTranslate.preDef.MillingHead + " " + buLangTranslate.preDef.Cutting;
				}
				else
				{
					marbleItemCam2.CamName = buLangTranslate.preDef.Milling + " " + buLangTranslate.preDef.Cutting;
				}
				marbleItemCam2.CamMarbleType = MarbleCamType.ContourMillingCut;
				marbleItemCam2.CamMode = MarbleCamMode.Contour;
				marbleItemCam2.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DContour.buPar);
				clsInit.cMarble.GetCamID(activeJob, ref marbleItemCam2.CamID);
				marbleItemCam2.ItemID = MI.ID;
				marbleItemCam2.setCam.Steps.StartValue = MI.SizeItem.MaxPoint.Z;
				marbleItemCam2.setCam.Steps.EndValue = MI.SizeItem.MaxPoint.Z - MI.SizeItem.Depth;
				marbleItemCam2.setCam.Steps.Enable = true;
				marbleItemCam2.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
				marbleItemCam2.WireType = selectedWireframeType2;
				marbleItemCam2.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
				marbleItemCam2.CamType = clsInit.cCam5.CamWireframeTypeToCamType(selectedWireframeType2);
				marbleItemCam2.ToolSelected = FindToolFromType(marbleItemCam2.ToolType);
				marbleItemCam2.EntityList = new buEntityList(MarbleTempVars.ItemsContour[l].EntGroup.Outside);
				marbleItemCam2.EntityList.InOutType = entityInOutDirectionType.Outside;
				for (int m = 0; m <= MarbleTempVars.ItemsContour[l].EntGroup.Inside.Count - 1; m++)
				{
					buEntityList buEntityList2 = new buEntityList(MarbleTempVars.ItemsContour[l].EntGroup.Inside[m]);
					buEntityList2.InOutType = entityInOutDirectionType.Inside;
					marbleItemCam2.EntityList.Entities.AddRange(buEntityList2.Entities);
				}
				clsInit.cMarble.GetCamID(activeJob, MI.CamList, ref marbleItemCam2.CamID);
				MI.CamList.Add(marbleItemCam2);
				if (!isMilling)
				{
					MI.ToolType = MarbleToolType.MillingHead;
				}
				else
				{
					MI.ToolType = MarbleToolType.Milling;
				}
			}
			doShapeCutCalculation(ref MI);
			for (int n = 0; n <= MI.CamList.Count - 1; n++)
			{
				clsInit.cMarble.EdgePropertiesFromWireEntities(MI.CamList[n].WireEntities, ref MI.Edges);
			}
			doAddItemCommonProps(ref MI);
			if (MI.ItemEntities.SolidEntity != null)
			{
				clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
			}
			doCamCalculateMarbleItem(-1, isLast: false, new TpPnt9D(), ref MI);
			if (JobListIndex != -1)
			{
				if (JobListIndex <= activeJob.Items.Count - 1)
				{
					activeJob.Items[JobListIndex] = MI;
				}
				continue;
			}
			doAddItemToJob(MI, OperationAfterThings: true, IncreaseID: true);
			if (buMarbleCalc.varMarbleSettings.AutoMagnet)
			{
				MarbleSelectionItems marbleSelectionItems2 = new MarbleSelectionItems();
				marbleSelectionItems2.ItemID = MI.ID;
				marbleSelectionItems2.indexItem = activeJob.Items.Count - 1;
				marbleSelectionItems2.pntMin = buVector5.ToPoint3D(MI.SizeItem.MinPoint);
				marbleSelectionItems2.pntMax = buVector5.ToPoint3D(MI.SizeItem.MaxPoint);
				marbleSelectionItems2.MI = MI;
				buMarbleCalc.SelectedItem.SelectionItems.Add(marbleSelectionItems2);
				doAlignment(MarbleCadCamCommands.MagnetLeftDown, 0.0);
			}
		}
	}

	public void doAddItemToJob(MarbleItem MI, bool OperationAfterThings, bool IncreaseID, int AddIndex = -1)
	{
		if (MI.EntGroup != null && MI.EntGroup.Outside != null && MI.EntGroup.Outside.Entities.Count > 0)
		{
			if (MI.EntGroup.Outside.Points != null)
			{
				if (MI.EntGroup.Outside.Points.Count == 0)
				{
					clsInit.cVector5.EntitiesToPointsWithCamDirection(MI.EntGroup.Outside.Entities, ref MI.EntGroup.Outside.Points);
				}
			}
			else
			{
				MI.EntGroup.Outside.Points = new List<Point3D>();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(MI.EntGroup.Outside.Entities, ref MI.EntGroup.Outside.Points);
			}
		}
		if (MI.EntGroup != null && MI.EntGroup.Outside != null && MI.EntGroup.Outside.Entities.Count > 0)
		{
			MI.EntGroup.Outside.pntMassCenter = clsInit.cVector5.CalculateCentroid(MI.EntGroup.Outside.Points);
		}
		AddOPToJobList(MI, activeJob.Items.Count);
		if (!((AddIndex == -1) | (activeJob.Items.Count == 0) | (AddIndex > activeJob.Items.Count - 1)))
		{
			activeJob.Items.Insert(AddIndex, MI);
		}
		else
		{
			activeJob.Items.Add(MI);
		}
		activeJob.CamCalculated = false;
		if (IncreaseID)
		{
			MarbleTempVars.ItemID++;
		}
		if (OperationAfterThings)
		{
			AddOperationAfterThings();
		}
		if (activeJob.Material == null)
		{
			activeJob.Material = new MaterialBase5();
		}
	}

	public void doAddItemShapeContour(Point3D pntActive, bool isShape, bool isFinished, bool isText, bool isMilling, bool isMillingHead, bool isWaterJet, bool isCamCalc, int JobListIndex)
	{
		string text = "doAddItemShapeContour";
		try
		{
			if (activeJob == null)
			{
				activeJob = new MarbleJob();
			}
			int num = 1;
			int num2 = 1;
			double num3 = 0.0;
			num3 = ((buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.Milling) ? buMarbleCalc.activeToolMilling.Geometry.Diameter : ((buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.MillingHead) ? buMarbleCalc.activeToolMillingHead.Geometry.Diameter : ((buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.WaterJet) ? buMarbleCalc.activeToolWaterjet.Geometry.Diameter : buMarbleCalc.activeToolSaw.Geometry.Thickness)));
			if (buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayEnable)
			{
				num = (int)buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayXCount;
				num2 = (int)buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayYCount;
			}
			if (!isShape)
			{
				MarbleToolType marbleToolType = MarbleToolType.Saw;
				marbleToolType = (isMilling ? MarbleToolType.Milling : (isWaterJet ? MarbleToolType.WaterJet : (isMillingHead ? MarbleToolType.MillingHead : MarbleToolType.Saw)));
				MarbleTempVars.ItemsContour.Clear();
				if (isText)
				{
					CreateTextContour(pntActive, entitiesGroupForContour, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref MarbleTempVars.ItemsContour, marbleToolType);
				}
				else
				{
					CreateShapeContour(pntActive, entitiesGroupForContour, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref MarbleTempVars.ItemsContour, marbleToolType, isText);
				}
			}
			else
			{
				MarbleTempVars.ItemsContour.Clear();
				Point3D MinPoint = new Point3D();
				Point3D MidPoint = new Point3D();
				Point3D MaxPoint = new Point3D();
				clsInit.cVector5.BoxSizeCalculate(clsInit.appMarble.entitiesForMove[0], ref MinPoint, ref MidPoint, ref MaxPoint);
				double num4 = MaxPoint.X - MinPoint.X + num3 + buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayXDistance;
				double num5 = MaxPoint.Y - MinPoint.Y + num3 + buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayYDistance;
				for (int i = 0; i <= num - 1; i++)
				{
					for (int j = 0; j <= num2 - 1; j++)
					{
						Point3D refPoint = new Point3D(pntActive.X + (double)i * num4, pntActive.Y + (double)j * num5, pntActive.Z);
						MarbleItem Item = new MarbleItem();
						if (!isMilling)
						{
							if (!isWaterJet)
							{
								if (!isMillingHead)
								{
									Item.ToolType = MarbleToolType.Saw;
								}
								else
								{
									Item.ToolType = MarbleToolType.MillingHead;
								}
							}
							else
							{
								Item.ToolType = MarbleToolType.WaterJet;
							}
						}
						else
						{
							Item.ToolType = MarbleToolType.Milling;
						}
						CreateShape(refPoint, clsInit.appMarble.ShapeType, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref Item, Item.ToolType);
						MarbleTempVars.ItemsContour.Add(Item);
					}
				}
			}
			if (isFinished)
			{
				doAddCamItemContour(isText, isMilling, isMillingHead, isWaterJet, JobListIndex);
				clsInit.appCommand.Reset();
				AddOperationAfterThings();
			}
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Exception");
		}
	}

	public void doAddItemCommonProps(ref MarbleItem Item)
	{
		string text = "doAddItemCommonProps";
		try
		{
			Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
			if (Item.ID < 0)
			{
				Item.ID = MarbleTempVars.ItemID;
			}
			if (Item.ItemEntities.SolidEntity != null)
			{
				for (int i = 0; i <= Item.ItemEntities.SolidEntity.Count - 1; i++)
				{
					CustomData customData = new CustomData();
					customData.typeDefination = entityTypeDefination.MarbleItem;
					customData.RefIndex = activeJob.Items.Count;
					Item.ItemEntities.SolidEntity[i].EntityData = customData;
				}
				clsInit.cMarble.ItemSizeCalculation(ref Item);
				clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: false, CamItems: false, -1, ref clsInit.appMarble.activeJob);
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doCheckItemWarningAndErrors(ref MarbleItem Item)
	{
		Item.ErrorMessages.Clear();
		Item.WarningMessages.Clear();
		if (Item.ItemEntities == null || Item.ItemEntities.WireEntities == null)
		{
			return;
		}
		for (int i = 0; i <= Item.ItemEntities.WireEntities.Count - 1; i++)
		{
			for (int j = 0; j <= Item.ItemEntities.WireEntities[i].Count - 1; j++)
			{
				if (Math.Abs(Item.ItemEntities.WireEntities[i][j].Orientation.A) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
				{
					Item.ErrorMessages.Add(buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit);
				}
				if (Item.ItemEntities.WireEntities[i][j].Info.Enable)
				{
				}
			}
		}
	}

	public void AddOperationBeforeThings()
	{
		UndoBuffer();
	}

	public void AddOperationAfterThings()
	{
		activeJob.isSimulationDone = false;
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: false, -1, ref clsInit.appMarble.activeJob);
		SaveMarbleFile();
		JobUpdate();
		doDrawActiveJob();
		MarbleItemOsnapCalculations();
	}

	public void doSelectSwitchItemByID(int ID)
	{
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			CustomData customData = entity.EntityData as CustomData;
			if (!((customData.typeDefination == entityTypeDefination.MarbleItem) & (customData.ID.Trim().Length >= 0) & (customData.Tags == "Solid") & clsInit.cVector5.isEntity3D(entity)))
			{
				continue;
			}
			int result = -1;
			int.TryParse(customData.ID, out result);
			if (result >= 0 && result == ID)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = false;
				}
				else
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
				}
