	public bool doIsSelectedItemAvailableInList(int ID)
	{
		for (int i = 0; i <= buMarbleCalc.SelectedItem.SelectionItems.Count - 1; i++)
		{
			if (buMarbleCalc.SelectedItem.SelectionItems[i].ItemID == ID)
			{
				return true;
