	public void doUpdateSelectionFromSelectedItem()
	{
		buMarbleCalc.SelectedItem.SelectionItems.Clear();
		buMarbleCalc.SelectedItem.pntTotalMin = new Point3D();
		buMarbleCalc.SelectedItem.pntTotalMax = new Point3D();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (entity.EntityData == null || !(entity.EntityData is CustomData))
			{
				continue;
			}
			CustomData customData = entity.EntityData as CustomData;
			int result = -1;
			int.TryParse(customData.ID, out result);
			if ((result >= 1) & (customData.typeDefination == entityTypeDefination.MarbleItem) & (customData.Tags == "Solid") & entity.Selected)
			{
				MarbleItem MI = null;
				clsInit.cMarble.GetMarbleItemByID(activeJob, result, ref MI);
				if (MI != null)
				{
					MI.Selected = entity.Selected;
				}
				MarbleSelectionItems marbleSelectionItems = new MarbleSelectionItems();
				marbleSelectionItems.ItemID = MI.ID;
				clsInit.cMarble.GetMarbleItemByID(activeJob, result, ref MI, ref marbleSelectionItems.indexItem);
				marbleSelectionItems.pntMin = buVector5.ToPoint3D(MI.SizeItem.MinPoint);
				marbleSelectionItems.pntMax = buVector5.ToPoint3D(MI.SizeItem.MaxPoint);
				marbleSelectionItems.MI = MI;
				buMarbleCalc.SelectedItem.SelectionItems.Add(marbleSelectionItems);
			}
		}
		if (okCommandWithFiveDataEventHandler_1 != null && buMarbleCalc.SelectedItem.SelectionItems.Count > 0)
		{
			okCommandWithFiveDataEventHandler_1(MarbleEventCommands.SelectionUpdate, null, null, null, null);
			AppBool.EditMode = true;
		}
	}

	public void doShapeCutCalculation(ref MarbleItem Item)
	{
		string text = "doShapeCutCalculation";
		try
		{
			for (int num = Item.CamList.Count - 1; num >= 0; num--)
			{
				if (Item.CamList[num].isTempCam)
				{
					Item.CamList.RemoveAt(num);
				}
			}
			int count = Item.CamList.Count;
			double ToolThickness = 0.0;
			clsInit.cMarble.GetToolThickness(Item.ToolType, ref ToolThickness);
			clsInit.cMarble.ItemOsnapCalculation(ref Item, MarbleOsnapCalcType.FromOffsetValue, ToolThickness);
			doCheckItemWarningAndErrors(ref Item);
			List<MarbleItemCam> list = new List<MarbleItemCam>();
			List<MarbleItemCam> list2 = new List<MarbleItemCam>();
			List<MarbleItemCam> list3 = new List<MarbleItemCam>();
			for (int i = 0; i <= count - 1; i++)
			{
				MarbleItemCam CamItem = Item.CamList[i];
				if (CamItem.ToolType != MarbleToolType.Saw)
				{
					if (!((CamItem.ToolType == MarbleToolType.Milling) | (CamItem.ToolType == MarbleToolType.MillingHead)))
					{
						if (CamItem.ToolType == MarbleToolType.WaterJet)
						{
							doShapeWaterJetCamCalc(ref Item, ref CamItem);
						}
					}
					else
					{
						doShapeMillingCamCalc(ref Item, ref CamItem);
					}
					continue;
				}
				buMWMarbleVars.varCamMarbleClosedContourSaw.buPar.Operations.TargetZ = buMarbleCalc.varOperation.settingMarbleCam.TargetZ;
				buMWMarbleVars.varCamMarbleClosedContourSaw.buPar.Steps.Enable = false;
				if (buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance < buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
				{
					buMWMarbleVars.varCamMarbleClosedContourSaw.buPar.Steps.Enable = true;
					buMWMarbleVars.varCamMarbleClosedContourSaw.buPar.Steps.StepType = CamStepType.StartToEndByCount;
					buMWMarbleVars.varCamMarbleClosedContourSaw.buPar.Steps.Step = buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance;
					buMWMarbleVars.varCamMarbleClosedContourSaw.buPar.Steps.StartValue = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
					buMWMarbleVars.varCamMarbleClosedContourSaw.buPar.Steps.EndValue = buMarbleCalc.varOperation.settingMarbleCam.TargetZ;
					buMWMarbleVars.varCamMarbleClosedContourSaw.buPar.Steps.Count = Convert.ToInt32(buMarbleCalc.varOperation.MaterialParameter.MaterialThickness / buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance);
				}
				doShapeSawCutCalc(ref Item, ref CamItem, buMarbleCalc.activeToolSaw);
				if (CamItem.ConcaveEntities != null && ((CamItem.ConcaveEntities.Count > 0) & (Item.Settings.settingMarbleCam.ConcaveCuttingType == MarbleConcaveCuttingType.Milling)))
				{
					MarbleItemCam marbleCam = new MarbleItemCam();
					buEntity.Copy(CamItem.ConcaveEntities, ref marbleCam.ConcaveEntities);
					CamItem.ConcaveEntities.Clear();
					if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool != MarbleCornerCleanToolType.MillingHead)
					{
						if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool != MarbleCornerCleanToolType.Waterjet)
						{
							marbleCam.CamName = buLangTranslate.preDef.Concave + " " + buLangTranslate.preDef.Corner + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.Milling + "]";
							marbleCam.ToolType = MarbleToolType.Milling;
							marbleCam.ToolSelected = buMarbleCalc.activeToolMilling;
						}
						else
						{
							marbleCam.CamName = buLangTranslate.preDef.Concave + " " + buLangTranslate.preDef.Corner + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.WaterJet + "]";
							marbleCam.ToolType = MarbleToolType.WaterJet;
							marbleCam.ToolSelected = buMarbleCalc.activeToolWaterjet;
						}
					}
					else
					{
						marbleCam.CamName = buLangTranslate.preDef.Concave + " " + buLangTranslate.preDef.Corner + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.MillingHead + "]";
						marbleCam.ToolType = MarbleToolType.MillingHead;
						marbleCam.ToolSelected = buMarbleCalc.activeToolMillingHead;
					}
					MarbleCamParameterSetArg data = new MarbleCamParameterSetArg
					{
						MarbleCamType = MarbleCamType.CornerConcaveByMilling,
						MarbleCamMode = MarbleCamMode.Contour,
						GeneralCamType = CamType.ContourOpen,
						ToolType = marbleCam.ToolType
					};
					SetMillingCamParameter(data, ref marbleCam);
					marbleCam.setCam.Offsets.ClosedContour = CamClosedContourType.Inner;
					marbleCam.isConcave = true;
					marbleCam.isTempCam = true;
					clsInit.cMarble.GetCamID(activeJob, ref marbleCam.CamID);
					marbleCam.ItemID = Item.ID;
					list.Add(marbleCam);
					doConcaveCamCalc(Item, isConcave: true, ref marbleCam);
				}
				if (CamItem.DrillEntities != null && ((CamItem.DrillEntities.Count > 0) & ((Item.Settings.settingMarbleCam.ConcaveCuttingType == MarbleConcaveCuttingType.Drill) | (Item.Settings.settingMarbleCam.ConvexCuttingType == MarbleConcaveCuttingType.Drill))))
				{
					MarbleItemCam marbleCam2 = new MarbleItemCam();
					buEntity.Copy(CamItem.DrillEntities, ref marbleCam2.DrillEntities);
					CamItem.ConcaveEntities.Clear();
					marbleCam2.CamMarbleType = MarbleCamType.CornerCleanByDrill;
					marbleCam2.CamMode = MarbleCamMode.Drill;
					marbleCam2.setCam = new camParameters5(buMWMarbleVars.varCamMarbleHole.buPar);
					if (Item.Settings.settingMarbleCam.DefaultDrillTool != MarbleMillingToolType.MillingHead)
					{
						marbleCam2.CamName = buLangTranslate.preDef.Concave + " " + buLangTranslate.preDef.Corner + " " + buLangTranslate.preDef.Drill + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.Milling + "]";
						marbleCam2.ToolType = MarbleToolType.Milling;
						marbleCam2.ToolSelected = buMarbleCalc.activeToolMilling;
					}
					else
					{
						marbleCam2.CamName = buLangTranslate.preDef.Concave + " " + buLangTranslate.preDef.Corner + " " + buLangTranslate.preDef.Drill + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.MillingHead + "]";
						marbleCam2.ToolType = MarbleToolType.MillingHead;
						marbleCam2.ToolSelected = buMarbleCalc.activeToolMillingHead;
					}
					marbleCam2.WireType = CamWireFrameType.Contour;
					marbleCam2.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
					marbleCam2.CamType = CamType.Drill;
					marbleCam2.isDrill = true;
					marbleCam2.isTempCam = true;
					clsInit.cMarble.GetCamID(activeJob, ref marbleCam2.CamID);
					marbleCam2.ItemID = Item.ID;
					list3.Add(marbleCam2);
					doDrillCamCalc(CamItem.DrillEntities, Item, ref marbleCam2);
					if (marbleCam2.CamBase != null)
					{
						marbleCam2.CamBase.TypeCam = CamType.CornerCleanByDrill;
						marbleCam2.CamBase.Sequnce = CamSequence.ContourConvexDrill;
						marbleCam2.CamBase.Obj1 = Item;
						marbleCam2.CamBase.Obj2 = CamItem;
						marbleCam2.CamBase.Name = CamItem.CamName;
					}
					if (Item.ItemEntities.DrawWireEntities == null)
					{
						Item.ItemEntities.DrawWireEntities = new List<buEntity>();
					}
					Item.ItemEntities.DrawWireEntities.Clear();
					for (int j = 0; j <= CamItem.DrillEntities.Count - 1; j++)
					{
						Entity copiedEntity = null;
						Entity entity = null;
						buEntity.Copy(CamItem.DrillEntities[j], ref copiedEntity);
						ICurve[] array = ((ICurve)copiedEntity).Offset(-4.0, Vector3D.AxisZ);
						if (array == null || array.Length == 0)
						{
							buEntity copiedEntity2 = null;
							buEntity.Copy(CamItem.DrillEntities[j], ref copiedEntity2);
							Item.ItemEntities.DrawWireEntities.Add(copiedEntity2);
							continue;
						}
						List<ICurve> list4 = new List<ICurve>();
						entity = (Entity)array[0];
						list4.Add((ICurve)copiedEntity);
						list4.Add((ICurve)entity);
						entity = (Entity)array[0];
						devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(list4, Plane.XY);
						Mesh mesh = region.ExtrudeAsMesh(2.0, 0.05, Mesh.natureType.RichSmooth);
						mesh.Selectable = false;
						mesh.Color = buMarbleCalc.varMarbleColorSettings.colorItemHole.Color;
						Item.ItemEntities.SolidEntity.Add(mesh);
					}
				}
				if (CamItem.ConvexEntities == null || !((CamItem.ConvexEntities.Count > 0) & ((Item.Settings.settingMarbleCam.ConvexCuttingType == MarbleConcaveCuttingType.Milling) | buMarbleCalc.varOperation.settingMarbleCam.OutsideArcCuttingByMilling)))
				{
					continue;
				}
				MarbleItemCam marbleCam3 = new MarbleItemCam();
				buEntity.Copy(CamItem.ConvexEntities, ref marbleCam3.ConvexEntities);
				CamItem.ConvexEntities.Clear();
				marbleCam3.CamName = buLangTranslate.preDef.Contour + " " + buLangTranslate.preDef.Convex + " " + buLangTranslate.preDef.Cleaning + " " + buLangTranslate.preDef.Shape + " " + buLangTranslate.preDef.Cut;
				if (!((buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool == MarbleCornerCleanToolType.Milling) | buMarbleCalc.varOperation.settingMarbleCam.OutsideArcCuttingByMilling))
				{
					if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool != MarbleCornerCleanToolType.MillingHead)
					{
						marbleCam3.ToolType = MarbleToolType.Milling;
						marbleCam3.CamName = buLangTranslate.preDef.Convex + " " + buLangTranslate.preDef.Corner + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.Milling + "]";
						marbleCam3.ToolSelected = buMarbleCalc.activeToolMilling;
					}
					else
					{
						marbleCam3.ToolType = MarbleToolType.MillingHead;
						marbleCam3.CamName = buLangTranslate.preDef.Convex + " " + buLangTranslate.preDef.Corner + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.MillingHead + "]";
						marbleCam3.ToolSelected = buMarbleCalc.activeToolMillingHead;
					}
				}
				else
				{
					marbleCam3.ToolType = MarbleToolType.Milling;
					marbleCam3.CamName = buLangTranslate.preDef.Convex + " " + buLangTranslate.preDef.Corner + " " + buLangTranslate.preDef.Cutting + " [" + buLangTranslate.preDef.Milling + "]";
					marbleCam3.ToolSelected = buMarbleCalc.activeToolMilling;
				}
				MarbleCamParameterSetArg data2 = new MarbleCamParameterSetArg
				{
					MarbleCamType = MarbleCamType.CornerConvexByMilling,
					MarbleCamMode = MarbleCamMode.Contour,
					GeneralCamType = CamType.ContourOpen,
					ToolType = marbleCam3.ToolType
				};
				SetMillingCamParameter(data2, ref marbleCam3);
				marbleCam3.isConvex = true;
				marbleCam3.isTempCam = true;
				clsInit.cMarble.MarbleCamParameterToCamParameter(buMarbleCalc.varOperation.settingMarbleCam, marbleCam3.ToolType, marbleCam3.WireType, ref marbleCam3.setCam);
				clsInit.cMarble.GetCamID(activeJob, ref marbleCam3.CamID);
				marbleCam3.ItemID = Item.ID;
				list2.Add(marbleCam3);
				doConcaveCamCalc(Item, isConcave: false, ref marbleCam3);
			}
			if (list2.Count > 0)
			{
				for (int k = 0; k <= list2.Count - 1; k++)
				{
					Item.CamList.Insert(0, list2[k]);
				}
			}
			if (list.Count > 0)
			{
				for (int l = 0; l <= list.Count - 1; l++)
				{
					Item.CamList.Insert(0, list[l]);
				}
			}
			if (list3.Count > 0)
			{
				for (int m = 0; m <= list3.Count - 1; m++)
				{
					Item.CamList.Insert(0, list3[m]);
				}
			}
			clsInit.cMarble.ItemOsnapCalculation(ref Item, MarbleOsnapCalcType.OffsetFromToolGeometry, -1.0);
			if (Item.ErrorMessages.Count > 0)
			{
				DialogBoxList dialogBoxList = new DialogBoxList();
				dialogBoxList.Caption = buLangTranslate.preDef.Marble + " " + buLangTranslate.preDef.Item + " " + buLangTranslate.preDef.Error;
				dialogBoxList.Width = 500;
				dialogBoxList.Items.AddRange(Item.ErrorMessages);
				dialogBoxList.Init("", 0);
				dialogBoxList.ShowDialog();
			}
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Exception");
		}
	}

	public int doShapeSawCutCalc(ref MarbleItem Item, ref MarbleItemCam CamItem, ToolBase5 toolSaw)
	{
		string text = "doShapeCutCalc";
		try
		{
			Item.ErrorMessages.Clear();
			Item.WarningMessages.Clear();
			if (Item.ItemEntities.ExtensionEntities == null)
			{
				Item.ItemEntities.ExtensionEntities = new List<buEntity>();
			}
			Item.ItemEntities.ExtensionEntities.Clear();
			Item.ItemEntities.ExtensionEntities = new List<buEntity>();
			if (Item.ItemEntities.CamEntities == null)
			{
				Item.ItemEntities.CamEntities = new List<List<buEntity>>();
			}
			Item.ItemEntities.CamEntities.Clear();
			Item.ItemEntities.CamEntities = new List<List<buEntity>>();
			new camTp();
			if (CamItem.WireEntities == null)
			{
				CamItem.WireEntities = new List<List<buEntity>>();
			}
			if (CamItem.ConcaveEntities == null)
			{
				CamItem.ConcaveEntities = new List<List<buEntity>>();
			}
			if (CamItem.ConvexEntities == null)
			{
				CamItem.ConvexEntities = new List<List<buEntity>>();
			}
			if (((buMarbleCalc.varOperation.settingMarbleCam.ConcaveCuttingType == MarbleConcaveCuttingType.Drill) | (buMarbleCalc.varOperation.settingMarbleCam.ConvexCuttingType == MarbleConcaveCuttingType.Drill)) && CamItem.DrillEntities == null)
			{
				CamItem.DrillEntities = new List<buEntity>();
			}
			CamItem.WireEntities.Clear();
			CamItem.ConcaveEntities.Clear();
			CamItem.ConvexEntities.Clear();
			marbleConvexConcaveCalculationPars marbleConvexConcaveCalculationPars2 = new marbleConvexConcaveCalculationPars();
