									CamItem.DrillEntities.Add(new buCircle(new Point3D(EndPnt12.X, EndPnt12.Y, EndPnt12.Z), toolBase2.Geometry.Diameter / 2.0));
								}
							}
							else
							{
								double num22 = Point3D.Distance(((ICurve)list4[num16]).StartPoint, array6[0]);
								double num23 = Point3D.Distance(((ICurve)list4[num16]).EndPoint, array6[0]);
								double num24 = Point3D.Distance(((ICurve)list5[num17]).StartPoint, array6[0]);
								double num25 = Point3D.Distance(((ICurve)list5[num17]).EndPoint, array6[0]);
								if (!(num23 < num22))
								{
									Point3D EndPnt13 = new Point3D();
									double angle13 = clsInit.cVector5.PointAngle(((ICurve)list4[num16]).EndPoint, ((ICurve)list4[num16]).StartPoint, Plane.XY);
									clsInit.cVector5.LineWithLengthAndAngle(array6[0], toolBase2.Geometry.Diameter, angle13, ref EndPnt13);
									CamItem.DrillEntities.Add(new buCircle(new Point3D(EndPnt13.X, EndPnt13.Y, EndPnt13.Z), toolBase2.Geometry.Diameter / 2.0));
								}
