									clsInit.cVector5.LineWithLengthAndAngle(array6[0], toolBase2.Geometry.Diameter, angle14, ref EndPnt14);
									CamItem.DrillEntities.Add(new buCircle(new Point3D(EndPnt14.X, EndPnt14.Y, EndPnt14.Z), toolBase2.Geometry.Diameter / 2.0));
								}
								CamItem.DrillEntities.Add(new buCircle(new Point3D(array6[0].X, array6[0].Y, array6[0].Z), toolBase2.Geometry.Diameter / 2.0));
								if (!(num25 < num24))
								{
									Point3D EndPnt15 = new Point3D();
									double angle15 = clsInit.cVector5.PointAngle(((ICurve)list5[num17]).EndPoint, ((ICurve)list5[num17]).StartPoint, Plane.XY);
									clsInit.cVector5.LineWithLengthAndAngle(array6[0], toolBase2.Geometry.Diameter, angle15, ref EndPnt15);
									CamItem.DrillEntities.Add(new buCircle(new Point3D(EndPnt15.X, EndPnt15.Y, EndPnt15.Z), toolBase2.Geometry.Diameter / 2.0));
								}
								else
								{
									Point3D EndPnt16 = new Point3D();
									double angle16 = clsInit.cVector5.PointAngle(((ICurve)list5[num17]).StartPoint, ((ICurve)list5[num17]).EndPoint, Plane.XY);
									clsInit.cVector5.LineWithLengthAndAngle(array6[0], toolBase2.Geometry.Diameter, angle16, ref EndPnt16);
									CamItem.DrillEntities.Add(new buCircle(new Point3D(EndPnt16.X, EndPnt16.Y, EndPnt16.Z), toolBase2.Geometry.Diameter / 2.0));
								}
							}
						}
					}
				}
				CamItem.ConvexEntities.Clear();
			}
			return 1;
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
