			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Exception");
		}
	}

	public void doConcaveCamCalc(MarbleItem Item, bool isConcave, ref MarbleItemCam marbleCam)
	{
		string text = "doConcaveCamCalc";
		try
		{
			if (marbleCam.isCamCalculated || !activeJob.isMillingAvailable || buMarbleCalc.activeToolMilling == null)
			{
				return;
			}
			MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
			mWCalculationOptions.NumberofAxis = 3;
			mWCalculationOptions.CamWireframeType = CamWireFrameType.Contour;
			mWCalculationOptions.Mode = CamMode.WireFrame;
			mWCalculationOptions.DontApplyReset = true;
			mWCalculationOptions.isBuWireframeCalculation = false;
			mWCalculationOptions.AddToCamListInLocalCalculation = false;
			mWCalculationOptions.AddToCamListInMWCalculation = false;
			mWCalculationOptions.ShowLeadInOutPage = false;
			mWCalculationOptions.DontShowDialogBox = true;
			ToolBase5 toolBase = null;
			if (!isConcave)
			{
				if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool != MarbleCornerCleanToolType.MillingHead)
				{
					if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool != MarbleCornerCleanToolType.Waterjet)
					{
						if (buMarbleCalc.varOperation.settingMarbleCam.DefaultMillingTool != MarbleMillingToolType.Milling)
						{
							marbleCam.ToolType = MarbleToolType.MillingHead;
							toolBase = new ToolBase5(buMarbleCalc.activeToolMillingHead);
						}
						else
						{
							marbleCam.ToolType = MarbleToolType.Milling;
							toolBase = new ToolBase5(buMarbleCalc.activeToolMilling);
						}
					}
					else
					{
						marbleCam.ToolType = MarbleToolType.WaterJet;
						toolBase = new ToolBase5(buMarbleCalc.activeToolWaterjet);
					}
				}
				else
				{
					marbleCam.ToolType = MarbleToolType.MillingHead;
					toolBase = new ToolBase5(buMarbleCalc.activeToolMillingHead);
				}
				toolBase.Geometry.Diameter = toolBase.Geometry.Diameter + buMarbleCalc.varOperation.settingMarbleCam.ConvexCornerExtraOffset * 2.0;
			}
			else
			{
				if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool != MarbleCornerCleanToolType.MillingHead)
				{
					if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool != MarbleCornerCleanToolType.Waterjet)
					{
						marbleCam.ToolType = MarbleToolType.Milling;
						toolBase = new ToolBase5(buMarbleCalc.activeToolMilling);
					}
					else
					{
						marbleCam.ToolType = MarbleToolType.WaterJet;
						toolBase = new ToolBase5(buMarbleCalc.activeToolWaterjet);
					}
				}
				else
				{
					marbleCam.ToolType = MarbleToolType.MillingHead;
					toolBase = new ToolBase5(buMarbleCalc.activeToolMillingHead);
				}
				toolBase.Geometry.Diameter = toolBase.Geometry.Diameter + buMarbleCalc.varOperation.settingMarbleCam.ConcaveCornerExtraOffset * 2.0;
			}
			camTp Cam = null;
			if (!isConcave)
			{
				if (marbleCam.ConvexEntities != null && marbleCam.ConvexEntities.Count > 0)
				{
					Cam = new camTp();
					doConcaveWireframe(mWCalculationOptions, Item, marbleCam, marbleCam.ConvexEntities, toolBase, isConcave, ref Cam);
				}
			}
			else if (marbleCam.ConcaveEntities != null && marbleCam.ConcaveEntities.Count > 0)
			{
				Cam = new camTp();
				doConcaveWireframe(mWCalculationOptions, Item, marbleCam, marbleCam.ConcaveEntities, toolBase, isConcave, ref Cam);
				Cam.Explanation = buLangTranslate.preDef.Concave + " " + buLangTranslate.preDef.Cleaning + " " + buLangTranslate.preDef.Cut;
			}
			if (Cam != null)
			{
				Cam.Explanation = buLangTranslate.preDef.Convex + " " + buLangTranslate.preDef.Cleaning + " " + buLangTranslate.preDef.Cut;
				Cam.TypeCam = CamType.CornerCleanByMilling;
				Cam.AxisCount = 3;
				marbleCam.CamBase = new camTp(Cam);
				marbleCam.CamBase.Obj1 = Item;
				marbleCam.CamBase.Obj2 = marbleCam;
				marbleCam.CamBase.OperationData = new MarbleItemSettings(Item.Settings);
				marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
				marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
				marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
				marbleCam.CamType = CamType.Contour;
				marbleMillingAnalyzePars marbleMillingAnalyzePars2 = new marbleMillingAnalyzePars();
				if (marbleCam.ToolType == MarbleToolType.MillingHead)
				{
					marbleMillingAnalyzePars2.Apply90DegreeToMillingHead = true;
				}
				AnalyzeMillingCam(marbleMillingAnalyzePars2, ref marbleCam.CamBase);
				marbleCam.isCamCalculated = true;
			}
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Exception");
		}
	}

	public void doShapeMillingCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doConcaveCamCalc";
		try
		{
			if (marbleCam.isCamCalculated || !((marbleCam.ToolType == MarbleToolType.Milling) | (marbleCam.ToolType == MarbleToolType.MillingHead)))
			{
				return;
			}
			marbleCam.CamBase = new camTp();
			clsInit.cMarble.MarbleCamParameterToCamParameter(buMarbleCalc.varOperation.settingMarbleCam, marbleCam.ToolType, marbleCam.WireType, ref marbleCam.setCam);
			MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
			mWCalculationOptions.NumberofAxis = 3;
			mWCalculationOptions.CamWireframeType = marbleCam.WireType;
			mWCalculationOptions.CamTriMeshType = marbleCam.MeshType;
			mWCalculationOptions.Mode = CamMode.WireFrame;
			mWCalculationOptions.DontApplyReset = true;
			mWCalculationOptions.isBuWireframeCalculation = false;
			mWCalculationOptions.AddToCamListInLocalCalculation = false;
			mWCalculationOptions.ShowLeadInOutPage = false;
			mWCalculationOptions.DontShowDialogBox = true;
			clsMW.CamEntities.Clear();
			clsMW.CamEntities = new List<Entity>();
			if (Item.ItemEntities.ConcaveEntities == null || Item.ItemEntities.ConcaveEntities.Count <= 0)
			{
				if (marbleCam.EntityList == null || marbleCam.EntityList.Entities.Count <= 0)
				{
					if (Item.EntGroup != null && Item.EntGroup.Outside != null)
					{
						for (int i = 0; i <= Item.EntGroup.Outside.Entities.Count - 1; i++)
						{
							Entity copiedEntity = null;
							buEntity.Copy(Item.EntGroup.Outside.Entities[i], ref copiedEntity);
							clsMW.CamEntities.Add(copiedEntity);
						}
						if (Item.EntGroup.Inside != null)
						{
							for (int j = 0; j <= Item.EntGroup.Inside.Count - 1; j++)
							{
								for (int k = 0; k <= Item.EntGroup.Inside[j].Entities.Count - 1; k++)
								{
									Entity copiedEntity2 = null;
									buEntity.Copy(Item.EntGroup.Inside[j].Entities[k], ref copiedEntity2);
									clsMW.CamEntities.Add(copiedEntity2);
								}
							}
						}
						if (Item.EntGroup.OpenEntities != null)
						{
							for (int l = 0; l <= Item.EntGroup.OpenEntities.Count - 1; l++)
							{
								for (int m = 0; m <= Item.EntGroup.OpenEntities[l].Entities.Count - 1; m++)
								{
									Entity copiedEntity3 = null;
									buEntity.Copy(Item.EntGroup.OpenEntities[l].Entities[m], ref copiedEntity3);
									clsMW.CamEntities.Add(copiedEntity3);
								}
							}
						}
					}
				}
				else
				{
					for (int n = 0; n <= marbleCam.EntityList.Entities.Count - 1; n++)
					{
						Entity copiedEntity4 = null;
						buEntity.Copy(marbleCam.EntityList.Entities[n], ref copiedEntity4);
						clsMW.CamEntities.Add(copiedEntity4);
					}
				}
			}
			else
			{
				mWCalculationOptions.CamWireframeType = CamWireFrameType.Contour;
				for (int num = 0; num <= Item.ItemEntities.ConcaveEntities.Count - 1; num++)
				{
					for (int num2 = 0; num2 <= Item.ItemEntities.ConcaveEntities[num].Count - 1; num2++)
					{
						Entity copiedEntity5 = null;
						buEntity.Copy(Item.ItemEntities.ConcaveEntities[num][num2], ref copiedEntity5);
						clsMW.CamEntities.Add(copiedEntity5);
					}
				}
			}
			if (clsMW.CamEntities.Count <= 0)
			{
				return;
			}
			ToolBase5 toolBase = null;
			toolBase = ((marbleCam.ToolType == MarbleToolType.Milling) ? new ToolBase5(buMarbleCalc.activeToolMilling) : ((marbleCam.ToolType == MarbleToolType.MillingHead) ? new ToolBase5(buMarbleCalc.activeToolMillingHead) : new ToolBase5(marbleCam.ToolSelected)));
			marbleCam.CamBase = null;
			doWireframeCamCalc(mWCalculationOptions, ref marbleCam, toolBase, ref marbleCam.CamBase, isWaterJet: false, Item.BaseHeight);
			if (marbleCam.CamBase != null)
			{
				marbleCam.CamBase.Explanation = buLangTranslate.preDef.Wireframe + " " + buLangTranslate.preDef.Cut;
				marbleCam.CamBase.TypeCam = CamType.MillingCut;
				marbleCam.CamBase.AxisCount = 3;
				marbleCam.CamBase.Obj1 = Item;
				marbleCam.CamBase.Obj2 = marbleCam;
				marbleCam.CamBase.OperationData = new MarbleItemSettings(Item.Settings);
				if (marbleCam.ToolType != MarbleToolType.Milling)
				{
					marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolMillingHead);
					marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMillingHead);
				}
				else
				{
					marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
					marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMilling);
				}
				if (marbleCam.CamPlane == planeNames.Bottom)
				{
					Point3D MinPoint = new Point3D();
					Point3D MidPoint = new Point3D();
					Point3D MaxPoint = new Point3D();
					clsInit.cVector5.BoxSizeCalculate(marbleCam.CamBase.EntitiesG1, ref MinPoint, ref MidPoint, ref MaxPoint);
					clsInit.cVector5.Rotate(new Point3D(MidPoint.X, MidPoint.Y, MidPoint.Z), 180.0, Vector3D.AxisX, ref marbleCam.CamBase.EntitiesG1);
					clsInit.cVector5.Rotate(new Point3D(MidPoint.X, MidPoint.Y, MidPoint.Z), 180.0, Vector3D.AxisX, ref marbleCam.CamBase.EntitiesG0);
					clsInit.cVector5.Rotate(new Point3D(MidPoint.X, MidPoint.Y, MidPoint.Z), 180.0, Vector3D.AxisX, ref marbleCam.CamBase.EntitiesPlunge);
					clsInit.cVector5.Rotate(new Point3D(MidPoint.X, MidPoint.Y, MidPoint.Z), 180.0, Vector3D.AxisX, ref marbleCam.CamBase.EntitiesLeave);
				}
				marbleMillingAnalyzePars marbleMillingAnalyzePars2 = new marbleMillingAnalyzePars();
				if (marbleCam.ToolType == MarbleToolType.MillingHead)
				{
					marbleMillingAnalyzePars2.Apply90DegreeToMillingHead = true;
				}
				AnalyzeMillingCam(marbleMillingAnalyzePars2, ref marbleCam.CamBase);
				marbleCam.isCamCalculated = true;
			}
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Exception");
		}
	}

	public void doShapeWaterJetCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
	{
		string text = "doCreateGCode";
		try
		{
			if (marbleCam.ToolType == MarbleToolType.WaterJet)
			{
				marbleCam.CamBase = new camTp();
				MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
				mWCalculationOptions.NumberofAxis = 3;
				mWCalculationOptions.CamWireframeType = CamWireFrameType.Contour;
				mWCalculationOptions.CamTriMeshType = marbleCam.MeshType;
				mWCalculationOptions.Mode = CamMode.WireFrame;
				mWCalculationOptions.DontApplyReset = true;
				mWCalculationOptions.isBuWireframeCalculation = false;
				mWCalculationOptions.AddToCamListInLocalCalculation = false;
				mWCalculationOptions.ShowLeadInOutPage = false;
				mWCalculationOptions.DontShowDialogBox = true;
				clsMW.CamEntities.Clear();
				buMWCalcs.OrientationLines.Clear();
				clsMW.CamEntities = new List<Entity>();
				Item.ItemEntities.DrawWireEntities = new List<buEntity>();
				camTp camTp2 = new camTp();
				camTpPoint camTpPoint2 = new camTpPoint();
				TpPnt9D tpPnt9D = new TpPnt9D();
				List<Pnt6D> list = new List<Pnt6D>();
				for (int i = 0; i <= Item.EntGroup.Outside.Entities.Count - 1; i++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(Item.EntGroup.Outside.Entities[i], ref copiedEntity);
					OrientationAngle orientationAngle = new OrientationAngle();
					orientationAngle.C = clsInit.cVector5.PointAngle(Item.EntGroup.Outside.Entities[i].EndPoint, Item.EntGroup.Outside.Entities[i].StartPoint);
					orientationAngle.A = Item.EntGroup.Outside.Entities[i].Marble.Angle;
					Point3D calcPoint = new Point3D();
					clsInit.cVector5.LineWithOrientationAngle(Item.EntGroup.Outside.Entities[i].StartPoint, orientationAngle, 50.0, ref calcPoint);
					Line item = new Line(Item.EntGroup.Outside.Entities[i].StartPoint, calcPoint);
					buMWCalcs.OrientationLines.Add(item);
					Item.ItemEntities.DrawWireEntities.Add(new buLine(Item.EntGroup.Outside.Entities[i].StartPoint, calcPoint));
					calcPoint = new Point3D();
					clsInit.cVector5.LineWithOrientationAngle(Item.EntGroup.Outside.Entities[i].EndPoint, orientationAngle, 50.0, ref calcPoint);
					item = new Line(Item.EntGroup.Outside.Entities[i].StartPoint, calcPoint);
					buMWCalcs.OrientationLines.Add(item);
					Item.ItemEntities.DrawWireEntities.Add(new buLine(Item.EntGroup.Outside.Entities[i].EndPoint, calcPoint));
					List<Point3D> Points = new List<Point3D>();
					clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.EntGroup.Outside.Entities[i], 0.01, ref Points);
					double num = 0.0;
					if (i == 0)
					{
						num = clsInit.cVector5.PointAngle(Points[1], Points[0]);
						list.Add(new Pnt6D(Points[0].X, Points[0].Y, Points[0].Z + Item.Settings.settingMarbleCam.WaterjetRapidDistance, 0.0 - Item.EntGroup.Outside.Entities[i].Marble.Angle, 0.0, num));
						list.Add(new Pnt6D(Points[0].X, Points[0].Y, Points[0].Z, 0.0 - Item.EntGroup.Outside.Entities[i].Marble.Angle, 0.0, num));
					}
					for (int j = 1; j <= Points.Count - 1; j++)
					{
						num = clsInit.cVector5.PointAngle(Points[j], new Point3D(list[list.Count - 1].X, list[list.Count - 1].Y, list[list.Count - 1].Z));
						_ = num - list[list.Count - 1].C;
						if (Item.EntGroup.Outside.Entities[i].Marble.Angle != list[list.Count - 1].A)
						{
							if (num != list[list.Count - 1].C)
							{
								list.Add(new Pnt6D(list[list.Count - 1].X, list[list.Count - 1].Y, list[list.Count - 1].Z, 0.0 - Item.EntGroup.Outside.Entities[i].Marble.Angle, 0.0, num));
							}
							list.Add(new Pnt6D(list[list.Count - 1].X, list[list.Count - 1].Y, list[list.Count - 1].Z, 0.0 - Item.EntGroup.Outside.Entities[i].Marble.Angle, 0.0, list[list.Count - 1].C));
						}
						list.Add(new Pnt6D(Points[j].X, Points[j].Y, Points[j].Z, 0.0 - Item.EntGroup.Outside.Entities[i].Marble.Angle, 0.0, num));
					}
				}
				list.Add(new Pnt6D(list[list.Count - 1].X, list[list.Count - 1].Y, list[list.Count - 1].Z + Item.Settings.settingMarbleCam.WaterjetRapidDistance, list[list.Count - 1].A, 0.0, list[list.Count - 1].C));
				for (int k = 0; k <= list.Count - 1; k++)
				{
					int type = 0;
					if (k > 0)
					{
						type = 1;
					}
					tpPnt9D = new TpPnt9D(list[k], 100.0, type);
					camTpPoint2.Points.Add(tpPnt9D);
				}
				camTp2.CamPoints.Add(camTpPoint2);
				if (Item.EntGroup.Inside != null)
				{
					for (int l = 0; l <= Item.EntGroup.Inside.Count - 1; l++)
					{
						list.Clear();
						for (int m = 0; m <= Item.EntGroup.Inside[l].Entities.Count - 1; m++)
						{
							Entity copiedEntity2 = null;
							buEntity.Copy(Item.EntGroup.Inside[l].Entities[m], ref copiedEntity2);
							OrientationAngle orientationAngle2 = new OrientationAngle();
							orientationAngle2.C = clsInit.cVector5.PointAngle(Item.EntGroup.Inside[l].Entities[m].EndPoint, Item.EntGroup.Inside[l].Entities[m].StartPoint);
							orientationAngle2.A = Item.EntGroup.Outside.Entities[l].Marble.Angle;
							Point3D calcPoint2 = new Point3D();
							clsInit.cVector5.LineWithOrientationAngle(Item.EntGroup.Inside[l].Entities[m].StartPoint, orientationAngle2, 50.0, ref calcPoint2);
							Line item2 = new Line(Item.EntGroup.Inside[l].Entities[m].StartPoint, calcPoint2);
							buMWCalcs.OrientationLines.Add(item2);
							Item.ItemEntities.DrawWireEntities.Add(new buLine(Item.EntGroup.Inside[l].Entities[m].StartPoint, calcPoint2));
							calcPoint2 = new Point3D();
							clsInit.cVector5.LineWithOrientationAngle(Item.EntGroup.Inside[l].Entities[m].EndPoint, orientationAngle2, 50.0, ref calcPoint2);
							item2 = new Line(Item.EntGroup.Outside.Entities[l].StartPoint, calcPoint2);
							buMWCalcs.OrientationLines.Add(item2);
							Item.ItemEntities.DrawWireEntities.Add(new buLine(Item.EntGroup.Inside[l].Entities[m].EndPoint, calcPoint2));
							List<Point3D> Points2 = new List<Point3D>();
							clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.EntGroup.Inside[l].Entities[m], 0.01, ref Points2);
							double num2 = 0.0;
							if (m == 0)
							{
								num2 = clsInit.cVector5.PointAngle(Points2[1], Points2[0]);
								list.Add(new Pnt6D(Points2[0].X, Points2[0].Y, Points2[0].Z + Item.Settings.settingMarbleCam.WaterjetRapidDistance, 0.0 - Item.EntGroup.Inside[l].Entities[m].Marble.Angle, 0.0, num2));
								list.Add(new Pnt6D(Points2[0].X, Points2[0].Y, Points2[0].Z, 0.0 - Item.EntGroup.Inside[l].Entities[m].Marble.Angle, 0.0, num2));
							}
							for (int n = 1; n <= Points2.Count - 1; n++)
							{
								num2 = clsInit.cVector5.PointAngle(Points2[n], new Point3D(list[list.Count - 1].X, list[list.Count - 1].Y, list[list.Count - 1].Z));
								_ = num2 - list[list.Count - 1].C;
								if (Item.EntGroup.Inside[l].Entities[m].Marble.Angle != list[list.Count - 1].A)
								{
									if (num2 != list[list.Count - 1].C)
									{
										list.Add(new Pnt6D(list[list.Count - 1].X, list[list.Count - 1].Y, list[list.Count - 1].Z, 0.0 - Item.EntGroup.Inside[l].Entities[m].Marble.Angle, 0.0, num2));
									}
									list.Add(new Pnt6D(list[list.Count - 1].X, list[list.Count - 1].Y, list[list.Count - 1].Z, 0.0 - Item.EntGroup.Inside[l].Entities[m].Marble.Angle, 0.0, list[list.Count - 1].C));
								}
								list.Add(new Pnt6D(Points2[n].X, Points2[n].Y, Points2[n].Z, 0.0 - Item.EntGroup.Inside[l].Entities[m].Marble.Angle, 0.0, num2));
							}
						}
						list.Add(new Pnt6D(list[list.Count - 1].X, list[list.Count - 1].Y, list[list.Count - 1].Z + Item.Settings.settingMarbleCam.WaterjetRapidDistance, list[list.Count - 1].A, 0.0, list[list.Count - 1].C));
						camTpPoint2 = new camTpPoint();
						for (int num3 = 0; num3 <= list.Count - 1; num3++)
						{
							int type2 = 0;
							if (num3 > 0)
							{
								type2 = 1;
							}
							tpPnt9D = new TpPnt9D(list[num3], 100.0, type2);
							camTpPoint2.Points.Add(tpPnt9D);
						}
						camTp2.CamPoints.Add(camTpPoint2);
					}
				}
				camTp2.Tool = new ToolBase5(buMarbleCalc.activeToolWaterjet);
				if (clsMW.CamEntities.Count <= 0)
				{
				}
				marbleCam.CamBase = new camTp(camTp2);
				if (marbleCam.CamBase != null)
				{
					marbleCam.CamBase.OperationData = new MarbleItemSettings(Item.Settings);
					marbleCam.CamBase.TypeCam = CamType.ContourClosedOutside;
				}
				if (marbleCam.CamBase != null)
				{
					bool flag = false;
					for (int num4 = 0; num4 <= marbleCam.CamBase.CamPoints[0].Points.Count - 1; num4++)
					{
						if (flag)
						{
							marbleCam.CamBase.CamPoints[0].Points[num4].AfterCodes.Add("M4 K" + marbleCam.ToolSelected.CamData.SpindleSpeed);
						}
						if (!flag && marbleCam.CamBase.CamPoints[0].Points[num4].PlungeAxisMovement)
						{
							flag = true;
						}
					}
				}
			}
			if (marbleCam.CamBase != null)
			{
				camTp camTp3 = marbleCam.CamBase;
				camTp3.CamID = Item.ID;
				camTp3.Post = new PostProcessor(ccVars.PostActive);
				camTp3.UsedCamPost = true;
				camTp3.Post.RepetitionDef.Tool = false;
				camTp3.Parameter = new camParameters5(marbleCam.setCam);
				camTp3.Post.ToolDef.ToolData.PreCode.Clear();
				camTp3.Post.SpindleDef.UseSpindle = true;
				camTp3.Post.AxesUsing.Z = true;
				camTp3.Post.AxesUsing.A = true;
				camTp3.Post.AxesUsing.C = true;
				marbleCam.isCamCalculated = true;
				if (!buSystem.Canceled)
				{
				}
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public int doConcaveWireframe(MWCalculationOptions MWCalcoptions, MarbleItem Item, MarbleItemCam ItemCam, List<List<buEntity>> CamEntities, ToolBase5 Tool, bool isConcave, ref camTp Cam)
	{
		string text = "doConcaveWireframe";
		try
		{
			Cam = new camTp();
			double safe = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
			double num = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
			double feed = buMarbleCalc.varOperation.settingMarbleCam.MillingCuttingVelocity;
			double plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeVelocity;
			double firstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeFirstVelocity;
			double depthStep = buMarbleCalc.varOperation.settingMarbleCam.MillingStepDown;
			double num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingFirstStepDown;
			if (ItemCam.ToolType == MarbleToolType.MillingHead)
			{
				safe = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
				num = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
				feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadCuttingVelocity;
				plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeVelocity;
				firstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeFirstVelocity;
				depthStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadStepDown;
				num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadFirstStepDown;
			}
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Runtime.SimG0DevideLength = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Runtime.SimG1DevideLength = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG1DevideLength;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar = new camParameters5(ItemCam.setCam);
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Offsets.ClosedContour = CamClosedContourType.Inner;
			if (!isConcave)
			{
				if (buMarbleCalc.varOperation.settingMarbleCam.ConcaveDirection != ClockDirectionType.CW)
				{
					buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Offsets.OpenContour = CamOpenContourType.Right;
				}
				else
				{
					buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Offsets.OpenContour = CamOpenContourType.Left;
				}
			}
			else if (buMarbleCalc.varOperation.settingMarbleCam.ConcaveDirection != ClockDirectionType.CW)
			{
				buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Offsets.OpenContour = CamOpenContourType.Left;
			}
			else
			{
				buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Offsets.OpenContour = CamOpenContourType.Right;
			}
			buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar = buMWCalcs.ConvertFromBuCamParToMwCamPar(buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar, buMWMarbleVars.varCamMarbleOpenContourMilling.buPar);
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Air = 0.0;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Safe = safe;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Rapid = num;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.EntryAndExit = num;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.EntryAndExit = num;
			if (buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Safe < buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
			{
				buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Safe = buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + 1.0;
			}
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Strategy.TangentFirstAngleGreaterThen180StartMinusAngle = true;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Speeds.Feed = feed;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Speeds.Plunge = plunge;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Speeds.FirstStep = firstStep;
			buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Steps.Enable = true;
			buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.DepthStep = depthStep;
			buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.FirstDepthStep = num2;
			buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.DepthStepMode = MachiningAreaRoughingParamsDepthStepMode.DsmConstantDepthStep;
			buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.StartHeight = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
			buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.EndHeight = buMarbleCalc.varOperation.settingMarbleCam.TargetZ;
			buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeZigzag;
			buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.MachiningAreaMode = MachiningParamsMachiningAreaMode.MachByRegions;
			if (!(num2 > 0.0))
			{
				buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.FirstDepthStepFlg = false;
			}
			else
			{
				buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.FirstDepthStepFlg = true;
			}
			clsMW.varMWCamWFContourPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar, buMWMarbleVars.varCamMarbleOpenContourMilling.buPar, out clsMW.varbuCamWFContourPars);
			clsMW.varMWCamWFContourPars.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.CuttingSide.ToString();
			buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.CuttingSide.ToString();
			clsMW.varMWCamWFContourPars.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
			clsMW.varMWCamWFContourPars.MachParam.CutTolerance = buMarbleCalc.varOperation.settingMarbleCam.CutTolerance;
			if (!buMarbleCalc.varOperation.settingMarbleCam.ToolPathPointDistributionMode)
			{
				clsMW.varMWCamWFContourPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.ToolpathOutputType = TriangleMeshBasedTpCalcParamsToolpathOutputType.TotFitArcsAndPointDistribution;
			}
			else
			{
				clsMW.varMWCamWFContourPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.ToolpathOutputType = TriangleMeshBasedTpCalcParamsToolpathOutputType.TotPolygonizeAndPointDistribution;
			}
			camResult Result = null;
			clsMW.CamEntities.Clear();
			clsMW.CamEntitiesGroup.Clear();
			clsMW.varbuCamWFContourPars.Operations.Direction = ClockDirectionType.CW;
			for (int i = 0; i <= CamEntities.Count - 1; i++)
			{
				List<Entity> ChangedEntities = new List<Entity>();
				for (int j = 0; j <= CamEntities[i].Count - 1; j++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(CamEntities[i][j], ref copiedEntity);
					if (!(CamEntities[i][j] is buCircle))
					{
						ChangedEntities.Add(copiedEntity);
						continue;
					}
					buArc Arc = new buArc();
					buArc Arc2 = new buArc();
					buArc Arc3 = new buArc();
					buArc Arc4 = new buArc();
					clsInit.cVector5.CircletoFourArc((buCircle)CamEntities[i][j], ref Arc, ref Arc2, ref Arc3, ref Arc4);
					Entity copiedEntity2 = null;
					Entity copiedEntity3 = null;
					Entity copiedEntity4 = null;
					Entity copiedEntity5 = null;
					buEntity.Copy(Arc, ref copiedEntity2);
					buEntity.Copy(Arc2, ref copiedEntity3);
					buEntity.Copy(Arc3, ref copiedEntity4);
					buEntity.Copy(Arc4, ref copiedEntity5);
					ChangedEntities.Add(copiedEntity2);
					ChangedEntities.Add(copiedEntity3);
					ChangedEntities.Add(copiedEntity4);
					ChangedEntities.Add(copiedEntity5);
				}
				if (clsInit.cVector5.EntitiesClockDirection(ChangedEntities) == ClockDirectionType.CCW)
				{
					clsInit.cVector5.ChangeEntitiesDirection(ref ChangedEntities);
				}
				clsMW.CamEntitiesGroup.Add(ChangedEntities);
			}
			MWCalcoptions.UseSortedAndSplitedEntities = true;
			int num3 = clsInit.appMW.doWireframeContour(MWCalcoptions, Tool, ref Cam, ref Result);
			if (Result.Errors.Count <= 0)
			{
				if (ItemCam.CamMarbleType != MarbleCamType.CornerConvexByMilling)
				{
					if (ItemCam.CamMarbleType != MarbleCamType.CornerConcaveByMilling)
					{
						if (ItemCam.Direction != InOutCenterType.Outside)
						{
							Cam.Sequnce = CamSequence.ContourInsideMillingCut;
						}
						else
						{
							Cam.Sequnce = CamSequence.ContourOutsideMillingCut;
						}
					}
					else
					{
						Cam.Sequnce = CamSequence.ContourConcaveMillingCut;
					}
				}
				else
				{
					Cam.Sequnce = CamSequence.ContourConvexMillingCut;
				}
				buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamWFContourPars, clsMW.varbuCamWFContourPars, out buMWMarbleVars.varCamMarbleOpenContourMilling.buPar);
				if (num3 >= 1)
				{
					Cam.Name = ItemCam.CamName;
					Cam.Mode = MWCalcoptions.Mode;
					Cam.CamWireframeType = MWCalcoptions.CamWireframeType;
					Cam.CamTriMeshType = MWCalcoptions.CamTriMeshType;
					Cam.NumberOfAxis = MWCalcoptions.NumberofAxis;
					Cam.Action = actionTypeBU.None;
					SaveMarbleFile();
					clsFiles.SaveParameter();
					return 1;
				}
				clsInit.appCommand.Reset();
				return num3;
			}
			F_ErrorList f_ErrorList = new F_ErrorList();
			f_ErrorList.Init(Result.Errors);
			f_ErrorList.ShowDialog();
			clsInit.appCommand.Reset();
			return -2;
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(string_0, text, ex.Message, "Exception");
			buException.throwException(ex, text, ShowMessageBox: true, "Exception");
			return -1;
		}
	}

	public void doWireframeCamCalc(MWCalculationOptions MWCalcoptions, ref MarbleItemCam ItemCam, ToolBase5 Tool, ref camTp Cam, bool isWaterJet = false, double ZOffset = 0.0)
	{
		string text = "doWireframeCamCalc";
		try
		{
			Cam = new camTp();
			double safe = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
			double num = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
			double feed = buMarbleCalc.varOperation.settingMarbleCam.MillingCuttingVelocity;
			double plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeVelocity;
			double firstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeFirstVelocity;
			double depthStep = buMarbleCalc.varOperation.settingMarbleCam.MillingStepDown;
			double num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingFirstStepDown;
			if (ItemCam.ToolType == MarbleToolType.MillingHead)
			{
				safe = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
				num = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
				feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadCuttingVelocity;
				plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeVelocity;
				firstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeFirstVelocity;
				depthStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadStepDown;
				num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadFirstStepDown;
			}
			MWCalcoptions.is5AxisWireframe = false;
			MWCalcoptions.isBuWireframeCalculation = false;
			if (MWCalcoptions.CamWireframeType == CamWireFrameType.Pocket)
			{
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Runtime.SimG0DevideLength = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength;
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Runtime.SimG1DevideLength = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG1DevideLength;
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar = new camParameters5(ItemCam.setCam);
				buMWMarbleVars.varCamMarbleMilling2DRough.mwPar = buMWCalcs.ConvertFromBuCamParToMwCamPar(buMWMarbleVars.varCamMarbleMilling2DRough.mwPar, buMWMarbleVars.varCamMarbleMilling2DRough.buPar);
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Distances.Air = 0.0;
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Distances.Safe = safe;
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Distances.Rapid = num;
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Distances.EntryAndExit = num;
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Distances.EntryAndExit = num;
				if (buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Distances.Safe < buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
				{
					buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Distances.Safe = buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + 1.0;
				}
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Speeds.Feed = feed;
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Speeds.Plunge = plunge;
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Speeds.FirstStep = firstStep;
				buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Steps.Enable = true;
				buMWMarbleVars.varCamMarbleMilling2DRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.DepthStep = depthStep;
				buMWMarbleVars.varCamMarbleMilling2DRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.FirstDepthStep = num2 + ZOffset;
				buMWMarbleVars.varCamMarbleMilling2DRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.DepthStepMode = MachiningAreaRoughingParamsDepthStepMode.DsmConstantDepthStep;
				buMWMarbleVars.varCamMarbleMilling2DRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.StartHeight = buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Steps.StartValue;
				buMWMarbleVars.varCamMarbleMilling2DRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.EndHeight = buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Steps.EndValue;
				buMWMarbleVars.varCamMarbleMilling2DRough.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeZigzag;
				buMWMarbleVars.varCamMarbleMilling2DRough.mwPar.MachParam.MachiningAreaMode = MachiningParamsMachiningAreaMode.MachByRegions;
				if (!(num2 > 0.0))
				{
					buMWMarbleVars.varCamMarbleMilling2DRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.FirstDepthStepFlg = false;
				}
				else
				{
					buMWMarbleVars.varCamMarbleMilling2DRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.FirstDepthStepFlg = true;
				}
				clsMW.varMWCamWFPocketPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMilling2DRough.mwPar, buMWMarbleVars.varCamMarbleMilling2DRough.buPar, out clsMW.varbuCamWFPocketPars);
				clsMW.varMWCamWFPocketPars.MachParam.MaxStepoverDistance = Tool.Geometry.Diameter * buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Pockets.StepOverPersentage / 100.0;
				clsMW.varMWCamWFPocketPars.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
				clsMW.varMWCamWFPocketPars.MachParam.CutTolerance = buMarbleCalc.varOperation.settingMarbleCam.CutTolerance;
				if (!buMarbleCalc.varOperation.settingMarbleCam.ToolPathPointDistributionMode)
				{
					clsMW.varMWCamWFPocketPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.ToolpathOutputType = TriangleMeshBasedTpCalcParamsToolpathOutputType.TotFitArcsAndPointDistribution;
				}
				else
				{
					clsMW.varMWCamWFPocketPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.ToolpathOutputType = TriangleMeshBasedTpCalcParamsToolpathOutputType.TotPolygonizeAndPointDistribution;
				}
			}
			if (MWCalcoptions.CamWireframeType == CamWireFrameType.Contour)
			{
				buMWMarbleVars.varCamMarbleMilling2DContour.buPar.Runtime.SimG0DevideLength = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength;
				buMWMarbleVars.varCamMarbleMilling2DContour.buPar.Runtime.SimG1DevideLength = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG1DevideLength;
				buMWMarbleVars.varCamMarbleMilling2DContour.buPar = new camParameters5(ItemCam.setCam);
