													}
												}
											}
										}
										else if (!marbleCam.isCamCalculated)
										{
											doSawMillingHorizontalCamCalc(ref Item, ref marbleCam);
										}
									}
									else if (!marbleCam.isCamCalculated)
									{
										doSawMillingVerticalCamCalc(ref Item, ref marbleCam);
									}
								}
								else
								{
									if (marbleCam.isCamCalculated)
									{
										continue;
									}
									MWCalculationOptions mWCalculationOptions2 = new MWCalculationOptions();
									mWCalculationOptions2.NumberofAxis = 5;
									mWCalculationOptions2.CamTriMeshType = marbleCam.MeshType;
									mWCalculationOptions2.Mode = CamMode.TriangularMesh;
									mWCalculationOptions2.DontApplyReset = true;
									mWCalculationOptions2.isBuWireframeCalculation = false;
									mWCalculationOptions2.AddToCamListInLocalCalculation = false;
									mWCalculationOptions2.ShowLeadInOutPage = false;
									mWCalculationOptions2.DontShowDialogBox = true;
									mWCalculationOptions2.DontShowbuDialogBox = true;
									if ((marbleCam.CamType == CamType.Rough) | (marbleCam.CamType == CamType.ParallelCut) | (marbleCam.CamType == CamType.ConstantZ))
									{
