											doMilling3AxisRotaryCamCalc(mWCalculationOptions2, Item, ref marbleCam);
										}
										if (marbleCam.AxesNumber == 4)
										{
											doMilling4AxisRotaryCamCalc(mWCalculationOptions2, Item, ref marbleCam);
										}
									}
								}
							}
							else if (!marbleCam.isCamCalculated)
							{
								MWCalculationOptions mWCalculationOptions3 = new MWCalculationOptions();
								mWCalculationOptions3.NumberofAxis = 3;
								mWCalculationOptions3.CamWireframeType = CamWireFrameType.Contour;
								mWCalculationOptions3.CamTriMeshType = marbleCam.MeshType;
								mWCalculationOptions3.Mode = CamMode.TriangularMesh;
								mWCalculationOptions3.DontApplyReset = true;
								mWCalculationOptions3.isBuWireframeCalculation = false;
								mWCalculationOptions3.AddToCamListInLocalCalculation = false;
								mWCalculationOptions3.ShowLeadInOutPage = false;
								mWCalculationOptions3.DontShowDialogBox = true;
								mWCalculationOptions3.DontShowbuDialogBox = true;
								doEngraveCamCalc(mWCalculationOptions3, Item, ref marbleCam);
							}
						}
						else
						{
							if (marbleCam.isCamCalculated)
							{
								continue;
							}
							if (marbleCam.ToolType != MarbleToolType.Saw)
