	public void doCamCalculateMarbleJob(ref MarbleJob Job, bool CreateButton = false)
	{
		string text = "doCamCalculateMarbleJob";
		try
		{
			if (clsItem.FrmProgress != null)
			{
				clsItem.FrmProgress.Visible = true;
			}
			CalculationEventArg calculationEventArg = new CalculationEventArg();
			AppBool.Calculation = true;
			ccVars.Pages[ccVars.PageIndex].Form.lbl_information.Text = buLangTranslate.preDef.Calculating + " , " + buLangTranslate.preDef.PleaseWait;
			ccVars.Pages[ccVars.PageIndex].Form.lbl_information.Visible = true;
			new TpPnt9D();
			bool flag = false;
			bool flag2 = false;
			Job.isMillingAvailable = true;
			if ((buMarbleCalc.varOperation.settingMarbleCam.CommonPathCalculation & !Job.isCommonPathDone) && CreateButton)
			{
				List<buEntity> list = new List<buEntity>();
				for (int i = 0; i <= Job.Items.Count - 1; i++)
				{
					MarbleItem marbleItem = Job.Items[i];
					if (marbleItem.ItemType != MarbleItemType.Contour)
					{
						continue;
					}
					for (int j = 0; j <= Job.Items[i].CamList.Count - 1; j++)
					{
						MarbleItemCam marbleItemCam = Job.Items[i].CamList[j];
						if (marbleItemCam.WireEntities == null)
						{
							continue;
						}
						for (int k = 0; k <= marbleItemCam.WireEntities.Count - 1; k++)
						{
							for (int l = 0; l <= marbleItemCam.WireEntities[k].Count - 1; l++)
							{
								buEntity buEntity2 = marbleItemCam.WireEntities[k][l];
								if (buEntity2 is buLine)
								{
									buEntity copiedEntity = null;
									buEntity.Copy(buEntity2, ref copiedEntity);
									list.Add((buLine)copiedEntity);
								}
							}
						}
					}
				}
				if (list.Count > 0)
				{
					List<buEntity> Result = new List<buEntity>();
					if (clsInit.cMarble.MergeCollinearLines(list, ref Result, 0.01, buMarbleCalc.varOperation.settingMarbleCam.CommonPathGapDistance))
					{
						clsInit.cMarble.CommonLinesToWireEntities(Result, ref Job);
					}
					Job.isCommonPathDone = true;
				}
			}
			int num = 0;
			int num2 = 1;
			for (int m = 0; m <= Job.Items.Count - 1; m++)
			{
				MarbleItem marbleItem2 = Job.Items[m];
				for (int n = 0; n <= marbleItem2.CamList.Count - 1; n++)
				{
					num++;
				}
			}
			TpPnt9D LastP = null;
			for (int num3 = 0; num3 <= Job.Items.Count - 1; num3++)
			{
				MarbleItem Item = Job.Items[num3];
				Item.indexItem = num3;
				bool flag3 = true;
				if (Item.CamList.Count == 0)
				{
					flag3 = false;
				}
				for (int num4 = 0; num4 <= Item.CamList.Count - 1; num4++)
				{
					Item.CamList[num4].indexCam = num4;
					if (Item.CamList[num4].CamBase == null)
					{
						Item.CamList[num4].isCamCalculated = false;
					}
					else if (Item.CamList[num4].CamBase.CamPoints.Count == 0)
					{
						Item.CamList[num4].isCamCalculated = false;
					}
					flag3 &= Item.CamList[num4].isCamCalculated;
					calculationEventArg.Job = buLangTranslate.preDef.Item + " " + buLangTranslate.preDef.Calculating;
					double num5 = (double)num2 / (double)num * 100.0;
					if (num5 > 100.0)
					{
						num5 = 100.0;
					}
					calculationEventArg.ActiveProgressPercentage = num5;
					calculationEventArg.OverallProgressPercentage = Convert.ToDouble(num3 + 1) / Convert.ToDouble(Job.Items.Count) * 100.0;
					clsInit.appCommand.CalculationInProgressCmd(calculationEventArg);
					num2++;
				}
				if (!flag3)
				{
					bool isLast = false;
					if (num3 == Job.Items.Count - 1)
					{
						isLast = true;
					}
					doCamCalculateMarbleItem(num3, isLast, LastP, ref Item);
					if (LastP != null)
					{
						clsInit.cMarble.GetLastCamPointOfItem(Item, ref LastP);
					}
					AppBool.Calculation = true;
					flag = true;
					flag2 = true;
				}
			}
			AppBool.Calculation = true;
			num2 = 1;
			if (flag | !Job.CamCalculated)
			{
				marbleGCodeCreateOptions marbleGCodeCreateOptions2 = new marbleGCodeCreateOptions();
				marbleGCodeCreateOptions2.AddM3M4WhilePlunge = buMarbleCalc.varMarbleSettings.StartSpindleBeforePlunge;
