	public void doCamSequence(ref List<camTp> Cams, ref List<camTp> JobCam)
	{
		JobCam.Clear();
		if (buMarbleCalc.varOperation.CuttingSequence.Count <= 0)
		{
			for (int i = 0; i <= Cams.Count - 1; i++)
			{
				Cams[i].Used = true;
				JobCam.Add(Cams[i]);
			}
		}
		else
		{
			for (int j = 0; j <= buMarbleCalc.varOperation.CuttingSequence.Count - 1; j++)
			{
				for (int k = 0; k <= Cams.Count - 1; k++)
				{
					if (buMarbleCalc.varOperation.CuttingSequence[j] != MarbleOperationSequence.CornerCleanByDrill)
					{
						if (buMarbleCalc.varOperation.CuttingSequence[j] != MarbleOperationSequence.CornerCleanByMilling)
						{
							if (!((buMarbleCalc.varOperation.CuttingSequence[j] == MarbleOperationSequence.Drills) & buMarbleCalc.varOperation.settingMarbleCam.UseDrillCut))
							{
								if (buMarbleCalc.varOperation.CuttingSequence[j] != MarbleOperationSequence.MillingCuttings)
								{
									if (buMarbleCalc.varOperation.CuttingSequence[j] != MarbleOperationSequence.SawAngleCutStraight)
									{
										if (buMarbleCalc.varOperation.CuttingSequence[j] != MarbleOperationSequence.SawCircular)
										{
											if (buMarbleCalc.varOperation.CuttingSequence[j] != MarbleOperationSequence.SawStraight)
											{
												if (buMarbleCalc.varOperation.CuttingSequence[j] != MarbleOperationSequence.RestCutting || Cams[k].Used)
												{
													continue;
												}
												if (Cams[k].Tool.Purpose != ToolPurpose.Saw)
												{
													if (Cams[k].Tool.Purpose != ToolPurpose.Milling)
													{
														if (Cams[k].Tool.Purpose != ToolPurpose.Milling5Axis)
														{
															if (Cams[k].Tool.Purpose != ToolPurpose.MillingHead)
															{
																JobCam.Add(Cams[k]);
															}
															else if (buMarbleCalc.varOperation.settingMarbleCam.UseMillingCuttings)
															{
																Cams[k].Used = true;
																JobCam.Add(Cams[k]);
															}
														}
														else if (buMarbleCalc.varOperation.settingMarbleCam.UseMillingCuttings)
														{
															Cams[k].Used = true;
															JobCam.Add(Cams[k]);
														}
													}
													else if (buMarbleCalc.varOperation.settingMarbleCam.UseMillingCuttings)
													{
														Cams[k].Used = true;
														JobCam.Add(Cams[k]);
													}
												}
												else if (buMarbleCalc.varOperation.settingMarbleCam.UseSawCuttings)
												{
													Cams[k].Used = true;
													JobCam.Add(Cams[k]);
												}
											}
											else if (!Cams[k].Used && ((Cams[k].TypeCam == CamType.SawCut) & buMarbleCalc.varOperation.settingMarbleCam.UseSawCuttings))
											{
												Cams[k].Used = true;
												JobCam.Add(Cams[k]);
											}
										}
										else if (!Cams[k].Used && ((Cams[k].TypeCam == CamType.SawCut) & buMarbleCalc.varOperation.settingMarbleCam.UseSawCuttings))
										{
											Cams[k].Used = true;
											JobCam.Add(Cams[k]);
										}
									}
									else if (!Cams[k].Used && ((Cams[k].TypeCam == CamType.SawCut) & buMarbleCalc.varOperation.settingMarbleCam.UseSawCuttings))
									{
										Cams[k].Used = true;
										JobCam.Add(Cams[k]);
									}
								}
								else if (!Cams[k].Used & ((Cams[k].TypeCam == CamType.MillingCut) | (Cams[k].TypeCam == CamType.Rough) | (Cams[k].TypeCam == CamType.ParallelCut) | (Cams[k].TypeCam == CamType.ConstantZ) | (Cams[k].TypeCam == CamType.ConstantCusp) | (Cams[k].TypeCam == CamType.Flatlands) | (Cams[k].TypeCam == CamType.Pencil)) & buMarbleCalc.varOperation.settingMarbleCam.UseMillingCuttings)
								{
									Cams[k].Used = true;
									JobCam.Add(Cams[k]);
								}
							}
							else if (!Cams[k].Used && Cams[k].TypeCam == CamType.Drill)
							{
								Cams[k].Used = true;
								JobCam.Add(Cams[k]);
							}
						}
						else if (!Cams[k].Used && ((Cams[k].TypeCam == CamType.CornerCleanByMilling) & buMarbleCalc.varOperation.settingMarbleCam.UseCornerByMilling))
						{
							Cams[k].Used = true;
							JobCam.Add(Cams[k]);
						}
					}
					else if (!Cams[k].Used && ((Cams[k].TypeCam == CamType.CornerCleanByDrill) & buMarbleCalc.varOperation.settingMarbleCam.UseCornerByDrill))
					{
						Cams[k].Used = true;
						JobCam.Add(Cams[k]);
					}
				}
			}
		}
		for (int l = 0; l <= Cams.Count - 1; l++)
		{
			if (Cams[l].Used)
			{
			}
		}
	}

	public void doSimulationCalculate(ref MarbleJob Job)
	{
		if (clsItem.FrmProgress != null)
		{
			clsItem.FrmProgress.Visible = true;
		}
		CalculationEventArg calculationEventArg = new CalculationEventArg();
		TpPnt9D pntFirst = null;
		if (!Job.isSimulationDone)
		{
			for (int i = 0; i <= Job.Cams.Count - 1; i++)
			{
				calculationEventArg.OverallProgressPercentage = Convert.ToDouble(i + 1) / Convert.ToDouble(Job.Cams.Count) * 100.0;
				camTp Cam = Job.Cams[i];
				Cam.SimilationPoint.SimMove.Clear();
				if (Cam.Enable)
				{
					if (i != 0)
					{
						if (Cam.CamPoints.Count > 0)
						{
							for (int j = 0; j <= Cam.CamPoints.Count - 1; j++)
							{
								if (j != 0)
								{
									TpPnt9D pntFirst2 = Cam.CamPoints[j - 1].Points[Cam.CamPoints[j - 1].Points.Count - 1];
									List<Pnt6DSimMove> simPoints = new List<Pnt6DSimMove>();
									clsInit.cCam5.SimilationPointBetweenTwoPoints(pntFirst2, Cam.CamPoints[j].Points[0], ref simPoints, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength);
									if (simPoints.Count > 0)
									{
										Cam.SimilationPoint.SimMove.AddRange(simPoints);
									}
									clsInit.cCam5.CreateSimulationPointsFromCamPoint(ref Cam, Cam.CamPoints[j], buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG1DevideLength);
								}
								else
								{
									List<Pnt6DSimMove> simPoints2 = new List<Pnt6DSimMove>();
									clsInit.cCam5.SimilationPointBetweenTwoPoints(pntFirst, Cam.CamPoints[j].Points[0], ref simPoints2, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength);
									if (simPoints2.Count > 0)
									{
										Cam.SimilationPoint.SimMove.AddRange(simPoints2);
									}
									clsInit.cCam5.CreateSimulationPointsFromCamPoint(ref Cam, Cam.CamPoints[j], buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG1DevideLength);
								}
								calculationEventArg.Job = buLangTranslate.preDef.Simulation + " " + buLangTranslate.preDef.Calculating;
								calculationEventArg.ActiveProgressPercentage = Convert.ToDouble(j + 1) / Convert.ToDouble(Cam.CamPoints.Count) * 100.0;
								clsInit.appCommand.CalculationInProgressCmd(calculationEventArg);
							}
						}
					}
					else if (Cam.CamPoints.Count > 0)
					{
						for (int k = 0; k <= Cam.CamPoints.Count - 1; k++)
						{
							if (k != 0)
							{
								TpPnt9D pntFirst3 = Cam.CamPoints[k - 1].Points[Cam.CamPoints[k - 1].Points.Count - 1];
								List<Pnt6DSimMove> simPoints3 = new List<Pnt6DSimMove>();
								clsInit.cCam5.SimilationPointBetweenTwoPoints(pntFirst3, Cam.CamPoints[k].Points[0], ref simPoints3, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength);
								if (simPoints3.Count > 0)
								{
									Cam.SimilationPoint.SimMove.AddRange(simPoints3);
								}
								clsInit.cCam5.CreateSimulationPointsFromCamPoint(ref Cam, Cam.CamPoints[k], buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG1DevideLength);
							}
							else
							{
								clsInit.cCam5.CreateSimulationPointsFromCamPoint(ref Cam, Cam.CamPoints[k], buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG1DevideLength);
							}
							calculationEventArg.Job = buLangTranslate.preDef.Simulation + " " + buLangTranslate.preDef.Calculating;
							calculationEventArg.ActiveProgressPercentage = Convert.ToDouble(k + 1) / Convert.ToDouble(Cam.CamPoints.Count) * 100.0;
							clsInit.appCommand.CalculationInProgressCmd(calculationEventArg);
						}
					}
				}
				int num = Cam.SimilationPoint.SimMove.Count / 10;
				if (num <= 0)
				{
					num = 1;
				}
				if (Cam.MaterialIndex >= 0 && Job.SimMaterials != null && Cam.MaterialIndex <= Job.SimMaterials.Count - 1)
				{
					List<MaterialBase5> CopiedList = new List<MaterialBase5>();
					MaterialBase5.Copy(Job.SimMaterials[Cam.MaterialIndex], ref CopiedList);
					Cam.SimilationPoint.MoveCommand = SimulationMoveCommand.DrawMaterial;
					Cam.SimilationPoint.Obj1 = CopiedList;
				}
				for (int l = 0; l <= Cam.SimilationPoint.SimMove.Count - 1; l++)
				{
					if (l == Cam.SimilationPoint.SimMove.Count - 1)
					{
						Pnt6DSimMove pnt6DSimMove = Cam.SimilationPoint.SimMove[l];
						pntFirst = new TpPnt9D(pnt6DSimMove.X, pnt6DSimMove.Y, pnt6DSimMove.Z, pnt6DSimMove.A, pnt6DSimMove.B, pnt6DSimMove.C);
					}
					double num2 = 0.0;
					double num3 = 0.0;
					double num4 = 0.0;
					if (Cam.Tool.Purpose != ToolPurpose.Saw)
					{
						if (Cam.Tool.Purpose != ToolPurpose.Milling)
						{
							if (Cam.Tool.Purpose != ToolPurpose.Milling5Axis)
							{
								if (Cam.Tool.Purpose != ToolPurpose.MillingHead)
								{
									if (Cam.Tool.Geometry.GeometryType != buClass.ToolType.WateJet)
									{
										if (Cam.Tool.Geometry.GeometryType != buClass.ToolType.Pneomatic)
										{
											if (Cam.Tool.Geometry.GeometryType == buClass.ToolType.LaserPointer)
											{
												if (l == 0)
												{
													Cam.SimilationPoint.SimMove[l].MCode = 45;
												}
												num2 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcLaserPointerToolXOffset;
												num3 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcLaserPointerToolYOffset;
												num4 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcLaserPointerToolZOffset;
											}
										}
										else
										{
											if (l == 0)
											{
												Cam.SimilationPoint.SimMove[l].MCode = 44;
											}
											num2 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcAirDryToolXOffset;
											num3 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcAirDryToolYOffset;
											num4 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcAirDryToolZOffset;
										}
									}
									else
									{
										if (l == 0)
										{
											Cam.SimilationPoint.SimMove[l].MCode = 43;
										}
										Cam.SimilationPoint.SimMove[l].X = Cam.SimilationPoint.SimMove[l].X;
										Cam.SimilationPoint.SimMove[l].Y = Cam.SimilationPoint.SimMove[l].Y;
										num4 = 0.0 - activeKinematic.OffsetXYZ.Z - activeKinematic.RotateCenterOffsetOfA.Z + activeKinematic.RotateCenterOffsetOfA.Y + Cam.Tool.Geometry.Length - 0.0;
										num4 = 0.0;
										Cam.SimilationPoint.SimMove[l].Z = Cam.SimilationPoint.SimMove[l].Z + num4;
									}
								}
								else
								{
									if (l == 0)
									{
										Cam.SimilationPoint.SimMove[l].MCode = 42;
									}
									if (buCompare5.EQ(Cam.SimilationPoint.SimMove[l].A, 90.0, 0.01))
									{
										num2 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcMillingHeadToolXOffset;
										num3 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcMillingHeadToolYOffset - (activeKinematic.RotateCenterOffsetOfA.Y - activeKinematic.RotateCenterOffsetOfC.Y);
									}
									num4 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcMillingHeadToolZOffset + (Cam.Tool.Geometry.Length + activeKinematic.RotateCenterOffsetOfA.Y - activeKinematic.RotateCenterOffsetOfA.Z - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingHeadToolYOffset) - buMarbleCalc.activeToolSaw.Geometry.Diameter / 2.0;
								}
							}
							else
							{
								if (l == 0)
								{
									Cam.SimilationPoint.SimMove[l].MCode = 41;
								}
								num2 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcMillingToolXOffset;
								num3 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcMillingToolYOffset;
								num4 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcMillingToolZOffset;
							}
						}
						else
						{
							if (l == 0)
							{
								Cam.SimilationPoint.SimMove[l].MCode = 41;
							}
							num2 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcMillingToolXOffset;
							num3 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcMillingToolYOffset;
							num4 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcMillingToolZOffset;
						}
					}
					else
					{
						if (l == 0)
						{
							Cam.SimilationPoint.SimMove[l].MCode = 40;
						}
						num2 = 0.0;
						num3 = 0.0;
						num4 = 0.0;
					}
					Cam.SimilationPoint.SimMove[l].X = Cam.SimilationPoint.SimMove[l].X + num2;
					Cam.SimilationPoint.SimMove[l].Y = Cam.SimilationPoint.SimMove[l].Y + num3;
					Cam.SimilationPoint.SimMove[l].Z = Cam.SimilationPoint.SimMove[l].Z + num4;
					if (l % num == 0)
					{
						calculationEventArg.Job = buLangTranslate.preDef.Simulation + " " + buLangTranslate.preDef.Move + " " + buLangTranslate.preDef.Calculating;
						calculationEventArg.ActiveProgressPercentage = Convert.ToDouble(l + 1) / Convert.ToDouble(Cam.SimilationPoint.SimMove.Count) * 100.0;
						clsInit.appCommand.CalculationInProgressCmd(calculationEventArg);
					}
				}
			}
		}
		Job.isSimulationDone = true;
		if (clsItem.FrmProgress != null)
		{
			clsItem.FrmProgress.Visible = false;
		}
	}

	public void doCreateGCode(MarbleJob Job, ref string strGCodes)
	{
		string text = "doCreateGCode";
		try
		{
			PostProcessor postProcessor = new PostProcessor(ccVars.PostActive);
			if (buMarbleCalc.varOperation.settingMarbleCam.MoveZCAAxesToSafeDistance)
			{
				postProcessor.EndLines.Insert(0, "M50");
				postProcessor.EndLines.Insert(1, "G0 A0");
				postProcessor.EndLines.Insert(2, "G0 Z" + buMarbleCalc.varOperation.settingMarbleCam.JobFinishZPostion);
				postProcessor.EndLines.Insert(3, "G0 C0");
			}
			strGCodes = "";
			clsInit.cGcodeCreate.CreatGCode(Job.Cams, postProcessor, ref strGCodes);
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void SetMillingCamParameter(MarbleCamParameterSetArg Data, ref MarbleItemCam marbleCam)
	{
		if (Data.GeneralCamType != CamType.ContourOpen)
		{
			if ((Data.GeneralCamType == CamType.Contour) | (Data.GeneralCamType == CamType.ContourClosed))
			{
				marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleClosedContourMilling.buPar);
				marbleCam.WireType = CamWireFrameType.Contour;
			}
		}
		else
		{
			marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleOpenContourMilling.buPar);
			marbleCam.WireType = CamWireFrameType.Contour;
		}
		marbleCam.CamMode = Data.MarbleCamMode;
		marbleCam.CamMarbleType = Data.MarbleCamType;
		marbleCam.CamType = Data.GeneralCamType;
		marbleCam.setCam.Steps.StartValue = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + Data.ZOffset;
		marbleCam.setCam.Steps.EndValue = buMarbleCalc.varOperation.settingMarbleCam.TargetZ + Data.ZOffset;
		marbleCam.setCam.Distances.Air = 0.0;
		marbleCam.setCam.Distances.Safe = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
		marbleCam.setCam.Distances.Rapid = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
		marbleCam.setCam.Speeds.Feed = buMarbleCalc.varOperation.settingMarbleCam.MillingCuttingVelocity;
		marbleCam.setCam.Speeds.Plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeVelocity;
		marbleCam.setCam.Speeds.FirstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeFirstVelocity;
		marbleCam.setCam.Steps.DepthStep = buMarbleCalc.varOperation.settingMarbleCam.MillingStepDown;
		marbleCam.setCam.Steps.FirstValue = buMarbleCalc.varOperation.settingMarbleCam.MillingFirstStepDown;
		marbleCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
		marbleCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
		if (Data.ToolType == MarbleToolType.MillingHead)
		{
			marbleCam.setCam.Distances.Safe = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
			marbleCam.setCam.Distances.Rapid = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
			marbleCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
			marbleCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
			marbleCam.setCam.Speeds.Feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadCuttingVelocity;
			marbleCam.setCam.Speeds.Plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeVelocity;
			marbleCam.setCam.Speeds.FirstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeFirstVelocity;
			marbleCam.setCam.Steps.DepthStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadStepDown;
			marbleCam.setCam.Steps.FirstValue = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadFirstStepDown;
		}
		if (marbleCam.setCam.Distances.Safe < marbleCam.setCam.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
		{
			marbleCam.setCam.Distances.Safe = marbleCam.setCam.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + 1.0;
		}
	}

	public void doDeleteItems(bool All, int ItemID)
	{
		try
		{
			if (!All)
			{
				if (!((ItemID >= 0) & (ItemID <= activeJob.Items.Count - 1)))
				{
					activeJob.Cams.Clear();
					List<CustomData> list = new List<CustomData>();
					int num = -1;
					for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
					{
						if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected && ((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData != null) & (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData is CustomData)))
						{
							CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
							int result = -1;
							int.TryParse(customData.ID, out result);
							if (result >= 0)
							{
								list.Add(customData);
								num = result;
							}
						}
					}
					if (list.Count > 0)
					{
						buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
						buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
						buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteThisItem);
						buDialogMessageBoxYesNo2.ShowDialog();
						if (buDialogMessageBoxYesNo2.Result != DialogResult.Yes)
						{
							return;
						}
						UndoBuffer();
						for (int j = 0; j <= list.Count - 1; j++)
						{
							if (list[j].Command == null || list[j].Command.Length <= 1)
							{
								if (activeJob.Items.Count <= 0)
								{
									continue;
								}
								for (int num2 = activeJob.Items.Count - 1; num2 >= 0; num2--)
								{
									if (activeJob.Items[num2].ID == num)
									{
										activeJob.Items.RemoveAt(num2);
									}
								}
								continue;
							}
							EntityCommandArgs e = new EntityCommandArgs();
							e.Result = clsInit.cMarble.GetEntityCommand(list[j].Command, ref e);
							if (!e.Result)
							{
								continue;
							}
							if (e.Command == MarbleCommandsEntity.Slat.ToString())
							{
								doSlatDelete(e.ItemID, e.EdgeIndex);
							}
							if (!(e.Command == MarbleCommandsEntity.Operation.ToString()))
							{
								continue;
							}
							for (int num3 = activeJob.Items.Count - 1; num3 >= 0; num3--)
							{
								if (activeJob.Items[num3].ID == num)
								{
									activeJob.Items.RemoveAt(num3);
								}
							}
						}
						clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: false, -1, ref activeJob);
					}
				}
				else
				{
					buDialogMessageBoxYesNo buDialogMessageBoxYesNo3 = new buDialogMessageBoxYesNo();
					buDialogMessageBoxYesNo3.StartPosition = FormStartPosition.CenterScreen;
					buDialogMessageBoxYesNo3.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteThisItem);
					buDialogMessageBoxYesNo3.ShowDialog();
					if (buDialogMessageBoxYesNo3.Result != DialogResult.Yes)
					{
						return;
					}
					UndoBuffer();
					activeJob.Items.RemoveAt(ItemID);
				}
			}
			else
			{
				buDialogMessageBoxYesNo buDialogMessageBoxYesNo4 = new buDialogMessageBoxYesNo();
				buDialogMessageBoxYesNo4.StartPosition = FormStartPosition.CenterScreen;
				buDialogMessageBoxYesNo4.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteAllItem);
				buDialogMessageBoxYesNo4.ShowDialog();
				if (buDialogMessageBoxYesNo4.Result != DialogResult.Yes)
				{
					return;
				}
				UndoBuffer();
				MarbleTempVars.VacuumEnable = false;
				MarbleTempVars.ItemID = 1;
				MarbleTempVars.MarbleCamID = 1;
				MarbleTempVars.MarbleEdgeID = 1;
				MarbleTempVars.MarbleStripID = 1;
				if (activeJob.VacuumCuts != null)
				{
					activeJob.VacuumCuts.Clear();
				}
				activeJob.Items.Clear();
				activeJob.Cams.Clear();
				activeJob.GCode = "";
				if (activeJob.VacuumMaterials != null)
				{
					activeJob.VacuumMaterials.Clear();
				}
				clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref activeJob);
			}
			activeJob.CamCalculated = false;
			AppBool.EditMode = false;
			doDrawActiveJob();
			JobUpdate();
			clsInit.appCommand.Reset();
		}
		catch (Exception)
		{
		}
	}

	public void doDeleteCam(bool All, int JobIndex, int CamIndex)
	{
		if (!All)
		{
			if (((JobIndex >= 0) & (JobIndex <= activeJob.Items.Count - 1)) && ((CamIndex >= 0) & (CamIndex <= activeJob.Items[JobIndex].CamList.Count - 1)))
			{
				buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
				buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
				buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteThisToolpath);
				buDialogMessageBoxYesNo2.ShowDialog();
				if (buDialogMessageBoxYesNo2.Result == DialogResult.Yes)
				{
					activeJob.Items[JobIndex].CamList.RemoveAt(CamIndex);
				}
			}
		}
		else
		{
			buDialogMessageBoxYesNo buDialogMessageBoxYesNo3 = new buDialogMessageBoxYesNo();
			buDialogMessageBoxYesNo3.StartPosition = FormStartPosition.CenterScreen;
			buDialogMessageBoxYesNo3.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteAllToolpath);
			buDialogMessageBoxYesNo3.ShowDialog();
			if (buDialogMessageBoxYesNo3.Result == DialogResult.Yes)
			{
				for (int i = 0; i <= activeJob.Items.Count - 1; i++)
				{
					activeJob.Items[i].CamList.Clear();
				}
			}
		}
		activeJob.CamCalculated = false;
		doCamCalculateMarbleJob(ref activeJob);
		JobUpdate();
		doDrawActiveJob();
		clsInit.appCommand.Reset();
	}

	public void doVisibleItems(bool All, int ItemID)
	{
		if (!All)
		{
			if (!((ItemID >= 0) & (ItemID <= activeJob.Items.Count - 1)))
			{
				return;
			}
			if (activeJob.Items[ItemID].Visible)
			{
				activeJob.Items[ItemID].Visible = false;
			}
			else
			{
				activeJob.Items[ItemID].Visible = true;
			}
		}
		else
		{
			UndoBuffer();
			for (int i = 0; i <= activeJob.Items.Count - 1; i++)
			{
				if (activeJob.Items[i].Visible)
				{
					activeJob.Items[i].Visible = false;
				}
				else
				{
					activeJob.Items[i].Visible = true;
				}
			}
		}
		doDrawActiveJob();
	}

	public void doVisibleCam(bool All, int JobIndex, int CamIndex)
	{
		if (!All)
		{
			if (((JobIndex >= 0) & (JobIndex <= activeJob.Items.Count - 1)) && ((CamIndex >= 0) & (CamIndex <= activeJob.Items[JobIndex].CamList.Count - 1)))
			{
				if (!activeJob.Items[JobIndex].CamList[CamIndex].Visible)
				{
					activeJob.Items[JobIndex].CamList[CamIndex].Visible = true;
				}
				else
				{
					activeJob.Items[JobIndex].CamList[CamIndex].Visible = false;
				}
			}
		}
		else
		{
			bool flag = false;
			bool flag2 = false;
			if (activeJob.Items.Count > 0)
			{
				for (int i = 0; i <= activeJob.Items.Count - 1; i++)
				{
					int num;
					for (num = 0; num <= activeJob.Items[i].CamList.Count - 1; num++)
					{
						flag = activeJob.Items[i].CamList[num].Visible;
						flag2 = true;
						num = activeJob.Items[i].CamList.Count;
					}
					if (flag2)
					{
						i = activeJob.Items.Count;
					}
				}
			}
			for (int j = 0; j <= activeJob.Items.Count - 1; j++)
			{
				for (int k = 0; k <= activeJob.Items[j].CamList.Count - 1; k++)
				{
					activeJob.Items[j].CamList[k].Visible = !flag;
				}
			}
		}
		doDrawActiveJob();
	}

	public void doMoveExecute(object Data1, object Data2, object Data3)
	{
		if (Data1 == null)
		{
			return;
		}
		if (Data1.ToString() == "MoveX" && Data2 != null)
		{
			buMarbleCalc.varMarbleRunSettings.ManuelMove = frmMove.spn_move.Value;
			buMarbleCalc.varMarbleRunSettings.ManuelRotate = frmMove.spn_rotate.Value;
			doMoveSelectedItem(Convert.ToDouble(Data2.ToString()), 0.0);
		}
		if (Data1.ToString() == "MoveY" && Data2 != null)
		{
			buMarbleCalc.varMarbleRunSettings.ManuelMove = frmMove.spn_move.Value;
			buMarbleCalc.varMarbleRunSettings.ManuelRotate = frmMove.spn_rotate.Value;
			doMoveSelectedItem(0.0, Convert.ToDouble(Data2.ToString()));
		}
		if (Data1.ToString() == "Rotate" && Data2 != null)
		{
			buMarbleCalc.varMarbleRunSettings.ManuelMove = frmMove.spn_move.Value;
			buMarbleCalc.varMarbleRunSettings.ManuelRotate = frmMove.spn_rotate.Value;
			doRotateSelectedItem(Convert.ToDouble(Data2.ToString()));
		}
		if (Data1.ToString() == "Close")
		{
			if (tempJob != null)
			{
				activeJob = new MarbleJob(tempJob);
				activeJob.CamCalculated = false;
			}
			tempJob = null;
			doCamCalculateMarbleJob(ref activeJob);
			JobUpdate();
			doDrawActiveJob();
		}
		if (Data1.ToString() == "MoveOk")
		{
			SaveMarbleFile();
			doCamCalculateMarbleJob(ref activeJob);
			JobUpdate();
			doDrawActiveJob();
		}
	}

	public void doMoveSelectedItem(double dX, double dY)
	{
		MarbleTempVars.LastSelectedEntitiesList.Clear();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (entity.Selected && ((entity.EntityData != null) & (entity.EntityData is CustomData)))
			{
				MarbleTempVars.LastSelectedEntitiesList.Add(i);
			}
		}
		if (MarbleTempVars.LastSelectedEntitiesList.Count > 0)
		{
			UndoBuffer();
		}
		for (int j = 0; j <= MarbleTempVars.LastSelectedEntitiesList.Count - 1; j++)
		{
			Entity entity2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[MarbleTempVars.LastSelectedEntitiesList[j]];
			CustomData customData = entity2.EntityData as CustomData;
			if (!((customData.typeDefination == entityTypeDefination.MarbleItem) & (customData.ID.Trim().Length >= 0)))
			{
				continue;
			}
			int result = -1;
			int.TryParse(customData.ID, out result);
			if (result < 0)
			{
				continue;
			}
			for (int k = 0; k <= activeJob.Items.Count - 1; k++)
			{
				if (activeJob.Items[k].ID == result)
				{
					MarbleItem Item = activeJob.Items[k];
					clsInit.cMarble.MoveItem(ref Item, dX, dY, 0.0);
					activeJob.CamCalculated = false;
				}
			}
		}
		ccVars.pntSelectedMid.X = ccVars.pntSelectedMid.X + dX;
		ccVars.pntSelectedMid.Y = ccVars.pntSelectedMid.Y + dY;
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref clsInit.appMarble.activeJob);
		doDrawActiveJob();
		SetSelectedToEntities();
	}

	public void doMoveAllItem(double dX, double dY)
	{
		UndoBuffer();
		for (int i = 0; i <= activeJob.Items.Count - 1; i++)
		{
			MarbleItem Item = activeJob.Items[i];
			clsInit.cMarble.MoveItem(ref Item, dX, dY, 0.0);
		}
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref clsInit.appMarble.activeJob);
		AppBool.EditMode = false;
		doDrawActiveJob();
	}

	public void doCopySelectedItem(double dX, double dY)
	{
		MarbleTempVars.LastSelectedEntitiesList.Clear();
		List<Entity> list = new List<Entity>();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (entity.Selected && ((entity.EntityData != null) & (entity.EntityData is CustomData)))
			{
				MarbleTempVars.LastSelectedEntitiesList.Add(i);
				list.Add(entity);
			}
		}
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint, ref MidPoint, ref MaxPoint);
		int count = activeJob.Items.Count;
		if (MarbleTempVars.LastSelectedEntitiesList.Count > 0 && count > 0)
		{
			UndoBuffer();
		}
		for (int j = 0; j <= MarbleTempVars.LastSelectedEntitiesList.Count - 1; j++)
		{
			Entity entity2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[MarbleTempVars.LastSelectedEntitiesList[j]];
			CustomData customData = entity2.EntityData as CustomData;
			if (!((customData.typeDefination == entityTypeDefination.MarbleItem) & (customData.ID.Trim().Length >= 0)))
			{
				continue;
			}
			int result = -1;
			int.TryParse(customData.ID, out result);
			if (result < 0)
			{
				continue;
			}
			for (int k = 0; k <= count - 1; k++)
			{
				if (activeJob.Items[k].ID == result)
				{
					MarbleItem Item = new MarbleItem(activeJob.Items[k]);
					Item.ID = MarbleTempVars.ItemID;
					double dX2 = 0.0;
					double dY2 = 0.0;
					if ((buMarbleCalc.varMarbleRunSettings.CopyType == MarbleCopyType.XYDirction) | (buMarbleCalc.varMarbleRunSettings.CopyType == MarbleCopyType.XDirection))
					{
						dX2 = dX + (MaxPoint.X - MinPoint.X) + buMarbleCalc.activeToolSaw.Geometry.Thickness;
					}
					if ((buMarbleCalc.varMarbleRunSettings.CopyType == MarbleCopyType.XYDirction) | (buMarbleCalc.varMarbleRunSettings.CopyType == MarbleCopyType.YDirection))
					{
						dY2 = dY + (MaxPoint.Y - MinPoint.Y) + buMarbleCalc.activeToolSaw.Geometry.Thickness;
					}
					clsInit.cMarble.MoveItem(ref Item, dX2, dY2, 0.0);
					activeJob.Items.Add(Item);
					activeJob.CamCalculated = false;
					MarbleTempVars.ItemID++;
				}
			}
		}
		ccVars.pntSelectedMid.X = ccVars.pntSelectedMid.X + dX;
		ccVars.pntSelectedMid.Y = ccVars.pntSelectedMid.Y + dY;
		AppBool.EditMode = false;
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref clsInit.appMarble.activeJob);
		doDrawActiveJob();
	}

	public void doCopySelectedItem(double dX, double dY, double countX, double countY)
	{
		MarbleTempVars.LastSelectedEntitiesList.Clear();
		List<Entity> list = new List<Entity>();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (entity.Selected && ((entity.EntityData != null) & (entity.EntityData is CustomData)))
			{
				MarbleTempVars.LastSelectedEntitiesList.Add(i);
				list.Add(entity);
			}
		}
		int count = activeJob.Items.Count;
		if (!(MarbleTempVars.LastSelectedEntitiesList.Count > 0 && count > 0))
		{
			return;
		}
		UndoBuffer();
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint, ref MidPoint, ref MaxPoint);
		for (double num = 0.0; num <= countX - 1.0; num += 1.0)
		{
			for (double num2 = 0.0; num2 <= countY - 1.0; num2 += 1.0)
			{
				if (!(num > 0.0 || num2 > 0.0))
				{
					continue;
				}
				for (int j = 0; j <= MarbleTempVars.LastSelectedEntitiesList.Count - 1; j++)
				{
					Entity entity2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[MarbleTempVars.LastSelectedEntitiesList[j]];
					CustomData customData = entity2.EntityData as CustomData;
					if (!((customData.typeDefination == entityTypeDefination.MarbleItem) & (customData.ID.Trim().Length >= 0)))
					{
						continue;
					}
					int result = -1;
					int.TryParse(customData.ID, out result);
					if (result < 0)
					{
						continue;
					}
					for (int k = 0; k <= count - 1; k++)
					{
						if (activeJob.Items[k].ID == result)
						{
							MarbleItem Item = new MarbleItem(activeJob.Items[k]);
							Item.ID = MarbleTempVars.ItemID;
							double num3 = 0.0;
							double num4 = 0.0;
							num3 = (dX + (MaxPoint.X - MinPoint.X) + buMarbleCalc.activeToolSaw.Geometry.Thickness) * num;
							num4 = (dY + (MaxPoint.Y - MinPoint.Y) + buMarbleCalc.activeToolSaw.Geometry.Thickness) * num2;
							clsInit.cMarble.MoveItem(ref Item, num3, num4, 0.0);
							activeJob.Items.Add(Item);
							activeJob.CamCalculated = false;
							MarbleTempVars.ItemID++;
						}
					}
				}
			}
		}
		ccVars.pntSelectedMid.X = ccVars.pntSelectedMid.X + dX;
		ccVars.pntSelectedMid.Y = ccVars.pntSelectedMid.Y + dY;
		AppBool.EditMode = false;
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref clsInit.appMarble.activeJob);
		doDrawActiveJob();
	}

	public void doRotateSelectedItem(double Rotation)
	{
		MarbleTempVars.LastSelectedEntitiesList.Clear();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
