	}

	public void doMirrorSelectedItem()
	{
		MarbleTempVars.LastSelectedEntitiesList.Clear();
		List<Entity> list = new List<Entity>();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (entity.Selected && ((entity.EntityData != null) & (entity.EntityData is CustomData)))
			{
				MarbleTempVars.LastSelectedEntitiesList.Add(i);
				list.Add(entity);
			}
		}
		if (MarbleTempVars.LastSelectedEntitiesList.Count <= 0)
		{
			return;
		}
		UndoBuffer();
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint, ref MidPoint, ref MaxPoint);
		_ = activeJob.Items.Count;
		Point3D point3D = new Point3D();
		Point3D point3D2 = new Point3D();
		double num = buMarbleCalc.varMarbleRunSettings.MirrorDistance;
		if (num < buMarbleCalc.activeToolSaw.Geometry.Thickness)
		{
			num = buMarbleCalc.activeToolSaw.Geometry.Thickness;
		}
		if (buMarbleCalc.varMarbleRunSettings.MirrorType != MirrorAxisXYType.X)
		{
			point3D.X = MinPoint.X;
			point3D.Y = MaxPoint.Y + num;
			point3D2.X = MaxPoint.X;
			point3D2.Y = MaxPoint.Y + num;
		}
		else
		{
			point3D.X = MaxPoint.X + num;
			point3D.Y = MinPoint.Y;
			point3D2.X = MaxPoint.X + num;
			point3D2.Y = MaxPoint.Y;
		}
		for (int j = 0; j <= MarbleTempVars.LastSelectedEntitiesList.Count - 1; j++)
		{
			Entity entity2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[MarbleTempVars.LastSelectedEntitiesList[j]];
			CustomData customData = entity2.EntityData as CustomData;
			if (!((customData.typeDefination == entityTypeDefination.MarbleItem) & (customData.ID.Trim().Length >= 0)))
			{
				continue;
			}
			int result = -1;
			int.TryParse(customData.ID, out result);
			if (result < 0)
			{
				continue;
			}
			for (int k = 0; k <= activeJob.Items.Count - 1; k++)
			{
				if (activeJob.Items[k].ID == result)
				{
					if (!buMarbleCalc.varMarbleRunSettings.MirrorDeleteOriginale)
					{
						MarbleItem Item = new MarbleItem(activeJob.Items[k]);
						Item.ID = MarbleTempVars.ItemID;
						clsInit.cMarble.MirrorItem(ref Item, point3D, point3D2);
						activeJob.Items.Add(Item);
						MarbleTempVars.ItemID++;
					}
					else
					{
						MarbleItem Item2 = activeJob.Items[k];
						clsInit.cMarble.MirrorItem(ref Item2, point3D, point3D2);
					}
					activeJob.CamCalculated = false;
					break;
				}
			}
		}
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref clsInit.appMarble.activeJob);
		AppBool.EditMode = false;
		doDrawActiveJob();
		activeJob.CamCalculated = false;
	}

	public void doScaleSelectedItem()
	{
		MarbleTempVars.LastSelectedEntitiesList.Clear();
		List<Entity> list = new List<Entity>();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (entity.Selected && ((entity.EntityData != null) & (entity.EntityData is CustomData)))
			{
				MarbleTempVars.LastSelectedEntitiesList.Add(i);
				list.Add(entity);
			}
		}
		if (MarbleTempVars.LastSelectedEntitiesList.Count <= 0)
		{
			return;
		}
		UndoBuffer();
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint, ref MidPoint, ref MaxPoint);
		double num = MaxPoint.X - MinPoint.X;
		double num2 = MaxPoint.Y - MinPoint.Y;
		double num3 = num / num2;
		double num4 = 1.0;
		double num5 = 1.0;
		if (num > 0.0)
		{
			num4 = buMarbleCalc.varMarbleRunSettings.ScaleWidth / num;
		}
		if (num2 > 0.0)
		{
			num5 = buMarbleCalc.varMarbleRunSettings.ScaleHeight / num2;
		}
		if (num4 <= 0.0)
		{
			num4 = 1.0;
		}
		if (num5 <= 0.0)
		{
			num5 = 1.0;
		}
		if (buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio)
		{
			buMarbleCalc.varMarbleRunSettings.ScaleHeight = buMarbleCalc.varMarbleRunSettings.ScaleWidth / num3;
			num5 = num4;
		}
		_ = activeJob.Items.Count;
		for (int j = 0; j <= MarbleTempVars.LastSelectedEntitiesList.Count - 1; j++)
		{
			Entity entity2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[MarbleTempVars.LastSelectedEntitiesList[j]];
			CustomData customData = entity2.EntityData as CustomData;
			if (!((customData.typeDefination == entityTypeDefination.MarbleItem) & (customData.ID.Trim().Length >= 0)))
			{
				continue;
			}
			int result = -1;
			int.TryParse(customData.ID, out result);
			if (result < 0)
			{
				continue;
			}
			for (int k = 0; k <= activeJob.Items.Count - 1; k++)
			{
				if (activeJob.Items[k].ID == result)
				{
					MarbleItem Item = activeJob.Items[k];
					clsInit.cMarble.ScaleItem(ref Item, MinPoint, num4, num5);
					activeJob.CamCalculated = false;
					break;
				}
			}
		}
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref clsInit.appMarble.activeJob);
		AppBool.EditMode = false;
		doDrawActiveJob();
		activeJob.CamCalculated = false;
	}

	public void doSetAngle()
	{
		new List<int>();
		List<ShapeEntityIndex> Lst = new List<ShapeEntityIndex>();
		List<int> EntList = new List<int>();
		EdgeFoundArgs Args = new EdgeFoundArgs();
		doGetEdgeList(ref Lst, ref EntList, ref Args);
		if (Lst.Count != 0)
		{
			if (Lst.Count >= 2)
			{
				buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
				buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
				buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.Angle, buLangTranslate.preSentencesMarble.ThereisMoreThanOneEdgeDoYouWanttoContinue);
				buDialogMessageBoxYesNo2.ShowDialog();
				if (buDialogMessageBoxYesNo2.Result != DialogResult.Yes)
				{
					clsInit.appCommand.Reset();
					return;
				}
			}
			F_MarbleSetAngle f_MarbleSetAngle = new F_MarbleSetAngle();
			f_MarbleSetAngle.AngleValue = Args.FoundAngle;
			f_MarbleSetAngle.Init();
			f_MarbleSetAngle.ShowDialog();
			if (f_MarbleSetAngle.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			if (!(Math.Abs(f_MarbleSetAngle.AngleValue) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA))
			{
				activeJob.CamCalculated = false;
				for (int i = 0; i <= EntList.Count - 1; i++)
				{
					if ((EntList[i] >= 0) & (EntList[i] <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1))
					{
						Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntList[i]];
						if (entity.EntityData is CustomData)
						{
							((CustomData)entity.EntityData).infoAngle = f_MarbleSetAngle.AngleValue;
						}
					}
				}
				if (Lst.Count > 0)
				{
					UndoBuffer();
				}
				for (int j = 0; j <= Lst.Count - 1; j++)
				{
					for (int k = 0; k <= clsInit.appMarble.activeJob.Items.Count - 1; k++)
					{
						if (Lst[j].ID != clsInit.appMarble.activeJob.Items[k].ID)
						{
							continue;
						}
						int CamIndex = -1;
						int EdgeIndex = -1;
						if (!((Lst[j].CamID >= 0) & (Lst[j].EdgeID >= 0)))
						{
							continue;
						}
						clsInit.cMarble.GetCamIndexFromCamID(activeJob.Items[k].CamList, Lst[j].CamID, ref CamIndex);
						clsInit.cMarble.GetEdgeIndexFromEdgeID(activeJob.Items[k].Edges, Lst[j].EdgeID, ref EdgeIndex);
						if (CamIndex >= 0)
						{
							MarbleItemCam marbleItemCam = activeJob.Items[k].CamList[CamIndex];
							if (marbleItemCam.EntityList != null && ((Lst[j].indexEntity >= 0) & (Lst[j].indexEntity <= marbleItemCam.EntityList.Entities.Count - 1)))
							{
								marbleItemCam.EntityList.Entities[Lst[j].indexEntity].Orientation.A = f_MarbleSetAngle.AngleValue;
								marbleItemCam.EntityList.Entities[Lst[j].indexEntity].Marble.Angle = f_MarbleSetAngle.AngleValue;
							}
						}
						if ((EdgeIndex >= 0) & (EdgeIndex <= activeJob.Items[k].Edges.Count - 1))
						{
							activeJob.Items[k].Edges[EdgeIndex].Angle = f_MarbleSetAngle.AngleValue;
						}
					}
				}
				clsInit.appMarble.activeJob.CamCalculated = false;
				for (int l = 0; l <= clsInit.appMarble.activeJob.Items.Count - 1; l++)
				{
					if ((clsInit.appMarble.activeJob.Items[l].ItemType == MarbleItemType.Shape) | (clsInit.appMarble.activeJob.Items[l].ItemType == MarbleItemType.Contour))
					{
						MarbleItem Item = clsInit.appMarble.activeJob.Items[l];
						doShapeCutCalculation(ref Item);
						clsInit.cMarble.CamWireItemEntityToExtendEntity(ref Item);
					}
					for (int m = 0; m <= clsInit.appMarble.activeJob.Items[l].CamList.Count - 1; m++)
					{
						clsInit.appMarble.activeJob.Items[l].CamList[m].isCamCalculated = false;
					}
				}
				doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
				clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: false, CamItems: false, -1, ref clsInit.appMarble.activeJob);
				JobUpdate();
				doDrawActiveJob();
			}
			else
			{
				buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit);
			}
		}
		else
		{
			buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
		}
	}

	public void doSlatAdd(AddSlatArgs AddSlatData)
	{
		DialogResult dialogResult = DialogResult.None;
		List<int> EntList = new List<int>();
		List<ShapeEntityIndex> Lst = new List<ShapeEntityIndex>();
		EdgeFoundArgs Args = new EdgeFoundArgs();
		if (AddSlatData != null)
		{
			ShapeEntityIndex shapeEntityIndex = new ShapeEntityIndex();
			shapeEntityIndex.indexEdge = AddSlatData.IndexEdge;
			shapeEntityIndex.indexEntity = AddSlatData.IndexEntity;
			shapeEntityIndex.ID = AddSlatData.ID;
			shapeEntityIndex.EdgeID = AddSlatData.EdgeID;
			shapeEntityIndex.CamID = AddSlatData.CamID;
			Lst.Add(shapeEntityIndex);
			Args.Outside = true;
			dialogResult = DialogResult.OK;
		}
		else
		{
			doGetEdgeList(ref Lst, ref EntList, ref Args);
			if (Lst.Count == 0)
			{
				buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
				return;
			}
			if (Lst.Count >= 2)
			{
				buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
				buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
				buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.Angle, buLangTranslate.preSentencesMarble.MoreThanOneEdgeSelectedSelectOnlyOneEdge);
				buDialogMessageBoxYesNo2.ShowDialog();
				if (buDialogMessageBoxYesNo2.Result != DialogResult.Yes)
				{
					clsInit.appCommand.Reset();
					return;
				}
			}
			F_MarbleSlat f_MarbleSlat = new F_MarbleSlat();
			f_MarbleSlat.RuntimeSettings = new MarbleRuntimeSettings(buMarbleCalc.varMarbleRunSettings);
			f_MarbleSlat.Init();
			f_MarbleSlat.ShowDialog();
			dialogResult = f_MarbleSlat.PropertiesForm.Result;
			buMarbleCalc.varMarbleRunSettings = new MarbleRuntimeSettings(f_MarbleSlat.RuntimeSettings);
		}
		if (dialogResult != DialogResult.OK)
		{
			return;
		}
		activeJob.CamCalculated = false;
		int num = -1;
		if (Lst.Count > 0)
		{
			num = Lst[0].indexEntity;
		}
		if (!(Args.Outside && num >= 0))
		{
			return;
		}
		UndoBuffer();
		for (int i = 0; i <= Lst.Count - 1; i++)
		{
			for (int j = 0; j <= clsInit.appMarble.activeJob.Items.Count - 1; j++)
			{
				if (Lst[i].ID != clsInit.appMarble.activeJob.Items[j].ID)
				{
					continue;
				}
				int CamIndex = -1;
				int EdgeIndex = -1;
				MarbleItem Item = clsInit.appMarble.activeJob.Items[j];
				MarbleItemCam marbleItemCam = null;
				if ((Lst[i].CamID >= 0) & (Lst[i].EdgeID >= 0))
				{
					clsInit.cMarble.GetCamIndexFromCamID(activeJob.Items[j].CamList, Lst[i].CamID, ref CamIndex);
					clsInit.cMarble.GetEdgeIndexFromEdgeID(activeJob.Items[j].Edges, Lst[i].EdgeID, ref EdgeIndex);
				}
				if (CamIndex >= 0 && EdgeIndex >= 0)
				{
					marbleItemCam = Item.CamList[CamIndex];
					for (int k = 0; k <= Item.CamList.Count - 1; k++)
					{
						Item.CamList[k].isCamCalculated = false;
					}
				}
				if (num <= Item.EntGroup.Outside.Entities.Count - 1)
				{
					buEntity buEntity2 = Item.EntGroup.Outside.Entities[num];
					if (buEntity2.Marble == null)
					{
						buEntity2.Marble = new MarbleInfo();
					}
					buEntity2.Marble.SlatWidth = buMarbleCalc.varMarbleRunSettings.SlatWidth;
					buEntity2.Marble.SlatStartAngle = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
					buEntity2.Marble.SlatEndAngle = buMarbleCalc.varMarbleRunSettings.SlatEndAngle;
					if (buMarbleCalc.varMarbleRunSettings.SlatAddAngleSelectedEdge)
					{
						buEntity2.Orientation.A = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
						buEntity2.Marble.Angle = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
						if (marbleItemCam != null && marbleItemCam.EntityList != null && ((num >= 0) & (num <= marbleItemCam.EntityList.Entities.Count - 1)))
						{
							marbleItemCam.EntityList.Entities[num].Orientation.A = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
							marbleItemCam.EntityList.Entities[num].Marble.Angle = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
						}
					}
					if (EdgeIndex <= Item.Edges.Count - 1)
					{
						if (Item.Edges[EdgeIndex].Slat == null)
						{
							Item.Edges[EdgeIndex].Slat = new marbleSlatPars();
						}
						clsInit.cMarble.GetStripID(activeJob, ref Item.Edges[EdgeIndex].Slat.DataSlat.StripID);
						Item.Edges[EdgeIndex].Slat.DataSlat.Enable = true;
						Item.Edges[EdgeIndex].Slat.DataSlat.indexEntitiy = num;
						Item.Edges[EdgeIndex].Slat.DataSlat.ItemID = Lst[i].ItemID;
						Item.Edges[EdgeIndex].Slat.DataSlat.EdgeID = Lst[i].EdgeID;
						Item.Edges[EdgeIndex].Slat.DataSlat.CamID = Lst[i].CamID;
						Item.Edges[EdgeIndex].Slat.DataSlat.Width = buMarbleCalc.varMarbleRunSettings.SlatWidth;
						Item.Edges[EdgeIndex].Slat.DataSlat.StartAngle = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
						Item.Edges[EdgeIndex].Slat.DataSlat.EndAngle = buMarbleCalc.varMarbleRunSettings.SlatEndAngle;
						clsInit.cMarble.CreatedSlatEntities(buEntity2, Item.EntGroup, ref Item.Edges[EdgeIndex].Slat.Solid, ref Item.Edges[EdgeIndex].Slat.cutEntities, ref Item.Edges[EdgeIndex].Slat.connectEntities);
						CustomData customData = new CustomData();
						customData.ID = Item.ID.ToString();
						customData.Command = clsInit.cMarble.SetEntityCommand(MarbleCommandsEntity.Slat.ToString(), Item.ID, num, num, -1, -1, "", "");
						Item.Edges[EdgeIndex].Slat.Solid.EntityData = customData;
						if (marbleItemCam != null)
						{
							marbleItemCam.isCamCalculated = false;
							if (marbleItemCam.WireAuxEntities == null)
							{
								marbleItemCam.WireAuxEntities = new List<List<buEntity>>();
							}
							for (int l = 0; l <= Item.Edges[EdgeIndex].Slat.cutEntities.Count - 1; l++)
							{
								List<buEntity> refEntities = new List<buEntity>();
								buEntity copiedEntity = null;
								buEntity.Copy(Item.Edges[EdgeIndex].Slat.cutEntities[l], ref copiedEntity);
								if (copiedEntity.Marble == null)
								{
									copiedEntity.Marble = new MarbleInfo();
								}
								refEntities.Add(copiedEntity);
								if (l != 0)
								{
									copiedEntity.Orientation.A = Item.Edges[EdgeIndex].Slat.DataSlat.EndAngle;
									copiedEntity.Marble.Angle = Item.Edges[EdgeIndex].Slat.DataSlat.EndAngle;
								}
								else
								{
									copiedEntity.Orientation.A = Item.Edges[EdgeIndex].Slat.DataSlat.StartAngle;
									copiedEntity.Marble.Angle = Item.Edges[EdgeIndex].Slat.DataSlat.StartAngle;
								}
								clsInit.cVector5.Move(0.0, 0.0, Item.Settings.settingMarbleCam.TargetZ, ref refEntities);
								marbleConvexConcaveCalculationPars pars = new marbleConvexConcaveCalculationPars();
								List<List<buEntity>> SawEntities = new List<List<buEntity>>();
								ClockDirectionType cDRefEnt = ClockDirectionType.CCW;
								if (Item.ClockDir == ClockDirectionType.CCW)
								{
									if (l != 0)
									{
										cDRefEnt = ClockDirectionType.CCW;
										refEntities[0].Orientation.A = buMarbleCalc.varMarbleRunSettings.SlatEndAngle;
									}
									else
									{
										cDRefEnt = ClockDirectionType.CW;
										refEntities[0].Orientation.A = 0.0 - buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
									}
								}
								clsInit.cMarble.OffsetModifiedEntities(refEntities, cDRefEnt, pars, marbleItemCam.ToolSelected, buMarbleCalc.varOperation, ref SawEntities);
								if (SawEntities.Count <= 0)
								{
									continue;
								}
								for (int m = 0; m <= SawEntities[0].Count - 1; m++)
								{
									if (SawEntities[0][m].Marble == null)
									{
										SawEntities[0][m].Marble = new MarbleInfo();
									}
									if (l != 0)
									{
										SawEntities[0][m].Marble.Sequence = CamSequence.StripStartCut;
									}
									else
									{
										SawEntities[0][m].Marble.Sequence = CamSequence.StripEndCut;
									}
									SawEntities[0][m].Marble.ItemID = Item.ID;
									SawEntities[0][m].Marble.indexEdge = num;
									SawEntities[0][m].Marble.CommandID = Item.Edges[EdgeIndex].Slat.DataSlat.StripID;
									SawEntities[0][m].Marble.Command = MarbleCommandsEntity.Slat;
								}
								marbleItemCam.WireAuxEntities.Add(SawEntities[0]);
							}
						}
					}
				}
				if (buMarbleCalc.varMarbleRunSettings.SlatAddAngleSelectedEdge)
				{
					doShapeCutCalculation(ref Item);
				}
				clsInit.cMarble.ItemSizeCalculation(ref Item);
			}
		}
		doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: false, CamItems: false, -1, ref clsInit.appMarble.activeJob);
		JobUpdate();
		doDrawActiveJob();
	}

	public void doSlatDelete(int ItemID, int EdgeIndex)
	{
		int num = 0;
		for (int i = 0; i <= clsInit.appMarble.activeJob.Items.Count - 1; i++)
		{
			if (clsInit.appMarble.activeJob.Items[i].ID != ItemID)
			{
				continue;
			}
			if (num == 0)
			{
				UndoBuffer();
			}
			MarbleItem Item = clsInit.appMarble.activeJob.Items[i];
			if ((EdgeIndex >= 0) & (EdgeIndex <= Item.Edges.Count - 1))
			{
				Item.Edges[EdgeIndex].Slat.DataSlat.Enable = false;
				Item.Edges[EdgeIndex].Slat.Solid = null;
			}
			for (int j = 0; j <= Item.CamList.Count - 1; j++)
			{
				Item.CamList[j].isCamCalculated = false;
				if (Item.CamList[j].WireAuxEntities == null)
				{
					continue;
				}
				for (int num2 = Item.CamList[j].WireAuxEntities.Count - 1; num2 >= 0; num2--)
				{
					for (int num3 = Item.CamList[j].WireAuxEntities[num2].Count - 1; num3 >= 0; num3--)
					{
						buEntity buEntity2 = Item.CamList[j].WireAuxEntities[num2][num3];
						if (buEntity2.Marble.Command != MarbleCommandsEntity.None && buEntity2.Marble.Command == MarbleCommandsEntity.Slat && ((buEntity2.Marble.indexEdge == EdgeIndex) & (buEntity2.Marble.ItemID == ItemID)))
						{
							Item.CamList[j].WireAuxEntities[num2].RemoveAt(num3);
						}
					}
					if (Item.CamList[j].WireAuxEntities[num2].Count == 0)
					{
						Item.CamList[j].WireAuxEntities.RemoveAt(num2);
					}
				}
			}
			clsInit.cMarble.ItemSizeCalculation(ref Item);
			num++;
		}
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref clsInit.appMarble.activeJob);
	}

	public void doCollopseAdd(AddCollapseArgs AddCollapseData)
	{
		DialogResult dialogResult = DialogResult.None;
		new List<int>();
		List<ShapeEntityIndex> Lst = new List<ShapeEntityIndex>();
		List<int> EntList = new List<int>();
		if (AddCollapseData != null)
		{
			ShapeEntityIndex shapeEntityIndex = new ShapeEntityIndex();
			shapeEntityIndex.indexInside = AddCollapseData.IndexInsideEntity;
			shapeEntityIndex.ID = AddCollapseData.ItemID;
			Lst.Add(shapeEntityIndex);
			dialogResult = DialogResult.OK;
		}
		else
		{
			EdgeFoundArgs Args = new EdgeFoundArgs();
			doGetEdgeList(ref Lst, ref EntList, ref Args);
			if (Lst.Count == 0)
			{
				buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
				return;
			}
			F_MarbleCollapse f_MarbleCollapse = new F_MarbleCollapse();
			f_MarbleCollapse.RuntimeSettings = new MarbleRuntimeSettings(buMarbleCalc.varMarbleRunSettings);
			f_MarbleCollapse.RuntimeSettings.CollapseEnable = true;
			f_MarbleCollapse.Init();
			f_MarbleCollapse.ShowDialog();
			dialogResult = f_MarbleCollapse.PropertiesForm.Result;
			buMarbleCalc.varMarbleRunSettings = new MarbleRuntimeSettings(f_MarbleCollapse.RuntimeSettings);
		}
		if (dialogResult != DialogResult.OK)
		{
			return;
		}
		activeJob.CamCalculated = false;
		marbleCollapseItem marbleCollapseItem2 = new marbleCollapseItem();
		marbleCollapseItem2.Depth = buMarbleCalc.varMarbleRunSettings.CollapseDepth;
		marbleCollapseItem2.Offset = buMarbleCalc.varMarbleRunSettings.CollapseOffset;
		marbleCollapseItem2.Direction = buMarbleCalc.varMarbleRunSettings.CollapseDirection;
		marbleCollapseItem2.ToolType = buMarbleCalc.varMarbleRunSettings.CollapseToolType;
		marbleCollapseItem2.EntityIndex = Lst[0].indexEntitySub;
		marbleCollapseItem2.isOutsideEntity = Lst[0].Outside;
		marbleCollapseItem2.Enable = buMarbleCalc.varMarbleRunSettings.CollapseEnable;
		if (marbleCollapseItem2.Enable)
		{
			if (Lst.Count > 0)
			{
				UndoBuffer();
			}
			for (int i = 0; i <= Lst.Count - 1; i++)
			{
				if (i == 0)
				{
					marbleCollapseItem2.ItemID = Lst[i].ID;
				}
				for (int j = 0; j <= clsInit.appMarble.activeJob.Items.Count - 1; j++)
				{
					if (Lst[i].ID != clsInit.appMarble.activeJob.Items[j].ID)
					{
						continue;
					}
					MarbleItem marbleItem = clsInit.appMarble.activeJob.Items[j];
					if (marbleCollapseItem2.isOutsideEntity)
					{
						if (marbleItem.EntGroup.Outside != null)
						{
							buEntity.Copy(marbleItem.EntGroup.Outside.Entities, ref marbleCollapseItem2.refEntity);
						}
					}
					else
					{
						int indexInside = Lst[i].indexInside;
						if (marbleItem.EntGroup.Inside != null && ((indexInside >= 0) & (indexInside <= marbleItem.EntGroup.Inside.Count - 1)))
						{
							for (int k = 0; k <= marbleItem.EntGroup.Inside[indexInside].Entities.Count - 1; k++)
							{
								if (marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble == null)
								{
									marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble = new MarbleInfo();
								}
								if (marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble.Collapse == null)
								{
									marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble.Collapse = new marbleCollapsePars();
								}
								marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble.Collapse.Enable = buMarbleCalc.varMarbleRunSettings.CollapseEnable;
								marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble.Collapse.Depth = buMarbleCalc.varMarbleRunSettings.CollapseDepth;
								marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble.Collapse.Offset = buMarbleCalc.varMarbleRunSettings.CollapseOffset;
								marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble.Collapse.Step = buMarbleCalc.varMarbleRunSettings.CollapseStep;
								marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble.Collapse.ToolType = buMarbleCalc.varMarbleRunSettings.CollapseToolType;
								marbleItem.EntGroup.Inside[indexInside].Entities[i].Marble.Collapse.Direction = buMarbleCalc.varMarbleRunSettings.CollapseDirection;
								marbleCollapseItem2.IndexInsideEntity = indexInside;
							}
							buEntity.Copy(marbleItem.EntGroup.Inside[indexInside].Entities, ref marbleCollapseItem2.refEntity);
						}
					}
					if (marbleCollapseItem2.refEntity == null)
					{
						continue;
					}
					clsInit.cVector5.Move(0.0, 0.0, marbleItem.SizeItem.Depth - marbleCollapseItem2.Depth, ref marbleCollapseItem2.refEntity);
					List<Point3D> Points = new List<Point3D>();
					clsInit.cVector5.EntitiesToPointsWithCamDirection(marbleCollapseItem2.refEntity, ref Points);
					ClockDirectionType clockDirection = clsInit.cVector5.GetClockDirection(Points);
					double num = 0.0;
					if (clockDirection != ClockDirectionType.CW)
					{
						num = marbleCollapseItem2.Offset;
						if (marbleCollapseItem2.Direction == OutsideInsideType.Inside)
						{
							num = 0.0 - marbleCollapseItem2.Offset;
						}
					}
					else
					{
						num = 0.0 - marbleCollapseItem2.Offset;
						if (marbleCollapseItem2.Direction == OutsideInsideType.Inside)
						{
							num = marbleCollapseItem2.Offset;
						}
					}
					LinearPath linearPath = new LinearPath(Points);
					ICurve[] array = linearPath.Offset(num, Vector3D.AxisZ, sharp: true);
					if (array != null && array.Length != 0)
					{
						buEntity copiedEntity = null;
						buEntity.Copy((Entity)array[0], ref copiedEntity);
						marbleCollapseItem2.ContourEntity = new List<buEntity>();
						marbleCollapseItem2.ContourEntity.Add(copiedEntity);
						List<ICurve> list = new List<ICurve>();
						list.Add(linearPath);
						list.Add(array[0]);
						devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(list, Plane.XY);
						marbleCollapseItem2.entSolid = region.ExtrudeAsMesh(marbleCollapseItem2.Depth, 0.1, Mesh.natureType.RichSmooth);
						marbleCollapseItem2.entSolid.Translate(0.0, 0.0, marbleItem.SizeItem.Depth - marbleCollapseItem2.Depth);
						marbleCollapseItem2.entSolid.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemCollopse.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemCollopse.Color);
						MarbleItemCam marbleItemCam = new MarbleItemCam();
						marbleItemCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleClosedContourMilling.buPar);
						clsInit.cMarble.MarbleCamParameterToCamParameter(buMarbleCalc.varOperation.settingMarbleCam, marbleItemCam.ToolType, marbleItemCam.WireType, ref marbleItemCam.setCam);
						marbleItemCam.setCam.Steps.StartValue = marbleItem.SizeItem.Depth;
						marbleItemCam.setCam.Steps.EndValue = marbleItem.SizeItem.Depth - marbleCollapseItem2.Depth;
						if (marbleCollapseItem2.Direction != OutsideInsideType.Outside)
						{
							marbleItemCam.setCam.Offsets.ClosedContour = CamClosedContourType.Outter;
						}
						else
						{
							marbleItemCam.setCam.Offsets.ClosedContour = CamClosedContourType.Inner;
						}
						marbleItemCam.ToolType = marbleCollapseItem2.ToolType;
						if (marbleItemCam.ToolType != MarbleToolType.MillingHead)
						{
							marbleItemCam.setCam.Speeds.Feed = buMarbleCalc.varOperation.settingMarbleCam.MillingCuttingVelocity;
							marbleItemCam.setCam.Speeds.Plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeVelocity;
							marbleItemCam.setCam.Speeds.FirstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeFirstVelocity;
							marbleItemCam.setCam.Distances.Safe = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
							marbleItemCam.setCam.Distances.Rapid = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
							marbleItemCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
							marbleItemCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMilling);
						}
						else
						{
							marbleItemCam.setCam.Speeds.Feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadCuttingVelocity;
							marbleItemCam.setCam.Speeds.Plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeVelocity;
							marbleItemCam.setCam.Speeds.FirstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeFirstVelocity;
							marbleItemCam.setCam.Distances.Safe = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
							marbleItemCam.setCam.Distances.Rapid = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
							marbleItemCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
							marbleItemCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMillingHead);
						}
						marbleItemCam.WireType = CamWireFrameType.Pocket;
						if (marbleItemCam.ToolSelected.Geometry.Diameter > marbleCollapseItem2.Offset * 0.9)
						{
							marbleItemCam.WireType = CamWireFrameType.Contour;
						}
						List<buEntity> copiedEntities = new List<buEntity>();
						marbleItemCam.EntityList = new buEntityList();
						if (marbleItemCam.WireType == CamWireFrameType.Pocket)
						{
							buEntity.Copy(marbleCollapseItem2.refEntity, ref copiedEntities);
							marbleItemCam.EntityList.Entities.AddRange(copiedEntities);
						}
						buEntity copiedEntity2 = null;
						buEntity.Copy(copiedEntity, ref copiedEntity2);
						marbleItemCam.EntityList.Entities.Add(copiedEntity2);
						marbleItemCam.indexInside = marbleCollapseItem2.EntityIndex;
						marbleItemCam.CamName = buLangTranslate.preDef.Collapse + " " + buLangTranslate.preDef.Offset + " " + buLangTranslate.preDef.Cut;
						marbleItemCam.CamMarbleType = MarbleCamType.Collapse;
						marbleItemCam.CamMode = MarbleCamMode.Contour;
						marbleItemCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
						marbleItemCam.CamType = CamType.Contour;
						marbleItemCam.indexCollapse = marbleItem.Collapses.Count;
						clsInit.cMarble.GetCamID(activeJob, marbleItem.CamList, ref marbleItemCam.CamID);
						marbleItem.CamList.Add(marbleItemCam);
						marbleCollapseItem2.ID = marbleItem.Collapses.Count;
						marbleItem.Collapses.Add(marbleCollapseItem2);
					}
				}
			}
			clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref clsInit.appMarble.activeJob);
			doDrawActiveJob();
		}
		else
		{
			UndoBuffer();
			for (int l = 0; l <= Lst.Count - 1; l++)
			{
				doCollopseRemove(Lst[l]);
			}
			doDrawActiveJob();
		}
	}

	public void doCollopseRemove(ShapeEntityIndex ShapeEntity)
	{
		int num = 0;
		for (int i = 0; i <= clsInit.appMarble.activeJob.Items.Count - 1; i++)
		{
			if (ShapeEntity.ID != clsInit.appMarble.activeJob.Items[i].ID)
			{
				continue;
			}
			MarbleItem marbleItem = clsInit.appMarble.activeJob.Items[i];
			if (ShapeEntity.Outside)
			{
				continue;
			}
			for (int num2 = marbleItem.CamList.Count - 1; num2 >= 0; num2--)
			{
				MarbleItemCam marbleItemCam = marbleItem.CamList[num2];
				if ((marbleItemCam.CamMarbleType == MarbleCamType.Collapse) & (marbleItemCam.indexInside == ShapeEntity.indexEntitySub))
				{
					if (num == 0)
					{
						UndoBuffer();
					}
					if ((marbleItemCam.indexCollapse >= 0) & (marbleItemCam.indexCollapse <= marbleItem.Collapses.Count - 1))
					{
						marbleItem.Collapses.RemoveAt(marbleItemCam.indexCollapse);
					}
					marbleItem.CamList.RemoveAt(num2);
					num++;
				}
			}
		}
		clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: true, -1, ref clsInit.appMarble.activeJob);
	}

