	public void doOffset()
	{
		try
		{
			List<ShapeEntityIndex> list = new List<ShapeEntityIndex>();
			bool outside = true;
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
			{
				Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
				if (entity.Selected && ((entity.EntityData != null) & (entity.EntityData is CustomData)) && ((CustomData)entity.EntityData).Tags == "Edge")
				{
					int result = -1;
					_ = ((CustomData)entity.EntityData).infoBasePoint;
					if (((CustomData)entity.EntityData).infoData != null && ((CustomData)entity.EntityData).infoData == "Inside")
					{
						outside = false;
					}
					if (result.ToString().Trim().Length > 0)
					{
						int.TryParse(((CustomData)entity.EntityData).ID, out result);
					}
					if (result >= 0)
					{
						list.Add(new ShapeEntityIndex(((CustomData)entity.EntityData).EntitySubIndex, ((CustomData)entity.EntityData).EntityIndex, result, outside, ((CustomData)entity.EntityData).infoAngle, ((CustomData)entity.EntityData).RefIndex, ((CustomData)entity.EntityData).CamIndex));
					}
				}
			}
			if (list.Count != 0)
			{
				if (list.Count >= 2)
				{
					buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
					buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
					buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.Angle, buLangTranslate.preSentencesMarble.ThereisMoreThanOneEdgeDoYouWanttoContinue);
					buDialogMessageBoxYesNo2.ShowDialog();
					if (buDialogMessageBoxYesNo2.Result != DialogResult.Yes)
					{
						clsInit.appCommand.Reset();
						return;
					}
				}
				F_MarbleEventOffset f_MarbleEventOffset = new F_MarbleEventOffset();
				f_MarbleEventOffset.Init();
				f_MarbleEventOffset.ShowDialog();
				if (f_MarbleEventOffset.PropertiesForm.Result != DialogResult.OK || buMarbleCalc.varMarbleRunSettings.ExtendLength == 0.0)
				{
					return;
				}
				activeJob.CamCalculated = false;
				if (list.Count > 0)
				{
					UndoBuffer();
				}
				for (int j = 0; j <= list.Count - 1; j++)
				{
					for (int k = 0; k <= clsInit.appMarble.activeJob.Items.Count - 1; k++)
					{
						if (list[j].ID == clsInit.appMarble.activeJob.Items[k].ID)
						{
							MarbleItem refItem = clsInit.appMarble.activeJob.Items[k];
							clsInit.cMarble.OffsetItem(ref refItem, list[j].indexEntity, list[j].indexEntitySub, buMarbleCalc.varMarbleRunSettings.OffsetDistance);
							entitiesGroupForContour.Clear();
							buEntitiesGroup item = new buEntitiesGroup(refItem.EntGroup);
							entitiesGroupForContour.Add(item);
							doAddItemShapeContour(new Point3D(), isShape: false, isFinished: true, isText: false, isMilling: false, isMillingHead: false, isWaterJet: false, buMarbleCalc.varMarbleSettings.ContourOnlineCamCalculation, k);
							for (int l = 0; l <= clsInit.appMarble.activeJob.Items[k].CamList.Count - 1; l++)
							{
								clsInit.appMarble.activeJob.Items[k].CamList[l].isCamCalculated = false;
							}
						}
					}
				}
				clsInit.appMarble.activeJob.CamCalculated = false;
				doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
				clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: false, CamItems: false, -1, ref clsInit.appMarble.activeJob);
				JobUpdate();
				doDrawActiveJob();
			}
			else
			{
				buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
			}
		}
		catch (Exception)
		{
		}
	}

	public void doAlignmentMove(MarbleCadCamCommands Cmd, double Value)
	{
		double dX = 0.0;
		double dY = 0.0;
		if (Cmd != MarbleCadCamCommands.MoveLeft)
		{
			if (Cmd != MarbleCadCamCommands.MoveRight)
			{
				if (Cmd != MarbleCadCamCommands.MoveUp)
				{
					if (Cmd != MarbleCadCamCommands.MoveDown)
					{
						if (Cmd != MarbleCadCamCommands.MoveLeftUp)
						{
							if (Cmd != MarbleCadCamCommands.MoveLeftDown)
							{
								if (Cmd != MarbleCadCamCommands.MoveRightUp)
								{
									if (Cmd == MarbleCadCamCommands.MoveRightDown)
									{
										dX = Value;
										dY = 0.0 - Value;
									}
								}
								else
								{
									dX = Value;
									dY = Value;
								}
							}
							else
							{
								dX = 0.0 - Value;
								dY = 0.0 - Value;
							}
						}
						else
						{
							dX = 0.0 - Value;
							dY = Value;
						}
					}
					else
					{
						dY = 0.0 - Value;
					}
				}
				else
				{
					dY = Value;
				}
			}
			else
			{
				dX = Value;
			}
		}
		else
		{
			dX = 0.0 - Value;
		}
		if (buMarbleCalc.SelectedItem.SelectionItems.Count != 0)
		{
			doMoveSelectedItem(dX, dY);
		}
		else
		{
			doMoveAllItem(dX, dY);
		}
	}

