	public void doEdgeChangeDirection()
	{
		string text = "doEdgeChangeDirection";
		try
		{
			if (!((buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand == MarbleOperationSelectionCommand.WireItem) & (buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0) & (buMarbleCalc.SelectedItem.ActiveItem.indexEdge >= 0)) || buMarbleCalc.SelectedItem.ActiveItem.indexCam < 0)
			{
				return;
			}
			MarbleItem Item = clsInit.appMarble.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
			if (Item.CamList.Count <= 0)
			{
				return;
			}
			MarbleItemCam marbleItemCam = clsInit.appMarble.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem].CamList[buMarbleCalc.SelectedItem.ActiveItem.indexCam];
			if (marbleItemCam.WireEntities == null || marbleItemCam.WireEntities.Count <= 0)
			{
				return;
			}
			for (int i = 0; i <= marbleItemCam.WireEntities.Count - 1; i++)
			{
				for (int j = 0; j <= marbleItemCam.WireEntities[i].Count - 1; j++)
				{
					buEntity buEntity2 = marbleItemCam.WireEntities[i][j];
					if ((buEntity2.Info.EntityIndex == buMarbleCalc.SelectedItem.ActiveItem.indexEdge) & (buEntity2.Info.EntitySubIndex == buMarbleCalc.SelectedItem.ActiveItem.indexEdgeSub))
					{
						if (buEntity2.sortDirection != entitySortDirection.Normal)
						{
							buEntity2.sortDirection = entitySortDirection.Normal;
						}
						else
						{
							buEntity2.sortDirection = entitySortDirection.Reverse;
						}
					}
				}
			}
			marbleItemCam.isCamCalculated = false;
			clsInit.cMarble.EdgePropertiesFromWireEntities(marbleItemCam.WireEntities, ref Item.Edges);
			bool isExpanded = tnPanel.IsExpanded;
			bool isExpanded2 = tnItem.IsExpanded;
			bool isExpanded3 = tnCams.IsExpanded;
			bool isExpanded4 = tnEdgeInside.IsExpanded;
			bool isExpanded5 = tnEdgeOutside.IsExpanded;
			JobUpdate();
			if (isExpanded)
			{
				tnPanel.Expand();
			}
			if (isExpanded2)
			{
				tnItem.Expand();
			}
			if (isExpanded3)
			{
				tnCams.Expand();
			}
			if (isExpanded4)
			{
				tnEdgeInside.Expand();
			}
			if (isExpanded5)
			{
				tnEdgeOutside.Expand();
			}
			doCamCalculateMarbleItem(buMarbleCalc.SelectedItem.ActiveItem.indexItem, isLast: false, null, ref Item);
			clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: false, CamItems: false, -1, ref clsInit.appMarble.activeJob);
			doDrawActiveJob();
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doEdgeMoveUpDown(bool Up)
	{
		string text = "doEdgeMoveUpDown";
		try
		{
			if (!((buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand == MarbleOperationSelectionCommand.WireItem) & (buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0) & (buMarbleCalc.SelectedItem.ActiveItem.indexEdge >= 0)) || buMarbleCalc.SelectedItem.ActiveItem.indexCam < 0)
			{
				return;
			}
			MarbleItem Item = clsInit.appMarble.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
			if (Item.CamList.Count <= 0)
			{
				return;
			}
			MarbleItemCam marbleItemCam = clsInit.appMarble.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem].CamList[buMarbleCalc.SelectedItem.ActiveItem.indexCam];
			if (marbleItemCam.WireEntities == null || marbleItemCam.WireEntities.Count <= 1)
			{
				return;
			}
			int num = -1;
			List<int> list = new List<int>();
			for (int i = 0; i <= marbleItemCam.WireEntities.Count - 1; i++)
			{
				for (int j = 0; j <= marbleItemCam.WireEntities[i].Count - 1; j++)
				{
					buEntity buEntity2 = marbleItemCam.WireEntities[i][j];
					if ((buEntity2.Info.EntityIndex == buMarbleCalc.SelectedItem.ActiveItem.indexEdge) & (buEntity2.Info.EntitySubIndex == buMarbleCalc.SelectedItem.ActiveItem.indexEdgeSub))
					{
						num = i;
						list.Add(i);
					}
				}
				if (num < 0)
				{
				}
			}
			if (num >= 0)
			{
				for (int k = 0; k <= Item.Edges.Count - 1; k++)
				{
					if (!((Item.Edges[k].IndexEntity == buMarbleCalc.SelectedItem.ActiveItem.indexEdge) & (Item.Edges[k].IndexEntitySub == buMarbleCalc.SelectedItem.ActiveItem.indexEdgeSub)))
					{
						continue;
					}
					if (!Up)
					{
						if (k <= Item.Edges.Count - 2)
						{
							marbleEdgeItem item = Item.Edges[k];
							Item.Edges.RemoveAt(k);
							Item.Edges.Insert(k + 1, item);
						}
					}
					else if (k > 0)
					{
						marbleEdgeItem item2 = Item.Edges[k];
						Item.Edges.RemoveAt(k);
						Item.Edges.Insert(k - 1, item2);
					}
					k = Item.Edges.Count;
				}
			}
			if (!Up)
			{
				for (int l = 0; l <= list.Count - 1; l++)
				{
					num = list[l];
					if (num <= marbleItemCam.WireEntities.Count - 2)
					{
						List<buEntity> item3 = marbleItemCam.WireEntities[num];
						marbleItemCam.WireEntities.RemoveAt(num);
						marbleItemCam.WireEntities.Insert(num + 1, item3);
						marbleItemCam.isCamCalculated = false;
					}
				}
			}
			else if (num >= 1)
			{
				List<buEntity> item4 = marbleItemCam.WireEntities[num];
				marbleItemCam.WireEntities.RemoveAt(num);
				marbleItemCam.WireEntities.Insert(num - 1, item4);
				marbleItemCam.isCamCalculated = false;
			}
			clsInit.cMarble.EdgePropertiesFromWireEntities(marbleItemCam.WireEntities, ref Item.Edges);
			bool isExpanded = tnPanel.IsExpanded;
			bool isExpanded2 = tnItem.IsExpanded;
			bool isExpanded3 = tnCams.IsExpanded;
			bool isExpanded4 = tnEdgeInside.IsExpanded;
			bool isExpanded5 = tnEdgeOutside.IsExpanded;
			JobUpdate();
			if (isExpanded)
			{
				tnPanel.Expand();
			}
			if (isExpanded2)
			{
				tnItem.Expand();
			}
			if (isExpanded3)
			{
				tnCams.Expand();
			}
			if (isExpanded4)
			{
				tnEdgeInside.Expand();
			}
			if (isExpanded5)
			{
				tnEdgeOutside.Expand();
			}
			doCamCalculateMarbleItem(buMarbleCalc.SelectedItem.ActiveItem.indexItem, isLast: false, null, ref Item);
			clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: false, CamItems: false, -1, ref clsInit.appMarble.activeJob);
			doDrawActiveJob();
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_0, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

