	public void doGetEdgeList(ref List<ShapeEntityIndex> Lst, ref List<int> EntList, ref EdgeFoundArgs Args)
	{
		Args.FoundAngle = 0.0;
		Args.Outside = false;
		Args.pntPick = new Point3D();
		Lst = new List<ShapeEntityIndex>();
		EntList = new List<int>();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (!entity.Selected || !((entity.EntityData != null) & (entity.EntityData is CustomData)) || !(((CustomData)entity.EntityData).Tags == "Edge"))
			{
				continue;
			}
			int result = -1;
			if (((CustomData)entity.EntityData).infoData == null || !(((CustomData)entity.EntityData).infoData == "Inside"))
			{
				if (((CustomData)entity.EntityData).infoData != null && ((CustomData)entity.EntityData).infoData == "Outside")
				{
					Args.Outside = true;
				}
			}
			else
			{
				Args.Outside = false;
			}
			Args.pntPick = ((CustomData)entity.EntityData).infoBasePoint;
			if (result.ToString().Trim().Length > 0)
			{
				int.TryParse(((CustomData)entity.EntityData).ID, out result);
			}
			if (result < 0)
			{
			}
			ShapeEntityIndex shapeEntityIndex = new ShapeEntityIndex(((CustomData)entity.EntityData).EntitySubIndex, ((CustomData)entity.EntityData).EntityIndex, result, Args.Outside, ((CustomData)entity.EntityData).infoAngle, ((CustomData)entity.EntityData).RefIndex, ((CustomData)entity.EntityData).CamIndex);
			shapeEntityIndex.CamID = ((CustomData)entity.EntityData).CamID;
			shapeEntityIndex.ItemID = ((CustomData)entity.EntityData).ItemID;
			shapeEntityIndex.EdgeID = ((CustomData)entity.EntityData).EdgeID;
			shapeEntityIndex.indexInside = ((CustomData)entity.EntityData).InsideIndex;
			Lst.Add(shapeEntityIndex);
			EntList.Add(i);
			if (((CustomData)entity.EntityData).infoAngle != 0.0)
			{
				Args.FoundAngle = ((CustomData)entity.EntityData).infoAngle;
			}
		}
	}

