	public void doMoveDownItem(ref int SelectedIndex)
	{
		if ((activeJob.Items.Count > 1) & (SelectedIndex >= 0) & (SelectedIndex < activeJob.Items.Count - 1))
		{
			MarbleItem item = activeJob.Items[SelectedIndex];
			activeJob.Items.RemoveAt(SelectedIndex);
			SelectedIndex++;
			activeJob.Items.Insert(SelectedIndex, item);
			clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: false, -1, ref clsInit.appMarble.activeJob);
		}
	}

	public void doMoveUpItem(ref int SelectedIndex)
	{
		if ((activeJob.Items.Count > 1) & (SelectedIndex > 0) & (SelectedIndex <= activeJob.Items.Count - 1))
		{
			MarbleItem item = activeJob.Items[SelectedIndex];
			activeJob.Items.RemoveAt(SelectedIndex);
			SelectedIndex--;
			activeJob.Items.Insert(SelectedIndex, item);
			clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: true, CamItems: false, -1, ref clsInit.appMarble.activeJob);
		}
	}

	public void doEditItem()
	{
		List<double> list = new List<double>();
		List<int> list2 = new List<int>();
		List<ShapeEntityIndex> list3 = new List<ShapeEntityIndex>();
		List<int> list4 = new List<int>();
		bool flag = true;
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i];
			if (!entity.Selected || !((entity.EntityData != null) & (entity.EntityData is CustomData)) || !(((CustomData)entity.EntityData).Tags == "Edge"))
			{
				continue;
			}
			int result = -1;
			if (((CustomData)entity.EntityData).infoData != null && ((CustomData)entity.EntityData).infoData == "Inside")
			{
				flag = false;
			}
			if (result.ToString().Trim().Length > 0)
			{
				int.TryParse(((CustomData)entity.EntityData).ID, out result);
			}
			if (result >= 0)
			{
				list2.Add(result);
			}
			list3.Add(new ShapeEntityIndex(((CustomData)entity.EntityData).RefIndex, ((CustomData)entity.EntityData).Sequence));
			list4.Add(i);
			if (list.Count != 0)
			{
				bool flag2 = true;
				for (int j = 0; j <= list.Count - 1; j++)
				{
					if (buCompare5.EQ(list[j], ((CustomData)entity.EntityData).infoAngle))
					{
						flag2 = false;
					}
				}
				if (flag2)
				{
					list.Add(((CustomData)entity.EntityData).infoAngle);
				}
			}
			else
			{
				list.Add(((CustomData)entity.EntityData).infoAngle);
			}
		}
		if (list2.Count != 0)
		{
			if (list2.Count >= 2)
			{
				buDialogMessageBoxYesNo buDialogMessageBoxYesNo2 = new buDialogMessageBoxYesNo();
				buDialogMessageBoxYesNo2.StartPosition = FormStartPosition.CenterScreen;
				buDialogMessageBoxYesNo2.Init(buLangTranslate.preDef.Angle, buLangTranslate.preSentencesMarble.ThereisMoreThanOneEdgeDoYouWanttoContinue);
				buDialogMessageBoxYesNo2.ShowDialog();
				if (buDialogMessageBoxYesNo2.Result != DialogResult.Yes)
				{
					clsInit.appCommand.Reset();
					return;
				}
			}
			activeJob.CamCalculated = false;
			for (int k = 0; k <= list2.Count - 1; k++)
			{
				for (int l = 0; l <= clsInit.appMarble.activeJob.Items.Count - 1; l++)
				{
					if (list2[k] != clsInit.appMarble.activeJob.Items[l].ID || flag || !((activeJob.Items[l].EntGroup.Inside != null) & (list3.Count > 0)))
					{
						continue;
					}
					for (int m = 0; m <= list3.Count - 1; m++)
					{
						int indexEntity = list3[m].indexEntity;
						int indexEntitySub = list3[m].indexEntitySub;
						if (!((indexEntitySub >= 0) & (indexEntitySub <= activeJob.Items[l].EntGroup.Inside.Count - 1)) || !((indexEntity >= 0) & (indexEntity <= activeJob.Items[l].EntGroup.Inside[indexEntitySub].Entities.Count - 1)))
						{
							continue;
						}
						for (int n = 0; n <= activeJob.Items[l].CamList.Count - 1; n++)
						{
							if (!((activeJob.Items[l].CamList[n].Direction == InOutCenterType.Inside) & ((activeJob.Items[l].CamList[n].ToolType == MarbleToolType.Saw) | (activeJob.Items[l].CamList[n].ToolType == MarbleToolType.WaterJet))) || activeJob.Items[l].CamList[n].indexInside == indexEntitySub)
							{
							}
						}
					}
				}
			}
			clsInit.appMarble.activeJob.CamCalculated = false;
			doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
			clsInit.cMarble.JobCamCalculatedReset(GCodeCreate: true, CamCalculated: false, CamItems: false, -1, ref clsInit.appMarble.activeJob);
			JobUpdate();
			doDrawActiveJob();
		}
		else
		{
			buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
		}
	}

