			double feed2 = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeFirstVelocity;
			double num = buMarbleCalc.varOperation.settingMarbleCam.MillingFirstStepDown;
			if (CamBase.Tool.Purpose == ToolPurpose.MillingHead)
